#[cfg(feature = "internal-checker")]
fn run_prepared_ordered_check<E: OrderedRunEvidence>(
    prepared: &PreparedCheckerProject, scope: ScalarCheckerScope, startup_count: usize,
    policy: OrderedReachPolicy, evidence: E,
) -> Result<PreparedOrderedRun<E>, ProjectCheck> {
    run_prepared_ordered_check_with_effects(prepared, scope, startup_count, policy, evidence, OrderedFailures::default())
}

#[cfg(feature = "internal-checker")]
fn run_prepared_ordered_check_with_effects<E: OrderedRunEvidence>(
    prepared: &PreparedCheckerProject, scope: ScalarCheckerScope, startup_count: usize,
    policy: OrderedReachPolicy, evidence: E, effects: OrderedFailures,
) -> Result<PreparedOrderedRun<E>, ProjectCheck> {
    run_prepared_ordered_check_profiles::<E, false, false>(prepared, scope, startup_count, policy, evidence, effects)
}

#[cfg(feature = "internal-checker")]
fn run_prepared_ordered_check_profiles<E: OrderedRunEvidence, const PASSIVE_MIXED_STARTUP: bool, const FIXED_INDEX_OBSERVATION: bool>(
    prepared: &PreparedCheckerProject, scope: ScalarCheckerScope, startup_count: usize,
    policy: OrderedReachPolicy, evidence: E, mut effects: OrderedFailures,
) -> Result<PreparedOrderedRun<E>, ProjectCheck> {
    let (project, _) = prepared.parts();
    let (root, ordinals) = package_startup_order(project, &project.modules[..startup_count])?;
    let mut authored_roots = if E::CONTEXTUAL && scope == ScalarCheckerScope::MainFlowOnly {
        HashMap::new()
    } else {
        let (potential_obligations, authored_roots) = package_obligation_roots(prepared, scope, startup_count, root)?;
        if !potential_obligations && !E::CONTEXTUAL && !E::HAS_NAMED_ROOT && effects.contextual_proofs.entries.is_empty() {
            return Ok(PreparedOrderedRun { finished_all_initialization: false, active: false, directives: effects.records, actual: evidence, symbolic: E::SymbolicReport::default(), entry_evidence: None,
                contextual_proofs: effects.contextual_proofs, mixed_context_after_scalar: None });
        }
        authored_roots
    };
    // The unbounded command keeps its ordinary initialization and ordered
    // failure walk. Only already-proved exact requirements leave the roster.
    let verified_joins = if scope == ScalarCheckerScope::CurrentPackage && matches!(policy, OrderedReachPolicy::Closed)
        && E::TYPED_LOCAL_REQUIREMENTS && !PASSIVE_MIXED_STARTUP && effects.contextual_proofs.entries.is_empty()
    {
        prove_typed_local_roots(prepared, &mut authored_roots)?
    } else { Vec::new() };
    let (initialization, mut evidence) = if PASSIVE_MIXED_STARTUP {
        if !matches!(policy, OrderedReachPolicy::Closed) { return Err(ProjectCheck::Unsupported); }
        // Evaluate using precisely the ordinary contextual startup profile.
        // The tap records facts only after a canonical returning call.
        let (initialization, _) = check_package_initialization_observing_with_policy::<_, true, true>(
            prepared, root, ordinals, ProofFreeOrderedEvidence, Some(&mut effects),
        )?;
        (initialization, evidence)
    } else { match policy {
        OrderedReachPolicy::Legacy => check_package_initialization_observing_with_policy::<_, true, false>(
            prepared, root, ordinals, evidence, Some(&mut effects),
        ),
        OrderedReachPolicy::Closed => check_package_initialization_observing_with_policy::<_, true, true>(
            prepared, root, ordinals, evidence, Some(&mut effects),
        ),
    }? };
    let finished_all_initialization = FIXED_INDEX_OBSERVATION
        && initialization.visits.iter().all(|visit| *visit == InitializationVisit::Completed);
    for contextual in effects.contextual_proofs.entries.values_mut() {
        contextual.reached_at_startup = initialization.reached.contains(&contextual.target);
    }
    effects.mixed_proof_order = effects.mixed_startup.take().map(|tap| evidence.consume_mixed_startup(tap)).transpose()?;
    let mut active = evidence.complete_startup(&initialization.reached)? || initialization.had_obligations || !verified_joins.is_empty();
    let symbolic = if scope == ScalarCheckerScope::CurrentPackage {
        let mut proof = evidence.symbolic();
        active |= match policy {
            OrderedReachPolicy::Legacy => check_package_symbolic_roots::<true, false, _>(
                prepared, startup_count, root, initialization, authored_roots, Some(&mut effects), &mut proof,
            ),
            OrderedReachPolicy::Closed => check_package_symbolic_roots::<true, true, _>(
                prepared, startup_count, root, initialization, authored_roots, Some(&mut effects), &mut proof,
            ),
        }?;
        proof.complete()?;
        E::finish_symbolic(proof)
    } else {
        E::SymbolicReport::default()
    };
    // Resolve authored outputs only for a completed check, before planning
    // any client-visible code, stream, or file effect.
    effects.finalize_selected_outputs(E::AUTHORED_SINGLETON_CODE)?;
    Ok(PreparedOrderedRun {
        finished_all_initialization, active, directives: effects.records, actual: evidence, symbolic, entry_evidence: effects.entry_evidence,
        contextual_proofs: effects.contextual_proofs,
        mixed_context_after_scalar: effects.mixed_proof_order.map(|order| order.context_after_scalar),
    })
}

#[cfg(feature = "internal-checker")]
#[allow(dead_code)]
fn check_internal_contextual_calls(
    canonical: &wosy_syntax::CanonicalCstRoot, inputs: ScalarPreparationInputs,
) -> Result<PreparedOrderedRun<ProofFreeOrderedEvidence>, ProjectCheck> {
    let (prepared, _) = super::contextual::prepare_contextual_transport(canonical, inputs, true, false)
        .map_err(|_| ProjectCheck::Unsupported)?;
    // Checker directives are prepared once in checker mode. Context
    // authenticity comes from the same source scope and checked call rows,
    // not a second preparation or a proof-free runtime execution.
    let prepared = PreparedCheckerProject::from_contextual_transport(prepared);
    run_prepared_ordered_check(&prepared, ScalarCheckerScope::MainFlowOnly, 1,
        OrderedReachPolicy::Closed, ProofFreeOrderedEvidence)
}

#[cfg(feature = "internal-checker")]
#[derive(Debug)]
struct ContextualProofOccurrence {
    binding: ReferenceBindingId,
    supplying_call: ByteSpan,
    call: ByteSpan,
    call_source: SourceIdentity,
    symbolic: bool,
    entry: BigInt,
    exit: BigInt,
    explicit: Option<(String, BigInt)>,
    reused: bool,
}

#[cfg(feature = "internal-checker")]
struct VerifiedContextualOutcome {
    exact_binding: ReferenceBindingId,
    leaf_call: ByteSpan,
    caller_source: SourceIdentity,
    occurrence: OccurrenceOrdinal,
    entry: BigInt,
    explicit_entry: Option<BigInt>,
    exit: BigInt,
}

#[cfg(feature = "internal-checker")]
impl VerifiedContextualOutcome {
    fn matches_call(&self, source: &SourceIdentity, occurrence: OccurrenceOrdinal, span: ByteSpan) -> bool {
        &self.caller_source == source && self.occurrence == occurrence && self.leaf_call == span
    }
}

#[cfg(feature = "internal-checker")]
struct MixedProofOrder {
    context_after_scalar: Vec<usize>,
    scalar: usize,
}

#[cfg(feature = "internal-checker")]
struct MixedStartupTap {
    captured: HashMap<PreparedCallable, usize>,
    events: Vec<MixedStartupEvent>,
    work: usize,
}

#[cfg(feature = "internal-checker")]
enum MixedStartupEvent {
    Scalar {
        target: PreparedCallable, source: SourceIdentity, call: ByteSpan, directive_position: usize,
        ty: ScalarType, argument: BigInt, returned: BigInt,
    },
    Contextual,
}

#[cfg(feature = "internal-checker")]
#[derive(Default)]
struct ContextualProofCohort {
    entries: HashMap<PreparedCallable, ReachedContextualProof>,
    refutations: Vec<PreparedCallable>,
}

#[cfg(feature = "internal-checker")]
struct ReachedContextualProof {
    source: SourceIdentity,
    proof: ByteSpan,
    target: PreparedCallable,
    formal: ReferenceBindingId,
    ty: ScalarType,
    goal: ByteSpan,
    add: bool,
    amount: super::contextual::ContextualProofAmount,
    observations: Vec<ContextualProofOccurrence>,
    retain_observations: bool,
    explicit: Option<String>,
    saw_proved_occurrence: bool,
    saw_guarded_nonreturn: bool,
    reached_at_startup: bool,
    examined_symbolic_root: bool,
    typed_where: Option<CheckerPredicate>,
    saw_excluded_occurrence: bool,
    refutation: Option<ContextualProofOccurrence>,
    reusable_body: Option<*const FunctionCallSites>,
    verified: Option<VerifiedContextualOutcome>,
}

#[cfg(feature = "internal-checker")]
impl ReachedContextualProof {
    fn reusable_exit(
        &self, target: PreparedCallable, body: &FunctionCallSites, binding: &ReferenceBindingId,
        ty: &ScalarType, call: (&SourceIdentity, OccurrenceOrdinal, ByteSpan), entry: &BigInt,
        explicit: Option<&BigInt>,
    ) -> Option<&BigInt> {
        let receipt = self.verified.as_ref()?;
        if self.refutation.is_some() || self.reusable_body != Some(std::ptr::from_ref(body))
            || self.target != target || body.contextual_formal() != Some((&self.formal, &self.ty))
            || &self.ty != ty || &receipt.exact_binding != binding || call.0 != &self.formal.source
            || !receipt.matches_call(call.0, call.1, call.2)
            || &receipt.entry != entry || receipt.explicit_entry.as_ref() != explicit
        {
            return None;
        }
        Some(&receipt.exit)
    }

    fn observe(
        &mut self, body: &FunctionCallSites, (formal, formal_type): (&ReferenceBindingId, &ScalarType),
        binding: &ReferenceBindingId, ty: &ScalarType, supplying_call: ByteSpan,
        site @ (call_source, occurrence_id, call): (&SourceIdentity, OccurrenceOrdinal, ByteSpan),
        entry: &BigInt, exit: &BigInt, explicit: Option<&BigInt>, reused: bool,
    ) -> Result<(), ProjectCheck> {
        let explicit = match (self.explicit.as_ref(), explicit, body.boundary.parameters.as_slice()) {
            (None, None, []) => None,
            (Some(name), Some(value), [parameter]) if parameter.ordinal == 0
                && integer_literal_fits_type(value, &parameter.ty) => Some((name, value)),
            _ => return Err(ProjectCheck::Unsupported),
        };
        if formal != &self.formal || formal_type != &self.ty || ty != &self.ty
            || !matches!(binding.kind, super::ReferenceBindingKind::Declared)
            || binding.source.project != formal.source.project || binding.source.package != formal.source.package
        {
            return Err(ProjectCheck::Unsupported);
        }
        if let Some(CheckerPredicate::Integer(guard)) = &self.typed_where {
            let (_, value) = explicit.ok_or(ProjectCheck::Unsupported)?;
            if !IntegerRelation::from_operator(&guard.operator).ok_or(ProjectCheck::Unsupported)?
                .accepts(value.cmp(&guard.bound))
            {
                // A real ordinary return, but no theorem application and no
                // reusable postcondition authority outside its typed domain.
                if reused { return Err(ProjectCheck::Unsupported); }
                self.saw_excluded_occurrence = true;
                return Ok(());
            }
        }
        let proved = if reused {
            if self.reusable_exit(self.target, body, binding, ty, site, entry, explicit.map(|(_, value)| value)) != Some(exit) {
                return Err(ProjectCheck::Unsupported);
            }
            true
        } else {
            let amount = match &self.amount {
                super::contextual::ContextualProofAmount::Literal(amount) => amount,
                super::contextual::ContextualProofAmount::EntryParameter(_) =>
                    explicit.map(|(_, value)| value).ok_or(ProjectCheck::Unsupported)?,
            };
            let expected = if self.add { entry + amount } else { entry - amount };
            if !integer_literal_fits_type(&expected, ty) { return Err(ProjectCheck::Unsupported); }
            &expected == exit
        };
        if self.refutation.is_none() {
            let occurrence = || ContextualProofOccurrence {
                binding: binding.clone(), supplying_call, call, call_source: call_source.clone(), symbolic: false,
                entry: entry.clone(), exit: exit.clone(), explicit: explicit.map(|(name, value)| (name.clone(), value.clone())), reused,
            };
            if proved {
                self.saw_proved_occurrence = true;
                if !reused && self.verified.is_none() && call_source == &formal.source
                    && self.reusable_body == Some(std::ptr::from_ref(body))
                {
                    self.verified = Some(VerifiedContextualOutcome {
                        exact_binding: binding.clone(), leaf_call: call, caller_source: call_source.clone(),
                        occurrence: occurrence_id, entry: entry.clone(), explicit_entry: explicit.map(|(_, value)| value.clone()), exit: exit.clone(),
                    });
                }
                if self.retain_observations { self.observations.push(occurrence()); }
            } else {
                self.verified = None;
                self.refutation = Some(occurrence());
            }
        }
        Ok(())
    }
}

#[cfg(feature = "internal-checker")]
#[allow(dead_code)]
#[derive(Debug)]
enum InternalContextualProofError {
    Check(ProjectCheck),
    Refuted { goal: ByteSpan, occurrence: ContextualProofOccurrence },
}

#[cfg(feature = "internal-checker")]
impl From<ProjectCheck> for InternalContextualProofError {
    fn from(value: ProjectCheck) -> Self { Self::Check(value) }
}

#[cfg(feature = "internal-checker")]
struct ContextualProofHeader {
    name: CstToken,
    explicit: Option<String>,
    place: CstToken,
    proof: ByteSpan,
    goal: ByteSpan,
    add: bool,
    amount: super::contextual::ContextualProofAmount,
    where_declaration: Option<CstNode>,
}

#[cfg(feature = "internal-checker")]
const MAX_CONTEXTUAL_PROOFS: usize = 4;

#[cfg(feature = "internal-checker")]
fn contextual_proof_headers(canonical: &CanonicalCstRoot, allow_explicit: bool) -> Result<Vec<ContextualProofHeader>, ProjectCheck> {
    let root = child(&canonical.root, SyntaxKind::Root)?;
    let mut headers = Vec::new();
    let mut names = HashSet::new();
    for declaration in root.children().filter(|node| node.kind() == SyntaxKind::ProofDecl) {
        if headers.len() == MAX_CONTEXTUAL_PROOFS { return Err(ProjectCheck::Unsupported); }
        let proof_name = module_proof_name(&declaration).ok_or(ProjectCheck::InvalidProof)?;
        if !names.insert(proof_name.text().to_owned()) { return Err(ProjectCheck::InvalidProof); }
        headers.push(contextual_proof_header(&declaration, allow_explicit)?);
    }
    Ok(headers)
}

#[cfg(feature = "internal-checker")]
fn contextual_proof_header(declaration: &CstNode, allow_explicit: bool) -> Result<ContextualProofHeader, ProjectCheck> {
    if declaration.children().any(|node| matches!(node.kind(), SyntaxKind::ProofForall | SyntaxKind::ProofDecreases))
        || child(&declaration, SyntaxKind::Block)?.children().next().is_some()
    {
        return Err(ProjectCheck::Unsupported);
    }
    let target_node = child(&declaration, SyntaxKind::ProofTarget)?;
    let outputs = child(&declaration, SyntaxKind::ProofOutputs)?;
    let output_parameters = child(&outputs, SyntaxKind::Parameters)?;
    let mut output_names = identifiers(&output_parameters);
    // Canonical CST encodes an empty parameters rule as a leaf token,
    // whereas a named parameter list owns a Parameters node.
    let mut target_parameters = target_node.children_with_tokens()
        .filter(|element| element.kind() == SyntaxKind::Parameters);
    let explicit = match target_parameters.next() {
        Some(parameters) if parameters.as_token().is_some() => None,
        Some(parameters) if allow_explicit => {
            let parameters = parameters.into_node().ok_or(ProjectCheck::Unsupported)?;
            let mut names = identifiers(&parameters);
            let name = names.next().ok_or(ProjectCheck::Unsupported)?;
            if name == "null" || names.next().is_some() { return Err(ProjectCheck::Unsupported); }
            Some(name)
        }
        _ => return Err(ProjectCheck::Unsupported),
    };
    if target_parameters.next().is_some()
        || output_names.next().is_none_or(|discard| !is_null_literal_name(&discard))
        || output_names.next().is_some()
    {
        return Err(ProjectCheck::Unsupported);
    }
    let (namespace, name) = proof_target_tokens(&declaration)?;
    if namespace.is_some() { return Err(ProjectCheck::Unsupported); }
    let goal = child(&child(&declaration, SyntaxKind::ProofEnsures)?, SyntaxKind::Expression)?;
    let (place, add, amount) = super::contextual::contextual_proof_delta(&goal).ok_or(ProjectCheck::Unsupported)?;
    if let super::contextual::ContextualProofAmount::EntryParameter(parameter) = &amount {
        if explicit.as_deref() != Some(parameter.text()) { return Err(ProjectCheck::Unsupported); }
    }
    let guarded = declaration.children().any(|node| node.kind() == SyntaxKind::ProofWhere);
    if guarded && (!allow_explicit || explicit.is_none()) { return Err(ProjectCheck::Unsupported); }
    Ok(ContextualProofHeader { name, explicit, place, proof: wosy_syntax::byte_span(&declaration),
        goal: wosy_syntax::byte_span(&goal), add, amount, where_declaration: guarded.then(|| declaration.clone()) })
}

#[cfg(all(test, feature = "internal-checker"))]
fn check_internal_contextual_proof(
    canonical: &CanonicalCstRoot, inputs: ScalarPreparationInputs,
) -> Result<(Vec<ContextualProofOccurrence>, Vec<ScalarOrderedCheckerFailure>), InternalContextualProofError> {
    let source = derive_scalar_proof_declarations_from_cst(canonical);
    let [header]: [ContextualProofHeader; 1] = source.contextual_proofs.try_into().map_err(|_| ProjectCheck::Unsupported)?;
    let identity = source.declarations.source().clone();
    let mut report = check_prepared_contextual_proofs(vec![(source.declarations, Vec::new())], vec![identity.clone()],
        vec![(identity, header)], inputs, ScalarCheckerScope::MainFlowOnly, true)?;
    let (_, proved) = report.contextual_proofs.entries.drain().next().ok_or(ProjectCheck::Unsupported)?;
    if let Some(occurrence) = proved.refutation {
        return Err(InternalContextualProofError::Refuted { goal: proved.goal, occurrence });
    }
    Ok((proved.observations, report.directives))
}

#[cfg(all(test, feature = "internal-checker"))]
fn check_prepared_contextual_proofs(
    sources: Vec<(ScalarSourceDeclarations, Vec<ScalarNamespaceBinding>)>,
    initialization_order: Vec<SourceIdentity>, headers: Vec<(SourceIdentity, ContextualProofHeader)>,
    inputs: ScalarPreparationInputs, scope: ScalarCheckerScope, retain_observations: bool,
) -> Result<PreparedOrderedRun<ProofFreeOrderedEvidence>, ProjectCheck> {
    let (prepared, effects, startup_count) = prepare_contextual_check(
        sources, initialization_order, headers, inputs, retain_observations,
    )?;
    run_contextual_check(&prepared, effects, startup_count, scope, retain_observations)
}

#[cfg(feature = "internal-checker")]
fn prepare_contextual_check(
    sources: Vec<(ScalarSourceDeclarations, Vec<ScalarNamespaceBinding>)>,
    initialization_order: Vec<SourceIdentity>, headers: Vec<(SourceIdentity, ContextualProofHeader)>,
    inputs: ScalarPreparationInputs, retain_observations: bool,
) -> Result<(PreparedCheckerProject, OrderedFailures, usize), ProjectCheck> {
    let startup_count = initialization_order.len();
    let (prepared, context) = super::contextual::prepare_contextual_transport_graph_with_proof_root(
        sources, initialization_order, inputs, true, !retain_observations,
    )
        .map_err(|_| ProjectCheck::Unsupported)?;
    let prepared = PreparedCheckerProject::from_contextual_transport(prepared);
    let effects = prepare_contextual_effects(&prepared, &context, headers, startup_count, retain_observations)?;
    Ok((prepared, effects, startup_count))
}

#[cfg(feature = "internal-checker")]
fn run_contextual_check(
    prepared: &PreparedCheckerProject, effects: OrderedFailures, startup_count: usize,
    scope: ScalarCheckerScope, retain_observations: bool,
) -> Result<PreparedOrderedRun<ProofFreeOrderedEvidence>, ProjectCheck> {
    if effects.contextual_proofs.entries.values().any(|proof| proof.typed_where.is_some()) {
        return Err(ProjectCheck::Unsupported);
    }
    let mut report = run_prepared_ordered_check_with_effects(prepared, scope, startup_count,
        OrderedReachPolicy::Closed, ProofFreeOrderedEvidence, effects)?;
    complete_contextual_effects(&mut report, scope, retain_observations)?;
    Ok(report)
}

#[cfg(feature = "internal-checker")]
fn prepare_contextual_effects(
    prepared: &PreparedCheckerProject, context: &super::contextual::DormantContextReceipt,
    headers: Vec<(SourceIdentity, ContextualProofHeader)>, startup_count: usize, retain_observations: bool,
) -> Result<OrderedFailures, ProjectCheck> {
    let (project, calls) = prepared.parts();
    let mut contextual_proofs = ContextualProofCohort::default();
    for (proof_source, header) in headers {
        let (module_index, module) = project.modules.iter().enumerate().find(|(_, module)| module.source == proof_source)
            .ok_or(ProjectCheck::MissingRoot)?;
        let (item, function) = module.items.iter().enumerate().find_map(|(item, candidate)| match candidate {
            super::ScalarItem::Function(function) if function.name == header.name.text() => Some((item, function)),
            _ => None,
        }).ok_or(ProjectCheck::InvalidProof)?;
        let body = calls.function_body(module_index, item, None).ok_or(ProjectCheck::MissingRootOccurrences)?;
        let (formal, ty) = body.contextual_formal().ok_or(ProjectCheck::Unsupported)?;
        let explicit_parameter = match (header.explicit.as_ref(), body.boundary.parameters.as_slice()) {
            (None, []) => true,
            (Some(_), [slot]) => slot.ordinal == 0 && is_integer_type(&slot.ty),
            _ => false,
        };
        if ty != &context.ty || !explicit_parameter
            || !matches!(body.boundary.results.as_slice(), [output] if output.ty == ScalarType::Unit)
            || formal.source != module.source || formal.function_span != function.span
        {
            return Err(ProjectCheck::Unsupported);
        }
        let valid_amount = match &header.amount {
            super::contextual::ContextualProofAmount::Literal(amount) => integer_literal_fits_type(amount, ty),
            super::contextual::ContextualProofAmount::EntryParameter(_) =>
                matches!(body.boundary.parameters.as_slice(), [slot] if &slot.ty == ty),
        };
        if header.place.text() != context.name.as_ref() || !valid_amount {
            return Err(ProjectCheck::Unsupported);
        }
        let typed_where = if let Some(declaration) = &header.where_declaration {
            let formal_name = header.explicit.as_ref().ok_or(ProjectCheck::Unsupported)?;
            let filters = prepare_proof_entry_filter_in_scope(declaration, &proof_source, module.target_layout,
                std::slice::from_ref(formal_name), body, false)?.ok_or(ProjectCheck::Unsupported)?;
            let [predicate @ CheckerPredicate::Integer(_)] = filters.as_slice() else { return Err(ProjectCheck::Unsupported); };
            Some(predicate.clone())
        } else { None };
        let target = (module_index, item);
        if contextual_proofs.entries.insert(target, ReachedContextualProof {
            source: proof_source, proof: header.proof, target, formal: formal.clone(), ty: ty.clone(), goal: header.goal,
            add: header.add, amount: header.amount, observations: Vec::new(),
            retain_observations, explicit: header.explicit, saw_proved_occurrence: false, saw_guarded_nonreturn: false, reached_at_startup: false,
            examined_symbolic_root: false, refutation: None, typed_where, saw_excluded_occurrence: false,
            reusable_body: (startup_count == 1 && super::checker_flow::exact_contextual_summary_leaf(body))
                .then_some(std::ptr::from_ref(body)),
            verified: None,
        }).is_some() {
            return Err(ProjectCheck::AmbiguousRoot);
        }
    }
    Ok(OrderedFailures { contextual_proofs, ..OrderedFailures::default() })
}

#[cfg(feature = "internal-checker")]
fn complete_contextual_effects<E: OrderedRunEvidence>(
    report: &mut PreparedOrderedRun<E>, scope: ScalarCheckerScope, retain_observations: bool,
) -> Result<(), ProjectCheck> {
    for proof in report.contextual_proofs.entries.values() {
        if proof.refutation.is_none()
            && (((proof.reached_at_startup || retain_observations) && !proof.saw_proved_occurrence
                && !proof.saw_guarded_nonreturn)
                || (scope == ScalarCheckerScope::CurrentPackage && !proof.reached_at_startup && !proof.examined_symbolic_root))
        {
            return Err(ProjectCheck::Unsupported);
        }
        report.active |= proof.saw_proved_occurrence || proof.refutation.is_some();
    }
    Ok(())
}

#[cfg(all(test, feature = "internal-checker"))]
fn collect_ordered_package_failures(
    prepared: &PreparedCheckerProject, scope: ScalarCheckerScope, startup_count: usize,
) -> Result<(bool, Vec<ProjectCheck>), ProjectCheck> {
    let (active, failures) = collect_ordered_checker_records(prepared, scope, startup_count)?;
    Ok((active, failures.into_iter().map(ordered_failure_as_legacy).collect()))
}

fn check_package_roots_with_activity(
    prepared: &PreparedCheckerProject, scope: ScalarCheckerScope, startup_count: usize,
) -> Result<bool, ProjectCheck> {
    let (project, _) = prepared.parts();
    let (root, ordinals) = package_startup_order(project, &project.modules[..startup_count])?;
    let (potential_obligations, authored_roots) = package_obligation_roots(prepared, scope, startup_count, root)?;
    if !potential_obligations {
        return Ok(false);
    }
    let initialization = check_package_initialization_with_order(prepared, root, ordinals)?;
    if scope == ScalarCheckerScope::MainFlowOnly {
        return Ok(initialization.had_obligations);
    }
    check_package_symbolic_roots::<false, false, _>(
        prepared, startup_count, root, initialization, authored_roots, None, &mut (),
    )
}

fn package_obligation_roots(
    prepared: &PreparedCheckerProject, scope: ScalarCheckerScope, startup_count: usize, root: &SourceIdentity,
) -> Result<(bool, HashMap<usize, Vec<usize>>), ProjectCheck> {
    let (project, calls) = prepared.parts();
    let mut potential_obligations = false;
    let mut authored_roots = HashMap::<usize, Vec<usize>>::new();
    for (module, source_module) in project.modules.iter().enumerate() {
        if module < startup_count {
            let region = calls.initialization_region(module).ok_or(ProjectCheck::MissingRootOccurrences)?;
            let ModuleInitializationDetail::Occurrences(topology) = &region.detail else {
                return Err(ProjectCheck::MissingRootOccurrences);
            };
            potential_obligations |= !topology.structure.checker_directives.is_empty();
        }
        let is_current_symbolic_package = scope == ScalarCheckerScope::CurrentPackage
            && source_module.source.project == root.project && source_module.source.package == root.package;
        for (item, declaration) in source_module.items.iter().enumerate() {
            if matches!(declaration, ScalarItem::Function(_)) {
                let body = calls.function_body(module, item, None).ok_or(ProjectCheck::MissingRootOccurrences)?;
                if has_callable_obligations(body) {
                    potential_obligations = true;
                    if is_current_symbolic_package {
                        authored_roots.entry(module).or_default().push(item);
                    }
                }
            }
        }
    }
    Ok((potential_obligations, authored_roots))
}

fn check_package_symbolic_roots<const COLLECT: bool, const ENTRY_EVIDENCE: bool, Proof: SymbolicRootProof>(
    prepared: &PreparedCheckerProject, startup_count: usize, root: &SourceIdentity,
    initialization: CheckedInitialization<'_>, mut authored_roots: HashMap<usize, Vec<usize>>,
    mut failures: Option<&mut OrderedFailures>, proof: &mut Proof,
) -> Result<bool, ProjectCheck> {
    let (project, calls) = prepared.parts();
    let dormant = &project.modules[startup_count..];
    let CheckedInitialization { visits, reached, ordinals, mut had_obligations, .. } = initialization;
    let mut ordinary_local_callers = HashSet::new();
    let mut ordered_roots = if COLLECT {
        close_ordered_symbolic_roots(std::mem::take(&mut authored_roots), || {
            let mut ordinary_local_seeds = Vec::new();
            let callers = ordered_symbolic_callers(project, calls, root,
                Proof::INTEGER_RETURN_PARTITIONS.then_some(&mut ordinary_local_seeds))?;
            // The same prepared reverse call graph supplies both root selection
            // and ordinary-local cursor eligibility, including transitive callers.
            ordinary_local_callers.extend(ordinary_local_seeds.iter().copied());
            while let Some(callee) = ordinary_local_seeds.pop() {
                if let Some(edges) = callers.get(&callee) {
                    ordinary_local_seeds.extend(edges.iter().copied().filter(|caller| ordinary_local_callers.insert(*caller)));
                }
            }
            Ok(callers)
        })?
    } else {
        HashMap::new()
    };
    if COLLECT && Proof::ENABLED {
        proof.seed(&mut ordered_roots, &reached);
    }
    #[cfg(feature = "internal-checker")]
    if COLLECT {
        if let Some(effects) = failures.as_ref() {
            for &(module, item) in effects.contextual_proofs.entries.keys() {
                if !reached.contains(&(module, item)) {
                    ordered_roots.entry(module).or_default().insert(item);
                }
            }
        }
    }
    let mut module_roots = |ordinal: usize, module: &ScalarModule| {
        if COLLECT {
            Ok(ordered_roots.remove(&ordinal))
        } else {
            authored_roots.remove(&ordinal).map(|seeds| symbolic_obligation_roots(calls, module, ordinal, seeds)).transpose()
        }
    };
    for source in &project.initialization_order {
        if source.project != root.project || source.package != root.package {
            continue;
        }
        let ordinal = *ordinals.get(source).ok_or(ProjectCheck::RootSourceOutsideInitOrder)?;
        let completed = visits[ordinal] == InitializationVisit::Completed;
        if !COLLECT && !completed {
            continue;
        }
        let module = &project.modules[ordinal];
        if let Some(selected) = module_roots(ordinal, module)? {
            if !completed {
                if selected.into_iter().any(|item| !reached.contains(&(ordinal, item))) {
                    return Err(ProjectCheck::Unsupported);
                }
                continue;
            }
            had_obligations |= check_unused_module::<COLLECT, ENTRY_EVIDENCE, _>(
                project, calls, module, ordinal, &reached, selected, &ordinary_local_callers, failures.as_deref_mut(), Some(&visits), proof,
            )?;
        }
    }
    for (index, module) in dormant.iter().enumerate() {
        let ordinal = startup_count + index;
        if let Some(selected) = module_roots(ordinal, module)? {
            had_obligations |= check_unused_module::<COLLECT, ENTRY_EVIDENCE, _>(
                project, calls, module, ordinal, &reached, selected, &ordinary_local_callers, failures.as_deref_mut(), None, proof,
            )?;
        }
    }
    Ok(had_obligations)
}

type PreparedCallable = (usize, usize);

fn ordered_symbolic_callers(
    project: &ScalarProject,
    calls: &ProjectCallSiteResults,
    root: &SourceIdentity,
    mut ordinary_local_seeds: Option<&mut Vec<PreparedCallable>>,
) -> Result<HashMap<PreparedCallable, Vec<PreparedCallable>>, ProjectCheck> {
    #[cfg(not(feature = "internal-checker"))]
    let _ = &mut ordinary_local_seeds;
    let mut callers = HashMap::new();
    for (module, source_module) in project.modules.iter().enumerate() {
        if source_module.source.project != root.project || source_module.source.package != root.package {
            continue;
        }
        for (item, declaration) in source_module.items.iter().enumerate() {
            if !matches!(declaration, ScalarItem::Function(_)) {
                continue;
            }
            let body = calls.function_body(module, item, None).ok_or(ProjectCheck::MissingRootOccurrences)?;
            #[cfg(feature = "internal-checker")]
            if let Some(seeds) = ordinary_local_seeds.as_deref_mut() {
                if body.structure.has_ordinary_integer_operations() {
                    seeds.push((module, item));
                }
            }
            record_ordered_symbolic_callable_edges(body, (module, item), project, root, &mut callers);
        }
    }
    Ok(callers)
}

fn record_ordered_symbolic_callable_edges(
    body: &FunctionCallSites,
    caller: PreparedCallable,
    project: &ScalarProject,
    root: &SourceIdentity,
    callers: &mut HashMap<PreparedCallable, Vec<PreparedCallable>>,
) {
    for (occurrence, &target) in &body.structure.checker_direct_targets {
        if target.0 != caller.0 {
            let Some(signature) = body.checked_call_signatures.get(occurrence) else { continue; };
            if !matches!(signature.outputs.outputs.as_slice(), [output] if output.ty == ScalarType::Unit) {
                continue;
            }
            let Some(owner) = project.modules.get(target.0) else { continue; };
            if root.project != owner.source.project || root.package != owner.source.package {
                continue;
            }
        }
        let edges = callers.entry(target).or_default();
        if edges.last() != Some(&caller) {
            edges.push(caller);
        }
    }
    for arm in &body.arms {
        record_ordered_symbolic_callable_edges(arm, caller, project, root, callers);
    }
}

fn close_ordered_symbolic_roots(
    authored: HashMap<usize, Vec<usize>>,
    build_callers: impl FnOnce() -> Result<HashMap<PreparedCallable, Vec<PreparedCallable>>, ProjectCheck>,
) -> Result<HashMap<usize, HashSet<usize>>, ProjectCheck> {
    let mut selected = HashMap::new();
    if authored.is_empty() {
        return Ok(selected);
    }
    let mut callers = build_callers()?;
    let mut pending = Vec::new();
    for (module, items) in authored {
        selected.insert(module, items.iter().copied().collect::<HashSet<_>>());
        pending.extend(items.into_iter().map(|item| (module, item)));
    }
    while let Some(target) = pending.pop() {
        if let Some(edges) = callers.remove(&target) {
            for (module, item) in edges {
                if selected.entry(module).or_default().insert(item) {
                    pending.push((module, item));
                }
            }
        }
    }
    Ok(selected)
}

fn record_symbolic_callable_edges(
    body: &FunctionCallSites,
    ordinal: usize,
    caller: usize,
    callers: &mut HashMap<usize, Vec<usize>>,
) {
    for &(target_module, target_item) in body.structure.checker_direct_targets.values() {
        if target_module == ordinal {
            let edges = callers.entry(target_item).or_default();
            if edges.last() != Some(&caller) {
                edges.push(caller);
            }
        }
    }
    for arm in &body.arms {
        record_symbolic_callable_edges(arm, ordinal, caller, callers);
    }
}

fn symbolic_obligation_roots(
    calls: &ProjectCallSiteResults,
    module: &ScalarModule,
    ordinal: usize,
    mut pending: Vec<usize>,
) -> Result<HashSet<usize>, ProjectCheck> {
    let mut callers = HashMap::new();
    for (item, declaration) in module.items.iter().enumerate() {
        if !matches!(declaration, ScalarItem::Function(_)) {
            continue;
        }
        let body = calls.function_body(ordinal, item, None).ok_or(ProjectCheck::MissingRootOccurrences)?;
        record_symbolic_callable_edges(body, ordinal, item, &mut callers);
    }
    let mut roots: HashSet<_> = pending.iter().copied().collect();
    if !callers.is_empty() {
        while let Some(target) = pending.pop() {
            if let Some(edges) = callers.remove(&target) {
                pending.extend(edges.into_iter().filter(|caller| roots.insert(*caller)));
            }
        }
    }
    Ok(roots)
}

#[cfg(feature = "internal-checker")]
struct ProofFreeSymbolic<const ORDINARY_PROJECTIONS: bool = false, const NAMED_PARTITIONS: bool = false> {
    ordinary_projected_effects: bool,
    citation_only: bool,
    named_pair: bool,
    named_mixed_pair: bool,
    named_pair_work: usize,
}

#[cfg(feature = "internal-checker")]
impl SymbolicRootProof for ProofFreeSymbolic {
    const ENABLED: bool = false;
    const INTEGER_RETURN_PARTITIONS: bool = true;
}

#[cfg(feature = "internal-checker")]
impl<const ORDINARY_PROJECTIONS: bool, const NAMED_PARTITIONS: bool> ActualIntegerObserver
    for ProofFreeSymbolic<ORDINARY_PROJECTIONS, NAMED_PARTITIONS> {
    const ENABLED: bool = false;
    const EXACT_INTEGER_CALL_CONTINUATIONS: bool = true;
    const INTEGER_RETURN_PARTITIONS: bool = true;

    const PROJECTED_FORMAL_WRITES: bool = ORDINARY_PROJECTIONS;
    const ORDINARY_PROJECTED_PAIR: bool = ORDINARY_PROJECTIONS;
    const NAMED_RELATIONAL_PARTITIONS: bool = NAMED_PARTITIONS;
    const ORDINARY_INTEGER_LOCALS: bool = ORDINARY_PROJECTIONS;

    fn charge_named_pair_activation(&mut self, body: &FunctionCallSites) -> Option<()> {
        super::checker_flow::charge_call_work(&mut self.named_pair_work, body.occurrences.len().saturating_add(1))
    }

    fn named_mixed_pair(&self) -> bool { self.named_mixed_pair }

    fn named_pair(&self) -> bool { self.named_pair }

    fn citation_only(&self) -> bool { self.citation_only }

    fn permits_ordinary_projected_effects(&self) -> bool {
        ORDINARY_PROJECTIONS && self.ordinary_projected_effects
    }

    fn observe(&mut self, _: (usize, usize), _: &[&BigInt], _: &BigInt) {}
}

#[derive(Clone, Copy)]
struct SymbolicProofRuntime<'a> {
    project: &'a ScalarProject,
    calls: &'a ProjectCallSiteResults,
    visits: Option<&'a [InitializationVisit]>,
}

trait SymbolicRootProof {
    const ENABLED: bool;
    const INTEGER_RETURN_PARTITIONS: bool = false;
    const FIXED_ARRAY_RETURN: bool = false;

    fn seed(&self, _: &mut HashMap<usize, HashSet<usize>>, _: &HashSet<PreparedCallable>) {}

    fn complete(&self) -> Result<(), ProjectCheck> { Ok(()) }

    fn watches_literal_leaf(&self, _: PreparedCallable) -> bool { false }
    fn watches_result_pair(&self, _: PreparedCallable) -> bool { false }

    fn try_collect(
        &mut self, _: PreparedCallable, _: &FunctionCallSites, _: &ScalarFunction, _: &SourceIdentity,
        _: &mut OrderedFailures, _: SymbolicProofRuntime<'_>,
    ) -> Result<Option<bool>, ProjectCheck> {
        Ok(None)
    }
}

impl SymbolicRootProof for () {
    const ENABLED: bool = false;
}

fn check_unused_module<const COLLECT: bool, const ENTRY_EVIDENCE: bool, Proof: SymbolicRootProof>(
    project: &ScalarProject,
    calls: &ProjectCallSiteResults,
    module: &ScalarModule,
    ordinal: usize,
    reached: &HashSet<(usize, usize)>,
    symbolic_roots: HashSet<usize>,
    ordinary_local_callers: &HashSet<PreparedCallable>,
    mut failures: Option<&mut OrderedFailures>,
    completed_visits: Option<&[InitializationVisit]>,
    proof: &mut Proof,
) -> Result<bool, ProjectCheck> {
    #[cfg(not(feature = "internal-checker"))]
    let _ = ordinary_local_callers;
    let mut active = false;
    #[cfg(feature = "internal-checker")]
    let mut closed_units = HashSet::new();
    for (item, declaration) in module.items.iter().enumerate() {
        let ScalarItem::Function(function) = declaration else {
            continue;
        };
        if reached.contains(&(ordinal, item)) || !symbolic_roots.contains(&item) {
            continue;
        }
        let body = calls.function_body(ordinal, item, None).ok_or(ProjectCheck::MissingRootOccurrences)?;
        if !function.generic_parameters.is_empty() || !function.overload_arms.is_empty() {
            return Err(ProjectCheck::Unsupported);
        }
        #[cfg(feature = "internal-checker")]
        if let Some(plan) = (!Proof::ENABLED).then(|| mixed_guard_plan(project, calls, (ordinal, item), body,
            completed_visits.and_then(|visits| visits.get(ordinal)) == Some(&InitializationVisit::Completed))).flatten()
        {
            let work = std::cell::Cell::new(0);
            let Some(super::checker_flow::CallableHistoryCompletion::Exhausted(observed)) =
                super::checker_flow::search_mixed_float_guard_root(body, &plan, &work) else {
                    return Err(ProjectCheck::Unsupported);
                };
            active |= observed;
            continue;
        }
        #[cfg(feature = "internal-checker")]
        if let Some(plan) = (!Proof::ENABLED).then(|| closed_dormant_float_plan(project, calls, (ordinal, item), body,
            completed_visits.and_then(|visits| visits.get(ordinal)) == Some(&InitializationVisit::Completed))).flatten() {
            let work = std::cell::Cell::new(0);
            let mut first = None;
            let completion = search_closed_dormant_float(body, &plan, &work, |failure, _steps| {
                if COLLECT {
                    let effects = failures.as_deref_mut()?;
                    if ENTRY_EVIDENCE {
                        effects.capture_entry_evidence(body, function, &module.source, &failure);
                    }
                    effects.push_callable(body, &module.source, failure);
                    Some(false)
                } else {
                    first = Some(project_failure(body, &module.source, failure));
                    Some(true)
                }
            }).ok_or(ProjectCheck::Unsupported)?;
            if let Some(failure) = first { return Err(failure); }
            let super::checker_flow::CallableHistoryCompletion::Exhausted(observed) = completion else {
                return Err(ProjectCheck::Unsupported);
            };
            active |= observed;
            continue;
        }
        #[cfg(feature = "internal-checker")]
        if COLLECT && !Proof::ENABLED && body.checker_returns_unit()
            && has_projected_unit_history_edge(calls, (ordinal, item))
            && completed_visits.is_some()
            && failures.as_ref().is_some_and(|effects| effects.contextual_proofs.entries.is_empty())
        {
            let target = (ordinal, item);
            let mut spent = 0;
            if plan_finite_projected_history(project, calls, target, &mut closed_units, &mut spent).is_some() {
                let observed = collect_complete_unit_history::<ENTRY_EVIDENCE>(
                    project, calls, completed_visits.ok_or(ProjectCheck::Unsupported)?, target, spent,
                    failures.as_deref_mut().ok_or(ProjectCheck::Unsupported)?,
                )?;
                active |= observed;
                continue;
            }
        }
        if !matches!(body.boundary.results.as_slice(), [result]
            if result.ty == ScalarType::Unit || is_integer_type(&result.ty)
                || (COLLECT && ((result.ty == ScalarType::Bool && Proof::INTEGER_RETURN_PARTITIONS)
                    || (matches!(result.ty, ScalarType::Bool | ScalarType::Char)
                        && proof.watches_literal_leaf((ordinal, item)))))
                || (COLLECT && Proof::FIXED_ARRAY_RETURN && matches!(result.ty, ScalarType::Array { .. })))
            && !(COLLECT && body.boundary.results.len() == 2 && proof.watches_result_pair((ordinal, item)))
        {
            return Err(ProjectCheck::Unsupported);
        }
        #[cfg(feature = "internal-checker")]
        if COLLECT {
            if let Some(effects) = failures.as_deref_mut() {
                let target = (ordinal, item);
                if let Some(mut context) = effects.contextual_proofs.entries.remove(&target) {
                    if body.contextual_formal() != Some((&context.formal, &context.ty)) {
                        return Err(ProjectCheck::Unsupported);
                    }
                    let amount = match &context.amount {
                        super::contextual::ContextualProofAmount::Literal(amount) => Some(amount),
                        super::contextual::ContextualProofAmount::EntryParameter(_) => None,
                    };
                    let (observed, refuted) = super::checker_flow::check_symbolic_contextual_unit(
                        body, amount, context.add, &mut |failure| {
                            if body.structure.checker_selected_snapshots.is_empty() {
                                effects.snapshot_records.push(effects.records.len());
                            }
                            effects.push_callable(body, &module.source, failure);
                        },
                    ).ok_or(ProjectCheck::Unsupported)?;
                    if let Some(failure) = refuted {
                        let explicit = match (context.explicit.as_ref(), failure.explicit) {
                            (Some(name), Some(value)) => Some((name.clone(), value)),
                            (None, None) => None,
                            _ => return Err(ProjectCheck::Unsupported),
                        };
                        context.refutation = Some(ContextualProofOccurrence {
                            binding: context.formal.clone(), supplying_call: function.name_span,
                            call: function.name_span, call_source: module.source.clone(),
                            symbolic: true, entry: failure.entry, exit: failure.exit, explicit, reused: false,
                        });
                    }
                    context.examined_symbolic_root = true;
                    if context.refutation.is_some() {
                        effects.contextual_proofs.refutations.push(target);
                        if let Some(order) = &mut effects.mixed_proof_order {
                            order.context_after_scalar.push(order.scalar);
                        }
                    }
                    effects.contextual_proofs.entries.insert(target, context);
                    active |= observed;
                    continue;
                }
            }
        }
        if COLLECT && Proof::ENABLED {
            if let Some(observed) = proof.try_collect(
                (ordinal, item), body, function, &module.source, failures.as_deref_mut().ok_or(ProjectCheck::Unsupported)?,
                SymbolicProofRuntime { project, calls, visits: completed_visits },
            )? {
                active |= observed;
                continue;
            }
        }
        #[cfg(feature = "internal-checker")]
        let symbolic_integer_tail = !Proof::ENABLED && is_integer_type(&body.boundary.results[0].ty)
            && body.structure.blocks.get(body.structure.root.0).and_then(|block| block.items.last())
                .is_some_and(|item| matches!(&item.kind, BlockItemKind::FinalOutput(slot)
                    if body.structure.checker_direct_targets.contains_key(&slot.expression)));
        #[cfg(feature = "internal-checker")]
        if COLLECT && Proof::INTEGER_RETURN_PARTITIONS
            && matches!(body.boundary.results.as_slice(), [result]
                if matches!(result.ty, ScalarType::Unit | ScalarType::Bool)
                    || (!Proof::ENABLED && is_integer_type(&result.ty)
                        && body.assignments.is_empty()
                        && !body.structure.has_ordinary_contextual_places()
                        && !body.structure.checker_has_bool_contextual_declaration))
            && (!body.structure.checker_direct_targets.is_empty() || !body.structure.checker_ordinary_directive_calls.is_empty())
            && (symbolic_integer_tail || ordinary_local_callers.contains(&(ordinal, item))
                || !body.structure.checker_integer_call_locals.is_empty()
                || body.structure.checker_direct_targets.keys().any(|occurrence| {
                    body.checked_call_signatures.get(occurrence).is_some_and(|signature|
                        matches!(signature.parameters.as_slice(), [left, right] if is_integer_type(left) && is_integer_type(right))
                        && matches!(signature.outputs.outputs.as_slice(), [output] if output.ty == ScalarType::Unit))
                }))
        {
            let sink = RefCell::new(failures.as_deref_mut().ok_or(ProjectCheck::Unsupported)?);
            let collection = OrderedCallCollection::new(&sink, completed_visits);
            let mut symbolic = CheckedCalls::<ProofFreeSymbolic<true>, false> {
                project, calls, active: HashSet::from([(ordinal, item)]), active_depth: 1, reached: HashSet::new(),
            #[cfg(feature = "internal-checker")] mixed_reached: None,
                had_obligations: false, observer: ProofFreeSymbolic { ordinary_projected_effects: !Proof::ENABLED, citation_only: false, named_pair: false, named_mixed_pair: false, named_pair_work: 0 }, symbolic_module: ordinal,
            };
            let mut cursor = ExactCallCursor::arbitrary_root(body, &body.boundary.results[0].ty)
                .ok_or(ProjectCheck::Unsupported)?;
            if symbolic_integer_tail { cursor.allow_real_integer_tail_call(); }
            if !Proof::ENABLED && body.structure.checker_has_extended_scalar_local {
                cursor.allow_extended_scalar_locals();
            }
            if !Proof::ENABLED && body.structure.checker_has_bool_contextual_declaration {
                cursor.allow_symbolic_contextual_bool();
            }
            symbolic.run_call_cursor::<false>(body, &module.source, cursor, None, Some(collection), None)?;
            active |= symbolic.had_obligations;
            continue;
        }
        if body.structure.checker_direct_targets.is_empty() {
            if COLLECT {
                #[cfg(feature = "internal-checker")]
                let collected = super::checker_flow::collect_ordered_root_requirement_failures(
                    body, &function.body, Proof::INTEGER_RETURN_PARTITIONS, !Proof::ENABLED,
                );
                #[cfg(not(feature = "internal-checker"))]
                let collected = collect_integer_requirement_failures(body);
                let (observed, selected) = collected.ok_or(ProjectCheck::Unsupported)?;
                active |= observed;
                let failures = failures.as_deref_mut().ok_or(ProjectCheck::Unsupported)?;
                for failure in selected {
                    #[cfg(feature = "internal-checker")]
                    if ENTRY_EVIDENCE {
                        failures.capture_entry_evidence(body, function, &module.source, &failure);
                    }
                    failures.push_callable(body, &module.source, failure);
                }
            } else {
                match check_integer_requirement_activity(body) {
                    Some(Ok(observed)) => active |= observed,
                    Some(Err(failure)) => return Err(project_failure(body, &module.source, failure)),
                    None => return Err(ProjectCheck::Unsupported),
                }
            }
        } else {
            let mut symbolic = CheckedCalls::<(), false> {
                project, calls, active: HashSet::from([(ordinal, item)]), active_depth: 1, reached: HashSet::new(),
            #[cfg(feature = "internal-checker")] mixed_reached: None,
                had_obligations: false, observer: (), symbolic_module: ordinal,
            };
            if COLLECT {
                let sink = RefCell::new(failures.as_deref_mut().ok_or(ProjectCheck::Unsupported)?);
                let collection = OrderedCallCollection::new(&sink, completed_visits);
                symbolic.collect_requirements(body, &module.source, IntegerRequirementEntry::Arbitrary, collection)?;
                active |= symbolic.had_obligations;
            } else {
                let observed = symbolic.requirements(body, &module.source, None)?;
                active |= observed || symbolic.had_obligations;
            }
        }
    }
    Ok(active)
}

fn package_initialization_order(
    project: &ScalarProject,
) -> Result<(&SourceIdentity, HashMap<&SourceIdentity, usize>), ProjectCheck> {
    package_startup_order(project, &project.modules)
}

fn package_startup_order<'a>(
    project: &'a ScalarProject,
    startup: &'a [ScalarModule],
) -> Result<(&'a SourceIdentity, HashMap<&'a SourceIdentity, usize>), ProjectCheck> {
    let ordinals: HashMap<_, _> = startup.iter().enumerate()
        .map(|(ordinal, module)| (&module.source, ordinal)).collect();
    if ordinals.len() != startup.len() {
        return Err(ProjectCheck::AmbiguousRoot);
    }
    let root = project.initialization_order.first().ok_or(ProjectCheck::MissingRoot)?;
    if project.initialization_order.len() != ordinals.len() {
        return Err(ProjectCheck::RootSourceOutsideInitOrder);
    }
    let mut seen = vec![false; ordinals.len()];
    for source in &project.initialization_order {
        let ordinal = *ordinals.get(source).ok_or(ProjectCheck::RootSourceOutsideInitOrder)?;
        if std::mem::replace(&mut seen[ordinal], true) {
            return Err(ProjectCheck::AmbiguousRoot);
        }
    }
    Ok((root, ordinals))
}

#[cfg(test)]
fn check_package_initialization(prepared: &PreparedCheckerProject) -> Result<CheckedInitialization<'_>, ProjectCheck> {
    let (root, ordinals) = package_initialization_order(prepared.parts().0)?;
    check_package_initialization_with_order(prepared, root, ordinals)
}

fn check_package_initialization_with_order<'a>(
    prepared: &'a PreparedCheckerProject,
    root: &'a SourceIdentity,
    ordinals: HashMap<&'a SourceIdentity, usize>,
) -> Result<CheckedInitialization<'a>, ProjectCheck> {
    check_package_initialization_observing(prepared, root, ordinals, ()).map(|(initialization, ())| initialization)
}

#[cfg(all(test, feature = "internal-checker"))]
fn collect_package_startup_failures(
    prepared: &PreparedCheckerProject,
) -> Result<Vec<ProjectCheck>, ProjectCheck> {
    let (root, ordinals) = package_initialization_order(prepared.parts().0)?;
    let mut failures = OrderedFailures::default();
    check_package_initialization_observing_with_policy::<(), true, false>(
        prepared, root, ordinals, (), Some(&mut failures),
    )?;
    Ok(failures.records.into_iter().map(ordered_failure_as_legacy).collect())
}

fn check_package_initialization_observing<'a, Observer: ActualIntegerObserver>(
    prepared: &'a PreparedCheckerProject,
    root: &'a SourceIdentity,
    ordinals: HashMap<&'a SourceIdentity, usize>,
    observer: Observer,
) -> Result<(CheckedInitialization<'a>, Observer), ProjectCheck> {
    check_package_initialization_observing_with_policy::<Observer, false, false>(prepared, root, ordinals, observer, None)
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum StartupLane {
    Feasible,
    Empty,
}

fn check_package_initialization_observing_with_policy<'a, Observer: ActualIntegerObserver, const COLLECT: bool, const PRIVATE_NESTED_SCALAR: bool>(
    prepared: &'a PreparedCheckerProject,
    root: &'a SourceIdentity,
    ordinals: HashMap<&'a SourceIdentity, usize>,
    observer: Observer,
    failures: Option<&mut OrderedFailures>,
) -> Result<(CheckedInitialization<'a>, Observer), ProjectCheck> {
    let (outcome, observer) = walk_prepared_initialization::<Observer, COLLECT, PRIVATE_NESTED_SCALAR>(
        prepared, root, ordinals, observer, failures,
    );
    Ok((outcome?, observer))
}

fn walk_prepared_initialization<'a, Observer: ActualIntegerObserver, const COLLECT: bool, const PRIVATE_NESTED_SCALAR: bool>(
    prepared: &'a PreparedCheckerProject,
    root: &'a SourceIdentity,
    ordinals: HashMap<&'a SourceIdentity, usize>,
    observer: Observer,
    mut failures: Option<&mut OrderedFailures>,
) -> (Result<CheckedInitialization<'a>, ProjectCheck>, Observer) {
    let (project, calls) = prepared.parts();
    let mut visits = vec![InitializationVisit::Unseen; project.modules.len()];
    let mut actual = CheckedCalls {
        project, calls, active: HashSet::new(), active_depth: 0, reached: HashSet::new(),
            #[cfg(feature = "internal-checker")] mixed_reached: None,
        had_obligations: false, observer, symbolic_module: 0,
    };
    #[cfg(feature = "internal-checker")]
    if let Some(tap) = failures.as_ref().and_then(|effects| effects.mixed_startup.as_ref()) {
        actual.mixed_reached = Some(tap.captured.clone());
    }
    #[cfg(feature = "internal-checker")]
    let mut completed_passive = HashMap::new();
    #[cfg(feature = "internal-checker")]
    let mut completed_arrays = HashMap::new();
    #[cfg(feature = "internal-checker")]
    let mut projected_storage = super::checker_flow::ProjectedStorage::default();
    let outcome = walk_package_initialization::<COLLECT, PRIVATE_NESTED_SCALAR>(
        project, calls, &ordinals, &mut visits, &mut actual, root, &mut failures,
        #[cfg(feature = "internal-checker")] &mut completed_passive,
        #[cfg(feature = "internal-checker")] &mut completed_arrays,
        #[cfg(feature = "internal-checker")] &mut projected_storage);
    #[cfg(feature = "internal-checker")]
    if outcome.is_ok() {
        if let Some(tap) = failures.as_ref().and_then(|effects| effects.mixed_startup.as_ref()) {
            if actual.mixed_reached.as_ref() != Some(&tap.captured) {
                return (Err(ProjectCheck::Unsupported), actual.observer);
            }
        }
    }
    (outcome.map(|_| CheckedInitialization { visits, reached: actual.reached, ordinals, had_obligations: actual.had_obligations,
        #[cfg(feature = "internal-checker")] projected_storage }),
        actual.observer)
}

#[cfg(feature = "internal-checker")]
type CompletedPassiveStorage<'a> = HashMap<usize, HashMap<ByteSpan, InitializerValue<'a>>>;

fn walk_package_initialization<'a, const COLLECT: bool, const PRIVATE_NESTED_SCALAR: bool>(
    project: &'a ScalarProject,
    calls: &'a ProjectCallSiteResults,
    ordinals: &HashMap<&'a SourceIdentity, usize>,
    visits: &mut [InitializationVisit],
    actual: &mut CheckedCalls<'a, impl ActualIntegerObserver>,
    source: &SourceIdentity,
    failures: &mut Option<&mut OrderedFailures>,
    #[cfg(feature = "internal-checker")] completed_passive: &mut CompletedPassiveStorage<'a>,
    #[cfg(feature = "internal-checker")] completed_arrays: &mut CompletedPassiveStorage<'a>,
    #[cfg(feature = "internal-checker")] projected_storage: &mut super::checker_flow::ProjectedStorage,
) -> Result<StartupLane, ProjectCheck> {
    let ordinal = *ordinals.get(source).ok_or(ProjectCheck::RootSourceOutsideInitOrder)?;
    match visits[ordinal] {
        InitializationVisit::Completed => return Ok(StartupLane::Feasible),
        InitializationVisit::Started => return Err(ProjectCheck::Unsupported),
        InitializationVisit::Unseen => visits[ordinal] = InitializationVisit::Started,
    }
    let module = &project.modules[ordinal];
    let region = calls.initialization_region(ordinal).ok_or(ProjectCheck::MissingRootOccurrences)?;
    let ModuleInitializationDetail::Occurrences(topology) = &region.detail else {
        return Err(ProjectCheck::MissingRootOccurrences);
    };
    let structure = &topology.structure;
    let mut checked_items = structure.blocks[structure.root.0].items.iter();
    let mut storage = HashMap::new();
    // A copy is only valid in the same contiguous passive initializer
    // segment. Never defer analysis of possibly effectful intervening items.
    #[cfg(feature = "internal-checker")]
    let mut passive_generation = 0usize;
    #[cfg(feature = "internal-checker")]
    let mut completed_qualifiers = HashMap::new();
    for (generation, step) in region.steps.iter().enumerate() {
        #[cfg(not(feature = "internal-checker"))]
        let _ = generation;
        if let ModuleInitializationStepKind::NamespaceDispatch { target, binding_span, .. } = &step.kind {
            #[cfg(feature = "internal-checker")]
            { passive_generation = generation + 1; }
            let NamespaceTarget::Bound(target) = target else {
                return Err(ProjectCheck::Unsupported);
            };
            #[cfg(feature = "internal-checker")]
            if let Some(search) = failures.as_deref_mut().and_then(|effects| effects.startup_search.as_ref()) {
                if source.project != target.project || source.package != target.package { return Err(ProjectCheck::Unsupported); }
                search.borrow_mut().append(failure_search::PathStep::Namespace {
                    binding: wosy_syntax::SourceSpan::new(source.clone(), *binding_span), target: target.clone(),
                }).ok_or(ProjectCheck::Unsupported)?;
            }
            #[cfg(not(feature = "internal-checker"))]
            let _ = binding_span;
            if walk_package_initialization::<COLLECT, PRIVATE_NESTED_SCALAR>(
                project, calls, ordinals, visits, actual, target, failures,
                #[cfg(feature = "internal-checker")] completed_passive,
                #[cfg(feature = "internal-checker")] completed_arrays,
                #[cfg(feature = "internal-checker")] projected_storage,
            )? == StartupLane::Empty {
                return Ok(StartupLane::Empty);
            }
            #[cfg(feature = "internal-checker")]
            completed_qualifiers.insert(*binding_span,target);
            continue;
        }
        let checked_item = checked_items.next().filter(|item| item.position == step.item)
            .ok_or(ProjectCheck::MissingRootOccurrences)?;
        if let (ModuleInitializationStepKind::BindingInitialization,
            Some(ScalarItem::Binding(binding)), BlockItemKind::Binding(checked)) =
            (&step.kind, module.items.get(step.item), &checked_item.kind)
        {
            let BindingInitialization::Outputs(outputs) = &checked.initialization
                else { return Err(ProjectCheck::Unsupported); };
            #[cfg(feature = "internal-checker")]
            let passive_literal = COLLECT && !binding.is_allocation
                && matches!(checked.receivers(), [receiver]
                    if receiver.contextual_storage.is_none()
                        && passive_startup_initializer(&receiver.ty, &binding.value));
            #[cfg(feature = "internal-checker")]
            let passive_receiver = match checked.receivers() {
                [receiver] if COLLECT && !binding.is_allocation && outputs.secondary.is_empty()
                    && receiver.contextual_storage.is_none()
                    && topology.occurrences.get(outputs.primary.0).is_some_and(|occurrence|
                        occurrence.span == super::typecheck::expression_span(&binding.value)) => Some(receiver),
                _ => None,
            };
            #[cfg(feature = "internal-checker")]
            let passive_float = passive_receiver.and_then(|receiver|
                ranked_float::Atom::literal(&binding.value, &receiver.ty));
            #[cfg(feature = "internal-checker")]
            let passive_integer = passive_receiver.filter(|receiver| is_integer_type(&receiver.ty)).and_then(|receiver|
                failures.as_deref_mut().and_then(|effects| super::checker_flow::startup_checked_integer_constant(
                    &binding.value, outputs.primary, structure, &receiver.ty, &mut effects.passive_literal_work)));
            #[cfg(feature = "internal-checker")]
            let passive_enum = passive_receiver.and_then(|receiver| {
                let ScalarType::Enum(expected) = &receiver.ty else { return None; };
                prepared_passive_enum_tag(topology, outputs.primary, expected).map(|tag| (expected, tag))
            });
            #[cfg(feature = "internal-checker")]
            let passive_scalar = passive_integer.is_some() || passive_float.is_some() || passive_enum.is_some()
                || passive_receiver.is_some_and(|receiver| matches!((&receiver.ty, &binding.value),
                    (ScalarType::Bool, ScalarExpression::Boolean { .. })
                    | (ScalarType::Char, ScalarExpression::Char { .. })));
            #[cfg(feature = "internal-checker")]
            let passive_import = passive_receiver.and_then(|receiver| {
                if !actual.permits_authored_startup_scalars() || !matches!(&binding.value, ScalarExpression::Member { .. }) { return None; }
                let effects = failures.as_deref_mut()?;
                if !effects.contextual_proofs.entries.is_empty() || effects.mixed_startup.is_some()
                    || effects.startup_search.as_ref().is_some_and(|trace| !trace.borrow().proof_free_scalar_initializers)
                { return None; }
                let result = completed_nominal_initializer_copy(
                    topology, source, outputs.primary, &receiver.ty, visits, ordinals, project,
                    &completed_qualifiers, completed_passive,
                )?;
                super::checker_flow::charge_call_work(&mut effects.passive_literal_work,1)?;
                Some(result)
            });
            #[cfg(feature = "internal-checker")]
            let passive_return = passive_receiver.and_then(|receiver| {
                if !actual.permits_authored_startup_scalars() || !matches!(receiver.ty, ScalarType::Struct(_))
                    || !matches!(&binding.value, ScalarExpression::Call { receiver: Some(_), arguments, .. } if arguments.is_empty())
                { return None; }
                let effects = failures.as_deref_mut()?;
                if !effects.contextual_proofs.entries.is_empty() || effects.mixed_startup.is_some()
                    || effects.startup_search.as_ref().is_some_and(|trace| !trace.borrow().proof_free_scalar_initializers)
                { return None; }
                actual.passive_qualified_nominal_return(
                    topology, source, outputs.primary, &receiver.ty, visits, ordinals, completed_passive,
                    &mut effects.passive_literal_work,
                )
            });
            #[cfg(feature = "internal-checker")]
            if !passive_literal && !passive_scalar && passive_return.is_none() && passive_import.is_none() {
                passive_generation = generation + 1;
                // Namespace completion alone does not guarantee a value is
                // unchanged across a later executable initializer.
                completed_passive.clear();
                completed_arrays.clear();
                projected_storage.forget();
            }
            #[cfg(feature = "internal-checker")]
            if startup_trace_requested(failures) && !passive_literal && passive_return.is_none() && passive_import.is_none()
                && passive_float.is_none() && passive_integer.is_none() && passive_enum.is_none()
                && !matches!(binding.value, ScalarExpression::Boolean { .. } | ScalarExpression::Char { .. })
                && !(matches!(binding.value, ScalarExpression::If { .. }) && startup_ordinary_scalars_requested(failures))
                && !(matches!(binding.value, ScalarExpression::Call { .. }) && failures.as_ref()
                    .and_then(|effects| effects.startup_search.as_ref())
                    .is_some_and(|search| {
                        let search = search.borrow();
                        search.has_bare_startup || search.ranked_target.is_some() || search.proof_free_scalar_initializers
                            || (search.owns_initialization(source) && search.required_sites.get(&outputs.primary)
                                .is_some_and(|(_, role)| *role == failure_search::StartupProofRole::Cited))
                            || (COLLECT && actual.can_initialize_fixed_arrays()
                                && search.has_aggregate_site(source, outputs.primary))
                    }))
                && !(COLLECT && actual.can_initialize_fixed_arrays()
                    && matches!(binding.value, ScalarExpression::IndexedRead { place: super::ScalarPlace::Index { .. }, .. }))
                && concrete_integer_literal(&binding.value).is_none()
            {
                return Err(ProjectCheck::Unsupported);
            }
            #[cfg(feature = "internal-checker")]
            if let [first, second] = checked.receivers() {
                if !COLLECT || !matches!(binding.value, ScalarExpression::Call { .. })
                    || !matches!(outputs.secondary.as_slice(), [super::control::BindingOutput::ProjectPrimary { output: 1 }])
                    || first.contextual_storage.is_some() || second.contextual_storage.is_some()
                { return Err(ProjectCheck::Unsupported); }
                let ActualCallResult::ResultPair(pair) = run_scalar_initializer_call(
                    topology, actual, source, outputs.primary, &first.ty, Some(checked.receivers()), &storage, failures, visits, false, None,
                )? else { return Err(ProjectCheck::Unsupported); };
                for (receiver, value) in [first, second].into_iter().zip(pair) {
                    let typed = initialized_proof_atom(&receiver.ty, value).ok_or(ProjectCheck::Unsupported)?;
                    storage.insert(receiver.span, typed);
                }
                continue;
            }
            let [receiver] = checked.receivers() else { return Err(ProjectCheck::Unsupported); };
            #[cfg(not(feature = "internal-checker"))]
            let passive_literal = false;
            if !outputs.secondary.is_empty() || (!passive_literal && structure.checked_types.expressions.get(&outputs.primary).is_none_or(|actual| {
                if matches!(&receiver.ty, ScalarType::Array { .. }) {
                    !super::scalar_type_equal(actual, &receiver.ty)
                } else {
                    actual != &receiver.ty
                }
            })) {
                return Err(ProjectCheck::Unsupported);
            }
            let value = match (&receiver.ty, &binding.value) {
                (ScalarType::Bool, ScalarExpression::Boolean { value, .. }) => InitializerValue::Boolean(*value),
                #[cfg(feature = "internal-checker")]
                (ScalarType::Enum(_), _) if passive_enum.is_some() => {
                    let effects = failures.as_deref_mut().ok_or(ProjectCheck::Unsupported)?;
                    super::checker_flow::charge_call_work(&mut effects.passive_literal_work, 1)
                        .ok_or(ProjectCheck::Unsupported)?;
                    let (enumeration, tag) = passive_enum.ok_or(ProjectCheck::Unsupported)?;
                    InitializerValue::PassiveEnum { _enumeration: enumeration, _tag: tag }
                },
                #[cfg(feature = "internal-checker")]
                (ScalarType::F32 | ScalarType::F64, _) if passive_float.is_some() => {
                    let effects = failures.as_deref_mut().ok_or(ProjectCheck::Unsupported)?;
                    super::checker_flow::charge_call_work(&mut effects.passive_literal_work, 1)
                        .ok_or(ProjectCheck::Unsupported)?;
                    InitializerValue::PassiveFloat { _atom: passive_float.ok_or(ProjectCheck::Unsupported)? }
                },
                #[cfg(feature = "internal-checker")]
                (ty, _) if passive_import.is_some() => {
                    let (value,depth) = passive_import.ok_or(ProjectCheck::Unsupported)?;
                    InitializerValue::PassiveAggregate { ty,generation:passive_generation,depth,value }
                },
                #[cfg(feature = "internal-checker")]
                (ty, _) if passive_return.is_some() => {
                    let (target, value, depth) = passive_return.ok_or(ProjectCheck::Unsupported)?;
                    if let Some(trace) = failures.as_deref().and_then(|effects| effects.startup_search.as_ref()) {
                        let span = topology.occurrences.get(outputs.primary.0).ok_or(ProjectCheck::MissingRootOccurrences)?.span;
                        let site = wosy_syntax::SourceSpan::new(source.clone(), span);
                        let mut trace = trace.borrow_mut();
                        trace.append(failure_search::PathStep::Call(site.clone())).ok_or(ProjectCheck::Unsupported)?;
                        trace.append(failure_search::PathStep::Return(site)).ok_or(ProjectCheck::Unsupported)?;
                    }
                    actual.note_reached(target);
                    InitializerValue::PassiveAggregate { ty, generation: passive_generation, depth, value }
                },
                #[cfg(feature = "internal-checker")]
                (ty, expression) if passive_literal => {
                    let effects = failures.as_deref_mut().ok_or(ProjectCheck::Unsupported)?;
                    let mut preparation = PassiveLiteralPreparation {
                        occurrences: &topology.occurrences, structure: &topology.structure,
                        project, ordinals, work: &mut effects.passive_literal_work, maximum_depth: 0,
                        copies: Some(PassiveCopySource::Current { topology, storage: &storage, generation: passive_generation }),
                    };
                    let value = preparation.node(outputs.primary, ty, expression, 0).ok_or(ProjectCheck::Unsupported)?;
                    let value = match value {
                        PassiveLiteral::Copy(value) => value,
                        literal => std::rc::Rc::new(literal),
                    };
                    InitializerValue::PassiveAggregate {
                        ty, generation: passive_generation, depth: preparation.maximum_depth, value,
                    }
                }
                #[cfg(feature = "internal-checker")]
                (ScalarType::Char, ScalarExpression::Char { value, .. })
                    if COLLECT && actual.observer.enables_character_initializers() =>
                    InitializerValue::Character(BigInt::from(u32::from(*value))),
                #[cfg(feature = "internal-checker")]
                (ty, expression @ ScalarExpression::If { .. }) if (*ty == ScalarType::Bool || is_integer_type(ty))
                    && COLLECT && actual.permits_authored_startup_scalars() =>
                {
                    let Some(value) = selected_startup_scalar(
                        topology, actual, source, expression, outputs.primary, ty, &storage, failures, visits,
                    )? else { return Ok(StartupLane::Empty); };
                    value
                }
                #[cfg(feature = "internal-checker")]
                (ScalarType::Bool, expression) if !matches!(expression, ScalarExpression::Call { .. })
                    && COLLECT && actual.permits_authored_startup_scalars() =>
                {
                    let value = topology.initializer_predicates.get(&outputs.primary)
                        .and_then(|predicate| evaluate_initializer_predicate(predicate, &storage, true))
                        .ok_or(ProjectCheck::Unsupported)?;
                    InitializerValue::Boolean(value)
                }
                #[cfg(feature = "internal-checker")]
                (ty @ ScalarType::Array { .. }, ScalarExpression::Call { .. })
                    if COLLECT && actual.can_initialize_fixed_arrays() =>
                {
                    let trace = failures.as_deref().and_then(|effects| effects.startup_search.clone());
                    if let Some(trace) = &trace {
                        if !trace.borrow().has_aggregate_site(source, outputs.primary) { return Err(ProjectCheck::Unsupported); }
                        let span = topology.occurrences.get(outputs.primary.0).ok_or(ProjectCheck::MissingRootOccurrences)?.span;
                        trace.borrow_mut().append(failure_search::PathStep::Call(
                            wosy_syntax::SourceSpan::new(source.clone(), span))).ok_or(ProjectCheck::Unsupported)?;
                    }
                    let ActualCallResult::FixedArray(cells) = run_scalar_initializer_call(
                        topology, actual, source, outputs.primary, ty, None, &storage, failures, visits, false, None,
                    )? else { return Err(ProjectCheck::Unsupported); };
                    if let Some(trace) = &trace {
                        let mut trace = trace.borrow_mut();
                        let (_, role) = trace.required_sites.remove(&outputs.primary).ok_or(ProjectCheck::Unsupported)?;
                        if role != failure_search::StartupProofRole::Aggregate { return Err(ProjectCheck::Unsupported); }
                        let span = topology.occurrences.get(outputs.primary.0).ok_or(ProjectCheck::MissingRootOccurrences)?.span;
                        trace.append(failure_search::PathStep::Return(
                            wosy_syntax::SourceSpan::new(source.clone(), span))).ok_or(ProjectCheck::Unsupported)?;
                        if trace.remaining() == 0 && trace.cannot_continue() {
                            return Err(ProjectCheck::StartupAuthoredLimitReached);
                        }
                    }
                    InitializerValue::FixedArray { ty, cells }
                }
                #[cfg(feature = "internal-checker")]
                (ty, ScalarExpression::IndexedRead { place: super::ScalarPlace::Index { index, .. }, .. })
                    if COLLECT && is_integer_type(ty) && actual.can_initialize_fixed_arrays() =>
                {
                    let value = initialized_fixed_array_cell(topology, &storage, outputs.primary, index, ty)
                        .ok_or(ProjectCheck::Unsupported)?;
                    InitializerValue::Integer { ty, value: Cow::Owned(value.clone()) }
                }
                #[cfg(feature = "internal-checker")]
                (ty, _) if passive_integer.is_some() =>
                    InitializerValue::Integer { ty, value: passive_integer.ok_or(ProjectCheck::Unsupported)? },
                (ty, expression) if is_integer_type(ty)
                    || (COLLECT && matches!(ty, ScalarType::Bool | ScalarType::Char)
                        && matches!(expression, ScalarExpression::Call { .. })) =>
                {
                    #[cfg(feature = "internal-checker")]
                    let wide = if COLLECT && is_integer_type(ty) && receiver.contextual_storage.is_none()
                        && matches!(expression, ScalarExpression::Call { .. })
                        && !failures.as_ref().and_then(|effects| effects.startup_search.as_ref())
                            .is_some_and(|search| search.borrow().wide_rank_recipe.is_some()) {
                        let qualified = matches!(expression, ScalarExpression::Call { receiver: Some(_), .. });
                        actual.wide_ranked_startup_initializer(topology, source, outputs.primary, ty, &storage, qualified, visits)?
                    } else { None };
                    #[cfg(not(feature = "internal-checker"))]
                    let wide = None;
                    let value = if let Some(value) = wide {
                        Cow::Owned(value)
                    } else if let Some(value) = concrete_integer_literal(expression) {
                        value
                    } else if matches!(expression, ScalarExpression::Call { .. }) {
                        match run_scalar_initializer_call(
                            topology, actual, source, outputs.primary, ty, None, &storage, failures, visits, receiver.contextual_storage.is_none(), Some(expression),
                        )? {
                            ActualCallResult::Integer(value) => Cow::Owned(value),
                            #[cfg(feature = "internal-checker")]
                            ActualCallResult::EmptyScalar if COLLECT => return Ok(StartupLane::Empty),
                            _ => return Err(ProjectCheck::Unsupported),
                        }
                    } else {
                        return Err(ProjectCheck::Unsupported);
                    };
                    match ty {
                        #[cfg(feature = "internal-checker")]
                        ScalarType::Bool => {
                            let lane = super::checker_flow::bool_result_lane(&value).ok_or(ProjectCheck::Unsupported)?;
                            InitializerValue::Boolean(lane == 1)
                        }
                        #[cfg(feature = "internal-checker")]
                        ScalarType::Char => InitializerValue::Character(value.into_owned()),
                        _ => InitializerValue::Integer { ty, value },
                    }
                }
                _ => return Err(ProjectCheck::Unsupported),
            };
            #[cfg(feature = "internal-checker")]
            if COLLECT {
                let declaration = wosy_syntax::SourceSpan::new(source.clone(), receiver.span);
                match &value {
                    InitializerValue::Integer { ty, value } => projected_storage.observe_scalar(declaration, ty, value),
                    InitializerValue::Boolean(value) => projected_storage.observe_boolean(declaration, *value),
                    InitializerValue::PassiveFloat { _atom: ranked_float::Atom::Single(bits) } => projected_storage.observe_f32(declaration, *bits),
                    InitializerValue::PassiveEnum { _enumeration:id,_tag:tag } => projected_storage.observe_enum(declaration,(*id).clone(),*tag),
                    InitializerValue::FixedArray { ty, cells } => projected_storage.observe_array(declaration, ty, cells.iter()),
                    InitializerValue::PassiveAggregate { ty, value, .. } => {
                        let mut leaf = *ty;
                        while let ScalarType::Array {element,..} = leaf { leaf = element; }
                        let nominal = if let ScalarType::Struct(id) = leaf { Some(id) } else { None };
                        if nominal.is_some_and(|id| &id.source == source && module.structs.get(id.index)
                            .is_some_and(|structure| &structure.id == id && structure.copy_policy == super::CopyPolicy::Copy)) {
                            projected_storage.observe_aggregate(declaration.clone());
                        }
                        if let Some(cells) = flat_passive_integer_array(value, ty) {
                            projected_storage.observe_array(declaration, ty, cells.into_iter());
                        } else if observed_nested_array_leaf(ty).is_some() {
                            projected_storage.observe_aggregate(declaration);
                        }
                    }
                    _ => {}
                }
            }
            storage.insert(receiver.span, value);
            continue;
        }
        let (ModuleInitializationStepKind::ExecutableItem, BlockItemKind::Evaluation { expression }) =
            (&step.kind, &checked_item.kind) else {
                return Err(ProjectCheck::Unsupported);
            };
        #[cfg(feature = "internal-checker")]
        {
            passive_generation = generation + 1;
            completed_passive.clear();
            if COLLECT && try_observed_projected_storage_call(actual, topology, source, *expression,
                visits, projected_storage, &storage, completed_arrays, ordinals, failures)? {
                projected_storage.settle(|declaration, index, observed| {
                    if &declaration.source != source {
                        // A completed provider will not resume its local
                        // initializer lane. The shared projected storage
                        // settles its cells; never alter a still-active owner.
                        let provider = *ordinals.get(&declaration.source)?;
                        return (visits.get(provider) == Some(&InitializationVisit::Completed)).then_some(());
                    }
                    let value = storage.get_mut(&declaration.range)?;
                    match (index, value) {
                        (None, InitializerValue::Integer { value, .. }) => *value.to_mut() = observed.clone(),
                        (None, InitializerValue::Boolean(value)) => *value = match super::checker_flow::bool_result_lane(observed)? {
                            0 => false, 1 => true, _ => return None,
                        },
                        (Some(index), InitializerValue::FixedArray { cells, .. }) => *cells.get_mut(index)? = observed.clone(),
                        (Some(index), InitializerValue::PatchedIntegerArray { updates, .. }) => {
                            updates.insert(index, observed.clone());
                        }
                        (Some(index), value @ InitializerValue::PassiveAggregate { .. }) => {
                            let InitializerValue::PassiveAggregate { ty, value: original, .. } = value else { return None; };
                            *value = InitializerValue::PatchedIntegerArray {
                                ty, original: Rc::clone(original), updates: HashMap::from([(index, observed.clone())]),
                            };
                        }
                        _ => return None,
                    }
                    Some(())
                }).ok_or(ProjectCheck::Unsupported)?;
                continue;
            }
            if !topology.structure.checker_directives.contains_key(expression) {
                completed_arrays.clear();
                projected_storage.forget();
            }
        }
        if check_initializer_expression::<COLLECT, PRIVATE_NESTED_SCALAR>(topology, actual, source, &storage, *expression, 0, failures, visits)? == StartupLane::Empty {
            return Ok(StartupLane::Empty);
        }
    }
    visits[ordinal] = InitializationVisit::Completed;
    #[cfg(feature = "internal-checker")]
    if COLLECT {
        // Nominal copy still observes only the last passive generation.
        // Completed array backing outlives known observed calls, but its
        // exact capability and overlay live only in ProjectedStorage.
        storage.retain(|range,value| match value {
            InitializerValue::PassiveAggregate { ty: ScalarType::Struct(_),generation,.. } =>
                *generation == passive_generation,
            InitializerValue::PassiveAggregate { ty,generation,depth,value }
                if matches!(ty, ScalarType::Array { .. }) && projected_storage.has_observed_aggregate(
                    &wosy_syntax::SourceSpan::new(source.clone(),*range)) => {
                completed_arrays.entry(ordinal).or_default().insert(*range,InitializerValue::PassiveAggregate {
                    ty,generation:*generation,depth:*depth,value:Rc::clone(value),
                });
                false
            }
            _ => false,
        });
        if !storage.is_empty() { completed_passive.insert(ordinal, storage); }
    }
    Ok(StartupLane::Feasible)
}

#[cfg(all(test, feature = "internal-checker"))]
thread_local! {
    static OBSERVED_MATH_HITS: std::cell::Cell<usize> = const { std::cell::Cell::new(0) };
    static OBSERVED_MATH_MISSES: std::cell::Cell<usize> = const { std::cell::Cell::new(0) };
}

#[cfg(feature = "internal-checker")]
struct PreparedScalarGetter<'a> {
    declaration: &'a wosy_syntax::SourceSpan,
    ty: &'a ScalarType,
    negate: bool,
}

#[cfg(feature = "internal-checker")]
impl<'a> PreparedScalarGetter<'a> {
    fn from_body(body: &'a FunctionCallSites) -> Option<Self> {
        use super::reference::{OccurrenceEdge, OccurrenceNode, OccurrenceParent, PlainNameIdentity};
        if !body.boundary.parameters.is_empty() || body.contextual_formal().is_some()
            || !body.arms.is_empty() || !body.call_occurrences.is_empty()
            || !body.allocation_length_calls.is_empty() || !body.callable_escapes.is_empty()
        { return None; }
        let [result] = body.boundary.results.as_slice() else { return None; };
        let root = body.structure.root;
        let [block] = body.structure.blocks.as_slice() else { return None; };
        if root.0 != 0 || block.unsafe_context { return None; }
        let [item] = block.items.as_slice() else { return None; };
        let BlockItemKind::FinalOutput(output) = item.kind else { return None; };
        let at = output.expression;
        let ty = &result.ty;
        if output.output != 0 || body.structure.checked_types.expressions.get(&at)? != ty
            || body.structure.edges.get(&(OccurrenceParent::Block(root),OccurrenceEdge::FinalOutput { item:output.item,output:0 }))
                != Some(&OccurrenceNode::Expression(at))
        { return None; }
        let negated = if *ty == ScalarType::Bool { body.structure.observed_bool_negations.get(&at).copied() }
            else if is_integer_type(ty) { None } else { return None; };
        let place = negated.unwrap_or(at);
        if body.structure.checked_types.expressions.get(&place)? != ty { return None; }
        let PlainNameIdentity::ModuleValue(declaration) = body.prepared_plain_name(place)? else { return None; };
        Some(Self { declaration,ty,negate:negated.is_some() })
    }

    fn evaluate(&self, storage: &super::checker_flow::ProjectedStorage) -> Option<ObservedExactValue> {
        let result = storage.observed_atom(self.declaration)?;
        if &result.ty() != self.ty { return None; }
        if !self.negate { return Some(result); }
        let ObservedExactValue::Boolean(value) = result else { return None; };
        Some(ObservedExactValue::Boolean(!value))
    }
}

#[cfg(feature = "internal-checker")]
fn try_observed_projected_storage_call(
    actual: &mut CheckedCalls<'_, impl ActualIntegerObserver>,
    topology: &ModuleInitializationTopology,
    source: &SourceIdentity,
    site: OccurrenceOrdinal,
    visits: &[InitializationVisit],
    storage: &mut super::checker_flow::ProjectedStorage,
    initialized: &HashMap<ByteSpan, InitializerValue<'_>>,
    completed: &CompletedPassiveStorage<'_>,
    ordinals: &HashMap<&SourceIdentity,usize>,
    failures: &mut Option<&mut OrderedFailures>,
) -> Result<bool, ProjectCheck> {
    let Some(ModuleInitializationCallTarget::Direct { declaration, concrete: ConcreteCallSelection::Declaration }) =
        topology.call_targets.get(&site) else { return Ok(false); };
    let Some(signature) = topology.checked_call_signatures.get(&site) else { return Ok(false); };
    if &declaration.source != source || !signature.parameters.is_empty()
        || !matches!(signature.outputs.outputs.as_slice(), [out] if out.ty == ScalarType::Unit) {
        return Ok(false);
    }
    let (target, _, _, _) = actual.validated_direct_body(&topology.structure, site, source, declaration.range)?;
    let body_of = |(module, item)| actual.calls.function_body(module, item, None);
    let root_body = body_of(target).ok_or(ProjectCheck::MissingRootOccurrences)?;
    let potential_float_prefix = root_body.structure.blocks.get(root_body.structure.root.0)
        .is_some_and(|root| root.items.iter().map_while(|item| match &item.kind {
            BlockItemKind::Binding(binding) => Some(binding),
            _ => None,
        }).any(|binding| binding.receivers().iter().any(|receiver| receiver.ty == ScalarType::F32)));
    let plan = potential_float_prefix.then(|| ordered_float_prefix::plan_prefix::<false>(actual.project, actual.calls, target)).flatten()
        .filter(|plan| plan.bindings.iter().any(|binding| binding.ty == ScalarType::F32));
    let mut prefix_reads = HashSet::new();
    let mut prefix_calls = HashSet::new();
    if let Some(plan) = &plan {
        for effect in &plan.effects {
            if effect.owner != target { continue; }
            match &effect.operation {
                ordered_float_prefix::Effect::Read { storage_site, declaration, projected, .. } => {
                    use super::reference::ModuleStorageRole;
                    let role = if *projected { ModuleStorageRole::Project } else { ModuleStorageRole::Read };
                    prefix_reads.insert((declaration.clone(), *storage_site, role));
                }
                ordered_float_prefix::Effect::Call { at, .. } => { prefix_calls.insert(*at); }
                _ => {}
            }
        }
    }
    let trace = failures.as_ref().and_then(|effects| effects.startup_search.clone());
    let permits_capped_requirement = || trace.as_ref().is_some_and(|search| {
        let search=search.borrow();
        search.proof_free_scalar_initializers && search.remaining()==1 && !search.proof_only_continuation()
    });
    // Keep existing authoring/reporting routes for this first storage cohort:
    // only an ordinary state update, not a second source of diagnostics.
    enum Event { Enter(PreparedCallable), Exit(PreparedCallable) }
    let mut todo = vec![Event::Enter(target)];
    let mut visiting = HashSet::new();
    let mut complete = HashSet::new();
    let mut admitted = HashMap::new();
    let mut observed_owners = HashMap::new();
    let mut provider_units = HashSet::new();
    let mut provider_scalars = HashSet::new();
    let mut productive_ranges = HashMap::new();
    let mut authored_units=HashSet::new();
    let mut getters = HashMap::new();
    let mut frontiers = HashMap::new();
    let admit_getter = |node: PreparedCallable, body: &FunctionCallSites, site, child: PreparedCallable, signature: &CheckedCallSignature| {
        if child.0 != node.0 && visits.get(child.0) != Some(&InitializationVisit::Completed) { return None; }
        if authenticate_prepared_direct_edge(actual.project,actual.calls,node.0,body,site,signature) != Some(child) { return None; }
        let getter = PreparedScalarGetter::from_body(body_of(child)?)?;
        (getter.declaration.source == actual.project.modules.get(child.0)?.source).then_some(getter)
    };
    let mut writes_or_reads_storage = false;
    while let Some(event) = todo.pop() {
        match event {
            Event::Enter(node) if !complete.contains(&node) => {
                if !visiting.insert(node) { return Ok(false); }
                let Some(body) = body_of(node) else { return Ok(false); };
                observed_owners.insert(body as *const FunctionCallSites,node.0);
                if node!=target && node.0==target.0 && permits_capped_requirement() && stateful_provider::supports_requirements(body) {
                    let Some(rank)=stateful_provider::advancing_range_plan(body,node) else { return Ok(false); };
                    productive_ranges.insert(node,rank);
                    authored_units.insert(node);
                    provider_units.insert(node);
                    writes_or_reads_storage=true;
                    visiting.remove(&node);
                    complete.insert(node);
                    continue;
                }
                if node.0!=target.0 && visits.get(node.0)==Some(&InitializationVisit::Completed) {
                    let padding=stateful_provider::advancing_range_plan(body,node).filter(|_|
                        stateful_provider::qualified_store_reachable(actual.project,actual.calls,node,visits,true));
                    if stateful_provider::needs_unit_runner(body) || padding.is_some() {
                        if let Some(rank)=padding { productive_ranges.insert(node,rank); }
                        provider_units.insert(node);
                        writes_or_reads_storage = true;
                        visiting.remove(&node);
                        complete.insert(node);
                        continue;
                    }
                }
                if node != target {
                    let recursive_sites = body.structure.checker_direct_targets.iter()
                        .filter_map(|(&site,&child)| (child == node).then_some(site));
                    if let Some((condition, guard_calls)) = super::checker_flow::observed_recursive_guard_frontier(body,recursive_sites) {
                        for site in guard_calls {
                            let Some(signature) = super::checker_flow::observed_getter_signature(body,site) else { return Ok(false); };
                            let Some(&child) = body.structure.checker_direct_targets.get(&site) else { return Ok(false); };
                            let Some(getter) = admit_getter(node,body,site,child,signature) else { return Ok(false); };
                            getters.insert((body as *const FunctionCallSites,site),getter);
                        }
                        if let Some(rank)=stateful_provider::advancing_range_plan(body,node).filter(|_|
                            stateful_provider::qualified_store_reachable(actual.project,actual.calls,node,visits,false)) {
                            productive_ranges.insert(node,rank);
                            provider_units.insert(node);
                            writes_or_reads_storage=true;
                        } else {
                            frontiers.insert(node,condition);
                        }
                        visiting.remove(&node);
                        complete.insert(node);
                        continue;
                    }
                }
                let frame = if node == target {
                    super::checker_flow::projected_integer_storage_frame_after_prefix(body,
                        plan.as_ref().map_or(0, |plan| plan.bindings.len()), &prefix_reads, &prefix_calls)
                } else { super::checker_flow::projected_integer_storage_frame_after_prefix(body,0,&HashSet::new(),&HashSet::new()) };
                let Some((has_storage, scalar_calls)) = frame else { return Ok(false); };
                if has_callable_obligations(body) { return Ok(false); }
                writes_or_reads_storage |= has_storage;
                todo.push(Event::Exit(node));
                for (site, &child) in &body.structure.checker_direct_targets {
                    if scalar_calls.contains(site) {
                        if node == target && prefix_calls.contains(site) { continue; }
                        if let Some(signature) = super::checker_flow::observed_getter_signature(body,*site) {
                            let Some(getter) = admit_getter(node,body,*site,child,signature) else { return Ok(false); };
                            getters.insert((body as *const FunctionCallSites,*site),getter);
                        } else if let Some(signature)=body.checked_call_signatures.get(site).filter(|signature|
                            signature.parameters.len()>2 && signature.parameters.iter().all(|ty| *ty==ScalarType::I32)
                                && matches!(signature.outputs.outputs.as_slice(),[out] if out.ty==ScalarType::I32)) {
                            let Some(callee)=body_of(child) else { return Ok(false); };
                            let Some(child_module)=actual.project.modules.get(child.0) else { return Ok(false); };
                            if authenticate_prepared_direct_edge(actual.project,actual.calls,node.0,body,*site,signature)!=Some(child)
                                || !stateful_provider::has_nominal_integer_store(callee,&child_module.source)
                            { return Ok(false); }
                            provider_scalars.insert(child);
                            writes_or_reads_storage=true;
                        }
                        continue;
                    }
                    if child.0 != node.0 && visits.get(child.0) != Some(&InitializationVisit::Completed) {
                        return Ok(false);
                    }
                    let Some(signature) = body.checked_call_signatures.get(site) else { return Ok(false); };
                    if symbolic_history_call_target(actual.project, actual.calls, node.0, node.1, body, *site, signature) != Some(child) {
                        return Ok(false);
                    }
                    admitted.insert((node, *site), child);
                    todo.push(Event::Enter(child));
                }
            }
            Event::Exit(node) => { visiting.remove(&node); complete.insert(node); }
            _ => {}
        }
    }
    if !writes_or_reads_storage { return Ok(false); }
    if visits.get(target.0) != Some(&InitializationVisit::Started) { return Err(ProjectCheck::Unsupported); }
    let work = std::cell::Cell::new(0);
    let observed = std::cell::Cell::new(false);
    if let Some(trace) = &trace {
        let search = trace.borrow();
        if !search.proof_free_scalar_initializers || search.proof_only_continuation() {
            return Ok(false);
        }
    }
    let span = wosy_syntax::SourceSpan::new(source.clone(), topology.occurrences.get(site.0).ok_or(ProjectCheck::MissingRootOccurrences)?.span);
    let read_field = |storage: &super::checker_flow::ProjectedStorage, cell: &super::checker_flow::FloatFieldCell| {
        if &cell.declaration.source != source || !storage.has_observed_aggregate(&cell.declaration) { return None; }
        if let Some(value) = storage.observed_field(cell) { return Some(value); }
        let field = super::ScalarStructFieldId { structure: cell.structure.clone(), index: cell.field };
        let ObservedExactValue::F32(value) = observed_nominal_f32_field(initialized.get(&cell.declaration.range)?, cell.index, &field)? else { return None; };
        Some(value)
    };
    let observed_array_backing = |at: &wosy_syntax::SourceSpan| {
        if &at.source == source { return initialized.get(&at.range); }
        let owner = *ordinals.get(&at.source)?;
        completed_namespace_owner(source,&at.source,owner,Some(visits)).then_some(())?;
        completed.get(&owner)?.get(&at.range)
    };
    let read_array_atom = |storage: &super::checker_flow::ProjectedStorage,
        cell: &super::checker_flow::observed_f32_array::Cell, ty:&ScalarType| {
        if *ty==ScalarType::I32 && cell.indices.len()==1 {
            return storage.observed_flat_i32(cell).map(|value|(ObservedExactValue::Integer(ScalarType::I32,value.into()),1));
        }
        if !storage.has_observed_aggregate(&cell.declaration) { return None; }
        let overlay = match ty {
            ScalarType::F32 => storage.observed_f32_array_element(cell).map(ObservedExactValue::F32),
            ScalarType::I32 => storage.observed_i32_array_element(cell).map(|n| ObservedExactValue::Integer(ScalarType::I32,n.into())),
            ScalarType::U8 => storage.observed_u8_array_element(cell).map(|n| ObservedExactValue::Integer(ScalarType::U8,n.into())),
            ScalarType::U16 => storage.observed_u16_array_element(cell).map(|n| ObservedExactValue::Integer(ScalarType::U16,n.into())),
            _ => return None,
        };
        if let Some(atom) = overlay { return Some((atom,1)); }
        observed_passive_array_element(observed_array_backing(&cell.declaration)?, &cell.indices,ty,None)
    };
    let read_integer_field = |storage: &super::checker_flow::ProjectedStorage,
        field: &super::checker_flow::IntegerFieldCell, ty: &ScalarType| {
        if !storage.has_observed_aggregate(&field.cell.declaration) { return None; }
        if let Some(value) = storage.observed_integer_field(field,ty) {
            return Some((ObservedExactValue::Integer(ty.clone(),value.into()),1));
        }
        let field_id=super::ScalarStructFieldId { structure:field.structure.clone(),index:field.field };
        observed_passive_array_element(observed_array_backing(&field.cell.declaration)?,&field.cell.indices,ty,Some(&field_id))
    };
    let read_array = |storage: &super::checker_flow::ProjectedStorage,
        cell: &super::checker_flow::observed_f32_array::Cell| {
        let (ObservedExactValue::F32(value),work)=read_array_atom(storage,cell,&ScalarType::F32)? else { return None; };
        Some((value,work))
    };
    let mut prefix = Vec::new();
    let mut prefix_history = None;
    if let Some(plan) = &plan {
        let mut prefix_work = work.get();
        let (values, evaluated) = ordered_float_prefix::evaluate_observed_prefix(plan, None, HashMap::new(), |declaration, index, field| {
            match (index, field) {
                (None, None) => storage.observed_atom(declaration),
                (index, Some(field)) if &declaration.source == source && storage.has_observed_aggregate(declaration) => {
                    let cell = super::checker_flow::FloatFieldCell { declaration: declaration.clone(), index,
                        structure: field.structure.clone(), field: field.index };
                    read_field(storage, &cell).map(ObservedExactValue::F32)
                }
                _ => None,
            }
        }, trace.is_some(), &mut prefix_work, |owner, at| {
            if owner.0 != target.0 { return None; }
            Some(wosy_syntax::SourceSpan::new(source.clone(), body_of(owner)?.occurrences.get(at.0)?.span))
        }).ok_or(ProjectCheck::Unsupported)?;
        work.set(prefix_work);
        if values.len() != plan.bindings.len() { return Err(ProjectCheck::Unsupported); }
        prefix.extend(plan.bindings.iter().zip(values).map(|(fact, value)| (&fact.slot, &fact.ty, value)));
        prefix_history = evaluated.map(Rc::new);
    }
    // Scoped to this observed activation. Plan leaves never contain runtime
    // storage and are indexed by authenticated target identity and bits.
    let math_plans = RefCell::new(HashMap::new());
    type MathMemo = (Vec<u32>, ObservedExactValue, Option<usize>);
    let latest_math = RefCell::new(HashMap::<PreparedCallable, MathMemo>::new());
    let math_traces = RefCell::new(Vec::<Rc<ordered_float_prefix::ObservedTrace>>::new());
    let math_interned = RefCell::new(HashMap::<Rc<ordered_float_prefix::ObservedTrace>,usize>::new());
    let intern_trace = |trace: ordered_float_prefix::ObservedTrace| {
        let trace = Rc::new(trace);
        *math_interned.borrow_mut().entry(Rc::clone(&trace)).or_insert_with(|| {
            let mut traces = math_traces.borrow_mut();
            let id = traces.len();
            traces.push(trace);
            id
        })
    };
    let append_observed_history = |search:&mut failure_search::StartUpSearch,history:Vec<super::checker_flow::CallableHistoryStep>| {
        use super::checker_flow::CallableHistoryStep;
        use failure_search::PathStep;
        search.append(PathStep::Call(span.clone()))?;
        if let Some(steps) = &prefix_history { search.append(PathStep::ObservedPrefix(Rc::clone(steps)))?; }
        for step in history {
            let convert = |range| wosy_syntax::SourceSpan::new(source.clone(), range);
            let step = match step {
                CallableHistoryStep::Branch(range, accepted) => PathStep::Branch { condition: convert(range), accepted },
                CallableHistoryStep::Call(range) => PathStep::Call(convert(range)),
                CallableHistoryStep::Return(range) => PathStep::Return(convert(range)),
                CallableHistoryStep::MatchArm(range) => PathStep::MatchArm(convert(range)),
                CallableHistoryStep::ObservedFloatTrace(id) => PathStep::ObservedPrefix(Rc::clone(math_traces.borrow().get(id)?)),
                CallableHistoryStep::ProviderBranch(owner, range, accepted) => PathStep::Branch {
                    condition: wosy_syntax::SourceSpan::new(actual.project.modules.get(owner)?.source.clone(), range), accepted,
                },
                CallableHistoryStep::ProviderCall(owner, range) => PathStep::Call(
                    wosy_syntax::SourceSpan::new(actual.project.modules.get(owner)?.source.clone(), range)),
                CallableHistoryStep::ProviderReturn(owner, range) => PathStep::Return(
                    wosy_syntax::SourceSpan::new(actual.project.modules.get(owner)?.source.clone(), range)),
                CallableHistoryStep::ProviderMatchArm(owner, range) => PathStep::MatchArm(
                    wosy_syntax::SourceSpan::new(actual.project.modules.get(owner)?.source.clone(), range)),
            };
            search.append(step)?;
        }
        Some(())
    };
    let provider_dispatch = RefCell::new(stateful_provider::Dispatch::default());
    let selected_requirement=std::cell::Cell::new(false);
    let reached_requirement=std::cell::Cell::new(false);
    let collect=RefCell::new(failures);
    let provider_call = |body:&FunctionCallSites, site, args, storage:&mut super::checker_flow::ProjectedStorage,
        history:Option<&dyn Fn()-> Option<Vec<super::checker_flow::CallableHistoryStep>>>| {
        let signature=body.checked_call_signatures.get(&site)?;
        let caller=*observed_owners.get(&(body as *const FunctionCallSites))?;
        let child=authenticate_prepared_direct_edge(actual.project,actual.calls,caller,body,site,signature)?;
        // Do not observe an ambient owner. The real namespace provider has
        // finished initialization and shares this exact storage row.
        if child.0==caller {
            if !(productive_ranges.contains_key(&child)||provider_scalars.contains(&child))
                || visits.get(child.0)!=Some(&InitializationVisit::Started) { return None; }
        } else if !completed_namespace_owner(&actual.project.modules.get(caller)?.source,
            &actual.project.modules.get(child.0)?.source,child.0,Some(visits)) { return None; }
        let allow_failure=authored_units.contains(&child) && history.is_some() && permits_capped_requirement();
        let (value,result,cost,failure)=stateful_provider::run(actual.project,actual.calls,child,args,storage,trace.is_some(),
            &mut provider_dispatch.borrow_mut(),&productive_ranges,visits,allow_failure,&reached_requirement,&read_array_atom,&read_integer_field)?;
        if let Some(failure)=failure {
            use failure_search::{Admission,PathStep};
            if !allow_failure || failure.target.0!=target.0 { return None; }
            let body=body_of(failure.target)?;
            let directive=body.structure.checker_directives.get(&failure.site)?;
            let at=body.occurrences.get(failure.site.0)?.span;
            let mut search=trace.as_ref()?.borrow_mut();
            append_observed_history(&mut search,history?()?)?;
            search.append(PathStep::ObservedPrefix(Rc::new(failure.history)))?;
            if !matches!(search.admit(wosy_syntax::SourceSpan::new(source.clone(),at))?,Admission::SelectedAndStop)
                || !search.cannot_continue() { return None; }
            collect.borrow_mut().as_deref_mut()?.push(source,directive,at,IntegerInputs::closed(),Vec::new(),Vec::new());
            selected_requirement.set(true);
            return None;
        }
        Some((value,result.map(&intern_trace),cost))
    };
    let math_call = |body: &FunctionCallSites, site, args: Vec<super::checker_flow::projected_f32::ExactF32>| {
        use std::collections::hash_map::Entry;
        let signature = body.checked_call_signatures.get(&site)?;
        let caller = *observed_owners.get(&(body as *const FunctionCallSites))?;
        let [out] = signature.outputs.outputs.as_slice() else { return None; };
        if !(out.ty == ScalarType::F32 || out.ty == ScalarType::Bool || is_integer_type(&out.ty))
            || signature.parameters.is_empty() || !signature.parameters.iter().all(|ty| *ty == ScalarType::F32) { return None; }
        let child = authenticate_prepared_direct_edge(actual.project,actual.calls,caller,body,site,signature)?;
        if child.0 != caller && visits.get(child.0) != Some(&InitializationVisit::Completed) { return None; }
        let lookup_work = args.len().saturating_add(1);
        if let Some((_, value, trace)) = latest_math.borrow().get(&child).filter(|(known, _, _)|
            known.iter().copied().eq(args.iter().map(|value| value.0))) {
            #[cfg(test)] OBSERVED_MATH_HITS.with(|count| count.set(count.get() + 1));
            return Some((value.clone(), *trace, lookup_work));
        }
        #[cfg(test)] OBSERVED_MATH_MISSES.with(|count| count.set(count.get() + 1));
        let bits = args.iter().map(|arg| arg.0).collect();
        let mut plans = math_plans.borrow_mut();
        let (plan, root): &mut (ordered_float_prefix::PrefixCertificate, ordered_float_prefix::FunctionEffects) = match plans.entry(child) {
            Entry::Occupied(plan) => plan.into_mut(),
            Entry::Vacant(slot) => slot.insert(ordered_float_prefix::plan_observed_math_call(actual.project, actual.calls, child)?),
        };
        if args.len() != root.formals.len() || !root.formals.iter().all(|(_, ty)| *ty == ScalarType::F32) { return None; }
        let values = root.formals.iter().zip(args).map(|((id,_),value)| (id.clone(), ObservedExactValue::F32(value))).collect();
        let mut work = lookup_work;
        let (returned, nested) = ordered_float_prefix::evaluate_observed_prefix(plan, Some(root), values,
            |_,_,_| None, trace.is_some(), &mut work, |owner,at| {
                if owner.0 != child.0 { return None; }
                let owner_source = &actual.project.modules.get(owner.0)?.source;
                Some(wosy_syntax::SourceSpan::new(owner_source.clone(), body_of(owner)?.occurrences.get(at.0)?.span))
            })?;
        let [value] = returned.as_slice() else { return None; };
        if value.ty() != out.ty { return None; }
        let trace = nested.map(&intern_trace);
        latest_math.borrow_mut().insert(child, (bits, value.clone(), trace));
        Some((value.clone(),trace,work))
    };
    let mut record_return = |history:Vec<super::checker_flow::CallableHistoryStep>| {
        use failure_search::PathStep;
        let Some(trace)=&trace else { return Some(()); };
        let mut search=trace.borrow_mut();
        append_observed_history(&mut search,history)?;
        search.append(PathStep::Return(span.clone()))
    };
    let scalar_getter = |body: &FunctionCallSites, site, storage: &super::checker_flow::ProjectedStorage| {
        getters.get(&(body as *const FunctionCallSites,site))?.evaluate(storage)
    };
    let mut current = Rc::new(std::mem::take(storage));
    let result = super::checker_flow::drive_finite_history(target, &work, &observed, Some((&mut current, &mut record_return)), &prefix, Some(&read_field), Some(&read_array), Some(&math_call), Some(&scalar_getter), Some(&provider_call), Some(&provider_units), Some(&frontiers),
        body_of, |parent, _, site, _| admitted.get(&(parent, site)).copied(), |_, _, _| None);
    if selected_requirement.get() { return Err(ProjectCheck::StartupAuthoredLimitReached); }
    if !matches!(result, Some(super::checker_flow::CallableHistoryCompletion::Exhausted(false))) {
        return Err(ProjectCheck::Unsupported);
    }
    *storage = Rc::unwrap_or_clone(current);
    actual.had_obligations |= reached_requirement.get();
    Ok(true)
}

fn check_initializer_expression<const COLLECT: bool, const PRIVATE_NESTED_SCALAR: bool>(
    topology: &ModuleInitializationTopology,
    actual: &mut CheckedCalls<'_, impl ActualIntegerObserver>,
    source: &SourceIdentity,
    storage: &HashMap<ByteSpan, InitializerValue<'_>>,
    expression: OccurrenceOrdinal,
    depth: usize,
    failures: &mut Option<&mut OrderedFailures>,
    visits: &[InitializationVisit],
) -> Result<StartupLane, ProjectCheck> {
    let structure = &topology.structure;
    #[cfg(feature = "internal-checker")]
    let allow_authored_startup = COLLECT && actual.permits_authored_startup_scalars();
    #[cfg(not(feature = "internal-checker"))]
    let allow_authored_startup = false;
    if let Some(directive) = structure.checker_directives.get(&expression) {
        #[cfg(feature = "internal-checker")]
        let proof_only = failures.as_ref().and_then(|effects| effects.startup_search.as_ref())
            .is_some_and(|trace| trace.borrow().proof_only_continuation());
        let predicate = directive.initializer_predicate.as_ref().ok_or(ProjectCheck::Unsupported)?;
        #[cfg(feature = "internal-checker")]
        if startup_trace_requested(failures) && !startup_trace_atomic(predicate) { return Err(ProjectCheck::Unsupported); }
        #[cfg(feature = "internal-checker")]
        if proof_only && directive.operation == CheckerOperation::Require { return Ok(StartupLane::Feasible); }
        let value = evaluate_initializer_predicate(predicate, storage, allow_authored_startup).ok_or(ProjectCheck::Unsupported)?;
        #[cfg(feature = "internal-checker")]
        if proof_only { return Ok(if value { StartupLane::Feasible } else { StartupLane::Empty }); }
        actual.had_obligations = true;
        if directive.operation.rejects(value, !value) {
            let span = topology.occurrences.get(expression.0).ok_or(ProjectCheck::MissingRootOccurrences)?.span;
            #[cfg(feature = "internal-checker")]
            let startup_values = directive.output.has_module_values;
            #[cfg(feature = "internal-checker")]
            if startup_values && (!COLLECT || !actual.permits_authored_startup_scalars()) {
                return Err(ProjectCheck::Unsupported);
            }
            if !COLLECT {
                return Err(selected_failure(source, directive, span, IntegerInputs::closed(), Vec::new()));
            }
            let effects = failures.as_deref_mut().ok_or(ProjectCheck::Unsupported)?;
            #[cfg(feature = "internal-checker")]
            let capped = if let Some(search) = &mut effects.startup_search {
                use failure_search::Admission::*;
                match search.borrow_mut().admit(wosy_syntax::SourceSpan::new(source.clone(), span)).ok_or(ProjectCheck::Unsupported)? {
                    Duplicate => return Ok(if directive.operation == CheckerOperation::Narrow { StartupLane::Empty } else { StartupLane::Feasible }),
                    Selected => false,
                    SelectedAndStop => true,
                }
            } else { false };
            #[cfg(feature = "internal-checker")]
            if startup_values {
                // Resolve before recording, so a rejected/missing startup
                // value neither clones an unchecked payload nor leaves a
                // partially rendered record in the ordered ledger.
                let witness = ScalarCheckerIntegerWitness { axes: Vec::new(), equal_axes: Vec::new(), state: IntegerInputs::closed() };
                let output = render_authored_output(&directive.output, &witness, Some(storage), &mut effects.startup_output_work)
                    .ok_or(ProjectCheck::Unsupported)?;
                effects.push_with_witness(source, directive, span, witness, Rc::new(output));
            } else {
                effects.push(source, directive, span, IntegerInputs::closed(), Vec::new(), Vec::new());
            }
            #[cfg(not(feature = "internal-checker"))]
            effects.push(source, directive, span, IntegerInputs::closed(), Vec::new(), Vec::new());
            #[cfg(feature = "internal-checker")]
            if capped && effects.startup_search.as_ref().is_some_and(|trace| trace.borrow().cannot_continue()) { return Err(ProjectCheck::StartupAuthoredLimitReached); }
            if directive.operation == CheckerOperation::Narrow {
                return Ok(StartupLane::Empty);
            }
        }
        return Ok(StartupLane::Feasible);
    }
    if let Some(region) = topology.conditionals.get(&expression) {
        let (condition, then_block, else_block) = match region {
            ConditionalRegion::Unit { condition, then_block, .. } => (condition, *then_block, None),
            ConditionalRegion::Value { condition, then_block, else_block, .. }
                if structure.checked_types.expressions.get(&expression) == Some(&ScalarType::Unit) =>
            {
                (condition, *then_block, Some(*else_block))
            }
            _ => return Err(ProjectCheck::Unsupported),
        };
        let Some(value) = reached_startup_condition(
            topology, actual, source, *condition, storage, failures, visits, allow_authored_startup,
        )? else { return Ok(StartupLane::Empty); };
        #[cfg(feature = "internal-checker")]
        if let Some(search) = failures.as_deref_mut().and_then(|effects| effects.startup_search.as_mut()) {
            let site = topology.occurrences.get(condition.0).ok_or(ProjectCheck::MissingRootOccurrences)?;
            search.borrow_mut().branch(wosy_syntax::SourceSpan::new(source.clone(), site.span), value).ok_or(ProjectCheck::Unsupported)?;
        }
        let selected = if value { Some(then_block) } else { else_block };
        if let Some(selected) = selected {
            if depth == MAX_INITIALIZER_BRANCH_DEPTH {
                return Err(ProjectCheck::Unsupported);
            }
            let block = structure.blocks.get(selected.0).ok_or(ProjectCheck::MissingRootOccurrences)?;
            return check_initializer_statements::<COLLECT, PRIVATE_NESTED_SCALAR>(
                topology, actual, source, storage, &block.items, depth + 1, failures, visits,
            );
        }
        return Ok(StartupLane::Feasible);
    }
    #[cfg(feature = "internal-checker")]
    let startup_site = startup_trace_requested(failures).then_some(OrderedInitializerCall { topology, occurrence: expression });
    #[cfg(feature = "internal-checker")]
    let proof_site = actual.initializer_proof_site(topology, source, expression, failures.as_deref());
    let sink;
    let collection = if COLLECT {
        sink = RefCell::new(failures.as_deref_mut().ok_or(ProjectCheck::Unsupported)?);
        Some((source, OrderedCallCollection {
            #[cfg(feature = "internal-checker")]
            outer: (PRIVATE_NESTED_SCALAR && depth == 0).then_some(OrderedInitializerCall { topology, occurrence: expression }),
            #[cfg(feature = "internal-checker")]
            startup_site,
            #[cfg(feature = "internal-checker")]
            startup_site_source: startup_site.map(|_| source),
            ..OrderedCallCollection::new(&sink, Some(visits))
        }))
    } else { None };
    match run_initializer_call(topology, actual, expression, &ScalarType::Unit, None, |argument, ty| {
        if allow_authored_startup {
            initialized_scalar_initializer_argument(topology, storage, argument, ty)
        } else if COLLECT {
            initialized_integer_argument(topology, storage, argument, ty)
        } else {
            None
        }
    }, collection, None, #[cfg(feature = "internal-checker")] proof_site)? {
        ActualCallResult::Unit => Ok(StartupLane::Feasible),
        ActualCallResult::EmptyUnit if COLLECT => Ok(StartupLane::Empty),
        _ => Err(ProjectCheck::Unsupported),
    }
}

fn check_initializer_statements<const COLLECT: bool, const PRIVATE_NESTED_SCALAR: bool>(
    topology: &ModuleInitializationTopology,
    actual: &mut CheckedCalls<'_, impl ActualIntegerObserver>,
    source: &SourceIdentity,
    storage: &HashMap<ByteSpan, InitializerValue<'_>>,
    statements: &[BlockItem],
    depth: usize,
    failures: &mut Option<&mut OrderedFailures>,
    visits: &[InitializationVisit],
) -> Result<StartupLane, ProjectCheck> {
    for item in statements {
        let BlockItemKind::Evaluation { expression } = item.kind else { return Err(ProjectCheck::Unsupported); };
        if check_initializer_expression::<COLLECT, PRIVATE_NESTED_SCALAR>(
            topology, actual, source, storage, expression, depth, failures, visits,
        )? == StartupLane::Empty {
            return Ok(StartupLane::Empty);
        }
    }
    Ok(StartupLane::Feasible)
}

// None is a reached call that pruned the startup lane, not an opaque condition.
#[cfg(feature = "internal-checker")]
fn startup_trace_atomic(predicate: &InitializerPredicate) -> bool {
    matches!(predicate, InitializerPredicate::Boolean(_) | InitializerPredicate::BooleanStorage(_)
        | InitializerPredicate::IntegerComparison { .. })
}

#[cfg(feature = "internal-checker")]
fn startup_trace_requested(failures: &Option<&mut OrderedFailures>) -> bool {
    failures.as_ref().is_some_and(|effects| effects.startup_search.is_some())
}

#[cfg(feature = "internal-checker")]
fn startup_ordinary_scalars_requested(failures: &Option<&mut OrderedFailures>) -> bool {
    failures.as_ref().and_then(|effects| effects.startup_search.as_ref())
        .is_some_and(|trace| trace.borrow().proof_free_scalar_initializers)
}

fn reached_startup_condition(
    topology: &ModuleInitializationTopology,
    #[cfg_attr(not(feature = "internal-checker"), allow(unused_variables))] actual: &mut CheckedCalls<'_, impl ActualIntegerObserver>,
    #[cfg_attr(not(feature = "internal-checker"), allow(unused_variables))] source: &SourceIdentity,
    condition: OccurrenceOrdinal,
    storage: &HashMap<ByteSpan, InitializerValue<'_>>,
    #[cfg_attr(not(feature = "internal-checker"), allow(unused_variables))] failures: &mut Option<&mut OrderedFailures>,
    #[cfg_attr(not(feature = "internal-checker"), allow(unused_variables))] visits: &[InitializationVisit],
    allow_authored_startup: bool,
) -> Result<Option<bool>, ProjectCheck> {
    #[cfg(feature = "internal-checker")]
    if startup_trace_requested(failures) && !topology.initializer_predicates.get(&condition).is_some_and(startup_trace_atomic)
        && !(startup_ordinary_scalars_requested(failures) && !topology.initializer_predicates.contains_key(&condition)
            && topology.structure.checked_types.expressions.get(&condition) == Some(&ScalarType::Bool)
            && topology.call_targets.contains_key(&condition))
    {
        return Err(ProjectCheck::Unsupported);
    }
    if let Some(predicate) = topology.initializer_predicates.get(&condition) {
        return evaluate_initializer_predicate(predicate, storage, allow_authored_startup)
            .map(Some).ok_or(ProjectCheck::Unsupported);
    }
    #[cfg(feature = "internal-checker")]
    if allow_authored_startup && topology.structure.checked_types.expressions.get(&condition) == Some(&ScalarType::Bool)
        && topology.call_targets.contains_key(&condition)
    {
        return match run_scalar_initializer_call(
            topology, actual, source, condition, &ScalarType::Bool, None, storage, failures, visits, false, None,
        )? {
            ActualCallResult::Integer(value) => super::checker_flow::bool_result_lane(&value)
                .map(|lane| Some(lane == 1)).ok_or(ProjectCheck::Unsupported),
            ActualCallResult::EmptyScalar => Ok(None),
            _ => Err(ProjectCheck::Unsupported),
        };
    }
    Err(ProjectCheck::Unsupported)
}

#[cfg(feature = "internal-checker")]
fn selected_startup_scalar<'a>(
    topology: &ModuleInitializationTopology,
    actual: &mut CheckedCalls<'_, impl ActualIntegerObserver>,
    source: &SourceIdentity,
    mut expression: &'a ScalarExpression,
    mut occurrence: OccurrenceOrdinal,
    expected: &'a ScalarType,
    storage: &HashMap<ByteSpan, InitializerValue<'_>>,
    failures: &mut Option<&mut OrderedFailures>,
    visits: &[InitializationVisit],
) -> Result<Option<InitializerValue<'a>>, ProjectCheck> {
    // Follow only the reached scalar arm. Its statement prefix uses the
    // startup Unit evaluator; only its checked final output produces a value.
    let mut remaining = MAX_INITIALIZER_BRANCH_DEPTH;
    while let ScalarExpression::If { then_branch, else_branch, .. } = expression {
        if remaining == 0 { return Err(ProjectCheck::Unsupported); }
        remaining -= 1;
        let Some(ConditionalRegion::Value { condition, then_block, else_block, .. }) =
            topology.conditionals.get(&occurrence) else { return Err(ProjectCheck::Unsupported); };
        if topology.structure.conditional_output_projections.get(&occurrence)
            .is_some_and(|outputs| outputs.types.as_slice() != std::slice::from_ref(expected))
        {
            return Err(ProjectCheck::Unsupported);
        }
        let Some(taken) = reached_startup_condition(topology, actual, source, *condition,
            storage, failures, visits, true)? else { return Ok(None); };
        if let Some(trace) = failures.as_ref().and_then(|effects| effects.startup_search.as_ref()) {
            let site = topology.occurrences.get(condition.0).ok_or(ProjectCheck::MissingRootOccurrences)?;
            trace.borrow_mut().branch(wosy_syntax::SourceSpan::new(source.clone(), site.span), taken)
                .ok_or(ProjectCheck::Unsupported)?;
        }
        let (ast, selected) = if taken { (then_branch, then_block) } else { (else_branch, else_block) };
        let block = topology.structure.blocks.get(selected.0).ok_or(ProjectCheck::MissingRootOccurrences)?;
        let Some((item, statements)) = block.items.split_last() else { return Err(ProjectCheck::Unsupported); };
        let BlockItemKind::FinalOutput(slot) = &item.kind else { return Err(ProjectCheck::Unsupported); };
        if slot.output != 0 || ast.unsafe_context || ast.items.len() != block.items.len() || ast.final_output_values.len() != 1 {
            return Err(ProjectCheck::Unsupported);
        }
        let (tail, _) = ast.final_expressions().next().ok_or(ProjectCheck::Unsupported)?;
        expression = tail;
        occurrence = slot.expression;
        if topology.structure.checked_types.expressions.get(&occurrence) != Some(expected) {
            return Err(ProjectCheck::Unsupported);
        }
        if check_initializer_statements::<true, false>(
            topology, actual, source, storage, statements, MAX_INITIALIZER_BRANCH_DEPTH - remaining, failures, visits,
        )? == StartupLane::Empty {
            return Ok(None);
        }
    }

    let value = match expression {
        ScalarExpression::Boolean { value, .. } if *expected == ScalarType::Bool => InitializerValue::Boolean(*value),
        ScalarExpression::Name { .. } => {
            let Some(InitializationName::Storage(InitializationStorage::Module(span))) =
                topology.identities.names.get(&occurrence) else { return Err(ProjectCheck::Unsupported); };
            match storage.get(span).ok_or(ProjectCheck::Unsupported)? {
                InitializerValue::Boolean(value) if *expected == ScalarType::Bool => InitializerValue::Boolean(*value),
                InitializerValue::Integer { ty, value } if *ty == expected =>
                    InitializerValue::Integer { ty: expected, value: Cow::Owned(value.as_ref().clone()) },
                _ => return Err(ProjectCheck::Unsupported),
            }
        }
        ScalarExpression::Call { .. } => {
            let value = match run_scalar_initializer_call(
                topology, actual, source, occurrence, expected, None, storage, failures, visits, false, None,
            )? {
                ActualCallResult::Integer(value) => value,
                ActualCallResult::EmptyScalar => return Ok(None),
                _ => return Err(ProjectCheck::Unsupported),
            };
            if *expected == ScalarType::Bool {
                let lane = super::checker_flow::bool_result_lane(&value).ok_or(ProjectCheck::Unsupported)?;
                InitializerValue::Boolean(lane == 1)
            } else {
                InitializerValue::Integer { ty: expected, value: Cow::Owned(value) }
            }
        }
        _ if is_integer_type(expected) => {
            let value = concrete_integer_literal(expression).ok_or(ProjectCheck::Unsupported)?;
            InitializerValue::Integer { ty: expected, value }
        }
        _ => return Err(ProjectCheck::Unsupported),
    };
    Ok(Some(value))
}

// A stored scalar and a reached condition consume the same exact call
// result and ordered receipts. Only the caller decides what to do with it.
fn run_scalar_initializer_call(
    topology: &ModuleInitializationTopology,
    actual: &mut CheckedCalls<'_, impl ActualIntegerObserver>,
    #[cfg_attr(not(feature = "internal-checker"), allow(unused_variables))] source: &SourceIdentity,
    occurrence: OccurrenceOrdinal,
    expected: &ScalarType,
    pair_receivers: Option<&[BindingReceiverSlot]>,
    storage: &HashMap<ByteSpan, InitializerValue<'_>>,
    #[cfg_attr(not(feature = "internal-checker"), allow(unused_variables))] failures: &mut Option<&mut OrderedFailures>,
    #[cfg_attr(not(feature = "internal-checker"), allow(unused_variables))] visits: &[InitializationVisit],
    #[cfg_attr(not(feature = "internal-checker"), allow(unused_variables))] passive_binding: bool,
    binding_expression: Option<&ScalarExpression>,
) -> Result<ActualCallResult, ProjectCheck> {
    #[cfg(feature = "internal-checker")]
    let proof_site = actual.initializer_proof_site(topology, source, occurrence, failures.as_deref());
    #[cfg(feature = "internal-checker")]
    let sink = failures.as_deref_mut().map(RefCell::new);
    #[cfg(feature = "internal-checker")]
    let collection = sink.as_ref().map(|failures| {
        let traced = failures.borrow().startup_search.as_ref().is_some_and(|trace|
            passive_binding || trace.borrow().proof_free_scalar_initializers
                || (matches!(expected, ScalarType::Array { .. }) && trace.borrow().has_aggregate_site(source, occurrence)));
        (source, OrderedCallCollection {
            scalar_initializer: passive_binding.then_some(OrderedInitializerCall { topology, occurrence }),
            startup_site: traced.then_some(OrderedInitializerCall { topology, occurrence }),
            startup_site_source: traced.then_some(source),
            ..OrderedCallCollection::new(failures, Some(visits))
        })
    });
    #[cfg(not(feature = "internal-checker"))]
    let collection = None;
    run_initializer_call(
        topology, actual, occurrence, expected, pair_receivers,
        |argument, ty| initialized_scalar_initializer_argument(topology, storage, argument, ty),
        collection, binding_expression,
        #[cfg(feature = "internal-checker")]
        proof_site,
    )
}

fn run_initializer_call<'a, Observer: ActualIntegerObserver>(
    topology: &'a ModuleInitializationTopology,
    actual: &mut CheckedCalls<'_, Observer>,
    occurrence: OccurrenceOrdinal,
    expected: &ScalarType,
    pair_receivers: Option<&[BindingReceiverSlot]>,
    initialized_argument: impl Fn(OccurrenceOrdinal, &ScalarType) -> Option<&'a BigInt>,
    collection: Option<(&SourceIdentity, OrderedCallCollection<'_, '_>)>,
    #[cfg_attr(not(feature = "internal-checker"), allow(unused_variables))] binding_expression: Option<&'a ScalarExpression>,
    #[cfg(feature = "internal-checker")] proof_site: Option<InitializerProofSite<'_>>,
) -> Result<ActualCallResult, ProjectCheck> {
    let Some(ModuleInitializationCallTarget::Direct {
        declaration,
        concrete: ConcreteCallSelection::Declaration,
    }) = topology.call_targets.get(&occurrence) else {
        return Err(ProjectCheck::Unsupported);
    };
    let signature = topology.checked_call_signatures.get(&occurrence).ok_or(ProjectCheck::MissingRootOccurrences)?;
    #[cfg(feature = "internal-checker")]
    let check_completed_scalar_namespace = Observer::EXACT_COMPLETED_NAMESPACE_SCALAR_RETURNS;
    #[cfg(not(feature = "internal-checker"))]
    let check_completed_scalar_namespace = false;
    #[cfg(feature = "internal-checker")]
    let qualified_proof = || topology.structure.checker_direct_targets.get(&occurrence).is_some_and(|&target|
        actual.observer.named_exact_watch(target).is_some_and(|watch|
            watch.qualified_leaf || (watch.result_pair && pair_receivers.is_some())));
    #[cfg(not(feature = "internal-checker"))]
    let qualified_proof = || false;
    #[cfg(feature = "internal-checker")]
    let capped_qualified = || collection.is_some_and(|(caller, ordered)|
        topology.structure.checker_direct_targets.get(&occurrence).is_some_and(|target|
            ordered.failures.borrow().startup_search.as_ref().is_some_and(|search|
                search.borrow().allows_qualified_scalar_proof(caller, occurrence, *target))));
    #[cfg(not(feature = "internal-checker"))]
    let capped_qualified = || false;
    let collection = collection.filter(|(source, _)|
        check_completed_scalar_namespace || !is_integer_type(expected) || *source == &declaration.source
            || qualified_proof() || capped_qualified());
    let named_literal = matches!(expected, ScalarType::Bool | ScalarType::Char)
        && actual.named_literal_initializer(topology, occurrence, expected, collection.is_some());
    let named_character = *expected == ScalarType::Char && named_literal;
    let module_bool_initializer = (*expected == ScalarType::Bool && named_literal)
        || actual.real_module_boolean_initializer(expected, collection.is_some());
    if pair_receivers.is_none() && ((*expected == ScalarType::Bool && !module_bool_initializer)
        || (*expected == ScalarType::Char && !named_character))
    { return Err(ProjectCheck::Unsupported); }
    let real_input = pair_receivers.is_some() || named_character || module_bool_initializer
        || actual.real_integer_input_profile(expected, collection.is_some());
    #[cfg(feature = "internal-checker")]
    let named_bool_entry = collection.is_some() && is_integer_type(expected) && proof_site.is_some()
        && named_exact_mixed_pair(&signature.parameters, |ty| ty)
        && topology.structure.checker_direct_targets.get(&occurrence).is_some_and(|&target|
            actual.observer.named_exact_watch(target).is_some_and(|watch| !watch.citation));
    #[cfg(not(feature = "internal-checker"))]
    let named_bool_entry = false;
    let allow_bool = named_literal || named_bool_entry || ((real_input || *expected == ScalarType::Unit)
        && collection.is_some() && Observer::ORDINARY_INTEGER_LOCALS);
    #[cfg(feature = "internal-checker")]
    let fixed_array = actual.can_initialize_fixed_arrays() && collection.is_some() && proof_site.is_some()
        && matches!(expected, ScalarType::Array { .. });
    #[cfg(not(feature = "internal-checker"))]
    let fixed_array = false;
    #[cfg(feature = "internal-checker")]
    let wide_rank = collection.is_some_and(|(caller, ordered)|
        topology.structure.checker_direct_targets.get(&occurrence).is_some_and(|target|
            ordered.failures.borrow().startup_search.as_ref().is_some_and(|search| {
                let search = search.borrow();
                search.owns_initialization(caller) && search.wide_rank_recipe.as_ref().is_some_and(|recipe| recipe.target == *target || recipe.forwarder.is_some_and(|(wrapper, _)| wrapper == *target))
                    && search.required_sites.get(&occurrence) == Some(&(*target, failure_search::StartupProofRole::Ranked))
            })));
    #[cfg(feature = "internal-checker")]
    let prepared_forwarder = wide_rank && collection.is_some_and(|(_, ordered)|
        topology.structure.checker_direct_targets.get(&occurrence).is_some_and(|target|
            ordered.failures.borrow().startup_search.as_ref().is_some_and(|trace|
                trace.borrow().wide_rank_recipe.as_ref().and_then(|recipe| recipe.forwarder)
                    .is_some_and(|(wrapper, _)| wrapper == *target))));
    #[cfg(not(feature = "internal-checker"))]
    let wide_rank = false;
    let arguments = if wide_rank {
        if !(3..=MAX_RANKED_INTEGER_AXES).contains(&signature.parameters.len()) { return Err(ProjectCheck::Unsupported); }
        let tuple = signature.parameters.iter().enumerate().map(|(slot, parameter)| {
            let actual = exact_typed_call_argument_at(&topology.structure, occurrence, slot, false, &initialized_argument);
            #[cfg(feature = "internal-checker")]
            let actual = actual.or_else(|| {
                use super::reference::{OccurrenceEdge, OccurrenceNode, OccurrenceParent};
                if !prepared_forwarder { return None; }
                let original = binding_expression?;
                let ScalarExpression::Call { arguments, .. } = original else { return None; };
                let argument = arguments.get(slot)?;
                let ScalarExpression::Integer { value, .. } = argument else { return None; };
                let OccurrenceNode::Expression(at) = topology.structure.edges.get(&(
                    OccurrenceParent::Expression(occurrence), OccurrenceEdge::CallArgument(slot),
                ))? else { return None; };
                let expressions = &topology.structure.checked_types.expressions;
                let ty = expressions.get(at)?;
                if topology.occurrences.get(occurrence.0)?.span != super::typecheck::expression_span(original)
                    || topology.occurrences.get(at.0)?.span != super::typecheck::expression_span(argument)
                { return None; }
                Some((ty, value))
            });
            let (ty, value) = actual.ok_or(ProjectCheck::Unsupported)?;
            if ty != parameter || !integer_literal_fits_type(value, ty) { return Err(ProjectCheck::Unsupported); }
            Ok((ty, value))
        }).collect::<Result<Vec<_>, ProjectCheck>>()?;
        ActualProjectedArguments::ExactWide(tuple)
    } else if (real_input || fixed_array) && signature.parameters.is_empty() {
        ActualProjectedArguments::Single(None)
    } else if signature.parameters.len() == 2
        && (fixed_array || module_bool_initializer || is_integer_type(expected) || (*expected == ScalarType::Unit && collection.is_some()))
    {
        let first = exact_typed_call_argument_at(&topology.structure, occurrence, 0, allow_bool, &initialized_argument)
            .ok_or(ProjectCheck::Unsupported)?;
        let second = exact_typed_call_argument_at(&topology.structure, occurrence, 1, allow_bool, &initialized_argument)
            .ok_or(ProjectCheck::Unsupported)?;
        ActualProjectedArguments::ExactPair(first, second)
    } else {
        #[cfg(feature = "internal-checker")]
        let argument = if named_character {
            super::checker_flow::exact_named_character_argument_at(&topology.structure, occurrence, initialized_argument)
        } else {
            exact_typed_call_argument_at(&topology.structure, occurrence, 0, allow_bool, initialized_argument)
        };
        #[cfg(not(feature = "internal-checker"))]
        let argument = exact_typed_call_argument_at(&topology.structure, occurrence, 0, allow_bool, initialized_argument);
        if *expected != ScalarType::Unit && argument.is_none() {
            return Err(ProjectCheck::Unsupported);
        }
        ActualProjectedArguments::Single(argument)
    };
    actual.run(
        &topology.structure, occurrence, signature, arguments, &declaration.source, declaration.range,
        expected, pair_receivers, module_bool_initializer, collection, #[cfg(feature = "internal-checker")] proof_site,
    )
}

enum InitializerValue<'a> {
    Boolean(bool),
    #[cfg(feature = "internal-checker")]
    Character(BigInt),
    Integer { ty: &'a ScalarType, value: Cow<'a, BigInt> },
    #[cfg(feature = "internal-checker")]
    FixedArray { ty: &'a ScalarType, cells: Vec<BigInt> },
    #[cfg(feature = "internal-checker")]
    PatchedIntegerArray {
        ty: &'a ScalarType,
        original: Rc<PassiveLiteral<'a>>,
        updates: HashMap<usize, BigInt>,
    },
    #[cfg(feature = "internal-checker")]
    PassiveFloat { _atom: ranked_float::Atom },
    #[cfg(feature = "internal-checker")]
    PassiveEnum { _enumeration: &'a super::ScalarEnumId, _tag: u32 },
    // An exact typed value, not a license to access runtime storage.
    #[cfg(feature = "internal-checker")]
    PassiveAggregate {
        ty: &'a ScalarType,
        generation: usize,
        depth: usize,
        value: std::rc::Rc<PassiveLiteral<'a>>,
    },
}

#[cfg(feature = "internal-checker")]
fn completed_nominal_initializer_copy<'p>(
    topology: &ModuleInitializationTopology, caller: &SourceIdentity, at: OccurrenceOrdinal,
    expected: &ScalarType, visits: &[InitializationVisit], ordinals: &HashMap<&'p SourceIdentity,usize>,
    project: &'p ScalarProject, qualifiers: &HashMap<ByteSpan,&SourceIdentity>,
    captured: &CompletedPassiveStorage<'p>,
) -> Option<(Rc<PassiveLiteral<'p>>,usize)> {
    let ScalarType::Struct(id) = expected else { return None; };
    if topology.structure.checked_types.expressions.get(&at)? != expected { return None; }
    let super::control::InitializationMember::Module { qualifier, declaration, .. } =
        topology.identities.members.get(&at)? else { return None; };
    if caller == &declaration.source || &id.source != &declaration.source
        || *qualifiers.get(qualifier)? != &declaration.source
    { return None; }
    let ordinal = *ordinals.get(&declaration.source)?;
    if !completed_namespace_owner(caller,&declaration.source,ordinal,Some(visits)) { return None; }
    let owner = project.modules.get(ordinal)?;
    if owner.source != declaration.source
        || !owner.structs.get(id.index).is_some_and(|nominal| &nominal.id == id && nominal.copy_policy == super::CopyPolicy::Copy)
    { return None; }
    // The table contains only the final independently checked passive
    // generation; an unknown executable transition clears it before use.
    let InitializerValue::PassiveAggregate { ty,value,depth,.. } =
        captured.get(&ordinal)?.get(&declaration.range)? else { return None; };
    (expected == *ty).then(|| (Rc::clone(value),*depth))
}

#[cfg(feature = "internal-checker")]
fn prepared_passive_enum_tag(topology: &ModuleInitializationTopology, at: OccurrenceOrdinal, expected: &super::ScalarEnumId) -> Option<u32> {
    let super::control::InitializationMember::Enum { enumeration, tag } = topology.identities.members.get(&at)?
        else { return None; };
    (enumeration == expected).then_some(*tag)
}

#[cfg(feature = "internal-checker")]
fn passive_startup_initializer(ty: &ScalarType, expression: &ScalarExpression) -> bool {
    match (ty, expression) {
        (ScalarType::Struct(_), ScalarExpression::StructLiteral { .. }) => true,
        (ScalarType::Array { .. } | ScalarType::Struct(_), ScalarExpression::Name { .. }) => true,
        (ScalarType::Array { element, .. }, ScalarExpression::ArrayLiteral { .. }) =>
            is_integer_type(element) || matches!(element.as_ref(), ScalarType::Array { .. } | ScalarType::Struct(_)
                | ScalarType::Enum(_) | ScalarType::F32 | ScalarType::F64),
        _ => false,
    }
}

#[cfg(feature = "internal-checker")]
#[derive(Debug, PartialEq)]
enum PassiveLiteral<'a> {
    Boolean(bool),
    Character(char),
    Integer(&'a ScalarType, BigInt),
    Float(ranked_float::Atom),
    Enum(&'a super::ScalarEnumId, u32),
    Array(Box<[Self]>),
    Nominal(&'a super::ScalarStructId, Box<[Self]>),
    // Share immutable semantic data, not Wosy locations or runtime storage.
    Copy(std::rc::Rc<Self>),
}

#[cfg(feature = "internal-checker")]
fn observed_nominal_f32_field(value: &InitializerValue<'_>, index: Option<u64>,
    field: &super::ScalarStructFieldId) -> Option<ObservedExactValue> {
    let InitializerValue::PassiveAggregate { ty, value, .. } = value else { return None; };
    fn original<'v,'a>(mut value: &'v PassiveLiteral<'a>) -> &'v PassiveLiteral<'a> {
        while let PassiveLiteral::Copy(next) = value { value = next; }
        value
    }
    let nominal = match (index, ty) {
        (None, ScalarType::Struct(id)) if id == &field.structure => original(value),
        (Some(index), ScalarType::Array { element, length, .. })
            if element.as_ref() == &ScalarType::Struct(field.structure.clone()) && index < *length => {
                let PassiveLiteral::Array(values) = original(value) else { return None; };
                if u64::try_from(values.len()).ok()? != *length { return None; }
                original(values.get(usize::try_from(index).ok()?)?)
            }
        _ => return None,
    };
    let PassiveLiteral::Nominal(actual, fields) = nominal else { return None; };
    if *actual != &field.structure { return None; }
    let PassiveLiteral::Float(ranked_float::Atom::Single(bits)) = original(fields.get(field.index)?) else { return None; };
    Some(ObservedExactValue::F32(super::checker_flow::projected_f32::ExactF32::checked_bits(*bits)?))
}

#[cfg(feature = "internal-checker")]
fn observed_nested_array_leaf(mut ty: &ScalarType) -> Option<&ScalarType> {
    if !matches!(ty,ScalarType::Array { .. }) { return None; }
    while let ScalarType::Array { element,.. } = ty { ty = element; }
    matches!(ty,ScalarType::I32 | ScalarType::F32 | ScalarType::U16 | ScalarType::U8).then_some(ty)
}

#[cfg(feature = "internal-checker")]
fn observed_passive_array_element(value: &InitializerValue<'_>, indices: &[u64], expected:&ScalarType, field:Option<&super::ScalarStructFieldId>)
    -> Option<(ObservedExactValue,usize)> {
    let InitializerValue::PassiveAggregate { mut ty,value,.. } = value else { return None; };
    let mut value = value.as_ref();
    let mut work = 1usize;
    for &index in indices {
        let ScalarType::Array { element,length,.. } = ty else { return None; };
        work = work.checked_add(1)?;
        while let PassiveLiteral::Copy(next) = value { value = next; work = work.checked_add(1)?; }
        let PassiveLiteral::Array(cells) = value else { return None; };
        if u64::try_from(cells.len()).ok()? != *length || index >= *length { return None; }
        value = cells.get(usize::try_from(index).ok()?)?;
        ty = element;
    }
    if let Some(field) = field {
        let ScalarType::Struct(declared) = ty else { return None; };
        if declared != &field.structure { return None; }
        while let PassiveLiteral::Copy(next) = value { value = next; work = work.checked_add(1)?; }
        let PassiveLiteral::Nominal(actual,fields) = value else { return None; };
        if *actual != declared { return None; }
        value = fields.get(field.index)?;
        ty = expected;
        work = work.checked_add(1)?;
    }
    if ty != expected { return None; }
    while let PassiveLiteral::Copy(next) = value { value = next; work = work.checked_add(1)?; }
    let atom = match (ty,value) {
        (ScalarType::F32,PassiveLiteral::Float(ranked_float::Atom::Single(bits))) =>
            ObservedExactValue::F32(super::checker_flow::projected_f32::ExactF32::checked_bits(*bits)?),
        (ScalarType::I32|ScalarType::U16|ScalarType::U8,PassiveLiteral::Integer(actual,value)) if *actual == ty =>
            ObservedExactValue::Integer(ty.clone(),value.clone()),
        _ => return None,
    };
    Some((atom,work))
}

#[cfg(feature = "internal-checker")]
fn flat_passive_integer_array<'v>(mut value: &'v PassiveLiteral<'_>, ty: &ScalarType) -> Option<Vec<&'v BigInt>> {
    let ScalarType::Array { element, length, .. } = ty else { return None; };
    if !is_integer_type(element) { return None; }
    while let PassiveLiteral::Copy(original) = value { value = original; }
    let PassiveLiteral::Array(cells) = value else { return None; };
    if u64::try_from(cells.len()).ok()? != *length { return None; }
    cells.iter().map(|mut cell| {
        while let PassiveLiteral::Copy(original) = cell { cell = original; }
        let PassiveLiteral::Integer(actual, value) = cell else { return None; };
        (element.as_ref() == *actual).then_some(value)
    }).collect()
}

#[cfg(feature = "internal-checker")]
enum PassiveCopySource<'a, 'w> {
    Current {
        topology: &'w ModuleInitializationTopology,
        storage: &'w HashMap<ByteSpan, InitializerValue<'a>>,
        generation: usize,
    },
    Completed {
        body: &'w FunctionCallSites,
        owner: &'w SourceIdentity,
        storage: &'w HashMap<ByteSpan, InitializerValue<'a>>,
    },
}

#[cfg(feature = "internal-checker")]
struct PassiveLiteralPreparation<'a, 'w> {
    occurrences: &'w [super::reference::OccurrenceMetadata],
    structure: &'w OccurrenceStructure,
    project: &'a ScalarProject,
    ordinals: &'w HashMap<&'a SourceIdentity, usize>,
    work: &'w mut usize,
    copies: Option<PassiveCopySource<'a, 'w>>,
    maximum_depth: usize,
}

#[cfg(feature = "internal-checker")]
impl<'a> PassiveLiteralPreparation<'a, '_> {
    fn copy_type(&self, ty: &ScalarType) -> bool {
        super::copy_policy_with(ty, &std::collections::BTreeSet::new(),
            &mut |id| {
                let owner = self.project.modules.get(*self.ordinals.get(&id.source)?)?;
                owner.structs.get(id.index).filter(|declared| declared.id == *id)
                    .map(|declared| declared.copy_policy)
            }, &mut |id| {
                let owner = self.project.modules.get(*self.ordinals.get(&id.source)?)?;
                owner.enums.get(id.index).filter(|declared| declared.id == *id)
                    .map(|declared| declared.copy_policy)
            }) == Ok(super::CopyPolicy::Copy)
    }

    fn node(
        &mut self, at: OccurrenceOrdinal, ty: &'a ScalarType, expression: &ScalarExpression, depth: usize,
    ) -> Option<PassiveLiteral<'a>> {
        use super::reference::{OccurrenceEdge, OccurrenceNode, OccurrenceParent};
        use super::analysis_budget::charge_call_work;
        const MAX_DEPTH: usize = 16;
        if depth > MAX_DEPTH || self.occurrences.get(at.0)?.span != super::typecheck::expression_span(expression) {
            return None;
        }
        charge_call_work(self.work, 1)?;
        let typed = self.structure.checked_types.expressions.get(&at)?;
        self.maximum_depth = self.maximum_depth.max(depth);
        if matches!(expression, ScalarExpression::Name { .. })
            && matches!(ty, ScalarType::Array { .. } | ScalarType::Struct(_))
        {
            let (value, current_generation) = match self.copies.as_ref()? {
                PassiveCopySource::Current { topology, storage, generation } => {
                    let InitializationName::Storage(InitializationStorage::Module(span)) =
                        topology.identities.names.get(&at)? else { return None; };
                    (storage.get(span)?, Some(*generation))
                }
                PassiveCopySource::Completed { body, owner, storage } => {
                    let super::reference::PlainNameIdentity::ModuleValue(span) =
                        body.prepared_plain_name(at)? else { return None; };
                    if &span.source != *owner { return None; }
                    (storage.get(&span.range)?, None)
                }
            };
            let InitializerValue::PassiveAggregate { ty: original, generation, value, depth: source_depth } =
                value else { return None; };
            let expanded_depth = depth.checked_add(*source_depth)?;
            if current_generation.is_some_and(|live| *generation != live) || expanded_depth > MAX_DEPTH
                || !passive_type_equal(ty, original, MAX_DEPTH - depth)
                || !passive_type_equal(ty, typed, MAX_DEPTH - depth) || !self.copy_type(ty)
            { return None; }
            self.maximum_depth = self.maximum_depth.max(expanded_depth);
            return Some(PassiveLiteral::Copy(std::rc::Rc::clone(value)));
        }
        let child = |edge| {
            let OccurrenceNode::Expression(at) = *self.structure.edges.get(&(
                OccurrenceParent::Expression(at), edge,
            ))? else { return None; };
            Some(at)
        };
        match (ty, typed, expression) {
            (ScalarType::Array { element, length, .. },
                ScalarType::Array { element: typed_element, length: typed_length, .. },
                ScalarExpression::ArrayLiteral { elements, .. }) =>
            {
                if elements.is_empty() || u64::try_from(elements.len()).ok()? != *length
                    || typed_length != length
                    || !passive_type_equal(element, typed_element, MAX_DEPTH - depth)
                { return None; }
                let mut cells = Vec::with_capacity(elements.len());
                for (index, value) in elements.iter().enumerate() {
                    let node = child(OccurrenceEdge::AggregateElement(index))?;
                    cells.push(self.node(node, element, value, depth + 1)?);
                }
                Some(PassiveLiteral::Array(cells.into_boxed_slice()))
            }
            (ScalarType::Struct(id), ScalarType::Struct(typed_id), ScalarExpression::StructLiteral { fields, .. })
                if id == typed_id =>
            {
                let owner = self.project.modules.get(*self.ordinals.get(&id.source)?)?;
                let declared = owner.structs.get(id.index).filter(|item| item.id == *id)?;
                if fields.is_empty() || fields.len() != declared.fields.len()
                { return None; }
                let mut values: Vec<_> = std::iter::repeat_with(|| None).take(fields.len()).collect();
                for (position, field) in fields.iter().enumerate() {
                    let node = child(OccurrenceEdge::AggregateField(position))?;
                    let field_id = self.structure.literal_fields.get(&node)?;
                    let declaration = declared.fields.get(field_id.index)?;
                    if declaration.id != *field_id || field_id.structure != *id || field.name != declaration.name {
                        return None;
                    }
                    let slot = values.get_mut(field_id.index)?;
                    if slot.is_some() { return None; }
                    *slot = Some(self.node(node, &declaration.ty, &field.value, depth + 1)?);
                }
                Some(PassiveLiteral::Nominal(id, values.into_iter().collect::<Option<Vec<_>>>()?.into_boxed_slice()))
            }
            (ScalarType::Enum(expected), ScalarType::Enum(checked), _) if expected == checked => {
                let PassiveCopySource::Current { topology, .. } = self.copies.as_ref()? else { return None; };
                Some(PassiveLiteral::Enum(expected, prepared_passive_enum_tag(topology, at, expected)?))
            }
            (ScalarType::Bool, ScalarType::Bool, ScalarExpression::Boolean { value, .. }) =>
                Some(PassiveLiteral::Boolean(*value)),
            (ScalarType::Char, ScalarType::Char, ScalarExpression::Char { value, .. }) =>
                Some(PassiveLiteral::Character(*value)),
            (ScalarType::F32 | ScalarType::F64, _, _) if ty == typed =>
                Some(PassiveLiteral::Float(ranked_float::Atom::literal(expression, ty)?)),
            (_, _, _) if ty == typed && is_integer_type(ty) => {
                let value = concrete_integer_literal(expression)?.into_owned();
                integer_literal_fits_type(&value, ty).then_some(PassiveLiteral::Integer(ty, value))
            }
            _ => None,
        }
    }
}

#[cfg(feature = "internal-checker")]
fn passive_type_equal(expected: &ScalarType, typed: &ScalarType, depth: usize) -> bool {
    match (expected, typed) {
        (ScalarType::Array { element, length, .. }, ScalarType::Array { element: other, length: actual, .. }) =>
            depth > 0 && length == actual && passive_type_equal(element, other, depth - 1),
        (ScalarType::Struct(_) | ScalarType::Enum(_) | ScalarType::Bool | ScalarType::Char | ScalarType::F32 | ScalarType::F64, _) =>
            expected == typed,
        _ => is_integer_type(expected) && expected == typed,
    }
}

#[cfg(feature = "internal-checker")]
fn initialized_proof_atom(ty: &ScalarType, value: BigInt) -> Option<InitializerValue<'_>> {
    match ty {
        ScalarType::Bool => Some(InitializerValue::Boolean(super::checker_flow::bool_result_lane(&value)? == 1)),
        ScalarType::Char => {
            ProofLiteralType::Character.from_atom(&value)?;
            Some(InitializerValue::Character(value))
        }
        ty if integer_literal_fits_type(&value, ty) => Some(InitializerValue::Integer { ty, value: Cow::Owned(value) }),
        _ => None,
    }
}

#[cfg(feature = "internal-checker")]
fn initialized_fixed_array_cell<'a>(
    topology: &ModuleInitializationTopology, storage: &'a HashMap<ByteSpan, InitializerValue<'_>>,
    expression: OccurrenceOrdinal, index_expression: &ScalarExpression, expected: &ScalarType,
) -> Option<&'a BigInt> {
    use super::reference::{OccurrenceEdge, OccurrenceNode, OccurrenceParent};
    let structure = &topology.structure;
    let OccurrenceNode::Place(place) = *structure.edges.get(&(
        OccurrenceParent::Expression(expression), OccurrenceEdge::ExpressionPlace,
    ))? else { return None; };
    let OccurrenceNode::Place(base) = *structure.edges.get(&(
        OccurrenceParent::Place(place), OccurrenceEdge::PlaceBase,
    ))? else { return None; };
    let InitializationStorage::Module(binding) = topology.identities.roots.get(&base)? else { return None; };
    let array = storage.get(binding)?;
    let ty = match array {
        InitializerValue::FixedArray { ty, .. } | InitializerValue::PatchedIntegerArray { ty, .. } => *ty,
        _ => return None,
    };
    let ScalarType::Array { element, length, .. } = ty else { return None; };
    if element.as_ref() != expected || !super::scalar_type_equal(structure.checked_types.places.get(&base)?, ty)
        || structure.checked_types.places.get(&place)? != expected
    {
        return None;
    }
    let OccurrenceNode::Expression(index) = *structure.edges.get(&(
        OccurrenceParent::Place(place), OccurrenceEdge::PlaceIndex,
    ))? else { return None; };
    if structure.checked_types.expressions.get(&index)? != &ScalarType::U64
        || topology.occurrences.get(index.0)?.span != super::typecheck::expression_span(index_expression)
    {
        return None;
    }
    // Place indices are not call-argument or binding-root literals.
    let value = match index_expression {
        ScalarExpression::Integer { value, .. } => value,
        ScalarExpression::Name { .. } => initialized_integer_argument(topology, storage, index, &ScalarType::U64)?,
        _ => return None,
    };
    let index = usize::try_from(value).ok()?;
    if u64::try_from(index).ok()? >= *length { return None; }
    match array {
        InitializerValue::FixedArray { cells, .. } if u64::try_from(cells.len()).ok()? == *length => cells.get(index),
        InitializerValue::PatchedIntegerArray { original, updates, .. } => {
            if let Some(value) = updates.get(&index) { return Some(value); }
            let mut original = original.as_ref();
            while let PassiveLiteral::Copy(next) = original { original = next; }
            let PassiveLiteral::Array(cells) = original else { return None; };
            if u64::try_from(cells.len()).ok()? != *length { return None; }
            let mut cell = cells.get(index)?;
            while let PassiveLiteral::Copy(next) = cell { cell = next; }
            let PassiveLiteral::Integer(actual, number) = cell else { return None; };
            (element.as_ref() == *actual).then_some(number)
        }
        _ => None,
    }
}

fn initialized_scalar_initializer_argument<'a>(
    topology: &ModuleInitializationTopology,
    storage: &'a HashMap<ByteSpan, InitializerValue<'_>>,
    argument: OccurrenceOrdinal,
    argument_type: &ScalarType,
) -> Option<&'a BigInt> {
    #[cfg(feature = "internal-checker")]
    if *argument_type == ScalarType::Bool {
        let InitializationName::Storage(InitializationStorage::Module(span)) =
            topology.identities.names.get(&argument)? else { return None; };
        let InitializerValue::Boolean(value) = storage.get(span)? else { return None; };
        // Prepared exact argument rows use these two numeric Boolean atoms.
        // Share them rather than allocating a BigInt per read or declaration.
        static BOOL_VALUES: std::sync::LazyLock<[BigInt; 2]> =
            std::sync::LazyLock::new(|| [BigInt::from(0u8), BigInt::from(1u8)]);
        return BOOL_VALUES.get(usize::from(*value));
    }
    #[cfg(feature = "internal-checker")]
    if *argument_type == ScalarType::Char {
        let InitializationName::Storage(InitializationStorage::Module(span)) =
            topology.identities.names.get(&argument)? else { return None; };
        let InitializerValue::Character(value) = storage.get(span)? else { return None; };
        return Some(value);
    }
    initialized_integer_argument(topology, storage, argument, argument_type)
}

fn initialized_integer_argument<'a>(
    topology: &ModuleInitializationTopology,
    storage: &'a HashMap<ByteSpan, InitializerValue<'_>>,
    argument: OccurrenceOrdinal,
    argument_type: &ScalarType,
) -> Option<&'a BigInt> {
    let InitializationName::Storage(InitializationStorage::Module(span)) =
        topology.identities.names.get(&argument)? else {
            return None;
        };
    let InitializerValue::Integer { ty, value } = storage.get(span)? else {
        return None;
    };
    (*ty == argument_type).then_some(value.as_ref())
}

fn evaluate_initializer_predicate(
    predicate: &InitializerPredicate,
    storage: &HashMap<ByteSpan, InitializerValue<'_>>,
    #[cfg_attr(not(feature = "internal-checker"), allow(unused_variables))] allow_logic: bool,
) -> Option<bool> {
    match predicate {
        #[cfg(feature = "internal-checker")]
        InitializerPredicate::And(operands) if allow_logic => {
            let [left, right] = operands.as_ref();
            Some(evaluate_initializer_predicate(left, storage, true)?
                && evaluate_initializer_predicate(right, storage, true)?)
        }
        #[cfg(feature = "internal-checker")]
        InitializerPredicate::Or(operands) if allow_logic => {
            let [left, right] = operands.as_ref();
            Some(evaluate_initializer_predicate(left, storage, true)?
                || evaluate_initializer_predicate(right, storage, true)?)
        }
        #[cfg(feature = "internal-checker")]
        InitializerPredicate::Not(operand) if allow_logic =>
            Some(!evaluate_initializer_predicate(operand, storage, true)?),
        #[cfg(feature = "internal-checker")]
        InitializerPredicate::And(_) | InitializerPredicate::Or(_) | InitializerPredicate::Not(_)
            | InitializerPredicate::Opaque => None,
        InitializerPredicate::Boolean(value) => Some(*value),
        InitializerPredicate::BooleanStorage(span) => match storage.get(span)? {
            InitializerValue::Boolean(value) => Some(*value),
            _ => None,
        },
        InitializerPredicate::IntegerComparison { relation, operands } => {
            fn integer<'a>(
                operand: &'a InitializerIntegerOperand,
                storage: &'a HashMap<ByteSpan, InitializerValue<'_>>,
            ) -> Option<&'a BigInt> {
                match operand {
                    InitializerIntegerOperand::Literal(value) => Some(value),
                    InitializerIntegerOperand::Storage(span) => match storage.get(span)? {
                        InitializerValue::Integer { value, .. } => Some(value.as_ref()),
                        _ => None,
                    },
                }
            }
            let [left, right] = operands.as_ref();
            Some(relation.accepts(integer(left, storage)?.cmp(integer(right, storage)?)))
        }
    }
}

const MAX_INITIALIZER_BRANCH_DEPTH: usize = 64;

#[derive(Clone, Copy)]
struct OrderedCallCollection<'a, 'visits> {
    failures: &'a RefCell<&'a mut OrderedFailures>,
    visits: Option<&'visits [InitializationVisit]>,
    #[cfg(feature = "internal-checker")]
    outer: Option<OrderedInitializerCall<'a>>,
    #[cfg(feature = "internal-checker")]
    scalar_initializer: Option<OrderedInitializerCall<'a>>,
    #[cfg(feature = "internal-checker")]
    meter_named_legacy_unit: bool,
    #[cfg(feature = "internal-checker")]
    startup_site: Option<OrderedInitializerCall<'a>>,
    #[cfg(feature = "internal-checker")]
    startup_site_source: Option<&'a SourceIdentity>,
    #[cfg(feature = "internal-checker")]
    plain_unit_root: bool,
}

impl<'a, 'visits> OrderedCallCollection<'a, 'visits> {
    fn new(failures: &'a RefCell<&'a mut OrderedFailures>, visits: Option<&'visits [InitializationVisit]>) -> Self {
        Self {
            failures, visits,
            #[cfg(feature = "internal-checker")]
            outer: None,
            #[cfg(feature = "internal-checker")]
            scalar_initializer: None,
            #[cfg(feature = "internal-checker")]
            meter_named_legacy_unit: false,
            #[cfg(feature = "internal-checker")]
            startup_site: None,
            #[cfg(feature = "internal-checker")]
            startup_site_source: None,
            #[cfg(feature = "internal-checker")]
            plain_unit_root: false,
        }
    }
}

#[cfg(feature = "internal-checker")]
#[derive(Clone, Copy)]
struct OrderedInitializerCall<'a> {
    topology: &'a ModuleInitializationTopology,
    occurrence: OccurrenceOrdinal,
}

enum ActualProjectedArguments<'a> {
    Single(Option<ExactIntegerArgument<'a>>),
    ExactPair(ExactIntegerArgument<'a>, ExactIntegerArgument<'a>),
    ExactWide(Vec<ExactIntegerArgument<'a>>),
    SymbolicAxis(ProjectedIntegerArgument<'a>),
}

#[cfg(feature = "internal-checker")]
#[derive(Clone, Copy)]
struct NamedExactWatch {
    nested_work: usize,
    citation: bool,
    case_citation: bool,
    qualified_leaf: bool,
    literal_leaf: Option<ProofLiteralType>,
    result_pair: bool,
}

#[cfg(feature = "internal-checker")]
impl NamedExactWatch {
    fn supports_nested_scalar(self) -> bool {
        !self.citation && !self.case_citation && !self.result_pair
            && (self.literal_leaf == Some(ProofLiteralType::Boolean)
                || (self.qualified_leaf && self.literal_leaf.is_none()))
    }
}

#[cfg(feature = "internal-checker")]
enum NamedStackArguments {
    Empty,
    Unary(BigInt),
    Pair([BigInt; 2]),
}

#[cfg(feature = "internal-checker")]
struct NamedStackSite<'a> {
    call: ByteSpan,
    observed_entry: Option<(&'a [ScalarType], NamedStackArguments, usize)>,
    nested_scalar: bool,
}

#[derive(Clone, Copy)]
#[cfg_attr(not(feature = "internal-checker"), allow(dead_code))]
struct NamedStackRoot {
    outer: ByteSpan,
    nested_scalars: bool,
}

#[cfg(feature = "internal-checker")]
fn named_exact_frame_cost(body: &FunctionCallSites) -> Option<usize> {
    body.occurrences.len().checked_add(1)?.checked_add(body.boundary.parameters.len())
}

struct ExactCallActivation<'a> {
    body: &'a FunctionCallSites,
    source: &'a SourceIdentity,
    cursor: ExactCallCursor<'a>,
    entry: Option<BigInt>,
    followed_self_edge: bool,
    #[cfg(feature = "internal-checker")]
    named_site: Option<NamedStackSite<'a>>,
    #[cfg(feature = "internal-checker")]
    named_nested_scalars: bool,
    #[cfg(feature = "internal-checker")]
    plain_unit_frame: bool,
    #[cfg(feature = "internal-checker")]
    contextual_origin: Option<(&'a ReferenceBindingId, ByteSpan)>,
    #[cfg(feature = "internal-checker")]
    contextual_explicit: Option<BigInt>,
    #[cfg(feature = "internal-checker")]
    verified_contextual_result: Option<(BigInt, BigInt)>,
    target: Option<((usize, usize), bool, ExactCallEffect<'a>, Option<usize>)>,
}

struct CheckedCalls<'a, Observer, const ACTUAL_STARTUP: bool = true> {
    project: &'a ScalarProject,
    calls: &'a ProjectCallSiteResults,
    active: HashSet<(usize, usize)>,
    active_depth: usize,
    reached: HashSet<(usize, usize)>,
    #[cfg(feature = "internal-checker")]
    mixed_reached: Option<HashMap<PreparedCallable, usize>>,
    had_obligations: bool,
    observer: Observer,
    symbolic_module: usize,
}

#[cfg(feature = "internal-checker")]
struct InitializerProofSite<'a> {
    source: &'a SourceIdentity,
    call: InitializerProofOrigin<'a>,
}

#[cfg(feature = "internal-checker")]
enum InitializerProofOrigin<'a> {
    Direct { topology: &'a ModuleInitializationTopology, occurrence: OccurrenceOrdinal, directive_position: usize },
    CapturedDirect { call: ByteSpan, directive_position: usize },
    Nested { outer: OrderedInitializerCall<'a>, caller: &'a FunctionCallSites, inner: OccurrenceOrdinal, directive_position: usize },
    Stacked { outer: wosy_syntax::SourceSpan, intermediate: Vec<wosy_syntax::SourceSpan>, inner: ByteSpan, directive_position: usize, nested_scalar: bool },
}

trait ActualIntegerObserver {
    const ENABLED: bool;
    const PROOF_FREE_CONTEXTUAL_LOCAL_TRANSFERS: bool = false;
    const EXACT_SELF_REENTRY: bool = false;
    const EXACT_INTEGER_CALL_CONTINUATIONS: bool = false;
    #[cfg(feature = "internal-checker")]
    const EXACT_INTEGER_NARROW_CONTINUATIONS: bool = false;
    #[cfg(feature = "internal-checker")]
    const EXACT_INTEGER_LOCAL_WRITES: bool = false;
    #[cfg(feature = "internal-checker")]
    const EXACT_COMPLETED_NAMESPACE_SCALAR_RETURNS: bool = false;
    #[cfg(feature = "internal-checker")]
    const EXACT_CONTEXTUAL_BOOLEAN_UNIT: bool = false;
    #[cfg(feature = "internal-checker")]
    const AUTHORED_SINGLETON_CODE: bool = false;
    #[cfg(feature = "internal-checker")]
    const REAL_INTEGER_TAIL_CALLS: bool = false;
    #[cfg(feature = "internal-checker")]
    const REAL_INTEGER_INPUT_SIGNATURES: bool = false;
    #[cfg(feature = "internal-checker")]
    const REAL_EXTENDED_SCALAR_LOCALS: bool = false;
    #[cfg(feature = "internal-checker")]
    const REAL_MODULE_BOOLEAN_INITIALIZERS: bool = false;
    #[cfg(feature = "internal-checker")]
    const FIXED_ARRAY_INITIALIZERS: bool = false;
    #[cfg(feature = "internal-checker")]
    const REAL_BOOLEAN_NARROW_CONTINUATIONS: bool = false;
    #[cfg(feature = "internal-checker")]
    const AUTHORED_STARTUP_SCALARS: bool = false;
    const INTEGER_RETURN_PARTITIONS: bool = false;
    const PROJECTED_FORMAL_WRITES: bool = false;
    const ORDINARY_PROJECTED_PAIR: bool = false;
    #[cfg(feature = "internal-checker")]
    const NAMED_RELATIONAL_PARTITIONS: bool = false;
    const ORDINARY_INTEGER_LOCALS: bool = false;

    fn observe(&mut self, target: (usize, usize), arguments: &[&BigInt], value: &BigInt);

    #[cfg(feature = "internal-checker")]
    const EXACT_POINTEE_UPDATE: bool = false;

    #[cfg(feature = "internal-checker")]
    fn exact_pointee_update(
        &self, _: PreparedCallable, _: &FunctionCallSites, _: OccurrenceOrdinal,
        _: &SourceIdentity, _: SymbolicProofRuntime<'_>, _: &ExactCallCursor<'_>,
    ) -> Result<Option<Vec<super::checker_flow::LocalPointeeTransition>>, ProjectCheck> { Ok(None) }

    #[cfg(feature = "internal-checker")]
    fn watches_fixed_array(&self, _: PreparedCallable) -> bool { false }

    #[cfg(feature = "internal-checker")]
    fn enables_character_initializers(&self) -> bool { false }

    #[cfg(feature = "internal-checker")]
    fn observe_fixed_array_initializer(
        &mut self, _: PreparedCallable, _: &FunctionCallSites,
        _: &[&BigInt], _: wosy_syntax::SourceSpan, _: Option<&failure_search::SharedStartupTrace>,
    ) -> Result<Vec<BigInt>, ProjectCheck> { Err(ProjectCheck::Unsupported) }

    #[cfg(feature = "internal-checker")]
    fn charge_named_pair_activation(&mut self, _body: &FunctionCallSites) -> Option<()> { None }

    #[cfg(feature = "internal-checker")]
    fn named_mixed_pair(&self) -> bool { false }

    #[cfg(feature = "internal-checker")]
    fn named_pair(&self) -> bool { false }

    #[cfg(feature = "internal-checker")]
    fn citation_only(&self) -> bool { false }

    #[cfg(feature = "internal-checker")]
    fn permits_ordinary_projected_effects(&self) -> bool { false }

    const CONTEXTUAL: bool = false;

    #[cfg(feature = "internal-checker")]
    fn charge_named_exact_work(&mut self, _cost: usize) -> Option<()> { None }

    #[cfg(feature = "internal-checker")]
    fn named_exact_watch(&self, _target: PreparedCallable) -> Option<NamedExactWatch> { None }

    #[cfg(feature = "internal-checker")]
    fn named_nested_scalar_route(&self, _target: PreparedCallable) -> bool { false }

    #[cfg(feature = "internal-checker")]
    fn permits_named_pure_affine_return(&self, _target: PreparedCallable, _arguments: &[&BigInt]) -> bool {
        false
    }

    #[cfg(feature = "internal-checker")]
    fn observe_initializer(
        &mut self, _target: (usize, usize), _site: Option<InitializerProofSite<'_>>,
        _parameters: &[ScalarType], _arguments: &[&BigInt], _value: &BigInt,
    ) {}

    #[cfg(feature = "internal-checker")]
    fn check_initializer_pair(
        &mut self, _: PreparedCallable, _: &FunctionCallSites, _: InitializerProofSite<'_>,
        _: &[ScalarType], _: &[&BigInt],
    ) -> Result<[BigInt; 2], ProjectCheck> { Err(ProjectCheck::Unsupported) }

    #[cfg(feature = "internal-checker")]
    fn proved_wide_initializer_return(
        &mut self, _: PreparedCallable, _: &FunctionCallSites, _: &[&BigInt], _: &ScalarType, _: bool,
    ) -> Option<BigInt> { None }

    #[cfg(feature = "internal-checker")]
    fn proved_qualified_nested_return(
        &mut self, _: PreparedCallable, _: &FunctionCallSites, _: &[&BigInt], _: &ScalarType,
    ) -> Option<BigInt> { None }

    #[cfg(feature = "internal-checker")]
    fn proved_recursive_return(
        &mut self, _target: (usize, usize), _arguments: &[&BigInt], _expected: &ScalarType,
    ) -> Option<BigInt> {
        None
    }
}

impl ActualIntegerObserver for () {
    const ENABLED: bool = false;

    #[inline(always)]
    fn observe(&mut self, _target: (usize, usize), _arguments: &[&BigInt], _value: &BigInt) {}
}

impl<'project, Observer: ActualIntegerObserver, const ACTUAL_STARTUP: bool> CheckedCalls<'project, Observer, ACTUAL_STARTUP> {
    #[inline]
    fn note_reached(&mut self, target: (usize, usize)) {
        self.reached.insert(target);
        #[cfg(feature = "internal-checker")]
        if let Some(count) = self.mixed_reached.as_mut().and_then(|watched| watched.get_mut(&target)) {
            *count = count.saturating_add(1);
        }
    }

    #[cfg(feature = "internal-checker")]
    fn initializer_proof_site<'a>(
        &self, topology: &'a ModuleInitializationTopology, source: &'a SourceIdentity,
        occurrence: OccurrenceOrdinal, failures: Option<&OrderedFailures>,
    ) -> Option<InitializerProofSite<'a>> {
        if !ACTUAL_STARTUP || (!Observer::CONTEXTUAL
            && !(Observer::FIXED_ARRAY_INITIALIZERS && topology.structure.checker_direct_targets.get(&occurrence)
                .is_some_and(|&target| self.observer.watches_fixed_array(target))))
        {
            return None;
        }
        Some(InitializerProofSite { source, call: InitializerProofOrigin::Direct { topology, occurrence, directive_position: failures?.records.len() } })
    }

    #[cfg(feature = "internal-checker")]
    fn can_initialize_fixed_arrays(&self) -> bool {
        ACTUAL_STARTUP && Observer::FIXED_ARRAY_INITIALIZERS
    }

    fn named_literal_initializer(
        &self, topology: &ModuleInitializationTopology, call: OccurrenceOrdinal, expected: &ScalarType, collecting: bool,
    ) -> bool {
        #[cfg(feature = "internal-checker")]
        {
            ACTUAL_STARTUP && collecting && topology.structure.checker_direct_targets.get(&call)
                .and_then(|&target| self.observer.named_exact_watch(target))
                .and_then(|watch| watch.literal_leaf).is_some_and(|leaf| leaf.ty() == expected)
        }
        #[cfg(not(feature = "internal-checker"))]
        { let _ = (topology, call, expected, collecting); false }
    }

    fn nested(
        &mut self,
        caller: &FunctionCallSites,
        call: OccurrenceOrdinal,
        signature: &CheckedCallSignature,
        argument: NestedIntegerArgument<'_>,
        expected: &ScalarType,
        collection: Option<(&SourceIdentity, OrderedCallCollection<'_, '_>)>,
    ) -> Result<ActualCallResult, ProjectCheck> {
        #[cfg(feature = "internal-checker")]
        if *expected != ScalarType::Unit && collection.is_some_and(|(_, ordered)| ordered.meter_named_legacy_unit) {
            // The legacy Unit callback may not lose the meter by entering a
            // scalar path without a collected, authenticated call boundary.
            return Err(ProjectCheck::Unsupported);
        }
        let site = caller.resolved_call_site(call).ok_or(ProjectCheck::MissingRootOccurrences)?;
        let ResolvedCallTarget::ModuleCallable {
            source,
            declaration_span,
            concrete: ConcreteCallSelection::Declaration,
        } = &site.target else {
            return Err(ProjectCheck::Unsupported);
        };
        #[cfg(feature = "internal-checker")]
        if ACTUAL_STARTUP && Observer::ENABLED && is_integer_type(expected) {
            if let Some((caller_source, ordered)) = collection {
                if let Some(outer) = ordered.outer.filter(|_| caller_source != source && !ordered.meter_named_legacy_unit) {
                    return self.qualified_nested_ranked_return(
                        caller, call, signature, argument, expected, caller_source, source, *declaration_span,
                        outer, ordered.visits,
                    );
                }
            }
        }
        #[cfg(feature = "internal-checker")]
        let contextual_value = matches!(&argument, NestedIntegerArgument::ContextualValue(_));
        #[cfg(feature = "internal-checker")]
        if contextual_value && (!ACTUAL_STARTUP || Observer::ENABLED || Observer::CONTEXTUAL) {
            return Err(ProjectCheck::Unsupported);
        }
        #[cfg(feature = "internal-checker")]
        let mut proof_site = None;
        let collection = match collection {
            #[cfg(feature = "internal-checker")]
            Some((caller_source, ordered)) if contextual_value => {
                if caller_source != source || ordered.outer.is_none()
                    || caller.structure.checker_integer_call_locals.len() != 1 || !is_integer_type(expected)
                {
                    return Err(ProjectCheck::Unsupported);
                }
                Some((caller_source, OrderedCallCollection { outer: None, ..ordered }))
            }
            #[cfg(feature = "internal-checker")]
            None if contextual_value => return Err(ProjectCheck::Unsupported),
            Some((caller_source, ordered)) if *expected == ScalarType::Unit => {
                #[cfg(feature = "internal-checker")]
                let ordered = OrderedCallCollection { outer: None, ..ordered };
                Some((caller_source, ordered))
            }
            Some((_caller_source, _ordered)) => {
                #[cfg(feature = "internal-checker")]
                {
                    let outer = _ordered.outer.ok_or(ProjectCheck::Unsupported)?;
                    if !ACTUAL_STARTUP || !is_integer_type(expected) || _caller_source != source
                        || (caller.structure.checker_integer_call_locals.len() != 1
                            && !matches!(&argument, NestedIntegerArgument::RootLexical(_)))
                        || matches!(&argument, NestedIntegerArgument::Projected(_))
                    {
                        return Err(ProjectCheck::Unsupported);
                    }
                    if Observer::CONTEXTUAL {
                        let directive_position = _ordered.failures.borrow().records.len();
                        proof_site = Some(InitializerProofSite { source, call: InitializerProofOrigin::Nested {
                            outer, caller, inner: call, directive_position,
                        } });
                    }
                    None
                }
                #[cfg(not(feature = "internal-checker"))]
                return Err(ProjectCheck::Unsupported);
            }
            None => None,
        };
        let projected = match argument {
            NestedIntegerArgument::Single(exact) => ActualProjectedArguments::Single(exact),
            #[cfg(feature = "internal-checker")]
            NestedIntegerArgument::RootLexical(exact) | NestedIntegerArgument::ContextualValue(exact) =>
                ActualProjectedArguments::Single(Some(exact)),
            NestedIntegerArgument::Pair(first, second) => ActualProjectedArguments::ExactPair(first, second),
            NestedIntegerArgument::Projected(projection) => ActualProjectedArguments::SymbolicAxis(projection),
            #[cfg(feature = "internal-checker")]
            NestedIntegerArgument::UnitHistory(_) => return Err(ProjectCheck::Unsupported),
        };
        self.run(
            &caller.structure, call, signature, projected, source, *declaration_span, expected, None, false, collection,
            #[cfg(feature = "internal-checker")] proof_site,
        )
    }

    #[cfg(feature = "internal-checker")]
    fn qualified_nested_ranked_return(
        &mut self, caller: &FunctionCallSites, call: OccurrenceOrdinal, signature: &CheckedCallSignature,
        argument: NestedIntegerArgument<'_>, expected: &ScalarType, caller_source: &SourceIdentity,
        source: &SourceIdentity, declaration: ByteSpan, outer: OrderedInitializerCall<'_>,
        visits: Option<&[InitializationVisit]>,
    ) -> Result<ActualCallResult, ProjectCheck> {
        use super::reference::CheckerIntegerCallArgument;
        let Some(ModuleInitializationCallTarget::Direct {
            declaration: activation, concrete: ConcreteCallSelection::Declaration,
        }) = outer.topology.call_targets.get(&outer.occurrence) else { return Err(ProjectCheck::Unsupported); };
        let (active, _, _, active_body) = self.validated_direct_body(
            &outer.topology.structure, outer.occurrence, &activation.source, activation.range,
        )?;
        if activation.source != *caller_source || !self.active.contains(&active)
            || !std::ptr::eq(active_body, caller) || !caller.checker_returns_unit()
        {
            return Err(ProjectCheck::Unsupported);
        }
        let locals = &caller.structure.checker_integer_call_locals;
        let origin = locals.values().next().filter(|_| locals.len() == 1).ok_or(ProjectCheck::Unsupported)?;
        if origin.call != call || origin.binding.source != *caller_source
            || !caller.checked_call_signatures.get(&call).is_some_and(|actual| std::ptr::eq(actual, signature))
            || !matches!(signature.outputs.outputs.as_slice(), [result] if &result.ty == expected)
            || origin.arguments.as_slice().len() != signature.parameters.len()
            || origin.arguments.as_slice().iter().any(|(_, argument)|
                !matches!(argument, CheckerIntegerCallArgument::Literal(_) | CheckerIntegerCallArgument::PlainName))
        {
            return Err(ProjectCheck::Unsupported);
        }
        let (target, owner, function, body) = self.validated_direct_body(&caller.structure, call, source, declaration)?;
        if !completed_namespace_owner(caller_source, &owner.source, target.0, visits)
            || self.active.contains(&target) || self.active_depth == MAX_ACTUAL_CALL_DEPTH
            || !function.generic_parameters.is_empty() || !function.overload_arms.is_empty()
            || body.contextual_formal().is_some() || !body.assignments.is_empty()
            || !body.structure.checker_directives.is_empty() || !body.allocation_length_calls.is_empty()
            || !matches!(body.boundary.results.as_slice(), [result] if &result.ty == expected)
        {
            return Err(ProjectCheck::Unsupported);
        }
        let single;
        let pair;
        let actual: &[(&ScalarType, &BigInt)] = match argument {
            NestedIntegerArgument::Single(Some(one)) | NestedIntegerArgument::RootLexical(one) => {
                single = [one]; &single
            }
            NestedIntegerArgument::Pair(left, right) => { pair = [left, right]; &pair }
            _ => return Err(ProjectCheck::Unsupported),
        };
        if actual.len() != signature.parameters.len() || actual.len() != body.boundary.parameters.len()
            || !actual.iter().zip(signature.parameters.iter().zip(&body.boundary.parameters)).enumerate()
                .all(|(i, ((ty, value), (parameter, slot)))| slot.ordinal == i && *ty == parameter
                    && parameter == &slot.ty && is_integer_type(ty) && integer_literal_fits_type(value, ty))
        {
            return Err(ProjectCheck::Unsupported);
        }
        let arguments = actual.iter().map(|(_, value)| *value).collect::<Vec<_>>();
        // The independently verified pure provider supplies only this
        // result, to the existing enclosing local-binding continuation.
        let value = self.observer.proved_qualified_nested_return(target, body, &arguments, expected)
            .ok_or(ProjectCheck::Unsupported)?;
        self.note_reached(target);
        self.had_obligations = true;
        Ok(ActualCallResult::Integer(value))
    }

    #[cfg(feature = "internal-checker")]
    fn computed_self_descent(
        &self,
        caller: &FunctionCallSites,
        call: OccurrenceOrdinal,
        parameter: &ScalarType,
        previous: &BigInt,
    ) -> Result<BigInt, ProjectCheck> {
        use super::reference::{OccurrenceEdge, OccurrenceNode, OccurrenceParent, PlainNameIdentity};
        let structure = &caller.structure;
        if !caller.assignments.is_empty() {
            return Err(ProjectCheck::Unsupported);
        }
        let Some(OccurrenceNode::Expression(expression)) = structure.edges.get(&(
            OccurrenceParent::Expression(call), OccurrenceEdge::CallArgument(0),
        )) else { return Err(ProjectCheck::Unsupported); };
        let (left, decrement) = structure.checker_integer_call_subtractions.get(expression).ok_or(ProjectCheck::Unsupported)?;
        let Some([formal]) = caller.boundary.checker_parameter_bindings.as_deref() else {
            return Err(ProjectCheck::Unsupported);
        };
        if !matches!(caller.prepared_plain_name(*left), Some(PlainNameIdentity::Lexical(binding)) if binding == formal)            || structure.checked_types.expressions.get(expression) != Some(parameter)
            || previous < decrement
        {
            return Err(ProjectCheck::Unsupported);
        }
        Ok(previous - decrement)
    }

    fn requirements(
        &mut self,
        body: &FunctionCallSites,
        source: &SourceIdentity,
        exact: Option<&[&BigInt]>,
    ) -> Result<bool, ProjectCheck> {
        let mut nested_error = None;
        let checked = check_integer_requirements_with_calls(body, exact, &mut |caller, occurrence, signature, argument, expected| {
            match self.nested(caller, occurrence, signature, argument, expected, None) {
                Ok(result) => Some(result),
                Err(error) => {
                    nested_error = Some(error);
                    None
                }
            }
        });
        match checked {
            Some(Ok(active)) => Ok(active),
            Some(Err(failure)) => Err(project_failure(body, source, failure)),
            None => Err(nested_error.unwrap_or(ProjectCheck::Unsupported)),
        }
    }

    fn collect_requirements(
        &mut self,
        body: &FunctionCallSites,
        source: &SourceIdentity,
        entry: IntegerRequirementEntry<'_>,
        collection: OrderedCallCollection<'_, '_>,
    ) -> Result<ActualCallResult, ProjectCheck> {
        let terminal_projection = matches!(&entry, IntegerRequirementEntry::Projected { .. });
        let allow_contextual_local_transfers = ACTUAL_STARTUP && Observer::PROOF_FREE_CONTEXTUAL_LOCAL_TRANSFERS
            && matches!(&entry, IntegerRequirementEntry::Exact(_));
        let mut sink = |failure| collection.failures.borrow_mut().push_callable(body, source, failure);
        let mut nested_error = None;
        let mut nested = |caller: &FunctionCallSites, occurrence, signature: &CheckedCallSignature, argument: NestedIntegerArgument<'_>, expected: &ScalarType| {
            match self.nested(caller, occurrence, signature, argument, expected, Some((source, collection))) {
                Ok(result) => Some(result),
                Err(error) => {
                    nested_error = Some(error);
                    None
                }
            }
        };
        let handler: Option<&mut super::checker_flow::ActualCallHandler<'_, '_>> =
            if terminal_projection { None } else { Some(&mut nested) };
        let Some((active, continuation)) = collect_integer_requirement_failures_with_calls(
            body, entry, handler, !ACTUAL_STARTUP && !terminal_projection, allow_contextual_local_transfers, &mut sink,
        ) else {
            return Err(nested_error.unwrap_or(ProjectCheck::Unsupported));
        };
        self.had_obligations |= active;
        Ok(match continuation {
            IntegerRequirementContinuation::Feasible => ActualCallResult::Unit,
            IntegerRequirementContinuation::Empty => ActualCallResult::EmptyUnit,
            IntegerRequirementContinuation::Projected(values) => ActualCallResult::ProjectedUnit(values),
        })
    }

    #[cfg(feature = "internal-checker")]
    fn permits_authored_startup_scalars(&self) -> bool { ACTUAL_STARTUP && Observer::AUTHORED_STARTUP_SCALARS }

    fn real_module_boolean_initializer(&self, expected: &ScalarType, collecting: bool) -> bool {
        #[cfg(feature = "internal-checker")]
        { ACTUAL_STARTUP && collecting && *expected == ScalarType::Bool
            && Observer::REAL_MODULE_BOOLEAN_INITIALIZERS && Observer::ORDINARY_INTEGER_LOCALS
            && Observer::EXACT_INTEGER_CALL_CONTINUATIONS }
        #[cfg(not(feature = "internal-checker"))]
        { let _ = (expected, collecting); false }
    }

    fn real_integer_input_profile(&self, expected: &ScalarType, collecting: bool) -> bool {
        #[cfg(feature = "internal-checker")]
        { ACTUAL_STARTUP && collecting && Observer::EXACT_INTEGER_CALL_CONTINUATIONS
            && Observer::REAL_INTEGER_INPUT_SIGNATURES && is_integer_type(expected) }
        #[cfg(not(feature = "internal-checker"))]
        { let _ = (expected, collecting); false }
    }

    fn exact_self_reentry_allowed(&self, expected: &ScalarType, collecting: bool) -> bool {
        ACTUAL_STARTUP && Observer::EXACT_SELF_REENTRY
            && (*expected == ScalarType::Unit
                || (collecting && Observer::EXACT_INTEGER_CALL_CONTINUATIONS && is_integer_type(expected)))
    }

    fn exact_boolean_narrow_profile(&self, expected: &ScalarType, collecting: bool) -> bool {
        #[cfg(feature = "internal-checker")]
        { ACTUAL_STARTUP && collecting && *expected == ScalarType::Bool
            && Observer::EXACT_INTEGER_CALL_CONTINUATIONS && Observer::ORDINARY_INTEGER_LOCALS
            && Observer::REAL_BOOLEAN_NARROW_CONTINUATIONS }
        #[cfg(not(feature = "internal-checker"))]
        { let _ = (expected, collecting); false }
    }

    fn exact_boolean_narrow_body_has_supported_shape(body: &FunctionCallSites) -> bool {
        #[cfg(feature = "internal-checker")]
        {
            body.structure.checker_has_exact_boolean_narrow
                && !body.structure.checker_has_unsupported_boolean_narrow_body
                && body.allocation_length_calls.is_empty() && body.assignments.is_empty()
        }
        #[cfg(not(feature = "internal-checker"))]
        { let _ = body; false }
    }

    fn exact_integer_narrow_profile(&self, collecting: bool) -> bool {
        #[cfg(feature = "internal-checker")]
        { ACTUAL_STARTUP && collecting && Observer::EXACT_INTEGER_CALL_CONTINUATIONS
            && Observer::EXACT_INTEGER_NARROW_CONTINUATIONS }
        #[cfg(not(feature = "internal-checker"))]
        { let _ = collecting; false }
    }

    fn projected_integer_narrow_shape(
        &self, body: &FunctionCallSites, effect: ExactCallEffect<'_>, collecting: bool,
    ) -> bool {
        #[cfg(feature = "internal-checker")]
        {
            !ACTUAL_STARTUP && collecting && Observer::INTEGER_RETURN_PARTITIONS
                && self.observer.permits_ordinary_projected_effects()
                && matches!(effect, ExactCallEffect::Scalar { binding: Some(_), ty, .. } if is_integer_type(ty))
                && body.structure.checker_has_simple_narrow && !body.structure.checker_has_nonsimple_directive
                && body.structure.blocks.len() == 1 && body.boundary.parameters.len() == 1
                && body.call_occurrences.is_empty() && body.allocation_length_calls.is_empty()
                && body.assignments.is_empty() && body.arms.is_empty()
                && body.structure.checker_contextual_occurrences.is_empty()
        }
        #[cfg(not(feature = "internal-checker"))]
        { let _ = (body, effect, collecting); false }
    }

    fn exact_integer_narrow_shape(&self, body: &FunctionCallSites, expected: &ScalarType, collecting: bool) -> bool {
        #[cfg(feature = "internal-checker")]
        {
            self.exact_integer_narrow_profile(collecting) && is_integer_type(expected)
                && body.structure.checker_has_simple_narrow && !body.structure.checker_has_nonsimple_directive
                && body.allocation_length_calls.is_empty() && body.assignments.is_empty()
        }
        #[cfg(not(feature = "internal-checker"))]
        { let _ = (body, expected, collecting); false }
    }

    fn exact_integer_local_write_shape(&self, body: &FunctionCallSites, expected: &ScalarType, collecting: bool) -> bool {
        #[cfg(feature = "internal-checker")]
        {
            ACTUAL_STARTUP && collecting && Observer::EXACT_INTEGER_CALL_CONTINUATIONS
                && Observer::EXACT_INTEGER_LOCAL_WRITES && is_integer_type(expected)
                && !body.assignments.is_empty() && body.allocation_length_calls.is_empty()
                && !body.structure.checker_has_nonsimple_directive
                && (!body.structure.checker_has_simple_narrow || Observer::EXACT_INTEGER_NARROW_CONTINUATIONS)
        }
        #[cfg(not(feature = "internal-checker"))]
        { let _ = (body, expected, collecting); false }
    }

    fn completed_namespace_call(
        &self, caller: &SourceIdentity, owner: &ScalarModule, target: usize, body: &FunctionCallSites,
        signature: &CheckedCallSignature, expected: &ScalarType, visits: Option<&[InitializationVisit]>,
    ) -> bool {
        if !completed_namespace_owner(caller, &owner.source, target, visits) { return false; }
        if *expected == ScalarType::Unit { return true; }
        #[cfg(feature = "internal-checker")]
        {
            // Only a real exact, proof-free startup call may cross into
            // a completed sibling module for a scalar result. The admitted
            // leaf stays closed to contextual effects and helper calls.
            let scalar_leaf = if *expected == ScalarType::Bool {
                self.real_module_boolean_initializer(expected, true)
                    && matches!(signature.parameters.as_slice(), [parameter]
                        if *parameter == ScalarType::Bool || is_integer_type(parameter))
                    && !body.structure.checker_has_unsupported_boolean_narrow_body
                    && body.structure.checker_ordinary_directive_calls.is_empty()
                    && !body.structure.has_ordinary_contextual_places()
                    && !body.structure.checker_has_bool_contextual_declaration
            } else {
                is_integer_type(expected)
                    && matches!(signature.parameters.as_slice(), [parameter] if is_integer_type(parameter))
                    && !body.structure.checker_has_nonsimple_directive
            };
            ACTUAL_STARTUP && Observer::EXACT_COMPLETED_NAMESPACE_SCALAR_RETURNS
                && Observer::EXACT_INTEGER_CALL_CONTINUATIONS && scalar_leaf
                && body.call_occurrences.is_empty() && body.allocation_length_calls.is_empty()
                && body.assignments.is_empty() && body.arms.is_empty()
                && body.structure.checker_contextual_occurrences.is_empty()
        }
        #[cfg(not(feature = "internal-checker"))]
        { let _ = (body, signature); false }
    }

    fn exact_self_entry<'entry>(&self, exact: Option<&[&'entry BigInt]>) -> Option<&'entry BigInt> {
        if ACTUAL_STARTUP && Observer::EXACT_SELF_REENTRY {
            if let Some([value]) = exact {
                return Some(*value);
            }
        }
        None
    }

    fn validated_direct_body(
        &self, structure: &OccurrenceStructure, call: OccurrenceOrdinal,
        target_source: &SourceIdentity, target_span: ByteSpan,
    ) -> Result<((usize, usize), &'project ScalarModule, &'project ScalarFunction, &'project FunctionCallSites), ProjectCheck> {
        let &target = structure.checker_direct_targets.get(&call)
            .ok_or(ProjectCheck::MissingRootOccurrences)?;
        self.validated_prepared_body(target, target_source, target_span)
    }

    #[cfg(feature = "internal-checker")]
    fn passive_qualified_nominal_return(
        &self, topology: &ModuleInitializationTopology, caller: &SourceIdentity, call: OccurrenceOrdinal,
        expected: &'project ScalarType, visits: &[InitializationVisit],
        ordinals: &HashMap<&'project SourceIdentity, usize>, captured: &CompletedPassiveStorage<'project>,
        work: &mut usize,
    ) -> Option<(PreparedCallable, Rc<PassiveLiteral<'project>>, usize)> {
        use super::reference::PlainNameIdentity;
        let signature = topology.checked_call_signatures.get(&call)?;
        if !ACTUAL_STARTUP || !signature.parameters.is_empty()
            || !matches!(signature.outputs.outputs.as_slice(), [result] if &result.ty == expected)
        { return None; }
        let ModuleInitializationCallTarget::Direct { declaration, concrete: ConcreteCallSelection::Declaration } =
            topology.call_targets.get(&call)? else { return None; };
        let (target, owner, function, body) =
            self.validated_direct_body(&topology.structure, call, &declaration.source, declaration.range).ok()?;
        if caller == &owner.source || !completed_namespace_owner(caller, &owner.source, target.0, Some(visits))
            || body.contextual_formal().is_some() || function.body.unsafe_context || !body.boundary.parameters.is_empty()
            || !matches!(body.boundary.results.as_slice(), [result] if &result.ty == expected)
        { return None; }
        let [ScalarBlockItem::LocalBinding(local), ScalarBlockItem::Expression(tail)] =
            function.body.items.as_slice() else { return None; };
        let [output] = function.body.final_output_values.as_slice() else { return None; };
        if local.is_allocation || !matches!(&local.value, ScalarExpression::StructLiteral { .. })
            || !matches!(tail, ScalarExpression::Name { .. })
            || super::typecheck::expression_span(tail) != super::typecheck::expression_span(&output.value)
        { return None; }
        let root = body.structure.blocks.get(body.structure.root.0)?;
        let [binding, result] = root.items.as_slice() else { return None; };
        let BlockItemKind::Binding(checked) = &binding.kind else { return None; };
        let BlockItemKind::FinalOutput(result) = &result.kind else { return None; };
        let BindingInitialization::Outputs(outputs) = &checked.initialization else { return None; };
        let [receiver] = checked.receivers() else { return None; };
        let PlainNameIdentity::Lexical(returned) = body.prepared_plain_name(result.expression)? else { return None; };
        if &receiver.ty != expected || receiver.contextual_storage.is_some() || !outputs.secondary.is_empty()
            || returned.source != owner.source || returned.function_span != function.span
            || returned.declaration_span != receiver.span || returned.block_span != function.body.span
            || returned.kind != super::ReferenceBindingKind::Declared
            || body.structure.checked_types.expressions.get(&result.expression)? != expected
            || !matches!(output.value, ScalarExpression::Name { .. })
            || body.occurrences.get(result.expression.0)?.span != super::typecheck::expression_span(&output.value)
        { return None; }
        let storage = captured.get(&target.0)?;
        let mut preparation = PassiveLiteralPreparation {
            occurrences: &body.occurrences, structure: &body.structure, project: self.project,
            ordinals, work, maximum_depth: 0,
            copies: Some(PassiveCopySource::Completed { body, owner: &owner.source, storage }),
        };
        if !preparation.copy_type(expected) { return None; }
        let value = preparation.node(outputs.primary, expected, &local.value, 0)?;
        Some((target, Rc::new(value), preparation.maximum_depth))
    }

    #[cfg(feature = "internal-checker")]
    fn wide_ranked_startup_initializer(
        &mut self, topology: &ModuleInitializationTopology, source: &SourceIdentity, call: OccurrenceOrdinal,
        expected: &ScalarType, storage: &HashMap<ByteSpan, InitializerValue<'_>>,
        qualified: bool, visits: &[InitializationVisit],
    ) -> Result<Option<BigInt>, ProjectCheck> {
        let Some(signature) = topology.checked_call_signatures.get(&call) else { return Ok(None); };
        if !(3..=MAX_RANKED_INTEGER_AXES).contains(&signature.parameters.len()) { return Ok(None); }
        let Some(ModuleInitializationCallTarget::Direct {
            declaration, concrete: ConcreteCallSelection::Declaration,
        }) = topology.call_targets.get(&call) else { return Err(ProjectCheck::Unsupported); };
        let cross_source = &declaration.source != source;
        if !ACTUAL_STARTUP || !Observer::ENABLED || (cross_source && !qualified)
            || !matches!(signature.outputs.outputs.as_slice(), [result] if &result.ty == expected)
        {
            return Err(ProjectCheck::Unsupported);
        }
        let (target, _, _, body) = self.validated_direct_body(&topology.structure, call, &declaration.source, declaration.range)?;
        if (cross_source && !completed_namespace_owner(source, &declaration.source, target.0, Some(visits)))
            || self.active.contains(&target) || body.contextual_formal().is_some()
            || body.boundary.parameters.len() != signature.parameters.len()
            || !matches!(body.boundary.results.as_slice(), [result] if &result.ty == expected)
        {
            return Err(ProjectCheck::Unsupported);
        }
        let mut arguments = Vec::with_capacity(signature.parameters.len());
        for (i, (ty, slot)) in signature.parameters.iter().zip(&body.boundary.parameters).enumerate() {
            let (checked_ty, value) = exact_typed_call_argument_at(&topology.structure, call, i, false,
                |argument, ty| initialized_integer_argument(topology, storage, argument, ty))
                .ok_or(ProjectCheck::Unsupported)?;
            if slot.ordinal != i || ty != &slot.ty || ty != checked_ty || !integer_literal_fits_type(value, ty) {
                return Err(ProjectCheck::Unsupported);
            }
            arguments.push(value);
        }
        // The ordinary ordered proof token supplies this value. This does
        // not execute the recursive body or widen the scalar evaluator.
        let result = self.observer.proved_wide_initializer_return(target, body, &arguments, expected, cross_source)
            .ok_or(ProjectCheck::Unsupported)?;
        self.note_reached(target);
        Ok(Some(result))
    }

    fn validated_prepared_body(
        &self, target: (usize, usize), target_source: &SourceIdentity, target_span: ByteSpan,
    ) -> Result<((usize, usize), &'project ScalarModule, &'project ScalarFunction, &'project FunctionCallSites), ProjectCheck> {
        let (target_module, target_item) = target;
        let owner = self.project.modules.get(target_module).ok_or(ProjectCheck::MissingRoot)?;
        let Some(ScalarItem::Function(function)) = owner.items.get(target_item) else {
            return Err(ProjectCheck::MissingRoot);
        };
        if &owner.source != target_source || function.name_span != target_span {
            return Err(ProjectCheck::MissingRoot);
        }
        let body = self.calls.function_body(target_module, target_item, None).ok_or(ProjectCheck::MissingRootOccurrences)?;
        Ok((target, owner, function, body))
    }

    #[cfg(feature = "internal-checker")]
    fn traces_original_startup_rank(
        &self, body: &FunctionCallSites, collection: Option<OrderedCallCollection<'_, '_>>,
    ) -> bool {
        ACTUAL_STARTUP && collection.and_then(|ordered| {
            let effects = ordered.failures.borrow();
            let target = effects.startup_search.as_ref()?.borrow().ranked_target?;
            self.calls.function_body(target.0, target.1, None)
        }).is_some_and(|original| std::ptr::eq(original, body))
    }

    fn run_exact_calls<const NAMED: bool>(
        &mut self, body: &'project FunctionCallSites, source: &'project SourceIdentity,
        exact: &[&BigInt], expected: &ScalarType, collection: Option<OrderedCallCollection<'_, '_>>,
        named_root: Option<NamedStackRoot>,
    ) -> Result<ActualCallResult, ProjectCheck> {
        #[cfg(feature = "internal-checker")]
        let traced_rank = self.traces_original_startup_rank(body, collection);
        #[cfg(not(feature = "internal-checker"))]
        let traced_rank = false;
        #[allow(unused_mut)]
        let mut cursor = ExactCallCursor::new(body, exact, expected).ok_or(ProjectCheck::Unsupported)?;
        #[cfg(feature = "internal-checker")]
        if NAMED && !named_root.is_some_and(|root| root.nested_scalars) {
            cursor.allow_named_exact_bool_parameters().ok_or(ProjectCheck::Unsupported)?;
        }
        #[cfg(feature = "internal-checker")]
        if ACTUAL_STARTUP && collection.is_some() && *expected == ScalarType::Unit && Observer::EXACT_CONTEXTUAL_BOOLEAN_UNIT
            && body.structure.checker_has_bool_contextual_declaration
        {
            cursor.allow_exact_contextual_bool();
        }
        #[cfg(feature = "internal-checker")]
        if ACTUAL_STARTUP && collection.is_some() && Observer::REAL_EXTENDED_SCALAR_LOCALS
            && body.structure.checker_has_extended_scalar_local
        {
            cursor.allow_extended_scalar_locals();
        }
        #[cfg(feature = "internal-checker")]
        if ACTUAL_STARTUP && collection.is_some() && (Observer::REAL_INTEGER_TAIL_CALLS || traced_rank) && is_integer_type(expected)
            && !body.structure.checker_direct_targets.is_empty()
        {
            cursor.allow_real_integer_tail_call();
        }
        #[cfg(feature = "internal-checker")]
        if (is_integer_type(expected) && self.exact_integer_narrow_profile(collection.is_some()))
            || self.exact_boolean_narrow_profile(expected, collection.is_some())
        {
            cursor.allow_empty_scalar_return();
        }
        #[cfg(feature = "internal-checker")]
        if self.exact_integer_local_write_shape(body, expected, collection.is_some()) {
            cursor.restrict_returning_writes_to_direct_locals();
        }
        let entry = if traced_rank { exact.first().copied() } else { self.exact_self_entry(Some(exact)) }.cloned();
        self.run_call_cursor::<NAMED>(body, source, cursor, entry, collection, named_root)
    }

    #[cfg(feature = "internal-checker")]
    fn charge_named_exact_frame(&mut self, body: &FunctionCallSites) -> Result<(), ProjectCheck> {
        let cost = named_exact_frame_cost(body).ok_or(ProjectCheck::Unsupported)?;
        self.observer.charge_named_exact_work(cost).ok_or(ProjectCheck::Unsupported)
    }

    fn run_call_cursor<const NAMED: bool>(
        &mut self, body: &'project FunctionCallSites, source: &'project SourceIdentity,
        #[allow(unused_mut)] mut cursor: ExactCallCursor<'project>, entry: Option<BigInt>, collection: Option<OrderedCallCollection<'_, '_>>,
        named_root: Option<NamedStackRoot>,
    ) -> Result<ActualCallResult, ProjectCheck> {
        #[cfg(feature = "internal-checker")]
        if NAMED {
            self.charge_named_exact_frame(body)?;
        }
        #[cfg(feature = "internal-checker")]
        let authored_site = if let Some((ordered, site)) = collection.and_then(|ordered| ordered.startup_site.map(|site| (ordered, site))) {
            let at = site.topology.occurrences.get(site.occurrence.0).ok_or(ProjectCheck::MissingRootOccurrences)?.span;
            let site_source = ordered.startup_site_source.ok_or(ProjectCheck::Unsupported)?;
            let at = wosy_syntax::SourceSpan::new(site_source.clone(), at);
            let trace = ordered.failures.borrow().startup_search.clone().ok_or(ProjectCheck::Unsupported)?;
            trace.borrow_mut().append(failure_search::PathStep::Call(at.clone())).ok_or(ProjectCheck::Unsupported)?;
            #[cfg(test)]
            if trace.borrow().ranked_target.is_some_and(|target|
                self.calls.function_body(target.0, target.1, None).is_some_and(|rank| std::ptr::eq(rank, body))) {
                trace.borrow_mut().ranked_entries.push(entry.clone().ok_or(ProjectCheck::Unsupported)?);
            }
            // Bool is represented by an exact scalar atom, not by Unit or a
            // projected result. Only the prepared proof-free initializer route
            // may begin and finish this original source history.
            let exact_bool = ACTUAL_STARTUP && !NAMED && cursor.returns_startup_bool()
                && trace.borrow().proof_free_scalar_initializers;
            let snapshot = ACTUAL_STARTUP && !NAMED && trace.borrow().proof_free_scalar_initializers
                && !body.structure.checker_selected_snapshots.is_empty();
            if snapshot {
                trace.borrow_mut().charge_formal_replay(1, body.occurrences.len()).ok_or(ProjectCheck::Unsupported)?;
                cursor.allow_snapshot_history();
            }
            cursor.track_startup_path(source, Rc::clone(&trace), exact_bool).ok_or(ProjectCheck::Unsupported)?;
            Some((at, trace, exact_bool))
        } else { None };
        let mut frames = vec![ExactCallActivation { body, source, cursor, entry, followed_self_edge: false,
            #[cfg(feature = "internal-checker")]
            named_site: None,
            #[cfg(feature = "internal-checker")]
            named_nested_scalars: named_root.is_some_and(|root| root.nested_scalars),
            #[cfg(feature = "internal-checker")]
            plain_unit_frame: !NAMED && ACTUAL_STARTUP && collection.is_some_and(|ordered| ordered.plain_unit_root),
            #[cfg(feature = "internal-checker")]
            contextual_origin: None,
            #[cfg(feature = "internal-checker")]
            contextual_explicit: None,
            #[cfg(feature = "internal-checker")]
            verified_contextual_result: None,
            target: None }];
        let result = self.drive_exact_calls::<NAMED>(&mut frames, collection, named_root);
        for frame in frames.into_iter().rev() {
            if let Some((target, first_activation, _, _)) = frame.target {
                self.active_depth -= 1;
                if first_activation { self.active.remove(&target); }
            }
        }
        #[cfg(feature = "internal-checker")]
        if let Some((site, trace, exact_bool)) = authored_site {
            if trace.borrow().invalid() { return Err(ProjectCheck::Unsupported); }
            if trace.borrow().remaining() == 0 && trace.borrow().cannot_continue() { return Err(ProjectCheck::StartupAuthoredLimitReached); }
            let completed = match &result {
                Ok(ActualCallResult::Unit) => !exact_bool,
                Ok(ActualCallResult::Integer(value)) => !exact_bool || (*value == BigInt::from(0) || *value == BigInt::from(1)),
                _ => false,
            };
            if exact_bool && result.is_ok() && !completed { return Err(ProjectCheck::Unsupported); }
            if completed {
                trace.borrow_mut().append(failure_search::PathStep::Return(site)).ok_or(ProjectCheck::Unsupported)?;
            }
        }
        result
    }

    #[cfg(feature = "internal-checker")]
    fn enrolled_citation_helper(
        &self, trace: &failure_search::StartUpSearch, collection: Option<OrderedCallCollection<'_, '_>>,
        parent: &FunctionCallSites, site: OccurrenceOrdinal, child: PreparedCallable,
    ) -> bool {
        let Some(initializer) = collection.and_then(|ordered| ordered.scalar_initializer) else { return false; };
        let Some(&(caller, failure_search::StartupProofRole::Cited)) = trace.required_sites.get(&initializer.occurrence)
            else { return false; };
        trace.cited_routes.get(&caller) == Some(&(site, child))
            && self.calls.function_body(caller.0, caller.1, None).is_some_and(|original| std::ptr::eq(original, parent))
    }

    fn drive_exact_calls<const NAMED: bool>(
        &mut self, frames: &mut Vec<ExactCallActivation<'project>>,
        collection: Option<OrderedCallCollection<'_, '_>>,
        #[cfg_attr(not(feature = "internal-checker"), allow(unused_variables))] named_root: Option<NamedStackRoot>,
    ) -> Result<ActualCallResult, ProjectCheck> {
        loop {
            #[cfg(feature = "internal-checker")]
            let active_collection = if frames.len() == 1 { collection } else {
                collection.map(|collection| OrderedCallCollection { outer: None, ..collection })
            };
            #[cfg(not(feature = "internal-checker"))]
            let active_collection = collection;
            let frame = frames.last_mut().ok_or(ProjectCheck::Unsupported)?;
            #[cfg(feature = "internal-checker")]
            let ordinary_named = NAMED && frame.named_nested_scalars;
            #[cfg(not(feature = "internal-checker"))]
            let ordinary_named = false;
            let (body, source) = (frame.body, frame.source);
            #[cfg(feature = "internal-checker")]
            let traced_rank = self.traces_original_startup_rank(body, active_collection);
            #[cfg(not(feature = "internal-checker"))]
            let traced_rank = false;
            #[cfg(feature = "internal-checker")]
            let mut guarded_nonreturn = false;
            #[cfg(feature = "internal-checker")]
            let startup_context_entry = active_collection.is_some_and(|ordered| {
                let effects = ordered.failures.borrow();
                effects.startup_search.as_ref().is_some_and(|trace| {
                    let trace = trace.borrow();
                    trace.mixed_context.as_ref().is_some_and(|route|
                        self.calls.function_body(route.entry.0, route.entry.1, None).is_some_and(|actual| std::ptr::eq(actual, body)))
                })
            });
            let mut sink = |failure: IntegerCheckFailure<'_>| {
                #[cfg(feature = "internal-checker")]
                if frame.contextual_explicit.is_some()
                    && body.structure.checker_directives.get(&failure.directive)
                        .is_some_and(|directive| directive.operation == CheckerOperation::Narrow)
                    && body.structure.checker_ordinary_integer_comparisons.get(&failure.directive)
                        .is_some_and(|comparison| comparison.contextual)
                {
                    guarded_nonreturn = true;
                }
                if let Some(collection) = active_collection {
                    let mut effects = collection.failures.borrow_mut();
                    #[cfg(feature = "internal-checker")]
                    if let Some(trace) = &effects.startup_search {
                        let mut trace = trace.borrow_mut();
                        if startup_context_entry && trace.mixed_context.as_ref().is_some_and(|route|
                            route.dependent_requires.contains(&failure.directive))
                        {
                            if trace.mixed_context.as_ref().is_none_or(|route| !route.returned_context) { trace.invalidate(); return; }
                            if trace.mixed_context.as_ref().is_some_and(|route| !route.refuted_after_named.is_empty()) {
                                // This row's snapshot came from the very
                                // theorem that refuted. It cannot buy a slot
                                // or hide a later independent failure.
                                return;
                            }
                        }
                        let decision = body.occurrences.get(failure.directive.0)
                            .and_then(|site| trace.admit(wosy_syntax::SourceSpan::new(source.clone(), site.span)));
                        match decision {
                            Some(failure_search::Admission::Duplicate) => return,
                            Some(failure_search::Admission::Selected | failure_search::Admission::SelectedAndStop) => {},
                            None => { trace.invalidate(); return; }
                        }
                    }
                    effects.push_callable(body, source, failure);
                }
            };
            let mut nested_error = None;
            let mut nested_value = |caller: &FunctionCallSites, occurrence, signature: &CheckedCallSignature, argument: NestedIntegerArgument<'_>, expected: &ScalarType| {
                match self.nested(caller, occurrence, signature, argument, expected,
                    active_collection.map(|active| (source, active)))
                {
                    Ok(result) => Some(result),
                    Err(error) => { nested_error = Some(error); None }
                }
            };
            let handler = (!NAMED).then_some(&mut nested_value as &mut super::checker_flow::ActualCallHandler<'_, '_>);
            #[cfg(feature = "internal-checker")]
            let verified = frame.verified_contextual_result.take();
            #[cfg(not(feature = "internal-checker"))]
            let verified = Option::<(BigInt, BigInt)>::None;
            #[cfg(feature = "internal-checker")]
            let reused = verified.is_some();
            let progress = if let Some((entry, exit)) = verified {
                #[cfg(feature = "internal-checker")]
                { Some(ExactCallProgress::Done { active: false, result: ActualCallResult::ContextualUnit { entry, exit } }) }
                #[cfg(not(feature = "internal-checker"))]
                { let _ = (entry, exit); unreachable!() }
            } else if active_collection.is_some() {
                frame.cursor.advance::<true>(body, handler, Observer::PROOF_FREE_CONTEXTUAL_LOCAL_TRANSFERS,
                    NAMED || Observer::EXACT_INTEGER_CALL_CONTINUATIONS || traced_rank, Observer::ORDINARY_PROJECTED_PAIR,
                    ordinary_named || Observer::ORDINARY_INTEGER_LOCALS, &mut sink)
            } else {
                frame.cursor.advance::<false>(body, handler, false, false, false, false, &mut sink)
            }.ok_or_else(|| nested_error.unwrap_or(ProjectCheck::Unsupported))?;
            match progress {
                ExactCallProgress::Pending(call) => {
                    #[cfg(feature = "internal-checker")]
                    if ACTUAL_STARTUP && !NAMED && Observer::EXACT_POINTEE_UPDATE {
                        if let (Some(ordered), ExactCallEffect::Unit(occurrence)) = (active_collection, call) {
                            let site = body.resolved_call_site(occurrence).ok_or(ProjectCheck::MissingRootOccurrences)?;
                            if let ResolvedCallTarget::ModuleCallable {
                                source: owner, declaration_span, concrete: ConcreteCallSelection::Declaration,
                            } = &site.target {
                                let (target, _, _, _) =
                                    self.validated_direct_body(&body.structure, occurrence, owner, *declaration_span)?;
                                if let Some(update) = self.observer.exact_pointee_update(
                                    target, body, occurrence, source,
                                    SymbolicProofRuntime { project: self.project, calls: self.calls, visits: ordered.visits },
                                    &frame.cursor,
                                )? {
                                    let trace = ordered.failures.borrow().startup_search.clone();
                                    let point = if let Some(trace) = &trace {
                                        let trace = trace.borrow();
                                        let route = trace.pointee_route.as_ref().ok_or(ProjectCheck::Unsupported)?;
                                        if !trace.owns_initialization(source) || route.callee != target
                                            || !route.pending_calls.contains(&occurrence)
                                            || !self.calls.function_body(route.caller.0, route.caller.1, None)
                                                .is_some_and(|original| std::ptr::eq(original, body))
                                        { return Err(ProjectCheck::Unsupported); }
                                        Some(site.source_span.clone())
                                    } else { None };
                                    if let (Some(trace), Some(point)) = (&trace, &point) {
                                        trace.borrow_mut().append(failure_search::PathStep::Call(point.clone()))
                                            .ok_or(ProjectCheck::Unsupported)?;
                                    }
                                    frame.cursor.resume_exact_local_updates(update.into_iter()).ok_or(ProjectCheck::Unsupported)?;
                                    self.note_reached(target);
                                    self.had_obligations = true;
                                    if let (Some(trace), Some(point)) = (&trace, point) {
                                        let mut trace = trace.borrow_mut();
                                        trace.append(failure_search::PathStep::Return(point)).ok_or(ProjectCheck::Unsupported)?;
                                        if !trace.pointee_route.as_mut().ok_or(ProjectCheck::Unsupported)?.pending_calls.remove(&occurrence) {
                                            return Err(ProjectCheck::Unsupported);
                                        }
                                        if trace.remaining() == 0 && trace.cannot_continue() {
                                            return Err(ProjectCheck::StartupAuthoredLimitReached);
                                        }
                                    }
                                    continue;
                                }
                            }
                        }
                    }
                    #[cfg(feature = "internal-checker")]
                    let routed_unit = match call {
                        ExactCallEffect::Unit(occurrence) if ordinary_named && body.checker_returns_unit() => {
                            let &target = body.structure.checker_direct_targets.get(&occurrence)
                                .ok_or(ProjectCheck::MissingRootOccurrences)?;
                            if !self.observer.named_nested_scalar_route(target) {
                                // A Unit sibling outside the proof route
                                // keeps its ordinary call policy. Only its
                                // one completed result is resumed here.
                                let signature = body.checked_call_signatures.get(&occurrence)
                                    .ok_or(ProjectCheck::MissingRootOccurrences)?;
                                let ordered = active_collection.ok_or(ProjectCheck::Unsupported)?;
                                let argument = frame.cursor.arguments(body, occurrence, signature.parameters.len(),
                                    true, false, false, false, false).ok_or(ProjectCheck::Unsupported)?;
                                let result = self.nested(body, occurrence, signature, argument, &ScalarType::Unit,
                                    Some((source, OrderedCallCollection { meter_named_legacy_unit: true, ..ordered })))?;
                                frame.cursor.resume(call, None, result).ok_or(ProjectCheck::Unsupported)?;
                                continue;
                            }
                            true
                        }
                        _ => false,
                    };
                    #[cfg(not(feature = "internal-checker"))]
                    let routed_unit = false;
                    #[cfg(feature = "internal-checker")]
                    if matches!(call, ExactCallEffect::TailInteger { .. }) {
                        if let Some(trace) = active_collection.and_then(|ordered| ordered.failures.borrow().startup_search.clone()) {
                            // In the roster lane only direct verified self-tail
                            // work is admitted below. Meter before its cursor
                            // preparation using the same original body.
                            if trace.borrow().ranked_target.is_some() {
                                trace.borrow_mut().charge_proof_frame(body).ok_or(ProjectCheck::Unsupported)?;
                            }
                        }
                    }
                    #[allow(unused_mut)]
                    let mut child = self.prepare_exact_child::<NAMED>(frame, call, active_collection, routed_unit)?;
                    #[cfg(feature = "internal-checker")]
                    if let Some(trace) = active_collection.and_then(|ordered| ordered.failures.borrow().startup_search.clone()) {
                        let traced_rank = trace.borrow().ranked_target;
                        let target = child.target.map(|target| target.0);
                        let rank_self = traced_rank.is_some() && target == traced_rank && std::ptr::eq(frame.body, child.body);
                        let context_edge = {
                            let trace = trace.borrow();
                            let original = |target: PreparedCallable, body: &FunctionCallSites|
                                self.calls.function_body(target.0, target.1, None).is_some_and(|actual| std::ptr::eq(actual, body));
                            let enrolled = trace.contextual_roster.as_ref().is_some_and(|roster| {
                                let parent = frame.target.map_or(roster.entry, |parent| parent.0);
                                target.is_some_and(|child_target| roster.expects(parent, call.occurrence(), child_target))
                                    && original(parent, frame.body)
                                    && (frame.source == child.source || target.is_some_and(|target|
                                        completed_namespace_owner(frame.source, child.source, target.0,
                                            active_collection.and_then(|ordered| ordered.visits))))
                            });
                            (enrolled || trace.mixed_context.as_ref().is_some_and(|mixed| {
                                (target == Some(mixed.entry_target) && call.occurrence() == mixed.entry_site
                                    && !mixed.returned_context && original(mixed.entry, frame.body))
                                || target.is_some_and(|target| mixed.pending_leaves.front() == Some(&(call.occurrence(), target))
                                    && mixed.bridge.is_some_and(|bridge| original(bridge, frame.body)))
                            })) && child.contextual_origin.is_some() && matches!(call, ExactCallEffect::Unit(_))
                        };
                        // prepare_exact_child already authenticated the
                        // resolved edge and completed namespace owner.
                        let qualified_scalar = trace.borrow().proof_free_scalar_initializers && frame.source != child.source
                            && closed_startup_qualified_scalar_wrapper(frame.body, frame.source)
                            && matches!(call, ExactCallEffect::Scalar { binding: Some(_), ty, .. } if is_integer_type(ty))
                            && closed_startup_scalar_history(child.body)
                            && matches!(child.body.boundary.parameters.as_slice(), [entry] if is_integer_type(&entry.ty))
                            && child.body.structure.checker_directives.is_empty()
                            && child.body.contextual_formal().is_none();
                        let cited_helper = NAMED && frame.source == child.source
                            && matches!(call, ExactCallEffect::Scalar { binding: Some(_), ty, .. } if is_integer_type(ty))
                            && target.is_some_and(|target| self.enrolled_citation_helper(&trace.borrow(), active_collection, frame.body, call.occurrence(), target));
                        let span = frame.body.occurrences.get(call.occurrence().0)
                            .ok_or(ProjectCheck::MissingRootOccurrences)?.span;
                        let wide_forward = frame.source != child.source && trace.borrow().pending_wide_forward.as_ref()
                            .is_some_and(|(_, inner, _)| inner.range == span && &inner.source == frame.source)
                            && target == traced_rank;
                        // prepare_exact_child has already resolved this exact
                        // original typed call and checked its completed namespace.
                        // This proof-free lane uses the same live DFS frames;
                        // it neither invokes the symbolic cursor nor replays calls.
                        let plain_unit_edge = frame.plain_unit_frame
                            && matches!(call, ExactCallEffect::Unit(_))
                            && closed_actual_unit_history_frame(child.body);
                        if plain_unit_edge {
                            trace.borrow_mut().charge_plain_history_frame(child.body).ok_or(ProjectCheck::Unsupported)?;
                            child.plain_unit_frame = true;
                        }
                        if !(qualified_scalar || context_edge || cited_helper || wide_forward || plain_unit_edge || (rank_self && frame.source == child.source)) {
                            return Err(ProjectCheck::Unsupported);
                        }
                        trace.borrow_mut().append(failure_search::PathStep::Call(
                            wosy_syntax::SourceSpan::new(frame.source.clone(), span))).ok_or(ProjectCheck::Unsupported)?;
                        child.cursor.track_startup_path(child.source, Rc::clone(&trace), false).ok_or(ProjectCheck::Unsupported)?;
                        #[cfg(test)]
                        if rank_self || wide_forward { trace.borrow_mut().ranked_entries.push(child.entry.clone().ok_or(ProjectCheck::Unsupported)?); }
                    }
                    frames.push(child);
                }
                ExactCallProgress::Failed(failure) => return Err(project_failure(body, source, failure)),
                ExactCallProgress::Done { active, result } => {
                    self.had_obligations |= active;
                    let completed = frames.pop().unwrap();
                    let Some((target, first_activation, effect, caller_axis)) = completed.target else { return Ok(result); };
                    #[cfg(feature = "internal-checker")]
                    let hypothetical = frames.last().is_some_and(|parent|
                        parent.body.structure.checker_ordinary_directive_calls.contains_key(&effect.occurrence()));
                    #[cfg(not(feature = "internal-checker"))]
                    let hypothetical = false;
                    if !hypothetical { self.note_reached(target); }
                    self.active_depth -= 1;
                    if first_activation { self.active.remove(&target); }
                    #[cfg(feature = "internal-checker")]
                    if NAMED {
                        let site = completed.named_site.ok_or(ProjectCheck::Unsupported)?;
                        if let Some((parameters, entry, proof_work)) = site.observed_entry {
                            let ActualCallResult::Integer(value) = &result else { return Err(ProjectCheck::Unsupported); };
                            let ordered = collection.ok_or(ProjectCheck::Unsupported)?;
                            let outer = wosy_syntax::SourceSpan::new(
                                frames.first().ok_or(ProjectCheck::Unsupported)?.source.clone(),
                                named_root.ok_or(ProjectCheck::Unsupported)?.outer,
                            );
                            let cost = frames.len().saturating_add(proof_work);
                            self.observer.charge_named_exact_work(cost).ok_or(ProjectCheck::Unsupported)?;
                            let intermediate = frames.windows(2)
                                .map(|edge| edge[1].named_site.as_ref()
                                    .map(|site| wosy_syntax::SourceSpan::new(edge[0].source.clone(), site.call)))
                                .collect::<Option<Vec<_>>>().ok_or(ProjectCheck::Unsupported)?;
                            let directive_position = ordered.failures.borrow().records.len();
                            let unary;
                            let pair;
                            let exact: &[&BigInt] = match &entry {
                                NamedStackArguments::Empty => &[],
                                NamedStackArguments::Unary(value) => { unary = [value]; &unary }
                                NamedStackArguments::Pair([first, second]) => { pair = [first, second]; &pair }
                            };
                            self.observer.observe_initializer(target, Some(InitializerProofSite {
                                source: frames.last().ok_or(ProjectCheck::Unsupported)?.source,
                                call: InitializerProofOrigin::Stacked { outer, intermediate, inner: site.call, directive_position,
                                    nested_scalar: site.nested_scalar },
                            }), parameters, exact, value);
                        }
                    }
                    let parent = frames.last_mut().ok_or(ProjectCheck::Unsupported)?;
                    #[cfg(feature = "internal-checker")]
                    if let ActualCallResult::ContextualUnit { entry, exit } = result {
                        if !ACTUAL_STARTUP || NAMED || !matches!(effect, ExactCallEffect::Unit(_))
                            || caller_axis.is_some()
                        {
                            return Err(ProjectCheck::Unsupported);
                        }
                        let (binding, ty) = parent.body.contextual_argument(effect.occurrence())
                            .ok_or(ProjectCheck::Unsupported)?;
                        if let Some(ordered) = collection {
                            let mut effects = ordered.failures.borrow_mut();
                            if let Some(proof) = effects.contextual_proofs.entries.get_mut(&target) {
                                let formal = completed.body.contextual_formal().ok_or(ProjectCheck::Unsupported)?;
                                let span = parent.body.occurrences.get(effect.occurrence().0)
                                    .ok_or(ProjectCheck::Unsupported)?.span;
                                let (original_binding, supplying_call) = completed.contextual_origin
                                    .ok_or(ProjectCheck::Unsupported)?;
                                let previously_refuted = proof.refutation.is_some();
                                proof.observe(completed.body, formal, original_binding, ty, supplying_call,
                                    (parent.source, effect.occurrence(), span), &entry, &exit, completed.contextual_explicit.as_ref(), reused)?;
                                if !previously_refuted && proof.refutation.is_some() {
                                    effects.contextual_proofs.refutations.push(target);
                                    if let Some(trace) = &effects.startup_search {
                                        let mut trace = trace.borrow_mut();
                                        let earlier = trace.named_observations.len();
                                        if let Some(mixed) = &mut trace.mixed_context {
                                            mixed.refuted_after_named.push(earlier);
                                        }
                                    }
                                    if let Some(tap) = &mut effects.mixed_startup {
                                        super::checker_flow::charge_call_work(&mut tap.work, 1).ok_or(ProjectCheck::Unsupported)?;
                                        tap.events.push(MixedStartupEvent::Contextual);
                                    }
                                }
                            }
                        }
                        parent.cursor.resume_exact_local_update(binding, ty, entry, exit)
                            .ok_or(ProjectCheck::Unsupported)?;
                        if let Some(trace) = collection.and_then(|ordered| ordered.failures.borrow().startup_search.clone()) {
                            let mut trace = trace.borrow_mut();
                            let mut roster_complete = false;
                            if let Some(roster) = &mut trace.contextual_roster {
                                let caller = parent.target.map_or(roster.entry, |parent| parent.0);
                                if !self.calls.function_body(caller.0, caller.1, None)
                                    .is_some_and(|original| std::ptr::eq(original, parent.body))
                                { return Err(ProjectCheck::Unsupported); }
                                roster.observe(caller, effect.occurrence(), target).ok_or(ProjectCheck::Unsupported)?;
                                roster_complete = roster.pending.is_empty();
                            } else if let Some(route) = &mut trace.mixed_context {
                                let matches_caller = |caller: PreparedCallable| self.calls.function_body(caller.0, caller.1, None)
                                    .is_some_and(|original| std::ptr::eq(original, parent.body));
                                if route.pending_leaves.front() == Some(&(effect.occurrence(), target))
                                    && route.bridge.is_some_and(matches_caller)
                                {
                                    route.pending_leaves.pop_front();
                                } else if route.pending_leaves.is_empty() && !route.returned_context
                                    && target == route.entry_target && effect.occurrence() == route.entry_site
                                    && matches_caller(route.entry)
                                {
                                    route.returned_context = true;
                                } else {
                                    return Err(ProjectCheck::Unsupported);
                                }
                            } else {
                                return Err(ProjectCheck::Unsupported);
                            }
                            let span = parent.body.occurrences.get(effect.occurrence().0)
                                .ok_or(ProjectCheck::MissingRootOccurrences)?.span;
                            trace.append(failure_search::PathStep::Return(
                                wosy_syntax::SourceSpan::new(parent.source.clone(), span))).ok_or(ProjectCheck::Unsupported)?;
                            if roster_complete && trace.remaining() == 0 {
                                return Err(ProjectCheck::StartupAuthoredLimitReached);
                            }
                        }
                        continue;
                    }
                    #[cfg(feature = "internal-checker")]
                    if guarded_nonreturn && matches!(result, ActualCallResult::EmptyUnit) {
                        let ordered = collection.ok_or(ProjectCheck::Unsupported)?;
                        let mut effects = ordered.failures.borrow_mut();
                        let proof = effects.contextual_proofs.entries.get_mut(&target).ok_or(ProjectCheck::Unsupported)?;
                        if !matches!(proof.amount, super::contextual::ContextualProofAmount::EntryParameter(_)) {
                            return Err(ProjectCheck::Unsupported);
                        }
                        // Only a real direct Narrow failure with no return:
                        // retain its ordinary witness, never manufacture an
                        // exit, summary, or postcondition for this occurrence.
                        proof.saw_guarded_nonreturn = true;
                    }
                    #[cfg(feature = "internal-checker")]
                    if let Some(trace) = collection.and_then(|ordered| ordered.failures.borrow().startup_search.clone()) {
                        let plain_unit_return = parent.plain_unit_frame && completed.plain_unit_frame
                            && matches!(effect, ExactCallEffect::Unit(_));
                        if plain_unit_return && matches!(&result, ActualCallResult::EmptyUnit) {
                            // The exact child's Narrow eliminated the path.
                            // Resume the original continuation as empty, with
                            // no invented Return or subsequent authored work.
                            parent.cursor.resume(effect, caller_axis, result).ok_or(ProjectCheck::Unsupported)?;
                            continue;
                        }
                        let trace_state = trace.borrow();
                        let qualified_scalar = trace_state.proof_free_scalar_initializers && parent.source != completed.source;
                        let cited_helper = NAMED && parent.source == completed.source
                            && self.enrolled_citation_helper(&trace_state, collection, parent.body, effect.occurrence(), target);
                        let eligible_return = if plain_unit_return {
                            matches!(&result, ActualCallResult::Unit)
                        } else {
                            (qualified_scalar || cited_helper || trace_state.ranked_target == Some(target))
                                && matches!(&result, ActualCallResult::Integer(_))
                        };
                        if !eligible_return {
                            return Err(ProjectCheck::Unsupported);
                        }
                        drop(trace_state);
                        let span = parent.body.occurrences.get(effect.occurrence().0)
                            .ok_or(ProjectCheck::MissingRootOccurrences)?.span;
                        let site = wosy_syntax::SourceSpan::new(parent.source.clone(), span);
                        let mut trace = trace.borrow_mut();
                        if parent.source != completed.source && trace.ranked_target == Some(target) {
                            let (outer, inner, arguments) = trace.pending_wide_forward.take().ok_or(ProjectCheck::Unsupported)?;
                            let ActualCallResult::Integer(returned) = &result else { return Err(ProjectCheck::Unsupported); };
                            if inner != site { return Err(ProjectCheck::Unsupported); }
                            trace.wide_rank_observations.push(failure_search::WideRankObservation {
                                target, site: inner, outer: Some(outer), arguments, returned: returned.clone(),
                            });
                        }
                        trace.append(failure_search::PathStep::Return(site)).ok_or(ProjectCheck::Unsupported)?;
                    }
                    parent.cursor.resume(effect, caller_axis, result).ok_or(ProjectCheck::Unsupported)?;
                }
            }
        }
    }

    #[cfg(feature = "internal-checker")]
    fn exact_contextual_debit_forwarder(
        &self, owner: &ScalarModule, body: &FunctionCallSites, parameter: &ScalarType,
        cohort: &ContextualProofCohort,
    ) -> Option<()> {
        use super::reference::{OccurrenceEdge, OccurrenceNode, OccurrenceParent, PlainNameIdentity};
        let (formal, ty) = body.contextual_formal()?;
        let [input] = body.boundary.checker_parameter_bindings.as_deref()? else { return None; };
        if !body.checker_returns_unit() || !body.assignments.is_empty() || !body.arms.is_empty()
            || !body.structure.checker_directives.is_empty() || !body.callable_escapes.is_empty()
        {
            return None;
        }
        let [site] = body.call_occurrences.as_slice() else { return None; };
        let [statement] = body.structure.blocks.get(body.structure.root.0)?.items.as_slice() else { return None; };
        let BlockItemKind::Evaluation { expression: call } = statement.kind else { return None; };
        if call != site.ordinal || body.contextual_argument(call) != Some((formal, ty)) { return None; }
        let selected = body.resolved_call_site(call)?;
        let ResolvedCallTarget::ModuleCallable {
            source, declaration_span, concrete: ConcreteCallSelection::Declaration,
        } = &selected.target else { return None; };
        if source != &owner.source { return None; }
        let (target, _, _, leaf) = self.validated_direct_body(&body.structure, call, source, *declaration_span).ok()?;
        let proof = cohort.entries.get(&target)?;
        if !matches!(proof.amount, super::contextual::ContextualProofAmount::EntryParameter(_))
            || !matches!(body.checked_call_signatures.get(&call)?.parameters.as_slice(), [ty] if ty == parameter)
            || leaf.contextual_formal() != Some((&proof.formal, &proof.ty))
            || &proof.ty != ty || proof.explicit.is_none()
            || !leaf.call_occurrences.is_empty() || !leaf.allocation_length_calls.is_empty()
        {
            return None;
        }
        let OccurrenceNode::Expression(argument) = body.structure.edges.get(&(
            OccurrenceParent::Expression(call), OccurrenceEdge::CallArgument(0),
        ))? else { return None; };
        if !matches!(body.prepared_plain_name(*argument), Some(PlainNameIdentity::Lexical(binding)) if binding == input)
            || body.structure.checked_types.expressions.get(argument) != Some(parameter)
        {
            return None;
        }
        Some(())
    }

    fn prepare_exact_child<const NAMED: bool>(
        &mut self, parent: &mut ExactCallActivation<'project>, effect: ExactCallEffect<'project>,
        collection: Option<OrderedCallCollection<'_, '_>>,
        #[cfg_attr(not(feature = "internal-checker"), allow(unused_variables))] routed_unit: bool,
    ) -> Result<ExactCallActivation<'project>, ProjectCheck> {
        if self.active_depth == MAX_ACTUAL_CALL_DEPTH { return Err(ProjectCheck::Unsupported); }
        let caller = parent.body;
        let call = effect.occurrence();
        let expected = effect.expected();
        let prepared = {
            #[cfg(feature = "internal-checker")]
            if let Some(receipt) = caller.structure.checker_ordinary_directive_calls.get(&call) {
                if !Observer::ORDINARY_INTEGER_LOCALS || collection.is_none() || *expected != ScalarType::Bool {
                    return Err(ProjectCheck::Unsupported);
                }
                let (target, owner, _, body) = self.validated_prepared_body(receipt.target, &receipt.source, receipt.declaration)?;
                if parent.source != &owner.source || !body.structure.checker_directives.is_empty()
                    || !body.call_occurrences.is_empty() || !body.allocation_length_calls.is_empty()
                    || !body.assignments.is_empty() || !body.arms.is_empty()
                    || !body.structure.checker_selected_snapshots.is_empty()
                    || !body.structure.checker_contextual_occurrences.is_empty()
                {
                    return Err(ProjectCheck::Unsupported);
                }
                let signature = caller.structure.checker_directives.get(&call)
                    .and_then(|directive| directive.call_signature.as_ref()).ok_or(ProjectCheck::MissingRootOccurrences)?;
                Some((target, owner, body, signature))
            } else { None }
            #[cfg(not(feature = "internal-checker"))]
            { None }
        };
        let (target, owner, body, signature) = if let Some(prepared) = prepared {
            prepared
        } else {
            let site = caller.resolved_call_site(call).ok_or(ProjectCheck::MissingRootOccurrences)?;
            let ResolvedCallTarget::ModuleCallable { source, declaration_span, concrete: ConcreteCallSelection::Declaration } =
                &site.target else { return Err(ProjectCheck::Unsupported); };
            let (target, owner, _, body) = self.validated_direct_body(&caller.structure, call, source, *declaration_span)?;
            let signature = caller.checked_call_signatures.get(&call).ok_or(ProjectCheck::Unsupported)?;
            (target, owner, body, signature)
        };
        #[cfg(feature = "internal-checker")]
        let unary_context = ACTUAL_STARTUP && !NAMED && Observer::PROOF_FREE_CONTEXTUAL_LOCAL_TRANSFERS
            && matches!(signature.parameters.as_slice(), [ty] if is_integer_type(ty))
            && matches!(body.boundary.parameters.as_slice(), [slot] if slot.ordinal == 0 && Some(&slot.ty) == signature.parameters.first())
            && body.allocation_length_calls.is_empty()
            && collection.is_some_and(|ordered| {
                let effects = ordered.failures.borrow();
                let cohort = &effects.contextual_proofs;
                if let Some(proof) = cohort.entries.get(&target) {
                    body.call_occurrences.is_empty() && proof.explicit.is_some()
                        && body.contextual_formal() == Some((&proof.formal, &proof.ty))
                } else {
                    self.exact_contextual_debit_forwarder(owner, body, &signature.parameters[0], cohort).is_some()
                }
            });
        #[cfg(feature = "internal-checker")]
        let contextual_entry = match (caller.contextual_argument(call), body.contextual_formal()) {
            (None, None) => None,
            (Some((binding, ty)), Some((formal, formal_ty)))
                if ACTUAL_STARTUP && !NAMED && Observer::PROOF_FREE_CONTEXTUAL_LOCAL_TRANSFERS
                    && collection.is_some_and(|ordered| parent.source == &owner.source
                        || self.completed_namespace_call(parent.source, owner, target.0, body, signature, expected, ordered.visits))
                    && ty == formal_ty
                    && matches!(effect, ExactCallEffect::Unit(_))
                    && ((signature.parameters.is_empty() && body.boundary.parameters.is_empty()) || unary_context)
                    && !self.active.contains(&target)
                    && matches!(signature.outputs.outputs.as_slice(), [out] if out.ty == ScalarType::Unit) =>
            {
                let ordered = collection.ok_or(ProjectCheck::Unsupported)?;
                super::checker_flow::charge_call_work(
                    &mut ordered.failures.borrow_mut().contextual_call_work,
                    body.occurrences.len().saturating_add(1),
                ).ok_or(ProjectCheck::Unsupported)?;
                let origin = if matches!(binding.kind, super::ReferenceBindingKind::ContextualFormal) {
                    parent.contextual_origin.ok_or(ProjectCheck::Unsupported)?
                } else {
                    (binding, caller.occurrences.get(call.0).ok_or(ProjectCheck::Unsupported)?.span)
                };
                Some((formal, formal_ty, parent.cursor.contextual_singleton(binding, ty)
                    .ok_or(ProjectCheck::Unsupported)?.clone(), origin))
            }
            _ => return Err(ProjectCheck::Unsupported),
        };
        #[cfg(feature = "internal-checker")]
        let watched = if NAMED || ACTUAL_STARTUP { self.observer.named_exact_watch(target) } else { None };
        #[cfg(feature = "internal-checker")]
        let named_span = if NAMED {
            Some(caller.occurrences.get(call.0).ok_or(ProjectCheck::MissingRootOccurrences)?.span)
        } else { None };
        #[cfg(feature = "internal-checker")]
        let cross_source_leaf = watched.is_some_and(|watch| watch.qualified_leaf && watch.literal_leaf.is_none())
            && collection.is_some_and(|ordered|
                completed_namespace_owner(parent.source, &owner.source, target.0, ordered.visits));
        #[cfg(feature = "internal-checker")]
        let routed_parent = NAMED && ACTUAL_STARTUP && parent.named_nested_scalars;
        #[cfg(feature = "internal-checker")]
        let nested_scalar = routed_parent && (parent.source == &owner.source || cross_source_leaf)
            && watched.is_some_and(|watch| watch.supports_nested_scalar())
            && named_span.is_some_and(|span| self.calls.exact_nested_scalar_proof_sites(target)
                .is_some_and(|sites| sites.contains(&wosy_syntax::SourceSpan::new(parent.source.clone(), span))))
            && (if *expected == ScalarType::Bool { pure_literal_proof_leaf(body, ProofLiteralType::Boolean) }
                else { qualified_integer_proof_leaf(body, expected) });
        #[cfg(feature = "internal-checker")]
        let cross_source_unit = routed_parent && routed_unit && parent.source != &owner.source
            && self.observer.named_nested_scalar_route(target)
            && body.checker_pure_calling_frame()
            && collection.is_some_and(|ordered|
                self.completed_namespace_call(parent.source, owner, target.0, body, signature, expected, ordered.visits));
        #[cfg(feature = "internal-checker")]
        let ordinary_named = nested_scalar || cross_source_unit || (routed_parent && parent.source == &owner.source
            && (routed_unit || self.observer.named_nested_scalar_route(target)));
        #[cfg(not(feature = "internal-checker"))]
        let ordinary_named = false;
        #[cfg(feature = "internal-checker")]
        if (!nested_scalar && watched.is_some_and(|watch| watch.qualified_leaf || watch.literal_leaf.is_some() || watch.result_pair
            || (!NAMED && (watch.citation || watch.case_citation))))
            || (Observer::FIXED_ARRAY_INITIALIZERS && self.observer.watches_fixed_array(target))
        {
            // A previously observed call to this target does not authenticate
            // a different activation outside its enrolled exact path.
            return Err(ProjectCheck::Unsupported);
        }
        #[cfg(feature = "internal-checker")]
        if NAMED && ((parent.source != &owner.source && !nested_scalar && !cross_source_unit)
            || self.active.contains(&target)
            || !(if routed_unit { ordinary_named && *expected == ScalarType::Unit && body.checker_named_route_frame() }
                else { matches!(effect, ExactCallEffect::Scalar { binding: Some(_), .. })
                    && citation_safe_calling_body(body) })
            || !(if ordinary_named { named_nested_scalar_parameters(&signature.parameters, expected) }
                else { is_integer_type(expected) && named_stack_parameters(&signature.parameters) }))
        {
            return Err(ProjectCheck::Unsupported);
        }
        #[cfg(feature = "internal-checker")]
        if NAMED {
            self.charge_named_exact_frame(body)?;
        }
        #[cfg(feature = "internal-checker")]
        if self.observer.citation_only() && (parent.source != &owner.source || !citation_safe_calling_body(body)) {
            return Err(ProjectCheck::Unsupported);
        }
        #[cfg(feature = "internal-checker")]
        let named_pair = !ACTUAL_STARTUP && self.observer.named_pair();
        #[cfg(not(feature = "internal-checker"))]
        let named_pair = false;
        #[cfg(feature = "internal-checker")]
        let named_mixed_pair = named_pair && self.observer.named_mixed_pair();
        #[cfg(not(feature = "internal-checker"))]
        let named_mixed_pair = false;
        #[cfg(feature = "internal-checker")]
        if named_mixed_pair && !named_exact_mixed_pair(&signature.parameters, |ty| ty) {
            return Err(ProjectCheck::Unsupported);
        }
        if named_pair && (!matches!(effect, ExactCallEffect::Scalar { binding: Some(_), .. }) || !is_integer_type(expected)) {
            return Err(ProjectCheck::Unsupported);
        }
        #[cfg(feature = "internal-checker")]
        if named_pair {
            self.observer.charge_named_pair_activation(body).ok_or(ProjectCheck::Unsupported)?;
        }
        // The generic tail-call corridor still rejects active targets.
        // Only the enrolled original typed self-tail site may proceed to
        // the existing checked-decrement/strict-descent admission below.
        #[cfg(feature = "internal-checker")]
        let wide_recipe = collection.and_then(|ordered| {
            let effects = ordered.failures.borrow();
            let trace = effects.startup_search.as_ref()?.borrow();
            let recipe = trace.wide_rank_recipe.as_ref()?;
            (recipe.target == target && recipe.site == call && std::ptr::eq(caller, body)
                && parent.source == &owner.source
                && ordered.startup_site_source.is_some_and(|startup| trace.owns_initialization(startup)
                    && (startup == parent.source || (trace.named_cross_source
                        && completed_namespace_owner(startup, parent.source, target.0, ordered.visits)))))
                .then(|| Rc::clone(recipe))
        });
        #[cfg(feature = "internal-checker")]
        let forward_recipe = collection.and_then(|ordered| {
            let effects = ordered.failures.borrow();
            let trace = effects.startup_search.as_ref()?.borrow();
            let recipe = trace.wide_rank_recipe.as_ref()?;
            let (wrapper, occurrence) = recipe.forwarder?;
            let outer = ordered.startup_site?;
            let startup = ordered.startup_site_source?;
            (matches!(effect, ExactCallEffect::TailInteger { .. }) && !NAMED && occurrence == call
                && recipe.target == target && parent.source == startup && trace.owns_initialization(startup)
                && trace.required_sites.get(&outer.occurrence) == Some(&(wrapper, failure_search::StartupProofRole::Ranked))
                && self.calls.function_body(wrapper.0, wrapper.1, None).is_some_and(|actual| std::ptr::eq(actual, caller))
                && completed_namespace_owner(startup, &owner.source, target.0, ordered.visits))
                .then(|| Rc::clone(recipe))
        });
        #[cfg(not(feature = "internal-checker"))]
        let forward_recipe: Option<()> = None;
        #[cfg(not(feature = "internal-checker"))]
        let wide_recipe: Option<()> = None;
        #[cfg(feature = "internal-checker")]
        let traced_self = matches!(effect, ExactCallEffect::TailInteger { .. })
            && !NAMED && std::ptr::eq(caller, body)
            && (caller.self_tail_candidates.contains(&call) || wide_recipe.is_some()) && !parent.followed_self_edge
            && parent.entry.is_some() && self.traces_original_startup_rank(body, collection);
        #[cfg(not(feature = "internal-checker"))]
        let traced_self = false;
        #[cfg(feature = "internal-checker")]
        if matches!(effect, ExactCallEffect::TailInteger { .. }) {
            if collection.is_none() || (parent.source != &owner.source && forward_recipe.is_none()) || (self.active.contains(&target) && !traced_self) {
                return Err(ProjectCheck::Unsupported);
            }
            if !ACTUAL_STARTUP {
                use super::reference::{OccurrenceEdge, OccurrenceNode, OccurrenceParent, PlainNameIdentity};
                let lexical_argument = match caller.structure.edges.get(&(
                    OccurrenceParent::Expression(call), OccurrenceEdge::CallArgument(0),
                )) {
                    Some(OccurrenceNode::Expression(argument)) => {
                        matches!(caller.prepared_plain_name(*argument), Some(PlainNameIdentity::Lexical(_)))
                            && signature.parameters.first() == caller.structure.checked_types.expressions.get(argument)
                    }
                    _ => false,
                };
                if !lexical_argument || !parent.cursor.discards_symbolic_integer_return()
                    || !self.observer.permits_ordinary_projected_effects()
                    || !matches!(signature.parameters.as_slice(), [ty] if is_integer_type(ty))
                    || !body.call_occurrences.is_empty() || !body.allocation_length_calls.is_empty()
                    || !body.assignments.is_empty() || !body.arms.is_empty()
                    || !body.structure.checker_directives.is_empty()
                    || body.structure.has_ordinary_contextual_places()
                    || body.structure.checker_has_bool_contextual_declaration
                    || !body.structure.checker_selected_snapshots.is_empty()
                {
                    return Err(ProjectCheck::Unsupported);
                }
            } else if !Observer::REAL_INTEGER_TAIL_CALLS && !traced_self {
                return Err(ProjectCheck::Unsupported);
            }
        }
        #[cfg(feature = "internal-checker")]
        let enrolled_cross_source_leaf = nested_scalar && cross_source_leaf;
        #[cfg(not(feature = "internal-checker"))]
        let enrolled_cross_source_leaf = false;
        if collection.is_some_and(|collection| parent.source != &owner.source && !enrolled_cross_source_leaf && forward_recipe.is_none()
            && !self.completed_namespace_call(parent.source, owner, target.0, body, signature, expected, collection.visits))
        {
            return Err(ProjectCheck::Unsupported);
        }
        let real_bound_boolean = matches!(effect, ExactCallEffect::Scalar { binding: Some(_), .. })
            && self.exact_boolean_narrow_profile(expected, collection.is_some());
        let boolean_narrow = real_bound_boolean && Self::exact_boolean_narrow_body_has_supported_shape(body);
        let projected_narrow = self.projected_integer_narrow_shape(body, effect, collection.is_some());
        if !matches!(signature.outputs.outputs.as_slice(), [output] if &output.ty == expected)
            || (*expected != ScalarType::Unit && (!(NAMED || Observer::EXACT_INTEGER_CALL_CONTINUATIONS || traced_self)
                || !(supported_integer_continuation_shape_for(body, expected, ordinary_named || Observer::ORDINARY_INTEGER_LOCALS)
                    || boolean_narrow || self.exact_integer_narrow_shape(body, expected, collection.is_some())
                    || self.exact_integer_local_write_shape(body, expected, collection.is_some())
                    || projected_narrow)))
        {
            return Err(ProjectCheck::Unsupported);
        }
        let real_integer_input = self.real_integer_input_profile(expected, collection.is_some());
        if signature.parameters.is_empty()
            && matches!(effect, ExactCallEffect::Scalar { binding: Some(_), ty, .. } if is_integer_type(ty))
            && !real_integer_input
        {
            return Err(ProjectCheck::Unsupported);
        }
        #[cfg(feature = "internal-checker")]
        let named_affine_partitions = !ACTUAL_STARTUP && Observer::NAMED_RELATIONAL_PARTITIONS
            && parent.cursor.observes_named_affine_partitions();
        #[cfg(feature = "internal-checker")]
        let wide_values = if let Some(recipe) = &wide_recipe {
            if !traced_self || !self.active.contains(&target) || !body.assignments.is_empty() {
                return Err(ProjectCheck::Unsupported);
            }
            let ordered = collection.ok_or(ProjectCheck::Unsupported)?;
            ordered.failures.borrow().startup_search.as_ref().ok_or(ProjectCheck::Unsupported)?
                .borrow_mut().charge_formal_replay(1, recipe.work().ok_or(ProjectCheck::Unsupported)?)
                .ok_or(ProjectCheck::Unsupported)?;
            Some(recipe.compute(caller, &parent.cursor, &signature.parameters).ok_or(ProjectCheck::Unsupported)?)
        } else if let Some(recipe) = &forward_recipe {
            let ordered = collection.ok_or(ProjectCheck::Unsupported)?;
            let startup_site = ordered.startup_site.ok_or(ProjectCheck::Unsupported)?;
            let outer_range = startup_site.topology.occurrences.get(startup_site.occurrence.0).ok_or(ProjectCheck::Unsupported)?.span;
            let inner_range = caller.occurrences.get(call.0).ok_or(ProjectCheck::Unsupported)?.span;
            let effects = ordered.failures.borrow();
            let mut trace = effects.startup_search.as_ref().ok_or(ProjectCheck::Unsupported)?.borrow_mut();
            if trace.pending_wide_forward.is_some() { return Err(ProjectCheck::Unsupported); }
            trace.charge_formal_replay(1, recipe.work().ok_or(ProjectCheck::Unsupported)?).ok_or(ProjectCheck::Unsupported)?;
            let formals = caller.boundary.checker_parameter_bindings.as_deref().ok_or(ProjectCheck::Unsupported)?;
            if formals.len() != signature.parameters.len() { return Err(ProjectCheck::Unsupported); }
            let tuple = formals.iter().zip(&signature.parameters)
                .map(|(binding, ty)| parent.cursor.contextual_singleton(binding, ty))
                .collect::<Option<Vec<_>>>().ok_or(ProjectCheck::Unsupported)?;
            if !recipe.accepts(&tuple) { return Err(ProjectCheck::Unsupported); }
            let values = tuple.into_iter().cloned().collect::<Vec<_>>();
            trace.pending_wide_forward = Some((
                wosy_syntax::SourceSpan::new(parent.source.clone(), outer_range),
                wosy_syntax::SourceSpan::new(parent.source.clone(), inner_range), values.clone()));
            Some(values)
        } else { None };
        #[cfg(not(feature = "internal-checker"))]
        let wide_values: Option<Vec<BigInt>> = None;
        let arguments = if wide_values.is_some() { NestedIntegerArgument::Single(None) } else { parent.cursor.arguments(
            caller, call, signature.parameters.len(), collection.is_some(), Observer::INTEGER_RETURN_PARTITIONS,
            Observer::ORDINARY_PROJECTED_PAIR || named_pair,
            Observer::ORDINARY_PROJECTED_PAIR || named_pair,
            NAMED || named_mixed_pair || (Observer::ORDINARY_INTEGER_LOCALS && (matches!(*expected, ScalarType::Unit | ScalarType::Bool)
                || real_integer_input)),
        )
            .ok_or(ProjectCheck::Unsupported)? };
        if let NestedIntegerArgument::Projected(mut projection) = arguments {
            #[cfg(feature = "internal-checker")]
            if contextual_entry.is_some() { return Err(ProjectCheck::Unsupported); }
            if !Observer::INTEGER_RETURN_PARTITIONS
                || (!Observer::PROJECTED_FORMAL_WRITES && !body.assignments.is_empty())
                || self.active.contains(&target)
                || (projected_narrow && !matches!(projection.companion, ProjectedCompanion::Unary))
                || !projected_call_types_match(signature, body, &projection)
                || (!matches!(projection.companion, ProjectedCompanion::Unary) && !Observer::ORDINARY_PROJECTED_PAIR
                    && !(named_pair && matches!(projection.companion, ProjectedCompanion::Independent { .. })))
                || (matches!(projection.companion, ProjectedCompanion::Equal | ProjectedCompanion::Independent { .. })
                    && !body.assignments.is_empty())
            {
                return Err(ProjectCheck::Unsupported);
            }
            #[allow(unused_mut)]
            let mut cursor = if let ProjectedCompanion::Independent { axis, .. } = projection.companion {
                ExactCallCursor::projected_pair(body, &mut projection, axis, expected)
            } else {
                let values = projection.materialize_bounded().ok_or(ProjectCheck::Unsupported)?;
                ExactCallCursor::projected_arguments(body, values, &projection, expected)
            }.ok_or(ProjectCheck::Unsupported)?;
            #[cfg(feature = "internal-checker")]
            let pure_projection_leaf = !named_mixed_pair && (named_pair || named_affine_partitions)
                && parent.source == &owner.source && body.call_occurrences.is_empty()
                && citation_safe_calling_body(body)
                && body.structure.blocks.get(body.structure.root.0).and_then(|block| block.items.last())
                    .is_some_and(|item| matches!(&item.kind, BlockItemKind::FinalOutput(slot)
                        if matches!(body.structure.checker_integer_final_operations.get(&slot.expression),
                            Some((BinaryOperator::Add | BinaryOperator::Subtract, _)))));
            #[cfg(feature = "internal-checker")]
            if named_pair && matches!(projection.companion, ProjectedCompanion::Independent { .. }) {
                let bool_axis = if named_mixed_pair {
                    signature.parameters.iter().position(|ty| *ty == ScalarType::Bool)
                } else { None };
                cursor.require_named_pair_rectangles(pure_projection_leaf, bool_axis).ok_or(ProjectCheck::Unsupported)?;
            }
            #[cfg(feature = "internal-checker")]
            if (named_affine_partitions || named_pair) && is_integer_type(expected)
                && matches!(projection.companion, ProjectedCompanion::Unary)
            {
                cursor.observe_named_affine_partitions(pure_projection_leaf).ok_or(ProjectCheck::Unsupported)?;
            }
            #[cfg(feature = "internal-checker")]
            if projected_narrow { cursor.allow_empty_projected_integer().ok_or(ProjectCheck::Unsupported)?; }
            #[cfg(feature = "internal-checker")]
            if !ACTUAL_STARTUP && collection.is_some() && self.observer.permits_ordinary_projected_effects()
                && matches!(effect, ExactCallEffect::Scalar { binding: Some(_), ty, .. } if is_integer_type(ty))
                && matches!(projection.companion, ProjectedCompanion::Unary)
            {
                cursor.allow_projected_scalar_local_write().ok_or(ProjectCheck::Unsupported)?;
            }
            self.active.insert(target);
            self.active_depth += 1;
            return Ok(ExactCallActivation {
                body, source: &owner.source, cursor, entry: None, followed_self_edge: false,
                #[cfg(feature = "internal-checker")]
                named_site: None,
                #[cfg(feature = "internal-checker")]
                named_nested_scalars: false,
                #[cfg(feature = "internal-checker")]
                plain_unit_frame: false,
                #[cfg(feature = "internal-checker")]
                contextual_origin: None,
                #[cfg(feature = "internal-checker")]
                contextual_explicit: None,
                #[cfg(feature = "internal-checker")]
                verified_contextual_result: None,
                target: Some((target, true, effect, Some(projection.caller_axis))),
            });
        }
        // Only the unary projected evaluator has this partial-return contract.
        if projected_narrow { return Err(ProjectCheck::Unsupported); }
        let restricted_local_writes = self.exact_integer_local_write_shape(body, expected, collection.is_some());
        if *expected != ScalarType::Unit && !body.assignments.is_empty() && !restricted_local_writes {
            return Err(ProjectCheck::Unsupported);
        }
        // Mutating integer-return bodies cannot use the ranked self proof.
        let ranked = !restricted_local_writes && (traced_self || self.exact_self_reentry_allowed(expected, collection.is_some()))
            && (*expected == ScalarType::Unit || matches!(signature.parameters.as_slice(), [ty] if is_integer_type(ty)));
        let argument;
        let pair;
        #[cfg(feature = "internal-checker")]
        let computed;
        let wide_refs;
        let exact: &[&BigInt] = if let Some(values) = &wide_values {
            wide_refs = values.iter().collect::<Vec<_>>();
            &wide_refs
        } else { match (signature.parameters.as_slice(), body.boundary.parameters.as_slice(), arguments) {
            ([], [], NestedIntegerArgument::Single(None)) => &[],
            ([parameter], [slot], NestedIntegerArgument::Single(Some((ty, value)))) if *parameter == slot.ty && parameter == ty => {
                argument = [value];
                &argument
            }
            #[cfg(feature = "internal-checker")]
            ([parameter], [slot], NestedIntegerArgument::Single(None)) if *parameter == slot.ty => {
                if !ranked || !std::ptr::eq(caller, body) || parent.followed_self_edge {
                    return Err(ProjectCheck::Unsupported);
                }
                computed = self.computed_self_descent(caller, call, parameter,
                    parent.entry.as_ref().ok_or(ProjectCheck::Unsupported)?)?;
                argument = [&computed];
                &argument
            }
            ([first_param, second_param], [first_slot, second_slot], NestedIntegerArgument::Pair((first_ty, first), (second_ty, second)))
                if *first_ty == first_slot.ty && *second_ty == second_slot.ty
                    && first_ty == first_param && second_ty == second_param =>
            {
                pair = [first, second];
                &pair
            }
            _ => return Err(ProjectCheck::Unsupported),
        } };
        #[cfg(feature = "internal-checker")]
        let named_site = if let Some(span) = named_span {
            let observed_entry = if let Some(NamedExactWatch { nested_work, .. }) = watched {
                let values = match exact {
                    [] if nested_scalar => NamedStackArguments::Empty,
                    [value] => NamedStackArguments::Unary((*value).clone()),
                    [first, second] => NamedStackArguments::Pair([(*first).clone(), (*second).clone()]),
                    _ => return Err(ProjectCheck::Unsupported),
                };
                Some((signature.parameters.as_slice(), values, nested_work))
            } else {
                None
            };
            Some(NamedStackSite { call: span, observed_entry, nested_scalar })
        } else { None };
        let first_activation = !self.active.contains(&target);
        if !first_activation && wide_values.is_none() && !matches!(
            (parent.entry.as_ref(), exact),
            (Some(previous), [value]) if ranked && !parent.followed_self_edge && std::ptr::eq(caller, body)
                && value.sign() != num_bigint::Sign::Minus && *value < previous
        ) {
            return Err(ProjectCheck::Unsupported);
        }
        #[allow(unused_mut)]
        let mut cursor = ExactCallCursor::new(body, exact, expected).ok_or(ProjectCheck::Unsupported)?;
        #[cfg(feature = "internal-checker")]
        let (contextual_origin, contextual_explicit, verified_contextual_result) = if let Some((formal, ty, value, origin)) = contextual_entry {
            let span = caller.occurrences.get(call.0).ok_or(ProjectCheck::Unsupported)?.span;
            let explicit = match exact {
                [] if !unary_context => None,
                [value] if unary_context => Some((*value).clone()),
                _ => return Err(ProjectCheck::Unsupported),
            };
            let verified_exit = collection.and_then(|ordered| {
                let effects = ordered.failures.borrow();
                effects.contextual_proofs.entries.get(&target)?.reusable_exit(
                    target, body, origin.0, ty, (parent.source, call, span), &value, explicit.as_ref(),
                ).cloned()
            });
            let verified_result = if let Some(exit) = verified_exit {
                Some((value, exit))
            } else {
                let guarded_resource = explicit.is_some() && collection.is_some_and(|ordered|
                    ordered.failures.borrow().contextual_proofs.entries.get(&target).is_some_and(|proof|
                        matches!(proof.amount, super::contextual::ContextualProofAmount::EntryParameter(_))));
                cursor.enter_contextual_unit(formal, ty, value, guarded_resource).ok_or(ProjectCheck::Unsupported)?;
                None
            };
            (Some(origin), explicit, verified_result)
        } else { (None, None, None) };
        #[cfg(feature = "internal-checker")]
        if (NAMED && !ordinary_named) || named_mixed_pair {
            cursor.allow_named_exact_bool_parameters().ok_or(ProjectCheck::Unsupported)?;
        }
        #[cfg(feature = "internal-checker")]
        if ACTUAL_STARTUP && collection.is_some() && *expected == ScalarType::Unit && Observer::EXACT_CONTEXTUAL_BOOLEAN_UNIT
            && body.structure.checker_has_bool_contextual_declaration
        {
            cursor.allow_exact_contextual_bool();
        }
        #[cfg(feature = "internal-checker")]
        if ACTUAL_STARTUP && collection.is_some() && Observer::REAL_EXTENDED_SCALAR_LOCALS
            && body.structure.checker_has_extended_scalar_local
        {
            cursor.allow_extended_scalar_locals();
        }
        #[cfg(feature = "internal-checker")]
        if ACTUAL_STARTUP && collection.is_some() && (Observer::REAL_INTEGER_TAIL_CALLS || traced_self) && is_integer_type(expected)
            && !body.structure.checker_direct_targets.is_empty()
        {
            cursor.allow_real_integer_tail_call();
        }
        #[cfg(feature = "internal-checker")]
        if (is_integer_type(expected) && self.exact_integer_narrow_profile(collection.is_some())) || real_bound_boolean {
            cursor.allow_empty_scalar_return();
        }
        #[cfg(feature = "internal-checker")]
        if restricted_local_writes { cursor.restrict_returning_writes_to_direct_locals(); }
        if first_activation {
            self.active.insert(target);
        } else {
            parent.followed_self_edge = true;
        }
        self.active_depth += 1;
        Ok(ExactCallActivation {
            body, source: &owner.source, cursor,
            entry: if traced_self || forward_recipe.is_some() { exact.first().copied() } else { self.exact_self_entry(Some(exact)) }.cloned(),
            followed_self_edge: false,
            #[cfg(feature = "internal-checker")]
            named_site,
            #[cfg(feature = "internal-checker")]
            named_nested_scalars: ordinary_named,
            #[cfg(feature = "internal-checker")]
            plain_unit_frame: false,
            #[cfg(feature = "internal-checker")]
            contextual_origin,
            #[cfg(feature = "internal-checker")]
            contextual_explicit,
            #[cfg(feature = "internal-checker")]
            verified_contextual_result,
            target: Some((target, first_activation, effect, None)),
        })
    }

    fn run(
        &mut self,
        structure: &OccurrenceStructure,
        call: OccurrenceOrdinal,
        signature: &CheckedCallSignature,
        projected: ActualProjectedArguments<'_>,
        target_source: &SourceIdentity,
        target_span: ByteSpan,
        expected: &ScalarType,
        pair_receivers: Option<&[BindingReceiverSlot]>,
        module_bool_initializer: bool,
        collection: Option<(&SourceIdentity, OrderedCallCollection<'_, '_>)>,
        #[cfg(feature = "internal-checker")] mut proof_site: Option<InitializerProofSite<'_>>,
    ) -> Result<ActualCallResult, ProjectCheck> {
        let (target, owner, function, body) = self.validated_direct_body(structure, call, target_source, target_span)?;
        #[cfg(feature = "internal-checker")]
        let (startup_named, startup_plain_scalar, startup_ranked, startup_cited, startup_wide_rank, plain_unit_root) = if let Some((caller, ordered)) = collection.filter(|(_, ordered)| ordered.failures.borrow().startup_search.is_some()) {
            let effects = ordered.failures.borrow();
            let mut search = effects.startup_search.as_ref().ok_or(ProjectCheck::Unsupported)?.borrow_mut();
            use failure_search::StartupProofRole::{Aggregate, Bare, Cited, Ranked};
            let pending = search.required_sites.get(&call).filter(|_| search.owns_initialization(caller));
            let matches_aggregate = pending == Some(&(target, Aggregate))
                && matches!(expected, ScalarType::Array { .. })
                && self.observer.watches_fixed_array(target) && proof_site.is_some()
                && body.checker_pure_calling_frame();
            let matches_named = pending == Some(&(target, Bare)) && is_integer_type(expected)
                && (signature.parameters.len() == 1
                    || (caller == &owner.source && search.binary_bare.contains(&target)
                        && matches!(signature.parameters.as_slice(), [first, second] if is_integer_type(first) && is_integer_type(second))))
                && ordered.scalar_initializer.is_some();
            let plain_scalar_wrapper = search.proof_free_scalar_initializers && caller == &owner.source
                && closed_startup_qualified_scalar_wrapper(body, &owner.source);
            let matches_plain_scalar = search.proof_free_scalar_initializers
                && ordered.startup_site.is_some()
                && ((is_integer_type(expected) || (module_bool_initializer && *expected == ScalarType::Bool))
                    && closed_startup_scalar_history(body)
                    || (signature.parameters.len() == 1 && is_integer_type(expected) && plain_scalar_wrapper));
            let matches_wide_rank = pending == Some(&(target, Ranked))
                && (caller == &owner.source || search.allows_qualified_scalar_proof(caller, call, target))
                && ordered.scalar_initializer.is_some() && search.wide_rank_recipe.as_ref().is_some_and(|recipe| recipe.target == target || recipe.forwarder.is_some_and(|(wrapper, _)| wrapper == target))
                && (3..=MAX_RANKED_INTEGER_AXES).contains(&signature.parameters.len());
            let matches_ranked = pending == Some(&(target, Ranked))
                && (caller == &owner.source || search.allows_qualified_scalar_proof(caller, call, target))
                && ordered.scalar_initializer.is_some() && (signature.parameters.len() == 1 || matches_wide_rank) && is_integer_type(expected);
            let matches_cited = pending == Some(&(target, Cited)) && search.cited_routes.contains_key(&target)
                && caller == &owner.source && ordered.scalar_initializer.is_some() && signature.parameters.len() == 1
                && is_integer_type(expected);
            let matches_context_entry = (search.contextual_roster.as_ref().is_some_and(|route|
                target == route.entry && route.root_site == call && !route.pending.is_empty())
                || search.mixed_context.as_ref().is_some_and(|route| target == route.entry && route.root_site == call && !route.finished))
                && caller == &owner.source && *expected == ScalarType::Unit && signature.parameters.is_empty();
            let matches_pointee_entry = Observer::EXACT_POINTEE_UPDATE
                && search.pointee_route.as_ref().is_some_and(|route| route.caller == target && route.startup_site == call)
                && search.owns_initialization(caller) && caller == &owner.source
                && *expected == ScalarType::Unit && signature.parameters.is_empty();
            if search.pointee_route.is_some() && !matches_pointee_entry { return Err(ProjectCheck::Unsupported); }
            // Once the named route spends its ordinary quota, only the
            // pending, top-level authenticated binding calls may run.
            if search.proof_only_continuation() && search.pending_named_startup_observation()
                && !(matches_named || matches_ranked || matches_aggregate || matches_context_entry || matches_cited)
            { return Err(ProjectCheck::Unsupported); }
            let snapshot_candidate = search.proof_free_scalar_initializers && caller == &owner.source
                && *expected == ScalarType::Unit && !body.structure.checker_selected_snapshots.is_empty();
            let matches_plain_snapshot = snapshot_candidate && closed_affine_snapshot_history(body);
            let plain_unit_tree = search.proof_free_scalar_initializers && *expected == ScalarType::Unit
                && !body.call_occurrences.is_empty() && closed_actual_unit_history_frame(body);
            let ordinary_qualified = search.proof_free_scalar_initializers
                && (matches_plain_scalar || plain_unit_tree || (*expected == ScalarType::Unit
                    && body.checker_named_route_frame() && literal_history_directives(body)));
            let cross_proof = matches_aggregate || matches_ranked
                || (matches_named && search.allows_qualified_scalar_proof(caller, call, target)
                    && qualified_integer_proof_leaf(body, expected));
            let cross_authorized = caller != &owner.source && if cross_proof {
                // Both exact proof routes still consume the canonical typed site
                // below; no ordinary observer capability is granted.
                completed_namespace_owner(caller, &owner.source, target.0, ordered.visits)
            } else {
                ordinary_qualified && self.completed_namespace_call(caller, owner, target.0, body, signature, expected, ordered.visits)
            };
            if !ACTUAL_STARTUP || (*expected != ScalarType::Unit && !matches_named && !matches_plain_scalar && !matches_ranked && !matches_aggregate && !matches_cited)
                || (caller != &owner.source && !cross_authorized)
                || ordered.startup_site_source != Some(caller)
                || !ordered.startup_site.is_some_and(|site|
                    std::ptr::eq(&site.topology.structure, structure) && site.occurrence == call)
                || (!matches_plain_scalar && !matches_plain_snapshot && !matches_context_entry && !matches_pointee_entry && !body.checker_named_route_frame()) || (!matches_ranked && !matches_cited && !matches_context_entry && !matches_pointee_entry && !plain_scalar_wrapper && !plain_unit_tree && (!body.call_occurrences.is_empty()
                    || !body.structure.checker_direct_targets.is_empty()))
                || (!matches_plain_snapshot && !body.structure.checker_selected_snapshots.is_empty())
                || !body.structure.module_storage_uses.is_empty()
                || !body.callable_escapes.is_empty()
                || !function.generic_parameters.is_empty() || !function.overload_arms.is_empty()
                || (!matches_plain_scalar && !signature.parameters.iter().all(is_integer_type))
            { return Err(ProjectCheck::Unsupported); }
            if plain_unit_tree {
                search.charge_plain_history_frame(body).ok_or(ProjectCheck::Unsupported)?;
            }
            (matches_named, matches_plain_scalar, matches_ranked, matches_cited, matches_wide_rank, plain_unit_tree)
        } else { (false, false, false, false, false, false) };
        #[cfg(feature = "internal-checker")]
        let collection = collection.map(|(caller, ordered)| (caller, OrderedCallCollection { plain_unit_root, ..ordered }));
        #[cfg(feature = "internal-checker")]
        if body.contextual_formal().is_some() {
            // Only the exact child activation path can install a formal.
            return Err(ProjectCheck::Unsupported);
        }
        #[cfg(feature = "internal-checker")]
        if self.observer.citation_only() && !collection.is_some_and(|(caller_source, _)|
            caller_source == &owner.source && citation_safe_calling_body(body))
        {
            return Err(ProjectCheck::Unsupported);
        }
        #[cfg(feature = "internal-checker")]
        let named_watch = if ACTUAL_STARTUP { self.observer.named_exact_watch(target) } else { None };
        #[cfg(feature = "internal-checker")]
        let named_literal = named_watch.filter(|watch|
            watch.literal_leaf.is_some_and(|leaf| leaf.ty() == expected)
                || (watch.result_pair && pair_receivers.is_some()));
        #[cfg(feature = "internal-checker")]
        let named_outer = proof_site.as_ref().filter(|_| named_literal.is_none()).and_then(|site| match &site.call {
            InitializerProofOrigin::Direct { topology, occurrence, .. } if site.source == &owner.source
                && std::ptr::eq(&topology.structure, structure) && *occurrence == call =>
                topology.occurrences.get(occurrence.0).map(|node| node.span),
            _ => None,
        });
        #[cfg(feature = "internal-checker")]
        let nested_route = ACTUAL_STARTUP && named_outer.is_some() && self.observer.named_nested_scalar_route(target);
        #[cfg(feature = "internal-checker")]
        let candidate = named_outer.filter(|_| (named_watch.is_some() || nested_route)
            && collection.is_some_and(|(source, _)| source == &owner.source)
            && body.boundary.parameters.len() == signature.parameters.len());
        #[cfg(feature = "internal-checker")]
        let scalar_root = candidate.is_some() && named_stack_parameters(&signature.parameters)
            && supported_integer_continuation(body, expected) && citation_safe_calling_body(body);
        #[cfg(feature = "internal-checker")]
        let has_bound_integer = !body.structure.checker_integer_call_locals.is_empty();
        #[cfg(feature = "internal-checker")]
        let named_reached = scalar_root && named_watch.is_some()
            && (has_bound_integer || named_exact_mixed_pair(&signature.parameters, |ty| ty));
        #[cfg(feature = "internal-checker")]
        let ordinary_named = nested_route && signature.parameters.iter().all(is_integer_type)
            && (scalar_root || (candidate.is_some() && *expected == ScalarType::Unit
                && named_nested_scalar_parameters(&signature.parameters, expected)
                && body.checker_named_route_frame()));
        #[cfg(feature = "internal-checker")]
        let named_root = if named_reached || ordinary_named {
            candidate.map(|outer| NamedStackRoot { outer, nested_scalars: ordinary_named })
        } else { None };
        #[cfg(feature = "internal-checker")]
        if named_watch.is_some_and(|watch| (watch.citation && !named_reached)
            || (watch.case_citation && proof_site.is_none()))
        {
            return Err(ProjectCheck::Unsupported);
        }
        #[cfg(feature = "internal-checker")]
        let qualified_integer = named_watch.filter(|watch| watch.qualified_leaf
            && watch.literal_leaf.is_none() && !watch.result_pair);
        #[cfg(feature = "internal-checker")]
        let fixed_array = if matches!(expected, ScalarType::Array { .. }) {
            if !self.can_initialize_fixed_arrays() || !self.observer.watches_fixed_array(target) {
                return Err(ProjectCheck::Unsupported);
            }
            true
        } else { false };
        #[cfg(not(feature = "internal-checker"))]
        let fixed_array = false;
        #[cfg(feature = "internal-checker")]
        let proof_call = if named_literal.is_some() || qualified_integer.is_some() || fixed_array {
            Some(authorize_direct_proof_initializer(proof_site.as_ref(), structure, call, &owner.source, target.0, collection)?)
        } else { None };
        #[cfg(feature = "internal-checker")]
        if let Some(watch) = named_literal.or(qualified_integer) {
            if qualified_integer.is_some() && !qualified_integer_proof_leaf(body, expected) {
                return Err(ProjectCheck::Unsupported);
            }
            let cost = body.occurrences.len().checked_add(1).and_then(|cost| cost.checked_add(watch.nested_work))
                .ok_or(ProjectCheck::Unsupported)?;
            self.observer.charge_named_exact_work(cost).ok_or(ProjectCheck::Unsupported)?;
        }
        #[cfg(feature = "internal-checker")]
        let enrolled_direct_proof = proof_call.is_some();
        #[cfg(not(feature = "internal-checker"))]
        let enrolled_direct_proof = false;
        #[cfg(not(feature = "internal-checker"))]
        let named_root = None;
        let target_module = target.0;
        if !ACTUAL_STARTUP && (*expected != ScalarType::Unit
            || (collection.is_none() && target_module != self.symbolic_module))
        {
            return Err(ProjectCheck::Unsupported);
        }
        if let Some(receivers) = pair_receivers {
            #[cfg(feature = "internal-checker")]
            if ACTUAL_STARTUP && named_literal.is_some_and(|watch| watch.result_pair)
                && matches!((receivers, signature.outputs.outputs.as_slice(), body.boundary.results.as_slice()),
                    ([first, second], [output0, output1], [result0, result1])
                        if first.ty == output0.ty && second.ty == output1.ty
                        && output0.ty == result0.ty && output1.ty == result1.ty)
            {
                // The checked receiver projections are installed together,
                // below, only after the one actual call has returned.
            } else {
                return Err(ProjectCheck::Unsupported);
            }
            #[cfg(not(feature = "internal-checker"))]
            {
                let _ = receivers;
                return Err(ProjectCheck::Unsupported);
            }
        } else if !matches!(signature.outputs.outputs.as_slice(), [output]
            if &output.ty == expected || (fixed_array && super::scalar_type_equal(&output.ty, expected))) {
            return Err(ProjectCheck::Unsupported);
        }
        #[cfg(feature = "internal-checker")]
        let passive_caller = collection.map(|(source, _)| source);
        #[cfg(feature = "internal-checker")]
        // Both enrolled scalar proof roles have already checked the
        // exact caller site and completed provider above. The ordinary
        // namespace predicate below deliberately excludes recursive bodies.
        let capped_scalar_proof_initializer = startup_named || startup_ranked;
        #[cfg(not(feature = "internal-checker"))]
        let capped_scalar_proof_initializer = false;
        let collection = if let Some((caller_source, collection)) = collection {
            if caller_source != &owner.source
                && (matches!(&projected, ActualProjectedArguments::SymbolicAxis(..))
                    || (!enrolled_direct_proof && !capped_scalar_proof_initializer
                        && !self.completed_namespace_call(caller_source, owner, target_module, body, signature, expected, collection.visits)))
            {
                return Err(ProjectCheck::Unsupported);
            }
            #[cfg(feature = "internal-checker")]
            let collection = if caller_source != &owner.source {
                OrderedCallCollection { outer: None, ..collection }
            } else {
                collection
            };
            Some(collection)
        } else {
            None
        };
        let projected = match projected {
            ActualProjectedArguments::SymbolicAxis(projection) => {
                let Some(collection) = collection else { return Err(ProjectCheck::Unsupported); };
                let slot = projection.slot;
                let fixed = match projection.companion {
                    ProjectedCompanion::Unary => None,
                    ProjectedCompanion::Fixed((_, value)) => Some(value),
                    ProjectedCompanion::Equal | ProjectedCompanion::Independent { .. } => return Err(ProjectCheck::Unsupported),
                };
                if ACTUAL_STARTUP || *expected != ScalarType::Unit || !projected_call_types_match(signature, body, &projection)
                    || !function.generic_parameters.is_empty() || !function.overload_arms.is_empty()
                    || !body.structure.checker_direct_targets.is_empty()
                    || !body.call_occurrences.is_empty() || !body.allocation_length_calls.is_empty()
                    || !body.assignments.is_empty() || !body.arms.is_empty()
                    || body.structure.checker_directives.values().any(|directive| directive.call_signature.is_some())
                    || self.active_depth == MAX_ACTUAL_CALL_DEPTH || self.active.contains(&target)
                {
                    return Err(ProjectCheck::Unsupported);
                }
                let values = projection.materialize().ok_or(ProjectCheck::Unsupported)?;
                let outcome = self.collect_requirements(
                    body, &owner.source, IntegerRequirementEntry::Projected {
                        slot, values: Rc::clone(&values), fixed,
                    }, collection,
                )?;
                return Ok(match outcome {
                    ActualCallResult::ProjectedUnit(survivors) if Rc::ptr_eq(&values, &survivors) => ActualCallResult::Unit,
                    outcome => outcome,
                });
            }
            exact => exact,
        };
        let argument;
        let pair;
        #[cfg(feature = "internal-checker")]
        let wide;
        let exact: &[&BigInt] = match (signature.parameters.as_slice(), body.boundary.parameters.as_slice(), projected) {
            ([], [], ActualProjectedArguments::Single(None)) => &[],
            ([parameter], [slot], ActualProjectedArguments::Single(Some((ty, value))))
                if *parameter == slot.ty && parameter == ty =>
            {
                argument = [value];
                &argument
            }
            ([first, second], [first_slot, second_slot],
                ActualProjectedArguments::ExactPair((first_ty, first_value), (second_ty, second_value)))
                if (fixed_array || module_bool_initializer || is_integer_type(expected) || (*expected == ScalarType::Unit && collection.is_some()))
                    && *first == first_slot.ty && first == first_ty
                    && *second == second_slot.ty && second == second_ty =>
            {
                pair = [first_value, second_value];
                &pair
            }
            #[cfg(feature = "internal-checker")]
            (parameters, slots, ActualProjectedArguments::ExactWide(tuple)) if startup_wide_rank
                && tuple.len() == parameters.len() && slots.len() == parameters.len()
                && tuple.iter().zip(parameters.iter().zip(slots)).all(|((ty, value), (parameter, slot))|
                    *ty == parameter && &slot.ty == parameter && integer_literal_fits_type(value, ty)) =>
            {
                wide = tuple.into_iter().map(|(_, value)| value).collect::<Vec<_>>();
                &wide
            }
            _ => return Err(ProjectCheck::Unsupported),
        };
        if self.active_depth == MAX_ACTUAL_CALL_DEPTH {
            return Err(ProjectCheck::Unsupported);
        }
        #[cfg(feature = "internal-checker")]
        let metered_legacy_unit = collection.is_some_and(|ordered| ordered.meter_named_legacy_unit);
        #[cfg(not(feature = "internal-checker"))]
        let metered_legacy_unit = false;
        #[cfg(feature = "internal-checker")]
        if metered_legacy_unit && (!ACTUAL_STARTUP || *expected != ScalarType::Unit || named_root.is_some()) {
            return Err(ProjectCheck::Unsupported);
        }
        if !self.active.insert(target) {
            return Err(ProjectCheck::Unsupported);
        }
        #[cfg(feature = "internal-checker")]
        if metered_legacy_unit {
            // This is the ordinary collector's sole activation boundary.
            // Descendants keep the marker with their ordered continuation;
            // routed frames instead pay on their exact stack admission.
            if let Err(error) = self.charge_named_exact_frame(body) {
                self.active.remove(&target);
                return Err(error);
            }
        }
        self.active_depth += 1;
        #[cfg(feature = "internal-checker")]
        let exact_literal = named_literal.map(|watch| {
            if watch.result_pair {
                let site = proof_site.take().ok_or(ProjectCheck::Unsupported)?;
                return self.observer.check_initializer_pair(target, body, site, &signature.parameters, exact)
                    .map(ActualCallResult::ResultPair);
            }
            let leaf = watch.literal_leaf.ok_or(ProjectCheck::Unsupported)?;
            let value = super::checker_flow::exact_named_literal_return_at_entry(body, expected, exact)
                .ok_or(ProjectCheck::Unsupported)?;
            leaf.from_atom(&value).ok_or(ProjectCheck::Unsupported)?;
            Ok(ActualCallResult::Integer(value))
        });
        #[cfg(not(feature = "internal-checker"))]
        let exact_literal = None;
        #[cfg(feature = "internal-checker")]
        let startup_named_result = (startup_named || startup_plain_scalar || startup_ranked || startup_cited).then(|| {
            if startup_plain_scalar {
                // The ordinary binding retains its original complete
                // typed signature, never the unary proof-observer shape.
                return self.run_exact_calls::<false>(body, &owner.source, exact, expected, collection, None);
            }
            let ordered = collection.ok_or(ProjectCheck::Unsupported)?;
            let site = ordered.scalar_initializer.ok_or(ProjectCheck::Unsupported)?;
            let at = site.topology.occurrences.get(site.occurrence.0).ok_or(ProjectCheck::MissingRootOccurrences)?.span;
            if startup_named || startup_ranked {
                let effects = ordered.failures.borrow();
                let mut trace = effects.startup_search.as_ref().ok_or(ProjectCheck::Unsupported)?.borrow_mut();
                trace.charge_proof_frame(body).ok_or(ProjectCheck::Unsupported)?;
                if startup_wide_rank {
                    let recipe = trace.wide_rank_recipe.clone().ok_or(ProjectCheck::Unsupported)?;
                    trace.charge_formal_replay(1, recipe.work().ok_or(ProjectCheck::Unsupported)?)
                        .ok_or(ProjectCheck::Unsupported)?;
                    if !recipe.accepts(exact) { return Err(ProjectCheck::Unsupported); }
                }
            }
            let result = if startup_cited {
                let named_root = named_root.ok_or(ProjectCheck::Unsupported)?;
                self.run_exact_calls::<true>(body, &owner.source, exact, expected, collection, Some(named_root))?
            } else {
                self.run_exact_calls::<false>(body, &owner.source, exact, expected, collection, None)?
            };
            let ActualCallResult::Integer(value) = result else { return Err(ProjectCheck::Unsupported); };
            let effects = ordered.failures.borrow();
            let mut trace = effects.startup_search.as_ref().ok_or(ProjectCheck::Unsupported)?.borrow_mut();
            let proof_only = trace.proof_only_continuation() && trace.pending_named_startup_observation();
            use failure_search::StartupProofRole::{Bare, Cited, Ranked};
            let role = if startup_ranked { Ranked } else if startup_cited { Cited } else if startup_named { Bare } else { return Err(ProjectCheck::Unsupported); };
            if trace.required_sites.remove(&site.occurrence) != Some((target, role)) {
                return Err(ProjectCheck::Unsupported);
            }
            if startup_cited {
                let caller = ordered.startup_site_source.ok_or(ProjectCheck::Unsupported)?;
                let at = InitializerProofSite { source: caller, call: InitializerProofOrigin::Direct {
                    topology: site.topology, occurrence: site.occurrence, directive_position: effects.records.len(),
                } };
                let stop = proof_only && !trace.proof_only_continuation();
                drop(trace);
                self.observer.observe_initializer(target, Some(at), &signature.parameters, exact, &value);
                return if stop { Err(ProjectCheck::StartupAuthoredLimitReached) }
                    else { Ok(ActualCallResult::Integer(value)) };
            }
            let caller_site = wosy_syntax::SourceSpan::new(ordered.startup_site_source.ok_or(ProjectCheck::Unsupported)?.clone(), at);
            if startup_wide_rank {
                if role != Ranked { return Err(ProjectCheck::Unsupported); }
                let recipe = trace.wide_rank_recipe.as_ref().ok_or(ProjectCheck::Unsupported)?;
                if recipe.forwarder.is_some() {
                    if trace.pending_wide_forward.is_some() || !trace.wide_rank_observations.last().is_some_and(|inner|
                        inner.outer.as_ref() == Some(&caller_site) && inner.target == recipe.target && inner.returned == value) {
                        return Err(ProjectCheck::Unsupported);
                    }
                } else { trace.wide_rank_observations.push(failure_search::WideRankObservation {
                    target, site: caller_site, outer: None, arguments: exact.iter().map(|value| (*value).clone()).collect(), returned: value.clone(),
                }); }
                if proof_only && !trace.proof_only_continuation() { return Err(ProjectCheck::StartupAuthoredLimitReached); }
                return Ok(ActualCallResult::Integer(value));
            }
            let (parameter, argument, second) = match (signature.parameters.as_slice(), exact) {
                ([parameter], [argument]) => (parameter, *argument, None),
                ([first, second], [left, right]) if role == Bare && trace.binary_bare.contains(&target) =>
                    (first, *left, Some((second.clone(), (*right).clone()))),
                _ => return Err(ProjectCheck::Unsupported),
            };
            let observation = failure_search::StartupProofObservation {
                target, site: caller_site,
                directive_position: effects.records.len(), parameter: parameter.clone(),
                argument: argument.clone(), second, returned: value.clone(),
            };
            match role {
                Bare => trace.named_observations.push(observation),
                Ranked => trace.ranked_observations.push(observation),
                failure_search::StartupProofRole::Aggregate | Cited => return Err(ProjectCheck::Unsupported),
            }
            // Capture the real typed return before stopping. Do not resume
            // further startup items or ordinary witness selection.
            if proof_only && !trace.proof_only_continuation() {
                return Err(ProjectCheck::StartupAuthoredLimitReached);
            }
            Ok(ActualCallResult::Integer(value))
        });
        #[cfg(not(feature = "internal-checker"))]
        let startup_named_result = None;
        let result = if let Some(result) = startup_named_result {
            result
        } else if fixed_array {
            #[cfg(feature = "internal-checker")]
            {
                proof_call.ok_or(ProjectCheck::Unsupported).and_then(|(caller, span)| {
                    let trace = collection.and_then(|ordered| ordered.failures.borrow().startup_search.clone());
                    self.observer.observe_fixed_array_initializer(
                        target, body, exact, wosy_syntax::SourceSpan::new(caller.clone(), span), trace.as_ref(),
                    )
                }).map(ActualCallResult::FixedArray)
            }
            #[cfg(not(feature = "internal-checker"))]
            unreachable!()
        } else if let Some(result) = exact_literal {
            result
        } else if named_root.is_some() {
            self.run_exact_calls::<true>(body, &owner.source, exact, expected, collection, named_root)
        } else if *expected == ScalarType::Unit {
            if !metered_legacy_unit && ACTUAL_STARTUP && !Observer::ENABLED && !Observer::CONTEXTUAL {
                let result = self.run_exact_calls::<false>(body, &owner.source, exact, expected, collection, None);
                self.active_depth -= 1;
                self.active.remove(&target);
                #[cfg(feature = "internal-checker")]
                if matches!(result, Ok(ActualCallResult::Unit)) {
                    if let Some(trace) = collection.and_then(|ordered| ordered.failures.borrow().startup_search.clone()) {
                        let mut trace = trace.borrow_mut();
                        if let Some(route) = trace.mixed_context.as_mut().filter(|route|
                            route.entry == target && route.root_site == call)
                        {
                            if !route.returned_context || !route.pending_leaves.is_empty() { return Err(ProjectCheck::Unsupported); }
                            route.finished = true;
                            if trace.remaining() == 0 && trace.cannot_continue() {
                                return Err(ProjectCheck::StartupAuthoredLimitReached);
                            }
                        }
                    }
                }
                if result.is_ok() { self.note_reached(target); }
                return result;
            }
            if let Some(collection) = collection {
                self.collect_requirements(body, &owner.source, IntegerRequirementEntry::Exact(exact), collection)
            } else {
                self.requirements(body, &owner.source, Some(exact)).map(|active| {
                    self.had_obligations |= active;
                    ActualCallResult::Unit
                })
            }
        } else if (ACTUAL_STARTUP && Observer::EXACT_INTEGER_CALL_CONTINUATIONS && collection.is_some()
            && (module_bool_initializer || !body.call_occurrences.is_empty() || {
                #[cfg(feature = "internal-checker")]
                { Observer::ORDINARY_INTEGER_LOCALS && body.structure.has_ordinary_integer_operations() }
                #[cfg(not(feature = "internal-checker"))]
                { false }
            })
            && supported_integer_continuation_shape_for(body, expected, Observer::ORDINARY_INTEGER_LOCALS)
            && body.assignments.is_empty())
            || (module_bool_initializer && self.exact_boolean_narrow_profile(expected, collection.is_some())
                && Self::exact_boolean_narrow_body_has_supported_shape(body))
            || self.exact_integer_narrow_shape(body, expected, collection.is_some())
            || self.exact_integer_local_write_shape(body, expected, collection.is_some())
        {
            self.run_exact_calls::<false>(body, &owner.source, exact, expected, collection, None)
        } else if is_integer_type(expected)
            && body.structure.checker_directives.is_empty()
            && body.call_occurrences.is_empty()
            && body.allocation_length_calls.is_empty()
            && body.assignments.is_empty()
        {
            #[cfg(feature = "internal-checker")]
            let observed = if ACTUAL_STARTUP && proof_site.is_some()
                && self.observer.permits_named_pure_affine_return(target, exact)
                && super::checker_flow::pure_affine_proof_body(body)
            {
                super::checker_flow::exact_named_pure_affine_return_at_entry(body, expected, exact)
            } else {
                exact_integer_return_at_entry(body, expected, exact)
            };
            #[cfg(not(feature = "internal-checker"))]
            let observed = exact_integer_return_at_entry(body, expected, exact);
            observed.map(ActualCallResult::Integer).ok_or(ProjectCheck::Unsupported)
        } else {
            #[cfg(feature = "internal-checker")]
            let collected = collection.filter(|_| ACTUAL_STARTUP && is_integer_type(expected)
                && !body.structure.checker_directives.is_empty()
                && !body.structure.checker_has_nonexact_require
                && body.call_occurrences.is_empty() && body.allocation_length_calls.is_empty() && body.assignments.is_empty()
            ).map(|collection| {
                let mut failures = collection.failures.borrow_mut();
                let mut sink = |failure| failures.push_callable(body, &owner.source, failure);
                super::checker_flow::collect_exact_integer_return_requirements(body, expected, exact, &mut sink)
                    .map(|(active, value)| {
                        self.had_obligations |= active;
                        ActualCallResult::Integer(value)
                    }).ok_or(ProjectCheck::Unsupported)
            });
            #[cfg(not(feature = "internal-checker"))]
            let collected = None;
            if let Some(result) = collected {
                result
            } else {
                #[cfg(feature = "internal-checker")]
                let proved = if ACTUAL_STARTUP && Observer::ENABLED {
                    self.observer.proved_recursive_return(target, exact, expected)
                } else {
                    None
                };
                #[cfg(not(feature = "internal-checker"))]
                let proved = None;
                proved.map(ActualCallResult::Integer).ok_or(ProjectCheck::Unsupported)
            }
        };
        self.active_depth -= 1;
        self.active.remove(&target);
        if ACTUAL_STARTUP && Observer::ENABLED {
            if let Ok(ActualCallResult::Integer(value)) = &result {
                self.observer.observe(target, exact, value);
            }
        }
        #[cfg(feature = "internal-checker")]
        if ACTUAL_STARTUP && Observer::CONTEXTUAL && !startup_cited {
            if let Ok(ActualCallResult::Integer(value)) = &result {
                let mut scalar_site = proof_site.take();
                if let (Some(InitializerProofSite { call: InitializerProofOrigin::Direct { directive_position, .. }, .. }), Some(collection)) =
                    (&mut scalar_site, collection)
                {
                    *directive_position = collection.failures.borrow().records.len();
                }
                self.observer.observe_initializer(target, scalar_site, &signature.parameters, exact, value);
            }
        }
        #[cfg(feature = "internal-checker")]
        if ACTUAL_STARTUP {
            if let (Ok(ActualCallResult::Integer(returned)), Some(source), Some(ordered)) = (&result, passive_caller, collection) {
                if let Some(site) = ordered.scalar_initializer.filter(|site| site.occurrence == call
                    && std::ptr::eq(&site.topology.structure, structure))
                {
                    let mut effects = ordered.failures.borrow_mut();
                    let directive_position = effects.records.len();
                    if let Some(tap) = &mut effects.mixed_startup {
                        if let Some(count) = tap.captured.get_mut(&target) {
                            let ([ty], [argument]) = (signature.parameters.as_slice(), exact) else {
                                return Err(ProjectCheck::Unsupported);
                            };
                            if !is_integer_type(ty) || !is_integer_type(expected) {
                                return Err(ProjectCheck::Unsupported);
                            }
                            super::checker_flow::charge_call_work(&mut tap.work, MAX_CONTEXTUAL_PROOFS).ok_or(ProjectCheck::Unsupported)?;
                            let call = site.topology.occurrences.get(call.0).ok_or(ProjectCheck::Unsupported)?.span;
                            *count = count.checked_add(1).ok_or(ProjectCheck::Unsupported)?;
                            tap.events.push(MixedStartupEvent::Scalar {
                                target, source: source.clone(), call, directive_position,
                                ty: ty.clone(), argument: (*argument).clone(), returned: returned.clone(),
                            });
                        }
                    }
                }
            }
        }
        if ACTUAL_STARTUP && result.is_ok() {
            self.note_reached(target);
        }
        result
    }
}

#[cfg(feature = "internal-checker")]
fn authorize_direct_proof_initializer<'a>(
    site: Option<&InitializerProofSite<'a>>, structure: &OccurrenceStructure, call: OccurrenceOrdinal,
    owner: &SourceIdentity, target_module: usize, collection: Option<(&SourceIdentity, OrderedCallCollection<'_, '_>)>,
) -> Result<(&'a SourceIdentity, ByteSpan), ProjectCheck> {
    let Some(InitializerProofSite { source, call: InitializerProofOrigin::Direct { topology, occurrence, .. } }) = site
        else { return Err(ProjectCheck::Unsupported); };
    if !std::ptr::eq(&topology.structure, structure) || *occurrence != call
        || !collection.is_some_and(|(caller, ordered)| caller == *source
            && (caller == owner || completed_namespace_owner(caller, owner, target_module, ordered.visits)))
    {
        return Err(ProjectCheck::Unsupported);
    }
    let span = topology.occurrences.get(call.0).ok_or(ProjectCheck::MissingRootOccurrences)?.span;
    Ok((source, span))
}

fn completed_namespace_owner(
    caller: &SourceIdentity, owner: &SourceIdentity, target: usize, visits: Option<&[InitializationVisit]>,
) -> bool {
    caller.project == owner.project && caller.package == owner.package
        && visits.and_then(|visits| visits.get(target)) == Some(&InitializationVisit::Completed)
}

fn projected_call_types_match(
    signature: &CheckedCallSignature, body: &FunctionCallSites, projection: &ProjectedIntegerArgument<'_>,
) -> bool {
    let ProjectedIntegerArgument { ty, slot, companion, .. } = *projection;
    match (signature.parameters.as_slice(), body.boundary.parameters.as_slice(), companion) {
        ([parameter], [entry], ProjectedCompanion::Unary) => slot == 0 && parameter == ty && entry.ty == *ty,
        (parameters @ [_, _], entries @ [_, _], ProjectedCompanion::Fixed((fixed_ty, _))) if slot < 2 =>
            parameters[slot] == *ty && entries[slot].ty == *ty
                && parameters[1 - slot] == *fixed_ty && entries[1 - slot].ty == *fixed_ty,
        ([first, second], [left, right], ProjectedCompanion::Equal) =>
            slot == 0 && first == ty && second == ty && left.ty == *ty && right.ty == *ty,
        ([first, second], [left, right], ProjectedCompanion::Independent { ty: other, .. }) =>
            slot == 0 && first == ty && second == other && left.ty == *ty && right.ty == *other,
        _ => false,
    }
}

fn supported_integer_continuation(body: &FunctionCallSites, expected: &ScalarType) -> bool {
    supported_integer_continuation_shape(body, expected) && body.assignments.is_empty()
}

fn supported_integer_continuation_shape(body: &FunctionCallSites, expected: &ScalarType) -> bool {
    #[cfg(feature = "internal-checker")]
    let exact_requirements = !body.structure.checker_has_nonexact_require;
    #[cfg(not(feature = "internal-checker"))]
    let exact_requirements = false;
    is_integer_type(expected) && exact_requirements
        && body.allocation_length_calls.is_empty()
}

fn supported_integer_continuation_shape_for(body: &FunctionCallSites, expected: &ScalarType, ordinary: bool) -> bool {
    if supported_integer_continuation_shape(body, expected) { return true; }
    #[cfg(feature = "internal-checker")]
    if ordinary && (is_integer_type(expected) || *expected == ScalarType::Bool)
        && body.allocation_length_calls.is_empty()
        && (body.structure.has_ordinary_predicates() || *expected == ScalarType::Bool)
    {
        return !body.structure.checker_has_unsupported_ordinary_require;
    }
    #[cfg(not(feature = "internal-checker"))]
    let _ = ordinary;
    false
}

#[cfg(test)]
fn check_closed_project_callable(
    declarations: Vec<(ScalarSourceDeclarations, Vec<ScalarNamespaceBinding>)>,
    initialization_order: Vec<SourceIdentity>,
    inputs: ScalarPreparationInputs,
    root_source: &SourceIdentity,
    root_name: &str,
) -> ProjectCheck {
    let prepared = match prepare_checker_project(declarations, initialization_order, inputs) {
        Ok(prepared) => prepared,
        Err(error) => return error,
    };
    let (project, calls) = prepared.parts();
    let (module, item, function) = match select_checked_root(project, root_source, root_name) {
        Ok(root) => root,
        Err(error) => return error,
    };
    let ScalarType::Callable { outputs, parameters } = &function.signature else {
        return ProjectCheck::Unsupported;
    };
    if !parameters.is_empty()
        || !matches!(outputs.outputs.as_slice(), [output] if output.ty == ScalarType::Unit)
        || !function.generic_parameters.is_empty()
        || !function.overload_arms.is_empty()
    {
        return ProjectCheck::Unsupported;
    }
    let Some(body) = calls.function_body(module, item, None) else {
        return ProjectCheck::MissingRootOccurrences;
    };
    match check_integer_requirements(body) {
        None => ProjectCheck::Unsupported,
        Some(Ok(())) if body.structure.checker_directives.is_empty() => ProjectCheck::NoChecks,
        Some(Ok(())) => ProjectCheck::Proved,
        Some(Err(failure)) => project_failure(body, root_source, failure),
    }
}

pub(super) use prepared::PreparedCheckerProject;

mod prepared {
    use super::*;

    pub(in crate::scalar) struct PreparedCheckerProject {
        project: ScalarProject,
        calls: ProjectCallSiteResults,
    }

    impl PreparedCheckerProject {
        #[cfg(feature = "internal-checker")]
        pub(super) fn from_contextual_transport(prepared: super::super::PreparedScalarProject) -> Self {
            let (project, calls) = prepared.into_contextual_parts();
            Self { project, calls }
        }

        pub(in crate::scalar) fn parts(&self) -> (&ScalarProject, &ProjectCallSiteResults) {
            (&self.project, &self.calls)
        }

        #[cfg(feature = "internal-checker")]
        pub(super) fn occurrence_snapshot(&self) -> super::super::static_calls::PreparedOccurrenceSnapshot<'_> {
            super::super::static_calls::PreparedOccurrenceSnapshot::from_checker(self)
        }

        #[cfg(feature = "internal-checker")]
        #[allow(dead_code)] // The backend cannot consume this until it shares this prepared graph.
        pub(super) fn observe_runtime_fixed_indices(
            &self, module: usize, item: usize,
        ) -> Option<super::super::checker_flow::RuntimeFixedIndexEvidence<'_>> {
            let (function, calls) = self.occurrence_snapshot().monomorphic_body(module, item)?;
            super::super::checker_flow::observe_runtime_fixed_indices(calls, &function.body)
        }
    }

    #[cfg(feature = "internal-checker")]
    type FixedIndexRequest = (usize, usize, super::super::reference::OccurrenceOrdinal);

    #[cfg(feature = "internal-checker")]
    const MAX_FIXED_INDEX_OBSERVATION_REQUESTS: usize = 16;

    // Opt-in checker-only results for the ordinary whole-package route.
    // Staged cover stays private until this preparation's terminal verdict.
    #[cfg(feature = "internal-checker")]
    #[allow(dead_code)] // No production caller or Build helper validator yet.
    pub(super) struct CompletedFixedIndexCheck<'a> {
        reads: HashMap<FixedIndexRequest, super::super::static_calls::PreparedReadOccurrence<'a>>,
        #[cfg(test)]
        observed_bodies: usize,
    }

    #[cfg(feature = "internal-checker")]
    #[allow(dead_code)]
    impl CompletedFixedIndexCheck<'_> {
        pub(super) fn describes(
            &self, prepared: &PreparedCheckerProject, module: usize, item: usize,
            read: super::super::reference::OccurrenceOrdinal, extent: usize,
        ) -> bool {
            use super::super::static_calls::{PreparedReadKind, PreparedReadShape};
            self.reads.get(&(module, item, read)).is_some_and(|seen|
                seen.matches(prepared.occurrence_snapshot(), module, item, read, PreparedReadKind::FixedIndex)
                    && matches!(seen.shape(), PreparedReadShape::FixedIndex(shape) if shape.extent == extent))
        }

        #[cfg(test)]
        pub(super) fn observed_bodies(&self) -> usize { self.observed_bodies }
    }

    #[cfg(all(test, feature = "internal-checker"))]
    pub(super) fn check_ordinary_package_with_fixed_index_observation(
        prepared: &PreparedCheckerProject, module: usize, item: usize, occurrence: super::super::reference::OccurrenceOrdinal,
    ) -> (ScalarOrderedCheckerOutcome, Option<CompletedFixedIndexCheck<'_>>) {
        check_ordinary_package_with_fixed_index_observations(prepared, &[(module, item, occurrence)])
    }

    #[cfg(feature = "internal-checker")]
    #[allow(dead_code)]
    pub(super) fn check_ordinary_package_with_fixed_index_observations<'a>(
        prepared: &'a PreparedCheckerProject, requests: &[FixedIndexRequest],
    ) -> (ScalarOrderedCheckerOutcome, Option<CompletedFixedIndexCheck<'a>>) {
        use super::super::static_calls::{PreparedReadKind, PreparedReadShape};
        let snapshot = prepared.occurrence_snapshot();
        let root = prepared.project.initialization_order.first();
        let mut groups = std::collections::BTreeMap::<_, Vec<_>>::new();
        let mut seen = HashSet::new();
        if requests.len() <= MAX_FIXED_INDEX_OBSERVATION_REQUESTS {
            for &(module, item, occurrence) in requests {
                if !seen.insert((module, item, occurrence)) { continue; }
                let same_package = root.zip(prepared.project.modules.get(module))
                    .is_some_and(|(root, candidate)| root.project == candidate.source.project
                        && root.package == candidate.source.package);
                if !same_package { continue; }
                let Some(read) = snapshot.read(module, item, occurrence, PreparedReadKind::FixedIndex) else { continue; };
                groups.entry((module, item)).or_default().push((occurrence, read));
            }
        }
        let mut reads = HashMap::new();
        #[cfg(test)]
        let mut observed_bodies = 0;
        for ((module, item), candidates) in groups {
            #[cfg(test)]
            { observed_bodies += 1; }
            let Some(evidence) = prepared.observe_runtime_fixed_indices(module, item) else { continue; };
            for (occurrence, read) in candidates {
                let PreparedReadShape::FixedIndex(shape) = read.shape() else { continue; };
                if evidence.covers_read(occurrence, shape.extent) {
                    reads.insert((module, item, occurrence), read);
                }
            }
        }
        // No caller-supplied scope/startup count/verdict, and nothing
        // publishes from partial initialization or a nonpassing Check.
        let run = run_prepared_ordered_check_profiles::<_, false, true>(
            prepared, ScalarCheckerScope::CurrentPackage, prepared.project.modules.len(),
            OrderedReachPolicy::Legacy, (), OrderedFailures::default(),
        );
        let finished = run.as_ref().is_ok_and(|run| run.finished_all_initialization);
        let outcome = terminal_ordered_outcome(run.map(|run| (run.active, run.directives)));
        let completed = (finished && matches!(outcome, ScalarOrderedCheckerOutcome::Passed) && !reads.is_empty())
            .then_some(CompletedFixedIndexCheck {
                reads,
                #[cfg(test)]
                observed_bodies,
            });
        (outcome, completed)
    }

    pub(super) fn prepare_checker_project(
        declarations: Vec<(ScalarSourceDeclarations, Vec<ScalarNamespaceBinding>)>,
        initialization_order: Vec<SourceIdentity>,
        inputs: ScalarPreparationInputs,
    ) -> Result<PreparedCheckerProject, ProjectCheck> {
        prepare_checker_project_impl(declarations, initialization_order, inputs, &[])
    }

    pub(super) fn prepare_checker_project_with_queries(
        declarations: Vec<(ScalarSourceDeclarations, Vec<ScalarNamespaceBinding>)>,
        initialization_order: Vec<SourceIdentity>,
        inputs: ScalarPreparationInputs,
        queries: &[CheckerTargetQuery<'_>],
    ) -> Result<PreparedCheckerProject, ProjectCheck> {
        prepare_checker_project_impl(declarations, initialization_order, inputs, queries)
    }

    fn prepare_checker_project_impl(
        declarations: Vec<(ScalarSourceDeclarations, Vec<ScalarNamespaceBinding>)>,
        initialization_order: Vec<SourceIdentity>,
        inputs: ScalarPreparationInputs,
        queries: &[CheckerTargetQuery<'_>],
    ) -> Result<PreparedCheckerProject, ProjectCheck> {
        let (project, calls) = project_from_declarations(declarations, initialization_order, inputs)
            .and_then(|project| prepare_project_occurrences(
                typecheck_scalar_project_in_mode(project, true),
                queries,
            ))
            .map_err(|rejected| ProjectCheck::Invalid(rejected.into_inspection().diagnostics))?;
        Ok(PreparedCheckerProject { project, calls })
    }
}

use prepared::prepare_checker_project;

fn select_checked_root<'a>(
    project: &'a ScalarProject,
    source: &SourceIdentity,
    name: &str,
) -> Result<(usize, usize, &'a ScalarFunction), ProjectCheck> {
    let mut roots = project
        .modules
        .iter()
        .enumerate()
        .filter(|(_, module)| &module.source == source)
        .flat_map(|(module, source)| {
            source.items.iter().enumerate().filter_map(move |(item, value)| {
                let ScalarItem::Function(function) = value else {
                    return None;
                };
                (function.name == name).then_some((module, item, function))
            })
        });
    let root = roots.next().ok_or(ProjectCheck::MissingRoot)?;
    if roots.next().is_some() {
        return Err(ProjectCheck::AmbiguousRoot);
    }
    if !project.initialization_order.contains(source) {
        return Err(ProjectCheck::RootSourceOutsideInitOrder);
    }
    Ok(root)
}

#[derive(Default)]
struct OrderedFailures {
    records: Vec<ScalarOrderedCheckerFailure>,
    #[cfg(feature = "internal-checker")]
    startup_search: Option<Rc<RefCell<failure_search::StartUpSearch>>>,
    payloads: OrderedFailurePayloads,
    #[cfg(feature = "internal-checker")]
    has_authored_state: bool,
    #[cfg(feature = "internal-checker")]
    has_selected_code: bool,
    #[cfg(feature = "internal-checker")]
    startup_output_work: usize,
    #[cfg(feature = "internal-checker")]
    passive_literal_work: usize,
    #[cfg(feature = "internal-checker")]
    contextual_call_work: usize,
    #[cfg(feature = "internal-checker")]
    contextual_proofs: ContextualProofCohort,
    #[cfg(feature = "internal-checker")]
    mixed_startup: Option<MixedStartupTap>,
    #[cfg(feature = "internal-checker")]
    mixed_proof_order: Option<MixedProofOrder>,
    #[cfg(feature = "internal-checker")]
    snapshot_records: Vec<usize>,
    #[cfg(feature = "internal-checker")]
    entry_evidence: Option<Box<ScalarOrderedEntryEvidence>>,
}

#[cfg(feature = "internal-checker")]
#[doc(hidden)]
pub struct ScalarOrderedEntryEvidence {
    pub callable: wosy_syntax::SourceSpan,
    pub directive_index: usize,
    pub ty: ScalarType,
    pub entry_lower: BigInt,
    pub entry_upper: BigInt,
    pub failure_value: BigInt,
}

#[derive(Default)]
enum OrderedFailurePayloads {
    #[default]
    Empty,
    One(*const PreparedCheckerDirective, Rc<CheckedLiteralOutput>),
    Many(HashMap<*const PreparedCheckerDirective, Rc<CheckedLiteralOutput>>),
}

impl OrderedFailurePayloads {
    fn shared(&mut self, directive: &PreparedCheckerDirective) -> Rc<CheckedLiteralOutput> {
        let origin = std::ptr::from_ref(directive);
        match self {
            Self::Empty => {
                let output = Rc::new(directive.output.clone());
                *self = Self::One(origin, Rc::clone(&output));
                output
            }
            Self::One(prior, output) if *prior == origin => Rc::clone(output),
            Self::One(prior, previous) => {
                let next = Rc::new(directive.output.clone());
                *self = Self::Many(HashMap::from([(*prior, Rc::clone(previous)), (origin, Rc::clone(&next))]));
                next
            }
            Self::Many(payloads) => Rc::clone(payloads.entry(origin).or_insert_with(|| Rc::new(directive.output.clone()))),
        }
    }
}

impl OrderedFailures {
    #[cfg(feature = "internal-checker")]
    fn finalize_selected_outputs(&mut self, allow_singleton_code: bool) -> Result<(), ProjectCheck> {
        if self.has_selected_code && !allow_singleton_code { return Err(ProjectCheck::Unsupported); }
        if self.has_authored_state || self.has_selected_code || !self.snapshot_records.is_empty() {
            let mut hidden = std::mem::take(&mut self.snapshot_records).into_iter().peekable();
            for (index, record) in self.records.iter_mut().enumerate() {
                if !record.output.state_files.is_empty() || !matches!(record.output.code_value, CheckerCode::Literal(_)) {
                    record.output = Rc::new(render_authored_output(&record.output, &record.witness, None, &mut self.startup_output_work).ok_or(ProjectCheck::Unsupported)?);
                }
                if hidden.peek() == Some(&index) {
                    hidden.next();
                    record.witness.remove_snapshot_axes(&mut self.startup_output_work).ok_or(ProjectCheck::Unsupported)?;
                }
            }
        }
        Ok(())
    }

    fn push(
        &mut self,
        source: &SourceIdentity,
        directive: &PreparedCheckerDirective,
        span: ByteSpan,
        state: IntegerInputs,
        axes: Vec<(ReferenceBindingId, ScalarType)>,
        equal_axes: Vec<(usize, usize)>,
    ) {
        let output = self.payloads.shared(directive);
        self.push_with_witness(source, directive, span, ScalarCheckerIntegerWitness { axes, state, equal_axes }, output);
    }

    fn push_with_witness(
        &mut self, source: &SourceIdentity, directive: &PreparedCheckerDirective, span: ByteSpan,
        witness: ScalarCheckerIntegerWitness, output: Rc<CheckedLiteralOutput>,
    ) {
        #[cfg(feature = "internal-checker")]
        {
            self.has_authored_state |= !output.state_files.is_empty();
            self.has_selected_code |= !matches!(output.code_value, CheckerCode::Literal(_));
        }
        self.records.push(ScalarOrderedCheckerFailure {
            source: source.clone(), operation: directive.operation.into(), directive: span,
            condition: directive.condition, witness, output,
        });
    }

    #[cfg(feature = "internal-checker")]
    fn capture_entry_evidence(
        &mut self, body: &FunctionCallSites, function: &ScalarFunction, source: &SourceIdentity, failure: &IntegerCheckFailure<'_>,
    ) {
        if self.entry_evidence.is_some() {
            return;
        }
        let Some((ty, entry_lower, entry_upper, failure_value)) =
            super::checker_flow::backward_literal_overwrite_failure(body, failure) else { return; };
        self.entry_evidence = Some(Box::new(ScalarOrderedEntryEvidence {
            callable: wosy_syntax::SourceSpan { source: source.clone(), range: function.name_span },
            directive_index: self.records.len(), ty, entry_lower, entry_upper, failure_value,
        }));
    }

    fn push_callable(&mut self, body: &FunctionCallSites, source: &SourceIdentity, failure: IntegerCheckFailure<'_>) {
        #[cfg(feature = "internal-checker")]
        if !body.structure.checker_selected_snapshots.is_empty() {
            self.snapshot_records.push(self.records.len());
        }
        self.push(
            source,
            &body.structure.checker_directives[&failure.directive],
            body.occurrences[failure.directive.0].span,
            failure.state,
            failure.axes.into_iter().map(|(binding, ty)| (binding.clone(), ty.clone())).collect(),
            failure.equal_axes,
        );
    }
}

#[cfg(feature = "internal-checker")]
#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
enum AuthoredScalarOrigin<'a> {
    Binding(&'a ReferenceBindingId),
    Module(ByteSpan),
}

#[cfg(feature = "internal-checker")]
fn authored_scalar_origin<'a>(
    selection: &'a super::checker_directive::CheckerStateSelection, ty: &ScalarType,
) -> Option<AuthoredScalarOrigin<'a>> {
    use super::checker_directive::CheckerStateSelection;
    match selection {
        CheckerStateSelection::Binding(binding) => Some(AuthoredScalarOrigin::Binding(binding)),
        CheckerStateSelection::Module(span) => Some(AuthoredScalarOrigin::Module(*span)),
        CheckerStateSelection::AggregateLeaf { shape, leaf } => {
            let capture = shape.leaves.get(*leaf)?;
            (capture.ty == *ty).then_some(AuthoredScalarOrigin::Binding(&capture.capture))
        }
        _ => None,
    }
}

#[cfg(feature = "internal-checker")]
fn render_authored_output(
    prepared: &CheckedLiteralOutput, witness: &ScalarCheckerIntegerWitness,
    startup: Option<&HashMap<ByteSpan, InitializerValue<'_>>>, work: &mut usize,
) -> Option<CheckedLiteralOutput> {
    use super::{checker_directive::{CheckerScalarTransform, CheckerStateSelection, CheckerStateType, ScalarCheckerTextFile}, checker_flow::charge_call_work};
    let mut raw = HashMap::new();
    let mut scalar = |origin, ty, transform, work: &mut usize| {
        let (known_ty, values) = match raw.entry(origin) {
            std::collections::hash_map::Entry::Occupied(entry) => entry.into_mut(),
            std::collections::hash_map::Entry::Vacant(entry) => {
                let values = match origin {
                    AuthoredScalarOrigin::Binding(binding) => project_authored_scalar(witness, binding, ty, work)?,
                    AuthoredScalarOrigin::Module(span) => {
                        charge_call_work(work, 1)?;
                        let values = match startup?.get(&span)? {
                            InitializerValue::Boolean(value) if *ty == ScalarType::Bool =>
                                IntegerSet::singleton(&BigInt::from(u8::from(*value))),
                            InitializerValue::Integer { ty: actual, value } if *actual == ty =>
                                IntegerSet::singleton(value),
                            _ => return None,
                        };
                        Rc::new(values)
                    }
                };
                entry.insert((ty, values))
            }
        };
        if *known_ty != ty { return None; }
        if transform == CheckerScalarTransform::Identity { return Some(Rc::clone(values)); }
        // Both admitted unary operators are order-reversing unit affine
        // transformations. Check representability before allocating a result.
        let (lower, upper) = values.extremes()?;
        let offset = match transform {
            CheckerScalarTransform::LogicalNot if *ty == ScalarType::Bool => {
                let one = BigInt::from(1u8);
                if lower < &BigInt::ZERO || upper > &one { return None; }
                one
            }
            CheckerScalarTransform::Negate => {
                let (minimum, maximum) = integer_bounds(ty)?;
                if -upper < minimum || -lower > maximum { return None; }
                BigInt::ZERO
            }
            _ => return None,
        };
        charge_call_work(work, values.interval_count().saturating_add(1))?;
        Some(Rc::new(values.affine_unit(true, &offset, false)))
    };
    let selected_code = match &prepared.code_value {
        CheckerCode::Literal(_) => None,
        CheckerCode::Binding(binding, ty, transform) => Some((AuthoredScalarOrigin::Binding(binding.as_ref()), ty, *transform)),
        CheckerCode::Module(span, ty, transform) => Some((AuthoredScalarOrigin::Module(*span), ty, *transform)),
        CheckerCode::Projection(selection, ty, transform) => Some((authored_scalar_origin(selection, ty)?, ty, *transform)),
        CheckerCode::Lexical(..) => return None,
    };
    let projected_code = match selected_code {
        Some((origin, ty, transform)) => {
            let values = scalar(origin, ty, transform, work)?;
            values.singleton_value()?;
            Some((origin, ty, transform, values))
        }
        None => None,
    };
    let count = prepared.text_files.len().checked_add(prepared.state_files.len())?;
    let mut copied_bytes = prepared.stdout_bytes.len().saturating_add(prepared.stderr_bytes.len());
    for file in prepared.text_files.iter() {
        charge_call_work(work, 1)?;
        copied_bytes = copied_bytes.saturating_add(file.path.len()).saturating_add(file.text.len());
    }
    for file in prepared.state_files.iter() {
        charge_call_work(work, 1)?;
        copied_bytes = copied_bytes.saturating_add(file.path.len());
    }
    charge_call_work(work, count.saturating_add(copied_bytes.div_ceil(32)))?;
    let mut text = prepared.text_files.iter();
    let mut selected = prepared.state_files.iter().peekable();
    let mut files = Vec::with_capacity(count);
    // Cache within this one immutable observation only. Borrow checked
    // binding identities instead of cloning source metadata per output path.
    let mut encoded = HashMap::new();
    let mut encoded_shapes = HashMap::new();
    for position in 0..count {
        if selected.peek().is_some_and(|file| file.position == position) {
            let file = selected.next()?;
            let bytes: &Box<[u8]> = match (&file.selection, &file.ty) {
                (CheckerStateSelection::Aggregate(shape), CheckerStateType::Nominal(_) | CheckerStateType::FixedArray) => {
                    match encoded_shapes.entry(Rc::as_ptr(shape)) {
                        std::collections::hash_map::Entry::Occupied(entry) => entry.into_mut(),
                        std::collections::hash_map::Entry::Vacant(entry) => {
                            let mut json = String::new();
                            encode_snapshot_node(&shape.root, shape, witness, work, &mut json)?;
                            json.push('\n');
                            entry.insert(json.into_bytes().into_boxed_slice())
                        }
                    }
                }
                (selection, CheckerStateType::Scalar(file_ty)) => {
                    let origin = authored_scalar_origin(selection, file_ty)?;
                    let (ty, bytes) = match encoded.entry((origin, file.transform)) {
                        std::collections::hash_map::Entry::Occupied(entry) => entry.into_mut(),
                        std::collections::hash_map::Entry::Vacant(entry) => {
                            let values = match &projected_code {
                                Some((code_origin, code_ty, transform, values)) if *code_origin == origin
                                    && *code_ty == file_ty && *transform == file.transform => Rc::clone(values),
                                _ => scalar(origin, file_ty, file.transform, work)?,
                            };
                            let json = serialize_scalar_analysis_state(file_ty, &values)?;
                            entry.insert((file_ty, json.into_bytes().into_boxed_slice()))
                        }
                    };
                    if *ty != file_ty { return None; }
                    bytes
                }
                _ => return None,
            };
            // Each file owns its bytes; meter both copying and publication.
            charge_call_work(work, bytes.len().div_ceil(32).saturating_mul(2))?;
            files.push(ScalarCheckerTextFile {
                path: file.path.clone(), path_span: file.path_span, text_span: file.state_span, text: bytes.clone(),
            });
        } else {
            files.push(text.next()?.clone());
        }
    }
    let code_value = match projected_code {
        Some((_, _, _, values)) => CheckerCode::Literal(values.singleton_value()?.clone()),
        None => prepared.code_value.clone(),
    };
    Some(CheckedLiteralOutput {
        stdout: prepared.stdout, stderr: prepared.stderr, code: prepared.code, files: prepared.files,
        stdout_bytes: prepared.stdout_bytes.clone(), stderr_bytes: prepared.stderr_bytes.clone(), code_value,
        text_files: files.into_boxed_slice(), state_files: Box::new([]), has_module_values: false,
    })
}

#[cfg(feature = "internal-checker")]
fn project_authored_scalar(
    witness: &ScalarCheckerIntegerWitness, binding: &ReferenceBindingId, ty: &ScalarType, work: &mut usize,
) -> Option<Rc<IntegerSet>> {
    use super::checker_flow::charge_call_work;
    charge_call_work(work, witness.axes.len().saturating_add(1))?;
    let axis = witness.axes.iter().position(|(id, axis_ty)| id == binding && axis_ty == ty)?;
    let values = witness.state.project_axis_bounded(axis, work)?;
    charge_call_work(work, values.interval_count())?;
    Some(values)
}

#[cfg(feature = "internal-checker")]
fn encode_authored_scalar(
    witness: &ScalarCheckerIntegerWitness, binding: &ReferenceBindingId, ty: &ScalarType, work: &mut usize,
) -> Option<String> {
    let values = project_authored_scalar(witness, binding, ty, work)?;
    serialize_scalar_analysis_state(ty, &values)
}

#[cfg(feature = "internal-checker")]
fn encode_snapshot_node(
    node: &super::checker_directive::CheckerSnapshotNode,
    shape: &super::checker_directive::CheckerSnapshotShape,
    witness: &ScalarCheckerIntegerWitness, work: &mut usize, json: &mut String,
) -> Option<()> {
    use super::{checker_directive::CheckerSnapshotNode, checker_flow::charge_call_work};
    match node {
        CheckerSnapshotNode::Leaf(index) => {
            let leaf = shape.leaves.get(*index)?;
            let node = encode_authored_scalar(witness, &leaf.capture, &leaf.ty, work)?;
            json.push_str(node.strip_suffix('\n')?);
        }
        CheckerSnapshotNode::Array(elements) => {
            json.push_str(r#"{"type":"#);
            encode_snapshot_type(node, shape, work, json)?;
            json.push_str(r#","value":["#);
            for (index, child) in elements.iter().enumerate() {
                charge_call_work(work, 1)?;
                if index != 0 { json.push(','); }
                encode_snapshot_node(child, shape, witness, work, json)?;
            }
            json.push_str("]}");
        }
        CheckerSnapshotNode::Nominal { name, fields } => {
            charge_call_work(work, 1usize.saturating_add(name.len().div_ceil(32).saturating_mul(6)))?;
            json.push_str(r#"{"type":{"kind":"struct","name":"#);
            json.push_str(&serde_json::to_string(name.as_ref()).ok()?);
            json.push_str(r#"},"value":{"#);
            for (index, (name, child)) in fields.iter().enumerate() {
                charge_call_work(work, 1usize.saturating_add(name.len().div_ceil(32).saturating_mul(6)))?;
                if index != 0 { json.push(','); }
                json.push_str(&serde_json::to_string(name.as_ref()).ok()?);
                json.push(':');
                encode_snapshot_node(child, shape, witness, work, json)?;
            }
            json.push_str("}}");
        }
    }
    Some(())
}

#[cfg(feature = "internal-checker")]
fn encode_snapshot_type(
    node: &super::checker_directive::CheckerSnapshotNode,
    shape: &super::checker_directive::CheckerSnapshotShape, work: &mut usize, json: &mut String,
) -> Option<()> {
    use std::fmt::Write as _;
    use super::{checker_directive::CheckerSnapshotNode, checker_flow::charge_call_work};
    charge_call_work(work, 1)?;
    match node {
        CheckerSnapshotNode::Leaf(index) => {
            let kind = analysis_scalar_kind(&shape.leaves.get(*index)?.ty)?;
            write!(json, r#"{{"kind":"{kind}"}}"#).ok()?;
        }
        CheckerSnapshotNode::Nominal { name, .. } => {
            charge_call_work(work, name.len().div_ceil(32).saturating_mul(6))?;
            json.push_str(r#"{"kind":"struct","name":"#);
            json.push_str(&serde_json::to_string(name.as_ref()).ok()?);
            json.push('}');
        }
        CheckerSnapshotNode::Array(elements) => {
            write!(json, r#"{{"kind":"array","length":{},"element":"#, elements.len()).ok()?;
            encode_snapshot_type(elements.first()?, shape, work, json)?;
            json.push('}');
        }
    }
    Some(())
}

#[cfg(feature = "internal-checker")]
fn analysis_scalar_kind(ty: &ScalarType) -> Option<&'static str> {
    Some(match ty {
        ScalarType::Bool => "bool",
        ScalarType::I8 => "i8", ScalarType::I16 => "i16", ScalarType::I32 => "i32",
        ScalarType::I64 => "i64", ScalarType::I128 => "i128",
        ScalarType::U8 => "u8", ScalarType::U16 => "u16", ScalarType::U32 => "u32",
        ScalarType::U64 => "u64", ScalarType::U128 => "u128",
        _ => return None,
    })
}

#[cfg(feature = "internal-checker")]
fn serialize_scalar_analysis_state(ty: &ScalarType, values: &IntegerSet) -> Option<String> {
    use std::fmt::Write as _;
    let (min, max) = values.extremes()?;
    let kind = analysis_scalar_kind(ty)?;
    let mut result = format!(r#"{{"type":{{"kind":"{kind}"}},"value":"#);
    if *ty == ScalarType::Bool {
        let zero = BigInt::from(0u8);
        let one = BigInt::from(1u8);
        if min < &zero || max > &one { return None; }
        result.push_str(match (min == &zero, max == &one) {
            (true, true) => r#"{"kind":"alternatives","values":[false,true]}"#,
            (true, false) => "false",
            (false, true) => "true",
            _ => return None,
        });
    } else {
        let (floor, ceiling) = super::typecheck::integer_bounds(ty)?;
        if min < &floor || max > &ceiling { return None; }
        let alternatives = values.interval_count() > 1;
        if alternatives { result.push_str(r#"{"kind":"alternatives","values":["#); }
        for (i, (lo, hi)) in values.intervals().enumerate() {
            if i != 0 { result.push(','); }
            if lo == hi {
                write!(result, "{lo}").ok()?;
            } else {
                write!(result, r#"{{"kind":"range","minimum":{lo},"maximum":{hi}}}"#).ok()?;
            }
        }
        if alternatives { result.push_str("]}"); }
    }
    result.push_str("}\n");
    Some(result)
}

#[cfg(all(test, feature = "internal-checker"))]
fn ordered_failure_as_legacy(failure: ScalarOrderedCheckerFailure) -> ProjectCheck {
    let ScalarOrderedCheckerFailure {
        source, operation, directive, condition, witness: ScalarCheckerIntegerWitness { axes, state, .. }, output,
    } = failure;
    let operation = match operation {
        ScalarCheckerOperation::Require => CheckerOperation::Require,
        ScalarCheckerOperation::Narrow => CheckerOperation::Narrow,
    };
    ProjectCheck::Failed { source, operation, directive, condition, axes, state, output: Rc::unwrap_or_clone(output) }
}

fn project_failure(
    body: &FunctionCallSites,
    source: &SourceIdentity,
    failure: IntegerCheckFailure<'_>,
) -> ProjectCheck {
    selected_failure(
        source,
        &body.structure.checker_directives[&failure.directive],
        body.occurrences[failure.directive.0].span,
        failure.state,
        failure.axes.into_iter().map(|(binding, ty)| (binding.clone(), ty.clone())).collect(),
    )
}

fn selected_failure(
    source: &SourceIdentity,
    directive: &PreparedCheckerDirective,
    span: ByteSpan,
    state: IntegerInputs,
    axes: Vec<(ReferenceBindingId, ScalarType)>,
) -> ProjectCheck {
    ProjectCheck::Failed {
        source: source.clone(),
        operation: directive.operation,
        directive: span,
        condition: directive.condition,
        state,
        axes,
        output: directive.output.clone(),
    }
}

fn child(parent: &CstNode, kind: SyntaxKind) -> Result<CstNode, ProjectCheck> {
    parent.children().find(|node| node.kind() == kind).ok_or(ProjectCheck::InvalidProof)
}

fn identifiers(parent: &CstNode) -> impl Iterator<Item = String> + '_ {
    parent.children_with_tokens().filter_map(|element| {
        let token = element.into_token()?;
        (token.kind() == SyntaxKind::Identifier).then(|| token.text().to_owned())
    })
}

#[doc(hidden)]
pub struct ScalarProofModuleInput {
    pub source: SourceIdentity,
    pub text: String,
    pub namespaces: Vec<ScalarNamespaceBinding>,
}

#[doc(hidden)]
pub struct ScalarProofDeclarations {
    declarations: ScalarSourceDeclarations,
    definitions: Vec<CstNode>,
    #[cfg(feature = "internal-checker")]
    contextual_proofs: Vec<ContextualProofHeader>,
    #[cfg(feature = "internal-checker")]
    configured_mixed_catalog: bool,
    #[cfg(feature = "internal-checker")]
    configured_contextual_root: bool,
}

#[cfg(feature = "internal-checker")]
impl ScalarProofDeclarations {
    pub fn declarations(&self) -> &ScalarSourceDeclarations {
        &self.declarations
    }
}

pub(crate) fn derive_scalar_proof_declarations_from_cst(canonical: &CanonicalCstRoot) -> ScalarProofDeclarations {
    derive_scalar_proof_declarations_using_headers(canonical,
        #[cfg(feature = "internal-checker")] contextual_proof_headers(canonical, false).unwrap_or_default())
}

fn derive_scalar_proof_declarations_using_headers(
    canonical: &CanonicalCstRoot,
    #[cfg(feature = "internal-checker")] contextual_proofs: Vec<ContextualProofHeader>,
) -> ScalarProofDeclarations {
    let mut definitions = Vec::new();
    #[cfg(feature = "internal-checker")]
    let contextual = !contextual_proofs.is_empty();
    #[cfg(not(feature = "internal-checker"))]
    let contextual = false;
    let declarations = super::derive_scalar_declarations(canonical, contextual, contextual, false, None, Some(&mut definitions),
        #[cfg(feature = "internal-checker")] true);
    ScalarProofDeclarations { declarations, definitions,
        #[cfg(feature = "internal-checker")]
        contextual_proofs,
        #[cfg(feature = "internal-checker")]
        configured_mixed_catalog: false,
        #[cfg(feature = "internal-checker")]
        configured_contextual_root: false,
    }
}

#[cfg(feature = "internal-checker")]
pub(crate) fn derive_configured_scalar_proof_declarations_from_cst(canonical: &CanonicalCstRoot) -> ScalarProofDeclarations {
    let root = child(&canonical.root, SyntaxKind::Root).expect("canonical source root");
    let mut contextual_proofs = Vec::new();
    let mut ordinary_count = 0;
    let mut names = HashSet::new();
    let mut duplicate = None;
    for node in root.children().filter(|node| node.kind() == SyntaxKind::ProofDecl) {
        if contextual_proofs.len() + ordinary_count == 2 * MAX_CONTEXTUAL_PROOFS {
            return derive_scalar_proof_declarations_using_headers(canonical, Vec::new());
        }
        if let Some(name) = module_proof_name(&node) {
            if !names.insert(name.text().to_owned()) { duplicate = Some(wosy_syntax::byte_span(&node)); }
        }
        match contextual_proof_header(&node, true) {
            Ok(header) => contextual_proofs.push(header),
            Err(_) => ordinary_count += 1,
        }
    }
    if contextual_proofs.is_empty() || ordinary_count == 0 {
        if contextual_proofs.len() > MAX_CONTEXTUAL_PROOFS || duplicate.is_some() {
            contextual_proofs.clear();
        }
        return derive_scalar_proof_declarations_using_headers(canonical, contextual_proofs);
    }
    // Extract the exact two catalogs from the same canonical CST and type
    // the declarations once. No unrecognized proof goes unselected.
    let mut definitions = Vec::new();
    let mut declarations = super::derive_scalar_declarations(canonical, true, true, false, None, Some(&mut definitions), true);
    if let Some(span) = duplicate {
        declarations.diagnostics.push(super::contextual::reported_error(
            wosy_syntax::SourceSpan::new(declarations.source().clone(), span), "duplicate proof name in the configured source"));
    }
    definitions.retain(|node| !contextual_proofs.iter().any(|header| header.proof == wosy_syntax::byte_span(node)));
    ScalarProofDeclarations { declarations, definitions, contextual_proofs, configured_mixed_catalog: true, configured_contextual_root: false }
}

#[cfg(feature = "internal-checker")]
pub(crate) fn derive_configured_root_scalar_proof_declarations_from_cst(canonical: &CanonicalCstRoot) -> ScalarProofDeclarations {
    let contextual_proofs = contextual_proof_headers(canonical, true).unwrap_or_default();
    if !contextual_proofs.is_empty() {
        return derive_scalar_proof_declarations_using_headers(canonical, contextual_proofs);
    }
    let mut definitions = Vec::new();
    // Retain ordinary proof syntax diagnostics. Only the B0003 boundary
    // becomes provisional, and only this loader can consume the result.
    let mut boundary = None;
    let mut declarations = super::derive_scalar_declarations(canonical, false, false, false, Some(&mut boundary), Some(&mut definitions), true);
    let mut configured_contextual_root = false;
    if let Some(boundary) = boundary {
        let targets = definitions.iter().take(MAX_CONTEXTUAL_PROOFS + 1).map(proof_target_tokens)
            .collect::<Result<Vec<_>, _>>();
        let supported_candidate = !declarations.contextual_places.declarations.is_empty() && targets.as_ref().is_ok_and(|targets| targets.len() <= MAX_CONTEXTUAL_PROOFS
            && declarations.items.iter().any(|item| {
                let ScalarItem::Binding(binding) = item else { return false; };
                let ScalarExpression::Call { receiver: None, name, .. } = &binding.value else { return false; };
                targets.iter().any(|(namespace, target)| namespace.is_none() && target.text() == name)
            }));
        // This syntax check only decides whether to forward a provisional
        // candidate. Actual admission requires the canonical typed target.
        if supported_candidate {
            configured_contextual_root = true;
        } else {
            declarations.diagnostics.push(boundary);
        }
    }
    ScalarProofDeclarations { declarations, definitions, contextual_proofs: Vec::new(),
        configured_mixed_catalog: false, configured_contextual_root }
}

struct ModuleProofCatalog {
    source: SourceIdentity,
    definitions: Vec<CstNode>,
}

struct ModuleProofs {
    definitions: Vec<CstNode>,
    first_query: usize,
}

enum OrderedProofPreparation {
    None,
    #[cfg(feature = "internal-checker")]
    MatchOnly,
    #[cfg(feature = "internal-checker")]
    All,
}

struct PreparedProofModule {
    source: SourceIdentity,
    proofs: HashMap<SourceIdentity, ModuleProofs>,
    prepared: PreparedCheckerProject,
    #[cfg(feature = "internal-checker")]
    ordered_steps: Vec<Option<PreparedOrderedProofSteps>>,
    #[cfg(feature = "internal-checker")]
    context: Option<super::contextual::DormantContextReceipt>,
}

struct SelectedModuleProof<'a> {
    node: &'a CstNode,
    function: (usize, usize, &'a ScalarFunction),
    owner: &'a ScalarModule,
    body: &'a FunctionCallSites,
    target: &'a ResolvedCallTarget,
    #[cfg(feature = "internal-checker")]
    ordered_steps: Option<&'a PreparedOrderedProofSteps>,
}

#[cfg(test)]
struct VerifiedModuleReturnBound<'a> {
    issuer: &'a PreparedProofModule,
    proof: &'a CstNode,
    bound: VerifiedReturnBound,
}

fn module_proof_name(proof: &CstNode) -> Option<CstToken> {
    proof.children_with_tokens().filter_map(|element| element.into_token())
        .find(|token| token.kind() == SyntaxKind::Identifier)
}

impl PreparedProofModule {
    #[cfg(test)]
    fn prepare(source: SourceIdentity, text: String, inputs: ScalarPreparationInputs) -> Result<Self, ProjectCheck> {
        Self::prepare_project(
            source.clone(),
            vec![ScalarProofModuleInput { source: source.clone(), text, namespaces: Vec::new() }],
            vec![source],
            inputs,
        )
    }

    fn prepare_project(
        source: SourceIdentity,
        modules: Vec<ScalarProofModuleInput>,
        initialization_order: Vec<SourceIdentity>,
        inputs: ScalarPreparationInputs,
    ) -> Result<Self, ProjectCheck> {
        let mut declarations = Vec::with_capacity(modules.len());
        let mut proofs = Vec::new();
        for module in modules {
            let parsed = wosy_syntax::parse_proof_module(module.source, module.text, &[]);
            if !parsed.is_valid() {
                return Err(ProjectCheck::InvalidProof);
            }
            let catalog = derive_scalar_proof_declarations_from_cst(parsed.canonical_cst());
            #[cfg(feature = "internal-checker")]
            if !catalog.contextual_proofs.is_empty() || catalog.configured_contextual_root { return Err(ProjectCheck::Unsupported); }
            let ScalarProofDeclarations { declarations: module_declarations, definitions, .. } = catalog;
            if !definitions.is_empty() {
                proofs.push(ModuleProofCatalog { source: module_declarations.source().clone(), definitions });
            }
            declarations.push((module_declarations, module.namespaces));
        }
        Self::prepare_declarations(source, declarations, proofs, initialization_order, inputs, Vec::new(), OrderedProofPreparation::None)
    }

    fn prepare_declarations(
        source: SourceIdentity,
        declarations: Vec<(ScalarSourceDeclarations, Vec<ScalarNamespaceBinding>)>,
        catalogs: Vec<ModuleProofCatalog>,
        initialization_order: Vec<SourceIdentity>,
        inputs: ScalarPreparationInputs,
        dormant: Vec<ScalarProofDeclarations>,
        #[cfg_attr(not(feature = "internal-checker"), allow(unused_variables))] ordered: OrderedProofPreparation,
    ) -> Result<Self, ProjectCheck> {
        Self::prepare_declarations_in::<false>(source, declarations, catalogs, initialization_order, inputs, dormant, ordered, false)
    }

    fn prepare_declarations_in<const CONTEXTUAL: bool>(
        source: SourceIdentity,
        mut declarations: Vec<(ScalarSourceDeclarations, Vec<ScalarNamespaceBinding>)>,
        catalogs: Vec<ModuleProofCatalog>,
        initialization_order: Vec<SourceIdentity>,
        inputs: ScalarPreparationInputs,
        dormant: Vec<ScalarProofDeclarations>,
        #[cfg_attr(not(feature = "internal-checker"), allow(unused_variables))] ordered: OrderedProofPreparation,
        #[cfg_attr(not(feature = "internal-checker"), allow(unused_variables))] configured_root: bool,
    ) -> Result<Self, ProjectCheck> {
        let mut graph_sources: HashMap<_, _> = initialization_order.iter().map(|source| (source, false)).collect();
        if graph_sources.len() != initialization_order.len() {
            return Err(ProjectCheck::AmbiguousRoot);
        }
        if !graph_sources.contains_key(&source) {
            return Err(ProjectCheck::MissingRoot);
        }
        for (module, namespaces) in &declarations {
            let seen = graph_sources.get_mut(module.source()).ok_or(ProjectCheck::RootSourceOutsideInitOrder)?;
            if std::mem::replace(seen, true) {
                return Err(ProjectCheck::AmbiguousRoot);
            }
            if namespaces.iter().any(|edge| !graph_sources.contains_key(&edge.target)) {
                return Err(ProjectCheck::RootSourceOutsideInitOrder);
            }
        }
        if graph_sources.values().any(|seen| !seen) {
            return Err(ProjectCheck::MissingRoot);
        }
        if !dormant.is_empty() {
            validate_dormant_source_boundaries(
                &declarations, &source, |source| graph_sources.contains_key(source),
                dormant.iter().map(|proof| &proof.declarations),
            )?;
            declarations.reserve(dormant.len());
        }
        let mut proofs = HashMap::new();
        for catalog in catalogs {
            if !graph_sources.contains_key(&catalog.source) {
                return Err(ProjectCheck::RootSourceOutsideInitOrder);
            }
            if proofs.insert(catalog.source, ModuleProofs { definitions: catalog.definitions, first_query: 0 }).is_some() {
                return Err(ProjectCheck::AmbiguousRoot);
            }
        }
        for catalog in dormant {
            #[cfg(feature = "internal-checker")]
            if !catalog.contextual_proofs.is_empty() || catalog.configured_contextual_root { return Err(ProjectCheck::Unsupported); }
            let ScalarProofDeclarations { declarations: source, definitions, .. } = catalog;
            if !definitions.is_empty() {
                proofs.insert(source.source().clone(), ModuleProofs { definitions, first_query: 0 });
            }
            declarations.push((source, Vec::new()));
        }
        let mut targets = Vec::new();
        #[cfg(feature = "internal-checker")]
        let mut ordered_steps = Vec::new();
        for (source, proofs) in &mut proofs {
            proofs.first_query = targets.len();
            for definition in &proofs.definitions {
                let (receiver, name) = proof_target_tokens(definition)?;
                #[cfg(feature = "internal-checker")]
                match ordered {
                    OrderedProofPreparation::None => {}
                    OrderedProofPreparation::All => ordered_steps.push(PreparedOrderedProofSteps::prepare(definition)?),
                    OrderedProofPreparation::MatchOnly => {
                        let is_match = definition.children().any(|node| node.kind() == SyntaxKind::ProofMatchBlock);
                        ordered_steps.push(if is_match { PreparedOrderedProofSteps::prepare(definition)? } else { None });
                    }
                }
                targets.push((source, receiver, name));
            }
        }
        let queries = targets.iter().enumerate().map(|(_ordinal, (source, receiver, name))| CheckerTargetQuery {
            source,
            receiver: receiver.as_ref().map(CstToken::text),
            name: name.text(),
            #[cfg(feature = "internal-checker")]
            watch_case_nesting: ordered_steps.get(_ordinal).and_then(Option::as_ref)
                .is_some_and(|proof| matches!(proof.shape, Some(AuthoredShape::Cases))),
        }).collect::<Vec<_>>();
        #[cfg(feature = "internal-checker")]
        let (prepared, context) = if CONTEXTUAL {
            let (project, context) = super::contextual::prepare_contextual_transport_graph_with_targets(
                declarations, initialization_order, inputs, true, false, &queries, true, configured_root,
            ).map_err(|_| ProjectCheck::Unsupported)?;
            (PreparedCheckerProject::from_contextual_transport(project), Some(context))
        } else {
            (prepared::prepare_checker_project_with_queries(declarations, initialization_order, inputs, &queries)?, None)
        };
        #[cfg(not(feature = "internal-checker"))]
        let prepared = prepared::prepare_checker_project_with_queries(declarations, initialization_order, inputs, &queries)?;
        Ok(Self { source, proofs, prepared,
            #[cfg(feature = "internal-checker")]
            ordered_steps,
            #[cfg(feature = "internal-checker")]
            context,
        })
    }

    fn select(&self, source: &SourceIdentity, proof_name: &str) -> Result<(&CstNode, usize), ProjectCheck> {
        let proofs = self.proofs.get(source).ok_or(ProjectCheck::MissingRoot)?;
        let mut selected = proofs.definitions.iter().enumerate().filter(|(_, proof)| {
            module_proof_name(proof).is_some_and(|token| token.text() == proof_name)
        });
        let (index, proof) = selected.next().ok_or(ProjectCheck::MissingRoot)?;
        if selected.next().is_some() {
            return Err(ProjectCheck::AmbiguousRoot);
        }
        Ok((proof, proofs.first_query + index))
    }

    #[cfg(test)]
    fn check(&self, proof_name: &str) -> Result<(ByteSpan, ProjectCheck), ProjectCheck> {
        self.check_at(&self.source, proof_name)
    }

    #[cfg(test)]
    fn check_at(&self, source: &SourceIdentity, proof_name: &str) -> Result<(ByteSpan, ProjectCheck), ProjectCheck> {
        let proof = self.select_resolved(source, proof_name)?;
        let (outcome, _) = check_selected_proof(&self.prepared, proof.function, proof.node, source, None)?;
        Ok((byte_span(proof.node), outcome))
    }

    #[cfg(test)]
    fn type_where(&self, proof_name: &str) -> Result<(), ProjectCheck> {
        let proof = self.select_resolved(&self.source, proof_name)?;
        let body = proof.body;
        let target = child(proof.node, SyntaxKind::ProofTarget)?;
        let inputs = identifiers(&child(&target, SyntaxKind::Parameters)?).collect::<Vec<_>>();
        let layout = proof.owner.target_layout;
        if inputs.len() != body.boundary.parameters.len()
            || inputs.iter().collect::<HashSet<_>>().len() != inputs.len()
        {
            return Err(ProjectCheck::InvalidProof);
        }
        let _ = typed_proof_where(proof.node, &self.source, layout, &inputs, body)?;
        Ok(())
    }

    #[cfg(test)]
    fn verify(&self, proof_name: &str) -> Option<VerifiedModuleReturnBound<'_>> {
        let proof = self.select_resolved(&self.source, proof_name).ok()?;
        let (_, verified) = check_selected_proof(
            &self.prepared,
            proof.function,
            proof.node,
            &self.source,
            Some(ProofSummaryOrigin::ModuleDeclaration {
                source: &self.source,
                target: proof.target,
            }),
        ).ok()?;
        Some(VerifiedModuleReturnBound { issuer: self, proof: proof.node, bound: verified? })
    }

    fn select_resolved(
        &self,
        proof_source: &SourceIdentity,
        proof_name: &str,
    ) -> Result<SelectedModuleProof<'_>, ProjectCheck> {
        let (node, query) = self.select(proof_source, proof_name)?;
        self.resolve_selected_proof(node, query)
    }

    fn resolve_selected_proof<'a>(
        &'a self, node: &'a CstNode, query: usize,
    ) -> Result<SelectedModuleProof<'a>, ProjectCheck> {
        let (project, calls) = self.prepared.parts();
        let ResolvedCheckerTarget { target, declaration: (module, item) } =
            calls.checker_targets.get(query).and_then(Option::as_ref).ok_or(ProjectCheck::MissingRoot)?;
        let owner = project.modules.get(*module).ok_or(ProjectCheck::MissingRoot)?;
        let Some(ScalarItem::Function(function)) = owner.items.get(*item) else {
            return Err(ProjectCheck::MissingRoot);
        };
        let ResolvedCallTarget::ModuleCallable { source, declaration_span, concrete: ConcreteCallSelection::Declaration } = target
        else {
            return Err(ProjectCheck::Unsupported);
        };
        if source != &owner.source || *declaration_span != function.name_span {
            return Err(ProjectCheck::MissingRoot);
        }
        let body = calls.function_body(*module, *item, None).ok_or(ProjectCheck::MissingRootOccurrences)?;
        Ok(SelectedModuleProof { node, function: (*module, *item, function), owner, body, target,
            #[cfg(feature = "internal-checker")]
            ordered_steps: self.ordered_steps.get(query).and_then(Option::as_ref),
        })
    }

    #[cfg(test)]
    fn apply(
        &self,
        caller_name: &str,
        proof_name: &str,
        verified: &VerifiedModuleReturnBound<'_>,
    ) -> Option<ImportedRequirement> {
        let bound = &verified.bound;
        if !std::ptr::eq(self, verified.issuer)
            || bound.proof_venue != ProofVenue::ModuleDeclaration
            || bound.proof_source != self.source
            || bound.proof_name != proof_name
            || bound.proof_span != byte_span(verified.proof)
        {
            return None;
        }
        apply_verified_return_bound(&self.prepared, &self.source, caller_name, bound)
    }
}

#[cfg(feature = "internal-checker")]
#[doc(hidden)]
#[derive(Clone, Debug, PartialEq)]
pub enum ScalarModuleProofOutcome {
    Proved,
    Refuted,
    NoApplicableInputs,
    Invalid(Vec<Diagnostic>),
    Unsupported,
}

#[cfg(feature = "internal-checker")]
#[doc(hidden)]
pub fn check_scalar_module_proof(
    proof_source: SourceIdentity,
    proof_name: &str,
    modules: Vec<ScalarProofModuleInput>,
    initialization_order: Vec<SourceIdentity>,
    inputs: ScalarPreparationInputs,
) -> ScalarModuleProofOutcome {
    match check_scalar_module_proofs(proof_source, &[proof_name], modules, initialization_order, inputs) {
        Ok(mut outcomes) => outcomes.pop().unwrap_or(ScalarModuleProofOutcome::Unsupported),
        Err(outcome) => outcome,
    }
}

#[cfg(feature = "internal-checker")]
#[doc(hidden)]
pub fn check_scalar_module_proofs(
    proof_source: SourceIdentity,
    proof_names: &[&str],
    modules: Vec<ScalarProofModuleInput>,
    initialization_order: Vec<SourceIdentity>,
    inputs: ScalarPreparationInputs,
) -> Result<Vec<ScalarModuleProofOutcome>, ScalarModuleProofOutcome> {
    if proof_names.is_empty() {
        return Ok(Vec::new());
    }
    let prepared = PreparedProofModule::prepare_project(proof_source, modules, initialization_order, inputs)
        .map_err(|error| module_proof_outcome(Err(error)))?;
    Ok(prepared.check_module_proofs(proof_names))
}

#[cfg(feature = "internal-checker")]
#[doc(hidden)]
pub fn check_loaded_scalar_module_proofs(
    proof_names: &[&str],
    declarations: Vec<(ScalarSourceDeclarations, Vec<ScalarNamespaceBinding>)>,
    proof: (ScalarProofDeclarations, Vec<ScalarNamespaceBinding>),
    initialization_order: Vec<SourceIdentity>,
    inputs: ScalarPreparationInputs,
) -> Result<Vec<ScalarModuleProofOutcome>, ScalarModuleProofOutcome> {
    if proof_names.is_empty() {
        return Ok(Vec::new());
    }
    let source = proof.0.declarations.source().clone();
    let selections = proof_names.iter().map(|&name| (&source, name)).collect::<Vec<_>>();
    check_loaded_scalar_module_proof_selections(&selections, declarations, vec![proof], initialization_order, inputs)
}

#[cfg(feature = "internal-checker")]
#[doc(hidden)]
pub fn check_loaded_scalar_module_proof_selections(
    selections: &[(&SourceIdentity, &str)],
    declarations: Vec<(ScalarSourceDeclarations, Vec<ScalarNamespaceBinding>)>,
    proofs: Vec<(ScalarProofDeclarations, Vec<ScalarNamespaceBinding>)>,
    initialization_order: Vec<SourceIdentity>,
    inputs: ScalarPreparationInputs,
) -> Result<Vec<ScalarModuleProofOutcome>, ScalarModuleProofOutcome> {
    if selections.is_empty() {
        return Ok(Vec::new());
    }
    let prepared = prepare_loaded_proof_project(declarations, proofs, initialization_order, inputs, Vec::new(), OrderedProofPreparation::None)
        .map_err(|error| module_proof_outcome(Err(error)))?;
    Ok(prepared.check_module_proof_selections(selections))
}

#[cfg(feature = "internal-checker")]
fn prepare_loaded_proof_project(
    mut declarations: Vec<(ScalarSourceDeclarations, Vec<ScalarNamespaceBinding>)>,
    proofs: Vec<(ScalarProofDeclarations, Vec<ScalarNamespaceBinding>)>,
    initialization_order: Vec<SourceIdentity>,
    inputs: ScalarPreparationInputs,
    dormant: Vec<ScalarProofDeclarations>, ordered: OrderedProofPreparation,
) -> Result<PreparedProofModule, ProjectCheck> {
    let mut catalogs = Vec::with_capacity(proofs.len());
    declarations.reserve(proofs.len());
    for (proof, namespaces) in proofs {
        if !proof.contextual_proofs.is_empty() || proof.configured_contextual_root { return Err(ProjectCheck::Unsupported); }
        let ScalarProofDeclarations { declarations: proof_declarations, definitions, .. } = proof;
        catalogs.push(ModuleProofCatalog { source: proof_declarations.source().clone(), definitions });
        declarations.push((proof_declarations, namespaces));
    }
    let root = initialization_order.first().cloned().ok_or(ProjectCheck::MissingRoot)?;
    PreparedProofModule::prepare_declarations(root, declarations, catalogs, initialization_order, inputs, dormant, ordered)
}

