    #[cfg(feature = "internal-checker")]
    #[test]
    fn observed_flight_easing_keeps_original_call_and_rounding_order() {
        let app = source("src/main.w", "observed-flight-eased-unit");
        let program = r#"%%start
            struct copy RenderPose { f32 x; f32 heading; }
            RenderPose first = {.x=0.0;.heading=0.25;};
            RenderPose second = {.x=0.0;.heading=0.5;};
            RenderPose[2] presented_pose = [first,second];
            i32 wreck_age = 13;
            bool wreck_entered = false;
            f32 wreck_alpha = 0.0;
            i16 status = 5;
            f32(i32) float_i = fn(a) { core.sint_to_float<f32>(a) };
            f32(f32,f32,f32) clamp = fn(v,lo,hi) { if (v < lo) { lo } else { if (v > hi) { hi } else { v } } };
            f32(f32) eased_unit = fn(value) {
                f32 t = clamp(value,0.0,1.0);
                t*t*(3.0-2.0*t)
            };
            f32(f32) wrap = fn(a) { if (a > 3.14159265) { a - 6.28318530 } else { if (a < -3.14159265) { a + 6.28318530 } else { a } } };
            f32(f32) sin_small = fn(a) {
                f32 u = if (a > 1.57079633) { 3.14159265 - a } else { if (a < -1.57079633) { -3.14159265 - a } else { a } };
                f32 d = u*u;
                u*(1.0-d*(0.166666667-d*(0.008333333-d*0.000198413)))
            };
            f32(f32) cos_small = fn(a) { sin_small(wrap(a + 1.57079633)) };
            unit() render = fn {
                bool wrecking = wreck_age >= 0;
                f32 wreck_time = if (wrecking && !wreck_entered) { float_i(wreck_age)+wreck_alpha } else { 0.0 };
                f32 wreck_blend = eased_unit(wreck_time/13.0);
                f32 orbit = eased_unit(wreck_time/34.0);
                f32 p_heading = presented_pose[0].heading;
                f32 hp = sin_small(p_heading);
                f32 hz0 = cos_small(p_heading);
                bool active = wreck_blend == 1.0 && orbit > 0.0 && orbit < 1.0
                    && hp > 0.24 && hp < 0.26 && hz0 > 0.96 && hz0 < 0.98;
                if (active) { status = 37; } else { status = 19; };
            };
            render();
            core.narrow(false, {.stdout="";.stderr="";.code=status;.files=[];});
        %%end"#;
        for target_layout in [ScalarTargetLayout::NATIVE64, ScalarTargetLayout::WASM32] {
            for (age, index, code) in [("13", 0, 37), ("-1", 0, 19), ("13", 1, 19)] {
                let text = program.replace("wreck_age = 13", &format!("wreck_age = {age}"))
                    .replace("presented_pose[0]", &format!("presented_pose[{index}]"));
                let prepare = || prepare_loaded_scalar_ordered_local_proof_contexts(
                    vec![(declarations(&app, &text), Vec::new())], [], vec![app.clone()],
                    ScalarPreparationInputs { target_layout }, ScalarCheckerScope::CurrentPackage, Vec::new(),
                ).unwrap();
                let report = prepare().run().unwrap();
                let (capped, _, trace, _) = prepare().search_startup_authored_path(std::num::NonZeroUsize::MIN).unwrap();
                assert_eq!(capped, report.directives);
                assert_eq!(capped[0].code(), &BigInt::from(code));
                for call in ["eased_unit(wreck_time/13.0)", "eased_unit(wreck_time/34.0)", "clamp(value,0.0,1.0)", "sin_small(p_heading)", "cos_small(p_heading)"] {
                    let start = text.find(call).unwrap() as u32;
                    assert!(trace.contains_return(&wosy_syntax::SourceSpan::new(app.clone(), ByteSpan::new(start, start+call.len() as u32))));
                }
            }
        }
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn original_frame_computes_current_short_circuited_finite_f32_time() {
        use ordered_float_prefix::ExactValue;
        use super::super::checker_flow::projected_f32::ExactF32;
        let source = source("src/main.w", "original-flight-prefix-value");
        let text = r#"%%start
            i32 wreck_age = -1;
            bool wreck_entered = false;
            f32(i32) float_i = fn(a) { core.sint_to_float<f32>(a) };
            unit(f32) frame = fn(wreck_alpha) {
                bool wrecking = wreck_age >= 0;
                f32 wreck_time = if (wrecking && !wreck_entered) { float_i(wreck_age)+wreck_alpha } else { 0.0 };
                core.require(wreck_time >= 0.0, {.stdout="";.stderr="suffix";.code=7;.files=[];});
            };
        %%end"#;
        for target_layout in [ScalarTargetLayout::NATIVE64, ScalarTargetLayout::WASM32] {
            let prepared = prepare_checker_project(
                vec![(declarations(&source, text), Vec::new())], vec![source.clone()], ScalarPreparationInputs { target_layout },
            ).unwrap();
            let (project, calls) = prepared.parts();
            let target = project.modules[0].items.iter().position(|item| matches!(item, ScalarItem::Function(f) if f.name == "frame")).unwrap();
            let (root, ordinals) = package_startup_order(project, &project.modules).unwrap();
            let mut records = OrderedFailures::default();
            let (initialization, _) = check_package_initialization_observing_with_policy::<_, true, true>(
                &prepared, root, ordinals, ProofFreeOrderedEvidence, Some(&mut records),
            ).unwrap();
            let plan = ordered_float_prefix::prepare_readonly_prefix(&prepared, &initialization, (0,target)).unwrap();
            assert_eq!(plan.bindings.len(), 2);
            let formal = calls.function_body(0,target,None).unwrap().boundary.checker_parameter_bindings.as_ref().unwrap()[0].clone();
            let run = |age: i32, entered: Option<bool>, alpha: Option<u32>| {
                let formals = alpha.and_then(ExactF32::checked_bits).map(|value| (formal.clone(), ExactValue::F32(value))).into_iter().collect();
                let mut reads = 0;
                let result = ordered_float_prefix::evaluate_observed_prefix(&plan, None, formals, |decl, index, field| {
                    if field.is_some() || index.is_some() || decl.source != source { return None; }
                    reads += 1;
                    match &text[decl.range.start as usize..decl.range.end as usize] {
                        "wreck_age" => Some(ExactValue::Integer(ScalarType::I32, BigInt::from(age))),
                        "wreck_entered" => entered.map(ExactValue::Boolean),
                        _ => None,
                    }
                }, false, &mut 0, |_, _| None).map(|(values, _)| values);
                (result, reads)
            };
            let f32_value = |bits| ExactValue::F32(ExactF32::checked_bits(bits).unwrap());
            assert_eq!(run(-1, None, None), (Some(vec![ExactValue::Boolean(false), f32_value(0)]), 1));
            assert_eq!(run(0, Some(true), None), (Some(vec![ExactValue::Boolean(true), f32_value(0)]), 2));
            assert_eq!(run(0, Some(false), Some(1)), (Some(vec![ExactValue::Boolean(true), f32_value(1)]), 3));
            assert_eq!(run(0, Some(false), Some((-0.0f32).to_bits())), (Some(vec![ExactValue::Boolean(true), f32_value(0)]), 3));
            assert_eq!(run(16_777_217, Some(false), Some(0)), (Some(vec![ExactValue::Boolean(true), f32_value(16_777_216f32.to_bits())]), 3));
            assert_eq!(run(1, Some(false), None), (None, 3));
        }
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn dormant_float_literal_return_preserves_typed_guarded_integer_obligations() {
        use std::num::NonZeroUsize;
        for target_layout in [ScalarTargetLayout::NATIVE64, ScalarTargetLayout::WASM32] {
            let owner = source("src/main.w", "dormant-float-literal");
            let text = |claim: &str| format!(r#"%%start
                f32(i32,i32,i32) routes = fn(key,row,column) {{
                    if (key==19) {{
                        if (row==-1) {{
                            if (column==0) {{ core.require({claim}, {OUTPUT}); 2.0 }}
                            else {{ 0.0 }}
                        }} else {{ 0.0 }}
                    }} else {{ 0.0 }}
                }};
            %%end"#);
            let prepare = |text: &str, scope| prepare_loaded_scalar_ordered_local_proof_contexts(
                vec![(declarations(&owner, text), Vec::new())], [], vec![owner.clone()],
                ScalarPreparationInputs { target_layout }, scope, Vec::new(),
            ).ok().unwrap();
            let valid = text("key>=19 && key<=33");
            let invalid = text("key!=19 && key<=33");
            let scope = ScalarCheckerScope::CurrentPackage;
            let (receipt, end) = prepare(&valid, scope).run_private_authored_root(NonZeroUsize::MIN).unwrap();
            assert!(receipt.active && receipt.directives.is_empty());
            assert_eq!(end, Some(StartupAuthoredCompletion::Exhausted));
            let (receipt, end) = prepare(&invalid, scope).run_private_authored_root(NonZeroUsize::MIN).unwrap();
            let [failure] = receipt.directives.as_slice() else { panic!("one negative-control failure"); };
            for (index, value) in [19, -1, 0].into_iter().enumerate() {
                assert_eq!(failure.witness.axes().nth(index).unwrap().1, &ScalarType::I32);
                let value = BigInt::from(value);
                assert!(failure.witness.intervals_at(0, index).unwrap().eq([(&value, &value)]));
            }
            assert_eq!(end, Some(StartupAuthoredCompletion::LimitReached));
            let full = prepare(&invalid, scope).run().unwrap();
            assert_eq!(receipt.directives, full.directives);
            assert!(prepare(&valid, scope).run().unwrap().directives.is_empty());
            let (receipt, _) = prepare(&invalid, ScalarCheckerScope::MainFlowOnly)
                .run_private_authored_root(NonZeroUsize::MIN).unwrap();
            assert!(receipt.directives.is_empty());
            let computed = valid.replace("2.0", "1.0 + 1.0");
            assert!(matches!(prepare(&computed, scope).run_private_authored_root(NonZeroUsize::MIN),
                Err(ScalarOrderedCheckerOutcome::Unsupported)));
        }
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn dormant_float_integer_locals_preserve_correlated_quotient_and_remainder() {
        use std::num::NonZeroUsize;
        // This fixture bounds the key before arithmetic. The unrestricted
        // signed input is intentionally not covered by finite enumeration.
        let owner = source("src/main.w", "dormant-float-integer-locals");
        let text = |claim: &str| format!(r#"%%start
            f32(i32,i32,i32) routes = fn(key,row,column) {{
                if (key>=16 && key<=39) {{
                    i32 route=key/16;
                    i32 leg=key%16;
                    i32 previous=leg-1;
                    i32 start=if (leg>0) {{ previous }} else {{ 0 }};
                    i32 route_count=if (route==1) {{ 4 }} else {{ 10 }};
                    if (leg>=route_count) {{ 0.0 }} else {{
                        if (row==-1 && column==0) {{
                            i32 count=route_count-start;
                            core.require({claim}, {OUTPUT});
                            2.0
                        }} else {{ 0.0 }}
                    }}
                }} else {{ 0.0 }}
            }};
        %%end"#);
        let prepare = |program: &str, target_layout| prepare_loaded_scalar_ordered_local_proof_contexts(
            vec![(declarations(&owner, program), Vec::new())], [], vec![owner.clone()],
            ScalarPreparationInputs { target_layout }, ScalarCheckerScope::CurrentPackage, Vec::new(),
        ).ok().unwrap();
        for layout in [ScalarTargetLayout::NATIVE64, ScalarTargetLayout::WASM32] {
            let valid = text("count>=2 && count<=10");
            let unsafe_claim = text("(count>=3 || key!=19) && count<=10");
            let (valid, _) = prepare(&valid, layout).run_private_authored_root(NonZeroUsize::MIN).unwrap();
            assert!(valid.active && valid.directives.is_empty());
            let (bad, _) = prepare(&unsafe_claim, layout).run_private_authored_root(NonZeroUsize::MIN).unwrap();
            let full = prepare(&unsafe_claim, layout).run().unwrap();
            assert_eq!(bad.directives, full.directives);
            let [failure] = bad.directives.as_slice() else { panic!("one negative-control failure"); };
            for (index, value) in [19, -1, 0].into_iter().enumerate() {
                assert_eq!(failure.witness.axes().nth(index).unwrap().1, &ScalarType::I32);
                let value = BigInt::from(value);
                assert!(failure.witness.intervals_at(0, index).unwrap().eq([(&value, &value)]));
            }
            let unbounded = text("count>=2").replace("key>=16 && key<=39", "true");
            assert!(matches!(prepare(&unbounded, layout).run_private_authored_root(NonZeroUsize::MIN),
                Err(ScalarOrderedCheckerOutcome::Unsupported)));
        }
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn dormant_float_signed_radix_cuts_original_arbitrary_key_before_witness() {
        use std::num::NonZeroUsize;
        let owner = source("src/main.w", "dormant-float-signed-radix");
        let text = |claim: &str| format!(r#"%%start
            f32(i32,i32,i32) routes = fn(key,row,column) {{
                i32 route=key/16;
                i32 leg=key%16;
                if (row==-1 && column==0) {{
                    if (route==1 && leg==3) {{
                        core.require(key==19, {OUTPUT}); 2.0
                    }} else {{
                        if (route==-1 && leg==-3) {{
                            core.require({claim}, {OUTPUT}); 1.0
                        }} else {{ 0.0 }}
                    }}
                }} else {{ 0.0 }}
            }};
        %%end"#);
        let prepare = |program: &str, target_layout, scope| prepare_loaded_scalar_ordered_local_proof_contexts(
            vec![(declarations(&owner, program), Vec::new())], [], vec![owner.clone()],
            ScalarPreparationInputs { target_layout }, scope, Vec::new(),
        ).ok().unwrap();
        for layout in [ScalarTargetLayout::NATIVE64, ScalarTargetLayout::WASM32] {
            let valid = text("key==-19");
            let wrong = text("key!=-19");
            let scope = ScalarCheckerScope::CurrentPackage;
            let (valid, _) = prepare(&valid, layout, scope).run_private_authored_root(NonZeroUsize::MIN).unwrap();
            assert!(valid.active && valid.directives.is_empty());
            let (bad, _) = prepare(&wrong, layout, scope).run_private_authored_root(NonZeroUsize::MIN).unwrap();
            assert_eq!(bad.directives, prepare(&wrong, layout, scope).run().unwrap().directives);
            let [failure] = bad.directives.as_slice() else { panic!("one signed-radix negative-control failure"); };
            for (index, value) in [-19, -1, 0].into_iter().enumerate() {
                assert_eq!(failure.witness.axes().nth(index).unwrap().1, &ScalarType::I32);
                let value = BigInt::from(value);
                assert!(failure.witness.intervals_at(0, index).unwrap().eq([(&value, &value)]));
            }
            let (main, _) = prepare(&wrong, layout, ScalarCheckerScope::MainFlowOnly)
                .run_private_authored_root(NonZeroUsize::MIN).unwrap();
            assert!(main.directives.is_empty());
            let broad = wrong.replace("route==-1 && leg==-3", "route<0");
            assert!(matches!(prepare(&broad, layout, scope).run_private_authored_root(NonZeroUsize::MIN),
                Err(ScalarOrderedCheckerOutcome::Unsupported)));
            let both = wrong.replace("%%end", &format!("core.require(false, {OUTPUT}); %%end"));
            let (startup, _) = prepare(&both, layout, ScalarCheckerScope::MainFlowOnly)
                .run_private_authored_root(NonZeroUsize::MIN).unwrap();
            let (first, _) = prepare(&both, layout, scope).run_private_authored_root(NonZeroUsize::MIN).unwrap();
            let complete = prepare(&both, layout, scope).run().unwrap();
            assert_eq!(first.directives, startup.directives);
            assert_eq!(complete.directives.len(), 2);
            assert_eq!(&complete.directives[..1], startup.directives.as_slice());
            assert_eq!(&complete.directives[1..], bad.directives.as_slice());
            let extreme = |divisor: i32, quotient: i32| format!(r#"%%start
                f32(i32) inspect = fn(key) {{
                    i32 quotient=key/{divisor}; i32 residue=key%{divisor};
                    if (quotient=={quotient} && residue==0) {{
                        core.require(key==-2147483648, {OUTPUT}); 1.0
                    }} else {{ 0.0 }}
                }};
            %%end"#);
            for (divisor, quotient) in [(1, i32::MIN), (16, -134_217_728)] {
                let program = extreme(divisor, quotient);
                let (result, completion) = prepare(&program, layout, scope).run_private_authored_root(NonZeroUsize::MIN).unwrap();
                assert!(result.active && result.directives.is_empty());
                assert_eq!(completion, Some(StartupAuthoredCompletion::Exhausted));
                let impossible_claim = program.replace("key==-2147483648", "key!=-2147483648");
                let (bad, _) = prepare(&impossible_claim, layout, scope).run_private_authored_root(NonZeroUsize::MIN).unwrap();
                assert_eq!(bad.directives, prepare(&impossible_claim, layout, scope).run().unwrap().directives);
                let [failure] = bad.directives.as_slice() else { panic!("one typed extreme failure"); };
                let min = BigInt::from(i32::MIN);
                assert_eq!(failure.witness.axes().next().unwrap().1, &ScalarType::I32);
                assert!(failure.witness.intervals_at(0, 0).unwrap().eq([(&min, &min)]));
            }
            // This operation is visited with the typed, exact i32::MIN
            // input. It must fail closed; it cannot become a wrapped proof.
            let overflow = format!(r#"%%start
                f32(i32) inspect = fn(key) {{
                    if (key==-2147483648) {{
                        i32 value=key/-1;
                        core.require(value==0, {OUTPUT}); 1.0
                    }} else {{ 0.0 }}
                }};
            %%end"#);
            assert!(matches!(prepare(&overflow, layout, scope).run_private_authored_root(NonZeroUsize::MIN),
                Err(ScalarOrderedCheckerOutcome::Unsupported)));
            let fits = overflow.replace("key==-2147483648", "key==-2147483647")
                .replace("value==0", "value==2147483647");
            let (checked, _) = prepare(&fits, layout, scope).run_private_authored_root(NonZeroUsize::MIN).unwrap();
            assert!(checked.active && checked.directives.is_empty());
            assert!(matches!(prepare(&overflow, layout, scope).run(),
                Err(ScalarOrderedCheckerOutcome::Unsupported)));
        }
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn dormant_float_guard_reuses_proven_singleton_affine_class_without_losing_witness() {
        use std::num::NonZeroUsize;
        let owner = source("src/main.w", "dormant-float-retire-fixed-affine");
        let program = |claim: &str| format!(r#"%%start
            f32(i32,i32,i32) route_value = fn(seed,row,column) {{
                if (seed<2 || seed>3) {{ 0.0 }}
                else {{
                    i32 start=seed-1;
                    i32 count=if (column==0) {{ 4 }} else {{ 4 }};
                    if (row<0 || row>=count-start || column<0 || column>1) {{ 0.0 }}
                    else {{
                        i32 point=start+row;
                        core.require({claim}, {OUTPUT});
                        1.0
                    }}
                }}
            }};
        %%end"#);
        for target_layout in [ScalarTargetLayout::NATIVE64, ScalarTargetLayout::WASM32] {
            let run = |text: &str, capped: bool| {
                let prepared = prepare_loaded_scalar_ordered_local_proof_contexts(
                    vec![(declarations(&owner, text), Vec::new())], [], vec![owner.clone()],
                    ScalarPreparationInputs { target_layout }, ScalarCheckerScope::CurrentPackage, Vec::new(),
                ).unwrap_or_else(|error| panic!("route preparation: {error:?}"));
                if capped { prepared.run_private_authored_root(NonZeroUsize::MIN).map(|(result, _)| result) }
                else { prepared.run() }
            };
            let good = program("point>=1 && point<=3");
            let bad = program("point<=2 || seed!=3 || column!=1");
            for capped in [true, false] {
                let good = run(&good, capped).unwrap_or_else(|error| panic!("route closure: {error:?}"));
                assert!(good.active && good.directives.is_empty());
                let bad = run(&bad, capped).unwrap_or_else(|error| panic!("route witness: {error:?}"));
                let [false_claim] = bad.directives.as_slice() else { panic!("one authored failure"); };
                let axes: Vec<_> = false_claim.witness.axes().collect();
                assert_eq!(axes.len(), 6);
                assert!(axes.iter().all(|(_, ty)| **ty == ScalarType::I32));
                for (axis, value) in [3, 1, 1, 2, 4, 3].into_iter().enumerate() {
                    let value = BigInt::from(value);
                    assert!(false_claim.witness.intervals_at(0, axis).unwrap().eq([(&value, &value)]));
                }
            }
        }
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn dormant_float_coordinate_route_can_discard_only_readonly_leaves() {
        use std::num::NonZeroUsize;
        let owner = source("src/main.w", "dormant-float-coordinate-route");
        let program = |claim: &str, float: &str, alternative: &str| format!(r#"%%start
            f32 harbor_z = {float};
            f32[2][3] table = [[-1.0,1.0],[-2.0,2.0],[-3.0,3.0]];
            u64(i32) ix = fn(value) {{ core.int_extend<u64>(value) }};
            f32(i32,i32) harbor = fn(point,column) {{
                if (column==0) {{ if (point<2) {{ -4.55 }} else {{ 8.10 }} }}
                else {{ if (point==0) {{ 62.10 }} else {{ {alternative} }} }}
            }};
            f32(i32,i32,i32) route_value = fn(count,row,column) {{
                if (count<2 || count>3) {{ 0.0 }}
                else {{
                    i32 start=if (count==3) {{ 1 }} else {{ 0 }};
                    if (row<0 || row>=count-start || column<0 || column>1) {{ 0.0 }}
                    else {{
                        i32 point=start+row;
                        core.require({claim}, {OUTPUT});
                        if (column==0) {{
                            u64 n=ix(point); u64 c=ix(column);
                            table[n][c]
                        }} else {{
                            if (point==0) {{ harbor_z }} else {{ harbor(point,column) }}
                        }}
                    }}
                }}
            }};
        %%end"#);
        for target_layout in [ScalarTargetLayout::NATIVE64, ScalarTargetLayout::WASM32] {
            let prepare = |text: &str, scope| prepare_loaded_scalar_ordered_local_proof_contexts(
                vec![(declarations(&owner, text), Vec::new())], [], vec![owner.clone()],
                ScalarPreparationInputs { target_layout }, scope, Vec::new(),
            ).unwrap_or_else(|error| panic!("fixture preparation failed: {error:?}\n{text}"));
            let scope = ScalarCheckerScope::CurrentPackage;
            let good = program("point>=0 && point<=2", "-0.0", "harbor_z");
            let (valid, _) = prepare(&good, scope).run_private_authored_root(NonZeroUsize::MIN)
                .unwrap_or_else(|error| panic!("positive capped route: {error:?}"));
            assert!(valid.active && valid.directives.is_empty());
            assert!(prepare(&good, scope).run().unwrap().directives.is_empty());
            let wrong = program("point<=1 || column!=0", "-0.0", "harbor_z");
            let (bad, _) = prepare(&wrong, scope).run_private_authored_root(NonZeroUsize::MIN).unwrap();
            assert_eq!(bad.directives, prepare(&wrong, scope).run().unwrap().directives);
            let [failure] = bad.directives.as_slice() else { panic!("one false coordinate claim"); };
            let axes: Vec<_> = failure.witness.axes().collect();
            // Three function inputs plus two real lexical locals, never
            // the temporary subtraction used to test the row bounds.
            assert_eq!(axes.len(), 5);
            assert!(axes.iter().all(|(_, ty)| **ty == ScalarType::I32));
            for (axis, value) in [3, 1, 0, 1, 2].into_iter().enumerate() {
                let value = BigInt::from(value);
                assert!(failure.witness.intervals_at(0, axis).unwrap().eq([(&value, &value)]),
                    "unexpected coordinate witness at axis {axis}: {failure:?}");
            }
            for unsupported in [
                program("point>=0 && point<=2", "1.0+2.0", "harbor_z"),
                program("point>=0 && point<=2", "-0.0", "harbor_z+1.0"),
                program("point>=0 && point<=2", "-0.0", &format!("core.require(true, {OUTPUT}); harbor_z")),
            ] {
                assert!(matches!(prepare(&unsupported, scope).run_private_authored_root(NonZeroUsize::MIN),
                    Err(ScalarOrderedCheckerOutcome::Unsupported)));
                assert!(matches!(prepare(&unsupported, scope).run(),
                    Err(ScalarOrderedCheckerOutcome::Unsupported)));
            }
        }
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn dormant_float_ferry_count_prefix_preserves_unrestricted_key_and_nested_local_guards() {
        use std::num::NonZeroUsize;
        // Ferry's unrestricted integer prefix and authored test. The closed
        // fixture deliberately does not cover the original return calls or
        // the coordinate table reads.
        let owner = source("src/main.w", "dormant-float-ferry-count-prefix");
        let text = |claim: &str| format!(r#"%%start
            f32(i32,i32,i32) route_value = fn(key,row,column) {{
                i32 route=key/16;
                i32 leg=key%16;
                i32 start=if (leg>0) {{ leg-1 }} else {{ 0 }};
                i32 route_count=if (route==1) {{ 4 }}
                    else {{ if (route==2) {{ 10 }}
                    else {{ if (route==3) {{ 5 }}
                    else {{ if (route==4) {{ 4 }}
                    else {{ if (route==5) {{ 7 }}
                    else {{ if (route==6 || route==7) {{ 4 }} else {{ 0 }} }} }} }} }} }};
                if (key<=0 || leg>=route_count) {{ 0.0 }}
                else {{
                    if (row==-1 && column==0) {{
                        i32 count=route_count-start;
                        core.require({claim}, {OUTPUT}); 2.0
                    }} else {{ 0.0 }}
                }}
            }};
        %%end"#);
        for target_layout in [ScalarTargetLayout::NATIVE64, ScalarTargetLayout::WASM32] {
            let prepare = |program: &str| prepare_loaded_scalar_ordered_local_proof_contexts(
                vec![(declarations(&owner, program), Vec::new())], [], vec![owner.clone()],
                ScalarPreparationInputs { target_layout }, ScalarCheckerScope::CurrentPackage, Vec::new(),
            ).unwrap_or_else(|error| panic!("fixture preparation failed: {error:?}\n{program}"));
            let good = text("count>=2 && count<=10");
            let wrong = text("(count>=3 || key!=19) && count<=10");
            let (positive, _) = prepare(&good).run_private_authored_root(NonZeroUsize::MIN).unwrap();
            assert!(positive.active && positive.directives.is_empty());
            let (negative, _) = prepare(&wrong).run_private_authored_root(NonZeroUsize::MIN).unwrap();
            assert_eq!(negative.directives, prepare(&wrong).run().unwrap().directives);
            let [failure] = negative.directives.as_slice() else { panic!("one false route-count claim"); };
            for (axis, value) in [19, -1, 0].into_iter().enumerate() {
                let value = BigInt::from(value);
                assert!(failure.witness.intervals_at(0, axis).unwrap().eq([(&value, &value)]));
            }
            let direct_good = good.replace("2.0", "core.sint_to_float<f32>(count)");
            let direct_bad = wrong.replace("2.0", "core.sint_to_float<f32>(count)");
            let with_wrapper = |program: &str, body: &str| program.replace("%%start", &format!(
                "%%start f32(i32) float_i = fn(value) {{ {body} }};"
            )).replace("2.0", "float_i(count)");
            let wrapped_good = with_wrapper(&good, "core.sint_to_float<f32>(value)");
            let wrapped_bad = with_wrapper(&wrong, "core.sint_to_float<f32>(value)");
            for program in [&direct_good, &wrapped_good] {
                let (receipt, _) = prepare(program).run_private_authored_root(NonZeroUsize::MIN).unwrap();
                assert!(receipt.active && receipt.directives.is_empty());
                assert!(prepare(program).run().unwrap().directives.is_empty());
            }
            for program in [&direct_bad, &wrapped_bad] {
                let (receipt, _) = prepare(program).run_private_authored_root(NonZeroUsize::MIN).unwrap();
                assert_eq!(receipt.directives, prepare(program).run().unwrap().directives);
                let [failure] = receipt.directives.as_slice() else { panic!("one false route-count claim through conversion"); };
                let key = BigInt::from(19);
                assert!(failure.witness.intervals_at(0, 0).unwrap().eq([(&key, &key)]));
            }
            for refused in [
                with_wrapper(&good, "if (value>=0) { 0.0 } else { 1.0 }"),
                with_wrapper(&good, &format!("core.require(true, {OUTPUT}); core.sint_to_float<f32>(value)")),
            ] {
                assert!(matches!(prepare(&refused).run_private_authored_root(NonZeroUsize::MIN),
                    Err(ScalarOrderedCheckerOutcome::Unsupported)));
                assert!(matches!(prepare(&refused).run(),
                    Err(ScalarOrderedCheckerOutcome::Unsupported)));
            }
        }
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn checker_closes_and_refutes_wide_finite_dormant_history_past_old_work_ceiling() {
        use std::num::NonZeroUsize;
        let owner = source("src/main.w", "large-finite-dormant-history");
        let keep = format!("core.require(value>=0, {OUTPUT});\n");
        let violate = format!("core.require(value<0, {OUTPUT});\n");
        let text = |tail: &str| format!(r#"%%start
            f32(i32) inspect = fn(value) {{
                if (value>=0) {{ {} {tail} 1.0 }} else {{ 0.0 }}
            }};
        %%end"#, keep.repeat(768));
        for target_layout in [ScalarTargetLayout::NATIVE64, ScalarTargetLayout::WASM32] {
            let prepare = |program: &str| prepare_loaded_scalar_ordered_local_proof_contexts(
                vec![(declarations(&owner, program), Vec::new())], [], vec![owner.clone()],
                ScalarPreparationInputs { target_layout }, ScalarCheckerScope::CurrentPackage, Vec::new(),
            ).unwrap_or_else(|error| panic!("fixture preparation failed: {error:?}"));
            let valid = text("");
            let prepared = prepare(&valid);
            let owner = match &prepared.owner {
                PreparedConfiguredCheck::Plain { owner, .. } => owner,
                PreparedConfiguredCheck::Named { owner, .. } => &owner.prepared,
                _ => panic!("proof-free dormant fixture"),
            };
            let (project, calls) = owner.parts();
            let index = project.modules[0].items.iter().position(|item|
                matches!(item, ScalarItem::Function(function) if function.name == "inspect")).unwrap();
            let body = calls.function_body(0, index, None).unwrap();
            let plan = closed_dormant_float_plan(project, calls, (0, index), body, true).unwrap();
            let work = std::cell::Cell::new(0);
            assert!(matches!(search_closed_dormant_float(body, &plan, &work, |_, _| panic!("valid authored path")),
                Some(super::super::checker_flow::CallableHistoryCompletion::Exhausted(true))));
            assert!(work.get() > super::super::analysis_budget::FORMER_TRANSFER_CEILING,
                "fixture must exercise real work beyond the old cutoff, got {}", work.get());
            let (cap, _) = prepared.run_private_authored_root(NonZeroUsize::MIN).unwrap();
            let full = prepare(&valid).run().unwrap();
            assert!(cap.active && full.active && cap.directives.is_empty() && full.directives.is_empty());

            let bad = text(&violate.repeat(2));
            let (cap, _) = prepare(&bad).run_private_authored_root(NonZeroUsize::MIN).unwrap();
            let full = prepare(&bad).run().unwrap();
            assert_eq!(cap.directives.len(), 1);
            assert_eq!(full.directives.len(), 2);
            assert_eq!(cap.directives, full.directives[..1]);
            for failure in &full.directives {
                assert_eq!(failure.witness.axes().len(), 1);
                let zero = BigInt::ZERO;
                let maximum = BigInt::from(i32::MAX);
                assert!(failure.witness.intervals_at(0, 0).unwrap().eq([(&zero, &maximum)]));
            }
        }
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn dormant_float_demand_keeps_guard_arithmetic_and_real_branch_require() {
        use std::num::NonZeroUsize;
        let owner = source("src/main.w", "dormant-float-demanded-terminal");
        let guard = |limit: i32| format!(r#"%%start
            f32(i32,i32,i32) inspect = fn(count,start,row) {{
                if (count=={limit} && start==1) {{
                    core.require(true, {OUTPUT});
                    if (row<0 && row>=count-start) {{ 1.0 }} else {{ 0.0 }}
                }} else {{ 0.0 }}
            }};
        %%end"#);
        let obligation = format!(r#"%%start
            f32(i32) inspect = fn(row) {{
                if (row>0 && row<2) {{
                    core.require(row!=1, {OUTPUT}); 1.0
                }} else {{ 0.0 }}
            }};
        %%end"#);
        for target_layout in [ScalarTargetLayout::NATIVE64, ScalarTargetLayout::WASM32] {
            let prepare = |program: &str| prepare_loaded_scalar_ordered_local_proof_contexts(
                vec![(declarations(&owner, program), Vec::new())], [], vec![owner.clone()],
                ScalarPreparationInputs { target_layout }, ScalarCheckerScope::CurrentPackage, Vec::new(),
            ).unwrap_or_else(|error| panic!("fixture preparation failed: {error:?}\n{program}"));
            let valid = guard(i32::MIN + 1);
            let (cap, _) = prepare(&valid).run_private_authored_root(NonZeroUsize::MIN).unwrap();
            let full = prepare(&valid).run().unwrap();
            assert!(cap.active && full.active && cap.directives.is_empty() && full.directives.is_empty());
            let overflow = guard(i32::MIN);
            assert!(matches!(prepare(&overflow).run_private_authored_root(NonZeroUsize::MIN),
                Err(ScalarOrderedCheckerOutcome::Unsupported)));
            assert!(matches!(prepare(&overflow).run(), Err(ScalarOrderedCheckerOutcome::Unsupported)));

            let (cap, _) = prepare(&obligation).run_private_authored_root(NonZeroUsize::MIN).unwrap();
            assert_eq!(cap.directives, prepare(&obligation).run().unwrap().directives);
            let [failed] = cap.directives.as_slice() else { panic!("one branch-local authored failure"); };
            assert_eq!(failed.witness.axes().len(), 1);
            let one = BigInt::from(1u8);
            assert!(failed.witness.intervals_at(0, 0).unwrap().eq([(&one, &one)]));
        }
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn dormant_float_row_guard_preserves_difference_and_correlated_witness() {
        use std::num::NonZeroUsize;
        let owner = source("src/main.w", "dormant-float-row-guard");
        let text = |claim: &str| format!(r#"%%start
            f32(i32,i32,i32) guard = fn(count,start,row) {{
                if (count==4 && start>=0 && start<=2) {{
                    if (row<0 || row>=count-start) {{ 0.0 }} else {{
                        core.require({claim}, {OUTPUT}); 1.0
                    }}
                }} else {{ 0.0 }}
            }};
        %%end"#);
        for target_layout in [ScalarTargetLayout::NATIVE64, ScalarTargetLayout::WASM32] {
            let prepare = |program: &str| prepare_loaded_scalar_ordered_local_proof_contexts(
                vec![(declarations(&owner, program), Vec::new())], [], vec![owner.clone()],
                ScalarPreparationInputs { target_layout }, ScalarCheckerScope::CurrentPackage, Vec::new(),
            ).unwrap_or_else(|error| panic!("fixture preparation failed: {error:?}"));
            let good = text("row<=3");
            let wrong = text("row!=3");
            let (positive, _) = prepare(&good).run_private_authored_root(NonZeroUsize::MIN).unwrap();
            assert!(positive.active && positive.directives.is_empty());
            let (negative, _) = prepare(&wrong).run_private_authored_root(NonZeroUsize::MIN).unwrap();
            assert_eq!(negative.directives, prepare(&wrong).run().unwrap().directives);
            let [failure] = negative.directives.as_slice() else { panic!("one row-difference witness"); };
            assert_eq!(failure.witness.axes().len(), 3, "temporary operand is not a witness axis");
            for (axis, value) in [4, 0, 3].into_iter().enumerate() {
                assert_eq!(failure.witness.axes().nth(axis).unwrap().1, &ScalarType::I32);
                let value = BigInt::from(value);
                assert!(failure.witness.intervals_at(0, axis).unwrap().eq([(&value, &value)]));
            }

            let signed_edge = |count: i32| format!(r#"%%start
                f32(i32,i32,i32) guard = fn(count,start,row) {{
                    if (count=={count} && start==1) {{
                        if (row<0 && row>=count-start) {{
                            core.require(row<0, {OUTPUT}); 1.0
                        }} else {{ 0.0 }}
                    }} else {{ 0.0 }}
                }};
            %%end"#);
            let fits = signed_edge(i32::MIN + 1);
            let (verified, _) = prepare(&fits).run_private_authored_root(NonZeroUsize::MIN).unwrap();
            assert!(verified.active && verified.directives.is_empty());
            let complete = prepare(&fits).run().unwrap();
            assert!(complete.active && complete.directives.is_empty());
            let overflow = signed_edge(i32::MIN);
            assert!(matches!(prepare(&overflow).run_private_authored_root(NonZeroUsize::MIN),
                Err(ScalarOrderedCheckerOutcome::Unsupported)));
            assert!(matches!(prepare(&overflow).run(), Err(ScalarOrderedCheckerOutcome::Unsupported)));
        }
    }

