    #[cfg(feature = "internal-checker")]
    #[test]
    fn observed_partition_preserves_published_integer_cells_on_failed_path() {
        let app = source("src/main.w", "observed-partition-selected-cells");
        let program = r#"%%start
            bool failed = false;
            i32 next_vertex = 8;
            i32 ceiling = 12;
            i32 generation = 2147483645;
            i32[2] motion_base = [30, 38];
            i32[2] motion_unique = [91, 92];
            i32 room_partial = 0;
            i32 first_cell = 0;
            i32 second_cell = 0;
            unit(i32,i32) partition = fn(base, limit) {
                if (base < 0 || limit < base || limit > 20480 || generation >= 2147483646) {
                    failed = true;
                } else {
                    generation = generation + 1;
                    next_vertex = base;
                    ceiling = limit;
                };
            };
            unit(i32,i32) moving = fn(mask,id) {
                if (id < 2 && mask > 0) {
                    if (mask % 2 != 0) {
                        room_partial = id + 1;
                        u64 i = core.int_extend<u64>(id);
                        i32 base = motion_base[i];
                        motion_unique[i] = next_vertex - base;
                    };
                };
            };
            unit() launch = fn {
                partition(37, 90); moving(1, 0);
                partition(45, 100); moving(1, 1);
                moving(0, -1);
                first_cell = motion_unique[0];
                second_cell = motion_unique[1];
            };
            launch();
            core.narrow(false, {.stdout="";.stderr="";.code=next_vertex;.files=[
                {.path="room.json";.state=room_partial;},
                {.path="first.json";.state=first_cell;},
                {.path="second.json";.state=second_cell;},
                {.path="generation.json";.state=generation;},
                {.path="ceiling.json";.state=ceiling;},
                {.path="failed.json";.state=failed;}
            ];});
        %%end"#;
        let out_of_bounds = program.replace("moving(0, -1)", "moving(1, -1)");
        for target_layout in [ScalarTargetLayout::NATIVE64, ScalarTargetLayout::WASM32] {
            let run = |text, scope| prepare_loaded_scalar_ordered_local_proof_contexts(
                vec![(declarations(&app, text), Vec::new())], [], vec![app.clone()],
                ScalarPreparationInputs { target_layout }, scope, Vec::new(),
            ).unwrap().run();
            for scope in [ScalarCheckerScope::MainFlowOnly, ScalarCheckerScope::CurrentPackage] {
                let exact = run(program, scope).unwrap();
                let [failure] = exact.directives.as_slice() else { panic!("one sentinel output"); };
                assert_eq!(failure.code(), &BigInt::from(37));
                let files = failure.files();
                assert_eq!(files[0].text.as_ref(), b"{\"type\":{\"kind\":\"i32\"},\"value\":2}\n");
                assert_eq!(files[1].text.as_ref(), b"{\"type\":{\"kind\":\"i32\"},\"value\":7}\n");
                assert_eq!(files[2].text.as_ref(), b"{\"type\":{\"kind\":\"i32\"},\"value\":-1}\n");
                assert_eq!(files[3].text.as_ref(), b"{\"type\":{\"kind\":\"i32\"},\"value\":2147483646}\n");
                assert_eq!(files[4].text.as_ref(), b"{\"type\":{\"kind\":\"i32\"},\"value\":90}\n");
                assert_eq!(files[5].text.as_ref(), b"{\"type\":{\"kind\":\"bool\"},\"value\":true}\n");
                assert!(matches!(run(&out_of_bounds, scope), Err(ScalarOrderedCheckerOutcome::Unsupported)));
            }
        }
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    #[ignore = "requires independently pinned unmodified Orbital indexed-pack provider"]
    fn pinned_orbital_partition_transfers_prepared_provider_state_and_history() {
        use std::num::NonZeroUsize;
        use wosy_syntax::SourceSpan;
        let path = std::path::PathBuf::from(std::env::var_os("WOSY_TEST_PINNED_ORBITAL_PACKING").unwrap());
        let packing_text = std::fs::read_to_string(path).unwrap();
        let app = source("src/main.w","pinned-partition-consumer");
        let packing = source("src/indexed-pack.w","pinned-partition-provider");
        let template = r#"%%start
            packing = namespace demo "indexed-pack.w";
            unit() success_then_failure = fn {
                packing.start();
                packing.partition(37,90);
                packing.partition(18,12);
            };
            unit() restart = fn {
                packing.start();
            };
            success_then_failure();
            RESTART
            core.narrow(false,{.stdout="";.stderr="";.code=91;.files=[];});
        %%end"#;
        let span_for = |source: &SourceIdentity, text: &str, needle: &str| {
            let start = text.find(needle).unwrap();
            SourceSpan::new(source.clone(), ByteSpan::new(start as u32, (start+needle.len()) as u32))
        };
        let guard = span_for(&packing,&packing_text,"base<0||limit<base||limit>20480||generation>=2147483646");
        for target_layout in [ScalarTargetLayout::NATIVE64,ScalarTargetLayout::WASM32] {
            for (suffix, failed) in [("",true),("restart();",false)] {
                let text = template.replace("RESTART",suffix);
                let namespace = span_for(&app,&text,r#"packing = namespace demo "indexed-pack.w";"#);
                let modules = || vec![(declarations(&app,&text),vec![ScalarNamespaceBinding {
                    binding:"packing".into(),target:packing.clone(),span:namespace.range,
                }]),(declarations(&packing,&packing_text),Vec::new())];
                let prepare = || prepare_loaded_scalar_ordered_local_proof_contexts(
                    modules(), [], vec![app.clone(),packing.clone()], ScalarPreparationInputs { target_layout },
                    ScalarCheckerScope::MainFlowOnly, Vec::new(),
                ).unwrap();
                let prepared = prepare();
                let PreparedConfiguredCheck::Plain { owner, .. } = &prepared.owner
                    else { panic!("expected authenticated current main flow"); };
                let (root, ordinals) = package_initialization_order(owner.parts().0).unwrap();
                let mut failures = OrderedFailures::default();
                let (checked, ()) = check_package_initialization_observing_with_policy::<(),true,false>(
                    owner,root,ordinals,(),Some(&mut failures),
                ).unwrap();
                for (name, value) in [("generation",1),("next_vertex",37),("ceiling",90)] {
                    let key = span_for(&packing,&packing_text,name);
                    assert_eq!(checked.projected_storage.observed_atom(&key),
                        Some(ObservedExactValue::Integer(ScalarType::I32,BigInt::from(value))));
                }
                let key = span_for(&packing,&packing_text,"failed");
                assert_eq!(checked.projected_storage.observed_atom(&key),Some(ObservedExactValue::Boolean(failed)));
                let ordinary = prepared.run().unwrap();
                let (capped,_,path,_) = prepare().search_startup_authored_path(NonZeroUsize::MIN).unwrap();
                assert_eq!(capped,ordinary.directives);
                assert_eq!(capped.len(),1);
                assert_eq!(capped[0].code(),&BigInt::from(91));
                assert!(path.contains_return(&span_for(&app,&text,"packing.partition(37,90)")));
                assert!(path.contains_return(&span_for(&app,&text,"packing.partition(18,12)")));
                assert!(path.contains_branch(guard.clone(),false));
                assert!(path.contains_branch(guard.clone(),true));
                eprintln!("Orbital prepared packing generation=1 next=37 ceiling=90 failed={failed} {target_layout:?}");
            }
        }
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    #[ignore = "requires independently pinned unmodified Orbital indexed-pack provider"]
    fn pinned_orbital_partition_getters_use_current_rows_and_short_circuit() {
        use std::num::NonZeroUsize;
        use wosy_syntax::SourceSpan;
        let path = std::path::PathBuf::from(std::env::var_os("WOSY_TEST_PINNED_ORBITAL_PACKING").unwrap());
        let provider_text = std::fs::read_to_string(path).unwrap();
        let app = source("src/main.w","pinned-partition-getter-consumer");
        let provider = source("src/indexed-pack.w","pinned-partition-getter-provider");
        let text = r#"%%start
            packing = namespace demo "indexed-pack.w";
            i32[2] motion_base = [30,38];
            i32[2] motion_unique = [99,99];
            i32 first = 0;
            i32 second = 0;
            unit(i32) store = fn(id) {
                u64 i = core.int_extend<u64>(id);
                motion_unique[i] = packing.end() - motion_base[i];
            };
            unit() launch = fn {
                packing.start();
                packing.partition(37,90);
                if(packing.ok()){store(0);};
                packing.partition(18,12);
                if(packing.ok()){first=99;}else{store(1);};
                if(false&&packing.ok()){first=99;};
                first = motion_unique[0];
                second = motion_unique[1];
            };
            launch();
            core.narrow(false,{.stdout="";.stderr="";.code=first;.files=[
                {.path="second.json";.state=second;}
            ];});
        %%end"#;
        let at = |needle: &str| text.find(needle).unwrap() as u32;
        let qualified = r#"packing = namespace demo "indexed-pack.w";"#;
        let binding_start = at(qualified);
        let getter = |prefix: &str, name: &str| {
            let start = at(prefix) + prefix.find(name).unwrap() as u32;
            SourceSpan::new(app.clone(), ByteSpan::new(start,start+name.len() as u32))
        };
        let end_call = getter("packing.end()", "packing.end()");
        let first_ok = getter("if(packing.ok()){store(0);}", "packing.ok()");
        let second_ok = getter("if(packing.ok()){first=99;}", "packing.ok()");
        let dead_ok = getter("false&&packing.ok()", "packing.ok()");
        for target_layout in [ScalarTargetLayout::NATIVE64,ScalarTargetLayout::WASM32] {
            let prepare = || prepare_loaded_scalar_ordered_local_proof_contexts(
                vec![(declarations(&app,text), vec![ScalarNamespaceBinding {
                    binding:"packing".into(),target:provider.clone(),
                    span:ByteSpan::new(binding_start,binding_start+qualified.len() as u32),
                }]),(declarations(&provider,&provider_text),Vec::new())],
                [], vec![app.clone(),provider.clone()], ScalarPreparationInputs { target_layout },
                ScalarCheckerScope::MainFlowOnly, Vec::new(),
            ).unwrap();
            let all = prepare().run().unwrap();
            let [one] = all.directives.as_slice() else { panic!("one selected report"); };
            assert_eq!(one.code(),&BigInt::from(7));
            assert_eq!(one.files()[0].text.as_ref(),b"{\"type\":{\"kind\":\"i32\"},\"value\":-1}\n");
            let (capped,_,trace,_) = prepare().search_startup_authored_path(NonZeroUsize::MIN).unwrap();
            assert_eq!(capped,all.directives);
            assert!(trace.contains_return(&first_ok));
            assert!(trace.contains_return(&second_ok));
            assert!(!trace.contains_return(&dead_ok));
            let calls = trace.call_paths();
            let [path] = calls.as_slice() else { panic!("one ordered path"); };
            let getters = path.iter().filter(|site| [ &first_ok,&second_ok,&end_call,&dead_ok ].contains(site))
                .collect::<Vec<_>>();
            assert_eq!(getters,[&first_ok,&end_call,&second_ok,&end_call]);
            eprintln!("Orbital same-row getters {target_layout:?}: valid=7, invalid=-1, two returns, no unevaluated call");
        }
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    #[ignore = "requires independently pinned unmodified Orbital indexed-pack provider"]
    fn pinned_orbital_partition_computes_checked_arguments_once_before_call() {
        use std::num::NonZeroUsize;
        use super::super::checker_flow::take_observed_unit_argument_evaluations as evaluations;
        let path = std::path::PathBuf::from(std::env::var_os("WOSY_TEST_PINNED_ORBITAL_PACKING").unwrap());
        let provider_text = std::fs::read_to_string(path).unwrap();
        let app = source("src/main.w","pinned-partition-argument-consumer");
        let provider = source("src/indexed-pack.w","pinned-partition-argument-provider");
        let exact = r#"%%start
            packing = namespace demo "indexed-pack.w";
            i32 retained = 0;
            unit(i32,i32) moving = fn(target,reserve) {
                packing.partition(target,target+reserve);
            };
            unit(i32,i32) ordering = fn(target,reserve) {
                packing.partition(target+1,target+reserve);
            };
            unit() launch = fn {
                packing.start();
                moving(37,53);
                moving(18,-6);
                retained=packing.end();
            };
            launch();
            core.narrow(false,{.stdout="";.stderr="";.code=retained;.files=[];});
        %%end"#;
        let late_overflow = exact.replace("moving(18,-6)", "moving(2147483647,1)");
        let early_overflow = exact.replace("moving(18,-6)", "ordering(2147483647,1)");
        let prefix = r#"packing = namespace demo "indexed-pack.w";"#;
        let binding = exact.find(prefix).unwrap() as u32;
        let packed_site = "packing.partition(target,target+reserve)";
        let start = exact.find(packed_site).unwrap() as u32;
        let packed_site = wosy_syntax::SourceSpan::new(app.clone(),ByteSpan::new(start,start+packed_site.len() as u32));
        for target_layout in [ScalarTargetLayout::NATIVE64,ScalarTargetLayout::WASM32] {
            let prepare = |text| prepare_loaded_scalar_ordered_local_proof_contexts(
                vec![(declarations(&app,text),vec![ScalarNamespaceBinding {
                    binding:"packing".into(), target:provider.clone(),
                    span:ByteSpan::new(binding,binding+prefix.len() as u32),
                }]),(declarations(&provider,&provider_text),Vec::new())],
                [],vec![app.clone(),provider.clone()],ScalarPreparationInputs { target_layout },
                ScalarCheckerScope::MainFlowOnly,Vec::new(),
            ).unwrap();
            evaluations();
            let all = prepare(exact).run().unwrap();
            assert_eq!(evaluations(),2);
            let [report] = all.directives.as_slice() else { panic!("one result"); };
            assert_eq!(report.code(),&BigInt::from(37));
            let (capped,_,trace,_) = prepare(exact).search_startup_authored_path(NonZeroUsize::MIN).unwrap();
            assert_eq!(evaluations(),2);
            assert_eq!(capped,all.directives);
            let paths = trace.call_paths();
            let [steps] = paths.as_slice() else { panic!("one ordered path"); };
            assert_eq!(steps.iter().filter(|at| *at==&packed_site).count(),2);
            for bad in [&late_overflow,&early_overflow] {
                assert!(matches!(prepare(bad).run(),Err(ScalarOrderedCheckerOutcome::Unsupported)));
                // One valid argument, then the first invalid argument.
                // In ordering(), the second argument has not executed.
                assert_eq!(evaluations(),2);
            }
            eprintln!("Orbital checked User Unit operands {target_layout:?}: two original arithmetic values, no replay, overflow remains unsupported");
        }
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    #[ignore = "requires independently pinned unmodified Orbital engine and indexed-pack provider"]
    fn pinned_orbital_index_range_returns_only_from_known_false_entry() {
        use std::num::NonZeroUsize;
        use wosy_syntax::SourceSpan;
        let provider_text = std::fs::read_to_string(std::env::var_os("WOSY_TEST_PINNED_ORBITAL_PACKING").unwrap()).unwrap();
        let engine = std::fs::read_to_string(std::env::var_os("WOSY_TEST_PINNED_ORBITAL_ENGINE").unwrap()).unwrap();
        let (_, functions) = engine.split_once("unit(i32,i32) index_range=").unwrap();
        let (index_range, _) = functions.split_once("unit(i32,u64,u64,u64,u64) index_vertex=").unwrap();
        let app = source("src/main.w","pinned-index-range-consumer");
        let provider = source("src/indexed-pack.w","pinned-index-range-provider");
        let exact = format!(r#"%%start
            packing = namespace demo "indexed-pack.w";
            i32 touched=0;
            i32 retained=0;
            unit(i32,u64,u64,u64,u64) index_vertex=fn(i,p,a,j,k) {{ if(p==0&&a==0&&j==0&&k==3){{touched=i;}}; }};
            unit(i32,i32) index_range={index_range}
            unit() launch=fn {{
                packing.start();
                packing.partition(37,90);
                index_range(3,3);
                packing.partition(18,12);
                index_range(3,4);
                retained=packing.end()-touched;
            }};
            launch();
            core.narrow(false,{{.stdout="";.stderr="";.code=retained;.files=[];}});
        %%end"#);
        let true_arm=exact.replace("index_range(3,3)", "index_range(3,4)");
        let with_suffix=exact.replace(index_range, &index_range.replacen("    };\n};", "    }; touched=1;\n};",1));
        assert_ne!(with_suffix,exact);
        let span=|site:&str| {
            let start=exact.find(site).unwrap() as u32;
            SourceSpan::new(app.clone(),ByteSpan::new(start,start+site.len() as u32))
        };
        let declaration=span(r#"packing = namespace demo "indexed-pack.w";"#);
        let empty=span("index_range(3,3)");
        let failed=span("index_range(3,4)");
        let ok=span("packing.ok()");
        let left=span("begin<finish");
        let guard=span("begin<finish&&packing.ok()");
        let skipped=span("index_vertex(begin,p,a,j,k)");
        for target_layout in [ScalarTargetLayout::NATIVE64,ScalarTargetLayout::WASM32] {
            let prepare=|text| prepare_loaded_scalar_ordered_local_proof_contexts(
                vec![(declarations(&app,text),vec![ScalarNamespaceBinding {
                    binding:"packing".into(),target:provider.clone(),span:declaration.range,
                }]),(declarations(&provider,&provider_text),Vec::new())],
                [],vec![app.clone(),provider.clone()],ScalarPreparationInputs { target_layout },
                ScalarCheckerScope::MainFlowOnly,Vec::new(),
            ).unwrap();
            let all=prepare(&exact).run().unwrap();
            let [result]=all.directives.as_slice() else { panic!("one result"); };
            assert_eq!(result.code(),&BigInt::from(37));
            let (capped,_,trace,_)=prepare(&exact).search_startup_authored_path(NonZeroUsize::MIN).unwrap();
            assert_eq!(capped,all.directives);
            assert!(trace.contains_return(&empty));
            assert!(trace.contains_return(&failed));
            assert!(trace.contains_return(&ok));
            assert!(!trace.contains_return(&skipped));
            assert!(trace.contains_branch(left.clone(),false));
            assert!(trace.contains_branch(left.clone(),true));
            assert!(trace.contains_branch(ok.clone(),false));
            assert!(trace.contains_branch(guard.clone(),false));
            assert!(!trace.contains_branch(guard.clone(),true));
            let paths=trace.call_paths();
            let [calls]=paths.as_slice() else { panic!("one root history"); };
            assert_eq!(calls.iter().filter(|site| [&empty,&failed,&ok,&skipped].contains(site)).collect::<Vec<_>>(),
                [&empty,&failed,&ok]);
            for program in [&true_arm,&with_suffix] {
                assert!(matches!(prepare(program).run(),Err(ScalarOrderedCheckerOutcome::Unsupported)));
            }
            eprintln!("Orbital original index_range {target_layout:?}: empty and failed-provider return, live recursion remains unadmitted");
        }
    }

