    #[cfg(feature = "internal-checker")]
    #[test]
    fn fixed_array_state_capture_preserves_types_order_and_prewrite_alternatives() {
        let app = source("src/main.w", "fixed-array-state");
        let program = r#"%%start
            unit(i8) check = fn(value) {
                core.narrow(value == 1 || value == 3, { .stdout = ""; .stderr = ""; .code = 1; .files = []; });
                i8[2] snapshot = [value, 7];
                value = 9;
                core.require(value != 9, { .stdout = ""; .stderr = ""; .code = 1; .files = [
                    { .path = "one.json"; .state = snapshot; },
                    { .path = "two.json"; .state = snapshot; }
                ]; });
            };
        %%end"#;
        let receipt = check_loaded_scalar_ordered_local_proof_contexts(
            vec![(declarations(&app, program), Vec::new())], Vec::new(), vec![app.clone()],
            inputs(), ScalarCheckerScope::CurrentPackage, Vec::new(),
        ).unwrap();
        let [failure] = receipt.directives.as_slice() else { panic!("expected one array witness"); };
        let [first, second] = failure.files() else { panic!("expected both serialized files"); };
        assert_eq!(first.text, second.text);
        assert_eq!(first.text.as_ref(), concat!(
            r#"{"type":{"kind":"array","length":2,"element":{"kind":"i8"}},"value":["#,
            r#"{"type":{"kind":"i8"},"value":{"kind":"alternatives","values":[1,3]}},"#,
            r#"{"type":{"kind":"i8"},"value":7}]}"#,
            "\n",
        ).as_bytes());
        assert_eq!(failure.witness.axes().len(), 1);
        let nine = BigInt::from(9);
        assert!(failure.witness.intervals_at(0, 0).unwrap().eq([(&nine, &nine)]));
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn authored_affine_snapshot_construction_preserves_width_and_preimage() {
        let app = source("src/main.w", "authored-affine-snapshot");
        let text = r#"%%start
            struct Snapshot { i8 raised; i8 reflected; i8 plain; }
            unit(i8) inspect = fn(value) {
                core.narrow(value == 1 || value == 3, { .stdout = ""; .stderr = ""; .code = 1; .files = []; });
                Snapshot snapshot = { .raised = value + 2; .reflected = 7 - value; .plain = value; };
                if (value == 1) {
                    i8 read = snapshot.raised;
                    core.require(read == 3, { .stdout = ""; .stderr = "lost preimage"; .code = 58; .files = []; });
                };
                value = 7;
                core.require(value != 7, { .stdout = ""; .stderr = ""; .code = 59;
                    .files = [{ .path = "state.json"; .state = snapshot; }]; });
            };
        %%end"#;
        let run = |input: &str, scope| {
            let prepared = prepare_proof_target(&app, input).unwrap();
            run_closed_without_named_proofs(&prepared, scope, 1)
        };
        let symbolic = run(text, ScalarCheckerScope::CurrentPackage).unwrap();
        let [failure] = symbolic.directives.as_slice() else { panic!("one file from construction"); };
        assert_eq!(failure.code(), &BigInt::from(59));
        assert_eq!(failure.witness.axes().len(), 1);
        assert_eq!(failure.files()[0].text.as_ref(),
            concat!(
                "{\"type\":{\"kind\":\"struct\",\"name\":\"Snapshot\"},\"value\":{",
                "\"raised\":{\"type\":{\"kind\":\"i8\"},\"value\":{\"kind\":\"alternatives\",\"values\":[3,5]}},",
                "\"reflected\":{\"type\":{\"kind\":\"i8\"},\"value\":{\"kind\":\"alternatives\",\"values\":[4,6]}},",
                "\"plain\":{\"type\":{\"kind\":\"i8\"},\"value\":{\"kind\":\"alternatives\",\"values\":[1,3]}}}}\n"
            ).as_bytes());
        let actual = text.replace("%%end", "inspect(1); %%end");
        let receipt = run(&actual, ScalarCheckerScope::MainFlowOnly).unwrap();
        let [failure] = receipt.directives.as_slice() else { panic!("one actual construction"); };
        assert_eq!(failure.code(), &BigInt::from(59));
        let output = std::str::from_utf8(&failure.files()[0].text).unwrap();
        assert!(output.contains(r#""reflected":{"type":{"kind":"i8"},"value":6}"#));
        let overflow = text.replace("value == 1 || value == 3", "value >= 125")
            .replace("value + 2", "value + 3");
        for invalid in [overflow, text.replace("value + 2", "value * 2")] {
            assert!(matches!(run(&invalid, ScalarCheckerScope::CurrentPackage), Err(ProjectCheck::Unsupported)));
        }
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn private_affine_snapshot_preserves_live_capture_and_short_circuit_paths() {
        use std::num::NonZeroUsize;
        let app = source("src/main.w", "private-affine-snapshot-history");
        let text = r#"%%start
            struct Snapshot { i8 raised; i8 reflected; i8 plain; }
            unit(i8) inspect = fn(value) {
                core.narrow(value == 1 || value == 3, { .stdout = ""; .stderr = ""; .code = 1; .files = []; });
                Snapshot snapshot = { .raised = value + 2; .reflected = 7 - value; .plain = value; };
                if (value == 1) {
                    i8 read = snapshot.raised;
                    core.require(read == 3, { .stdout = ""; .stderr = "lost preimage"; .code = 58; .files = []; });
                };
                value = 7;
                core.require(value != 7, { .stdout = ""; .stderr = "construction"; .code = 59;
                    .files = [{ .path = "state.json"; .state = snapshot; }]; });
            };
        %%end"#;
        let lhs = text.find("value == 1").unwrap();
        let rhs = text.find("value == 3").unwrap();
        let at = |start: usize| wosy_syntax::SourceSpan::new(app.clone(), ByteSpan::new(start as u32, start as u32 + 10));
        for target_layout in [ScalarTargetLayout::NATIVE64, ScalarTargetLayout::WASM32] {
            let prepare = |program: &str, scope| prepare_loaded_scalar_ordered_local_proof_contexts(
                vec![(declarations(&app, program), Vec::new())], [], vec![app.clone()],
                ScalarPreparationInputs { target_layout }, scope, Vec::new()).unwrap();
            let expected = [1, 3].map(|value| format!(
                "{{\"type\":{{\"kind\":\"struct\",\"name\":\"Snapshot\"}},\"value\":{{\"raised\":{{\"type\":{{\"kind\":\"i8\"}},\"value\":{}}},\"reflected\":{{\"type\":{{\"kind\":\"i8\"}},\"value\":{}}},\"plain\":{{\"type\":{{\"kind\":\"i8\"}},\"value\":{}}}}}}}\n",
                value + 2, 7 - value, value));
            for scope in [ScalarCheckerScope::CurrentPackage, ScalarCheckerScope::MainFlowOnly] {
                for (index, value) in [1, 3].into_iter().enumerate() {
                    let actual = text.replace("%%end", &format!("inspect({value}); %%end"));
                    let old = prepare(&actual, scope).run().unwrap();
                    for cap in [1, 3] {
                        let (records, end, trace, _) = prepare(&actual, scope)
                            .search_startup_authored_path(NonZeroUsize::new(cap).unwrap()).unwrap();
                        assert_eq!(records, old.directives);
                        assert_eq!(records[0].files()[0].text.as_ref(), expected[index].as_bytes());
                        assert_eq!(end, if cap == 1 { StartupAuthoredCompletion::LimitReached } else { StartupAuthoredCompletion::Exhausted });
                        assert!(trace.contains_branch(at(lhs), value == 1));
                        assert_eq!(trace.contains_branch(at(rhs), true), value == 3);
                    }
                }
            }
            for cap in [1, 2, 3] {
                let (records, end, trace, _) = prepare(text, ScalarCheckerScope::CurrentPackage)
                    .search_startup_authored_path(NonZeroUsize::new(cap).unwrap()).unwrap();
                assert_eq!(records.len(), cap.min(2));
                assert_eq!(end, if cap <= 2 { StartupAuthoredCompletion::LimitReached } else { StartupAuthoredCompletion::Exhausted });
                for (record, file) in records.iter().zip(&expected) {
                    assert_eq!(record.code(), &BigInt::from(59));
                    assert_eq!(record.files()[0].text.as_ref(), file.as_bytes());
                    assert_eq!(record.witness.axes().len(), 1, "do not expose synthetic capture axes");
                }
                assert_eq!(trace.selected_steps().len(), records.len());
                let after = at(text.find("value == 1) {").unwrap());
                for (path, first) in trace.selected_steps().zip([true, false]) {
                    use failure_search::PathStep;
                    let conditions = path.iter().filter_map(|step| match step {
                        PathStep::Branch { condition, accepted } if [at(lhs), at(rhs), after.clone()].contains(condition)
                            => Some((condition.clone(), *accepted)),
                        _ => None,
                    }).collect::<Vec<_>>();
                    let expected = if first { vec![(at(lhs), true), (after.clone(), true)] }
                        else { vec![(at(lhs), false), (at(rhs), true), (after.clone(), false)] };
                    assert_eq!(conditions, expected);
                }
            }
        }
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn ordinary_nested_array_path_preserves_diagonal_and_checks_each_bound() {
        let app = source("src/main.w", "ordinary-nested-array-path");
        let text = r#"%%start
            unit(u64, i8) inspect = fn(index, value) {
                core.narrow(value == 1 || value == 3, { .stdout = ""; .stderr = ""; .code = 1; .files = []; });
                i8[2][2] matrix = [[value, 29], [49, 7]];
                i8[2][2] copied = matrix;
                value = 9;
                if (index <= 1) {
                    i8 observed = copied[index][index];
                    i8 constant = copied[0][1];
                    core.require(constant == 29, { .stdout = ""; .stderr = "wrong constant"; .code = 58; .files = []; });
                    if (observed == 3) {
                        core.require(index == 0, { .stdout = ""; .stderr = "wrong index"; .code = 60; .files = []; });
                        core.require(value != 9, { .stdout = ""; .stderr = ""; .code = 61;
                            .files = [{ .path = "observed.json"; .state = observed; }]; });
                    } else {
                        core.require(observed == 1 || (index == 1 && observed == 7),
                            { .stdout = ""; .stderr = "off diagonal"; .code = 63; .files = []; });
                    };
                };
            };
        %%end"#;
        let actual = text.replace("%%end", "inspect(0, 3); %%end");
        let run = |input: &str, scope| {
            let prepared = prepare_proof_target(&app, input).unwrap();
            run_closed_without_named_proofs(&prepared, scope, 1)
        };
        for (input, scope) in [(text, ScalarCheckerScope::CurrentPackage),
            (actual.as_str(), ScalarCheckerScope::MainFlowOnly), (actual.as_str(), ScalarCheckerScope::CurrentPackage)]
        {
            let receipt = run(input, scope).unwrap();
            let [failure] = receipt.directives.as_slice() else { panic!("only the preserved diagonal element fails"); };
            assert_eq!(failure.code(), &BigInt::from(61));
            assert_eq!(failure.witness.axes().len(), 4);
            assert!(failure.witness.axes().all(|(binding, _)| binding.kind == super::super::ReferenceBindingKind::Declared));
            assert_eq!(failure.files()[0].text.as_ref(), b"{\"type\":{\"kind\":\"i8\"},\"value\":3}\n");
        }
        let inner_outside = text.replace("index <= 1", "index <= 2")
            .replace("copied[index][index]", "copied[0][index]");
        assert!(matches!(run(&inner_outside, ScalarCheckerScope::CurrentPackage), Err(ProjectCheck::Unsupported)));
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn shared_checked_read_preflight_keeps_only_typed_lexical_dereferences() {
        use super::super::static_calls::{PreparedReadKind, PreparedReadShape};
        let src = source("src/main.w", "shared-checked-read-preflight");
        let text = r#"%%start
            u8(*u8) read = fn(pointer) { *pointer };
            u8(*u8) second_read = fn(pointer) { *pointer };
            u8(*!u8) mutable = fn(pointer) { *pointer };
            *?u8(*u8) address = fn(pointer) { unsafe { &?*pointer } };
            u8(*u8) alias_read = fn(pointer) { *u8 alias = pointer; *alias };
        %%end"#;
        let parsed = crate::parse_source(src.clone(), text.to_owned(), &[]);
        assert!(parsed.diagnostics.is_empty(), "{:?}", parsed.diagnostics);
        let scalar = parsed.result.canonical_cst();
        for target_layout in [ScalarTargetLayout::NATIVE64, ScalarTargetLayout::WASM32] {
            let checker = prepare_checker_project(
                vec![(crate::derive_scalar_check_declarations_from_cst(scalar), Vec::new())],
                vec![src.clone()], ScalarPreparationInputs { target_layout },
            ).unwrap();
            let build = crate::prepare_scalar_project(
                vec![(crate::derive_scalar_build_declarations_from_cst(scalar), Vec::new())],
                vec![src.clone()], ScalarPreparationInputs { target_layout },
            ).unwrap();
            for (item, expected) in [1, 1, 0, 0, 0].into_iter().enumerate() {
                let body = checker.parts().1.function_body(0, item, None).unwrap();
                let checker_view = checker.occurrence_snapshot();
                let build_view = build.occurrence_snapshot();
                let kind = PreparedReadKind::SharedCheckedReference;
                let shapes = (0..body.occurrences.len()).filter_map(|read| {
                    let read = OccurrenceOrdinal(read);
                    let checker_packet = checker_view.read(0, item, read, kind);
                    let build_packet = build_view.read(0, item, read, kind);
                    assert_eq!(checker_packet.is_some(), build_packet.is_some());
                    let checked = checker_packet?;
                    let ordinary = build_packet.unwrap();
                    assert!(checked.matches(checker_view, 0, item, read, kind));
                    assert_eq!(checked.target_layout(), target_layout);
                    let other_item = 1 - item;
                    let peer = checker_view.read(0, other_item, read, kind).expect("same ordinal in another actual read");
                    assert!(peer.matches(checker_view, 0, other_item, read, kind));
                    assert!(!checked.matches(checker_view, 0, other_item, read, kind));
                    assert!(!checked.matches(build_view, 0, item, read, kind));
                    assert!(!ordinary.matches(checker_view, 0, item, read, kind));
                    assert!(!checked.matches(checker_view, 0, item, read, PreparedReadKind::FixedIndex));
                    assert_eq!(checked.shape(), ordinary.shape());
                    let PreparedReadShape::SharedCheckedReference(shape) = checked.shape() else { unreachable!() };
                    assert_eq!(shape.result, &ScalarType::U8);
                    Some(())
                }).count();
                assert_eq!(shapes, expected);
            }
            let raw = crate::parse_source(src.clone(),
                "%%start u8(*?u8) raw = fn(pointer) { unsafe { *pointer } }; %%end".to_owned(), &[]);
            let rejected = prepare_checker_project(
                vec![(crate::derive_scalar_check_declarations_from_cst(raw.result.canonical_cst()), Vec::new())],
                vec![src.clone()], ScalarPreparationInputs { target_layout },
            );
            assert!(matches!(rejected, Err(ProjectCheck::Invalid(diagnostics))
                if diagnostics.iter().any(|d| d.message == "checked dereference requires a checked reference")));
            let validated = crate::analyze_scalar_build(&build);
            assert!(validated.diagnostics().is_empty(), "{:?}", validated.diagnostics());
            let ir = crate::emit_scalar_build_single_module_llvm(&validated).unwrap().to_text();
            let read = ir.split_once("define i8 @read(").unwrap().1.split_once("\n}").unwrap().0;
            assert!(read.contains("deref_is_null"), "{read}");
        }
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn runtime_fixed_index_evidence_requires_the_ordinary_guard_and_exact_preparation() {
        use super::super::static_calls::{PreparedReadKind, PreparedReadShape};
        use super::super::reference::{CheckerOrdinaryScalarLocalKind, CheckerSnapshotReadIndex, CheckerSnapshotArrayOffset};
        let src = source("src/main.w", "runtime-fixed-index-evidence");
        let text = r#"%%start
            unit(u64) inspect = fn(index) {
                i8[2] payload = [3, 9];
                if (index < 2) {
                    i8 checked = payload[index];
                    i8 second = payload[0];
                    if (checked == 3) {};
                    if (second == 3) {};
                };
            };
        %%end"#;
        let prepare = |text: &str, target_layout| {
            let parsed = crate::parse_source(src.clone(), text.to_owned(), &[]);
            prepare_checker_project(
                vec![(crate::derive_scalar_check_declarations_from_cst(parsed.result.canonical_cst()), Vec::new())],
                vec![src.clone()], ScalarPreparationInputs { target_layout },
            ).unwrap()
        };
        fn access(calls: &FunctionCallSites, lexical: bool) -> &super::super::reference::CheckerOrdinaryScalarLocal {
            calls.structure.checker_ordinary_scalar_locals.values().find(|origin| {
                match &origin.kind {
                    CheckerOrdinaryScalarLocalKind::SnapshotRead { index: CheckerSnapshotReadIndex::ArrayPath(steps), .. } =>
                        lexical && matches!(steps.as_ref(), [step] if matches!(step.offset, CheckerSnapshotArrayOffset::Lexical(_))),
                    CheckerOrdinaryScalarLocalKind::SnapshotRead { index: CheckerSnapshotReadIndex::Leaf(_), .. } => !lexical,
                    _ => false,
                }
            }).unwrap()
        }
        let native = ScalarTargetLayout::NATIVE64;
        let wasi = ScalarTargetLayout::WASM32;
        for target in [native, wasi] {
            let prepared = prepare(text, target);
            let result = prepared.observe_runtime_fixed_indices(0, 0).unwrap();
            let calls = prepared.parts().1.function_body(0, 0, None).unwrap();
            let dynamic = access(calls, true);
            let shape = calls.fixed_index_read_shape(dynamic.source).unwrap();
            assert_eq!(shape.extent, 2);
            assert_eq!(shape.result, &ScalarType::I8);
            assert!(calls.fixed_index_read_shape(access(calls, false).source).is_none());
            // Ordinary Build preparation can describe the same operation
            // without importing checker evidence or claiming authority.
            let parsed = crate::parse_source(src.clone(), text.to_owned(), &[]);
            let build = crate::prepare_scalar_project(
                vec![(crate::derive_scalar_build_declarations_from_cst(parsed.result.canonical_cst()), Vec::new())],
                vec![src.clone()], ScalarPreparationInputs { target_layout: target },
            ).unwrap();
            let kind = PreparedReadKind::FixedIndex;
            let checker_view = prepared.occurrence_snapshot();
            let build_view = build.occurrence_snapshot();
            let checker_packet = checker_view.read(0, 0, dynamic.source, kind).unwrap();
            let build_packet = build_view.read(0, 0, dynamic.source, kind).unwrap();
            assert_eq!(build_packet.shape(), checker_packet.shape());
            let PreparedReadShape::FixedIndex(build_shape) = build_packet.shape() else { unreachable!() };
            assert!(!std::ptr::eq(build_shape.base_binding, shape.base_binding));
            assert!(checker_packet.matches(checker_view, 0, 0, dynamic.source, kind));
            assert!(!checker_packet.matches(build_view, 0, 0, dynamic.source, kind));
            assert!(!checker_packet.matches(checker_view, 0, 0, access(calls, false).source, kind));
            assert!(result.authorizes(calls, dynamic, 2));
            assert!(!result.authorizes(calls, dynamic, 3));
            let similar = prepare(text, target);
            let similar_calls = similar.parts().1.function_body(0, 0, None).unwrap();
            assert!(!result.authorizes(similar_calls, access(similar_calls, true), 2));
            let other_target = prepare(text, if target == native { wasi } else { native });
            assert!(!checker_packet.matches(other_target.occurrence_snapshot(), 0, 0, dynamic.source, kind));
            assert!(!result.authorizes(other_target.parts().1.function_body(0, 0, None).unwrap(), dynamic, 2));
            assert!(!result.authorizes(calls, access(calls, false), 2));
            let dead = text.replace("index < 2", "false");
            assert!(prepare(&dead, target).observe_runtime_fixed_indices(0, 0).is_none());
            let erased = text.replace("if (index < 2) {", r#"
                core.narrow(index < 2, { .stdout = ""; .stderr = ""; .code = 1; .files = []; });
                if (true) {
            "#);
            assert!(prepare(&erased, target).observe_runtime_fixed_indices(0, 0).is_none());
            let nested_unsafe = text.replace("if (index < 2) {", "unsafe { if (index < 2) {")
                .replace("if (second == 3) {};", "if (second == 3) {}; };");
            assert!(prepare(&nested_unsafe, target).observe_runtime_fixed_indices(0, 0).is_none());
        }
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn terminal_fixed_index_batch_visits_each_selected_callable_once() {
        let src = source("src/main.w", "terminal-fixed-index-batch");
        let input = r#"%%start
            unit(u64) inspect = fn(index) {
                i8[2] pair = [3, 9];
                i8[3] triple = [3, 8, 5];
                if (index < 2) {
                    i8 selected = pair[index];
                    i8 other = triple[index];
                    if (selected == 3) {};
                    if (other == 3) {};
                };
            };
            unit(u64) never = fn(index) {
                i8[2] pair = [3, 9];
                if (false) {
                    i8 selected = pair[index];
                    if (selected == 3) {};
                };
            };
            unit(u8) verify = fn(value) { core.require(value >= 1, OUTPUT); };
            verify(1);
        %%end"#.replace("OUTPUT", OUTPUT);
        let candidates = |prepared: &PreparedCheckerProject, item: usize| {
            let (_, body) = prepared.occurrence_snapshot().monomorphic_body(0, item).unwrap();
            let mut reads = body.structure.checker_ordinary_scalar_locals.values()
                .filter_map(|local| Some((body.fixed_index_read_shape(local.source)?.extent, local.source)))
                .collect::<Vec<_>>();
            reads.sort_unstable_by_key(|(extent, _)| *extent);
            reads
        };
        for target_layout in [ScalarTargetLayout::NATIVE64, ScalarTargetLayout::WASM32] {
            let prepare = |input: &str| prepare_checker_project(
                vec![(declarations(&src, input), Vec::new())], vec![src.clone()], ScalarPreparationInputs { target_layout },
            ).unwrap();
            let project = prepare(&input);
            let one = candidates(&project, 0);
            let [(2, pair), (3, triple)] = one.as_slice() else { panic!("two distinct prepared reads"); };
            let dead = candidates(&project, 1);
            let [(2, dead)] = dead.as_slice() else { panic!("structural dead read is not evidence"); };
            let requests = [(0, 0, *pair), (0, 0, *triple), (0, 0, *pair), (0, 1, *dead), (0, 2, *pair)];
            let (outcome, observed) = prepared::check_ordinary_package_with_fixed_index_observations(&project, &requests);
            assert!(matches!(outcome, ScalarOrderedCheckerOutcome::Passed), "{outcome:?}");
            let observed = observed.unwrap();
            assert_eq!(observed.observed_bodies(), 2);
            assert!(observed.describes(&project, 0, 0, *pair, 2));
            assert!(observed.describes(&project, 0, 0, *triple, 3));
            assert!(!observed.describes(&project, 0, 0, *triple, 2));
            assert!(!observed.describes(&project, 0, 1, *dead, 2));
            assert!(!observed.describes(&project, 0, 2, *pair, 2));
            assert!(!observed.describes(&prepare(&input), 0, 0, *pair, 2));
            let over = vec![(0, 0, *pair); 17];
            let (outcome, observed) = prepared::check_ordinary_package_with_fixed_index_observations(&project, &over);
            assert!(matches!(outcome, ScalarOrderedCheckerOutcome::Passed));
            assert!(observed.is_none());
            let refuted = prepare(&input.replace("value >= 1", "value > 1"));
            let (outcome, observed) = prepared::check_ordinary_package_with_fixed_index_observations(&refuted, &requests);
            assert!(matches!(outcome, ScalarOrderedCheckerOutcome::Failed(_)));
            assert!(observed.is_none());
        }
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn fixed_index_observation_is_published_only_by_completed_explicit_check() {
        use super::super::static_calls::PreparedReadKind;
        let src = source("src/main.w", "terminal-fixed-index");
        let text = r#"%%start
            unit(u64) inspect = fn(index) {
                i8[2] payload = [3, 9];
                if (index < 2) {
                    i8 checked = payload[index];
                    if (checked == 3) {};
                };
            };
            unit(u8) verify = fn(value) {
                core.narrow(value > 0, OUTPUT);
                core.require(value >= 1, OUTPUT);
            };
            verify(1);
        %%end"#.replace("OUTPUT", OUTPUT);
        for target_layout in [ScalarTargetLayout::NATIVE64, ScalarTargetLayout::WASM32] {
            let prepare_with_init = |input: &str, order| {
                prepare_checker_project(vec![(declarations(&src, input), Vec::new())], order,
                    ScalarPreparationInputs { target_layout })
            };
            let prepare = |input: &str| prepare_with_init(input, vec![src.clone()]).unwrap();
            let project = prepare(&text);
            let find = |prepared: &PreparedCheckerProject| {
                let (_, body) = prepared.occurrence_snapshot().monomorphic_body(0, 0).unwrap();
                body.structure.checker_ordinary_scalar_locals.values().find_map(|local|
                    body.fixed_index_read_shape(local.source).map(|_| local.source)).unwrap()
            };
            let read = find(&project);
            let (outcome, proof) = prepared::check_ordinary_package_with_fixed_index_observation(&project, 0, 0, read);
            assert!(matches!(outcome, ScalarOrderedCheckerOutcome::Passed), "{outcome:?}");
            let proof = proof.unwrap();
            assert!(proof.describes(&project, 0, 0, read, 2));
            assert!(!proof.describes(&project, 0, 0, read, 3));
            let other = prepare(&text);
            assert!(!proof.describes(&other, 0, 0, find(&other), 2));
            assert!(project.occurrence_snapshot().read(0, 1, read, PreparedReadKind::FixedIndex).is_none());
            let (outcome, unmatched) = prepared::check_ordinary_package_with_fixed_index_observation(&project, 0, 1, read);
            assert!(matches!(outcome, ScalarOrderedCheckerOutcome::Passed) && unmatched.is_none());

            let refuted = prepare(&text.replace("value >= 1", "value > 1"));
            let (outcome, proof) = prepared::check_ordinary_package_with_fixed_index_observation(&refuted, 0, 0, find(&refuted));
            assert!(matches!(outcome, ScalarOrderedCheckerOutcome::Failed(failures) if !failures.is_empty()));
            assert!(proof.is_none());
            let skipped = prepare(&format!("{}%%end", text.split_once("unit(u8) verify").unwrap().0));
            let (outcome, proof) = prepared::check_ordinary_package_with_fixed_index_observation(&skipped, 0, 0, find(&skipped));
            assert!(matches!(outcome, ScalarOrderedCheckerOutcome::NoChecks), "{outcome:?}");
            assert!(proof.is_none());
            let partial = prepare(&text.replace("verify(1);", &format!("verify(1); core.narrow(false, {OUTPUT});")));
            let (outcome, proof) = prepared::check_ordinary_package_with_fixed_index_observation(&partial, 0, 0, find(&partial));
            assert!(matches!(outcome, ScalarOrderedCheckerOutcome::Failed(_) | ScalarOrderedCheckerOutcome::Unsupported));
            assert!(proof.is_none());
            match prepare_with_init(&text, Vec::new()) {
                Ok(invalid_order) => {
                    let (outcome, proof) = prepared::check_ordinary_package_with_fixed_index_observation(&invalid_order, 0, 0, find(&invalid_order));
                    assert!(matches!(outcome, ScalarOrderedCheckerOutcome::Unsupported));
                    assert!(proof.is_none());
                }
                Err(ProjectCheck::Invalid(_)) => (),
                Err(_) => panic!("unexpected initialization error"),
            }
            assert!(matches!(prepare_with_init(&text.replace("i8 checked", "bool checked"), vec![src.clone()]),
                Err(ProjectCheck::Invalid(_))));
        }
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn ordinary_fixed_array_read_partitions_only_in_bounds_index_preimages() {
        let app = source("src/main.w", "ordinary-array-read");
        let text = r#"%%start
            unit(u64, i8) inspect = fn(index, value) {
                core.narrow(value == 1 || value == 3, { .stdout = ""; .stderr = ""; .code = 1; .files = []; });
                i8[2] original = [value, 9];
                i8[2] copied = original;
                value = 7;
                if (index == 0) {
                    i8 observed = copied[index];
                    i8 fixed = copied[1];
                    core.require(fixed == 9, { .stdout = ""; .stderr = "wrong literal index"; .code = 59; .files = []; });
                    if (observed == 3) {
                        core.require(index == 0, { .stdout = ""; .stderr = "wrong preimage"; .code = 60; .files = []; });
                        core.require(value != 7, { .stdout = ""; .stderr = ""; .code = 61;
                            .files = [{ .path = "observed.json"; .state = observed; }]; });
                    } else {
                        core.require(observed == 1, { .stdout = ""; .stderr = "lost correlation"; .code = 63; .files = []; });
                    };
                };
            };
        %%end"#;
        let actual = text.replace("%%end", "inspect(0, 3); %%end");
        let run = |input: &str, scope| {
            let prepared = prepare_proof_target(&app, input).unwrap();
            run_closed_without_named_proofs(&prepared, scope, 1)
        };
        for (input, scope) in [(text, ScalarCheckerScope::CurrentPackage),
            (actual.as_str(), ScalarCheckerScope::MainFlowOnly), (actual.as_str(), ScalarCheckerScope::CurrentPackage)]
        {
            let receipt = run(input, scope).unwrap();
            let [failure] = receipt.directives.as_slice() else { panic!("only the preserved indexed read selects its branch"); };
            assert_eq!(failure.code(), &BigInt::from(61));
            assert_eq!(failure.witness.axes().len(), 4);
            assert!(failure.witness.axes().all(|(binding, _)| binding.kind == super::super::ReferenceBindingKind::Declared));
            assert_eq!(failure.files()[0].text.as_ref(), b"{\"type\":{\"kind\":\"i8\"},\"value\":3}\n");
        }
        let alternatives = text.replace("if (index == 0)", "if (index == 0 || index == 2)")
            .replace("i8[2]", "i8[3]").replace("[value, 9]", "[value, 13, 9]").replace("copied[1]", "copied[2]")
            .replace("observed == 1,", "observed == 1 || (index == 2 && observed == 9),");
        let receipt = run(&alternatives, ScalarCheckerScope::CurrentPackage).unwrap();
        let [failure] = receipt.directives.as_slice() else { panic!("only the authored index preimage fails"); };
        assert_eq!(failure.code(), &BigInt::from(61));
        let zero = BigInt::from(0);
        assert!(failure.witness.intervals_at(0, 0).unwrap().eq([(&zero, &zero)]));
        let invalid = alternatives.replace("index == 2)", "index == 3)");
        assert!(matches!(run(&invalid, ScalarCheckerScope::CurrentPackage), Err(ProjectCheck::Unsupported)));
        let beyond = actual.replace("if (index == 0)", "if (index == 2)").replace("inspect(0, 3)", "inspect(2, 3)");
        assert!(matches!(run(&beyond, ScalarCheckerScope::MainFlowOnly), Err(ProjectCheck::Unsupported)));
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn ordinary_immutable_member_read_preserves_captured_control_and_public_axes() {
        let app = source("src/main.w", "ordinary-nominal-member-read");
        let text = r#"%%start
            struct copy Snapshot { i8 saved; bool enabled; }
            unit(i8) inspect = fn(value) {
                core.narrow(value == 1 || value == 3, { .stdout = ""; .stderr = ""; .code = 1; .files = []; });
                Snapshot original = { .saved = value; .enabled = true; };
                Snapshot copied = original;
                if (value == 3) {
                    i8 earlier = copied.saved;
                    core.require(earlier == 3, { .stdout = ""; .stderr = "lost relation"; .code = 59; .files = []; });
                };
                value = 7;
                i8 observed = copied.saved;
                bool enabled = copied.enabled;
                if (enabled && observed == 3) {
                    core.require(value != 7, { .stdout = ""; .stderr = "selected"; .code = 61;
                        .files = [{ .path = "observed.json"; .state = observed; }]; });
                } else {
                    core.require(observed == 1, { .stdout = ""; .stderr = "wrong lane"; .code = 63; .files = []; });
                };
            };
        %%end"#;
        let actual = text.replace("%%end", "inspect(3); %%end");
        for (input, scope) in [(text, ScalarCheckerScope::CurrentPackage),
            (actual.as_str(), ScalarCheckerScope::MainFlowOnly), (actual.as_str(), ScalarCheckerScope::CurrentPackage)]
        {
            let prepared = prepare_proof_target(&app, input).unwrap();
            let receipt = run_closed_without_named_proofs(&prepared, scope, 1).unwrap();
            let [failure] = receipt.directives.as_slice() else { panic!("only the preserved member selects its branch"); };
            assert_eq!(failure.code(), &BigInt::from(61));
            assert_eq!(failure.witness.axes().len(), 3);
            assert!(failure.witness.axes().all(|(binding, _)| binding.kind == super::super::ReferenceBindingKind::Declared));
            assert!(failure.witness.equal_axes().is_empty());
            assert_eq!(failure.files()[0].text.as_ref(), b"{\"type\":{\"kind\":\"i8\"},\"value\":3}\n");
        }
        let mutated = actual.replace("value = 7;", "copied.saved = 2; value = 7;");
        let prepared = prepare_proof_target(&app, &mutated).unwrap();
        assert!(matches!(run_closed_without_named_proofs(&prepared, ScalarCheckerScope::MainFlowOnly, 1),
            Err(ProjectCheck::Unsupported)));
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn authored_aggregate_projection_can_select_exact_code_and_state() {
        let app = source("src/main.w", "authored-aggregate-projected-output");
        let array = r#"%%start
            unit(i8) check = fn(value) {
                core.narrow(value == 1 || value == 3, { .stdout = ""; .stderr = ""; .code = 1; .files = []; });
                i8[3] original = [value, 57, 99];
                i8[3] copied = original;
                value = 7;
                core.require(value != 7, { .stdout = ""; .stderr = ""; .code = copied[1];
                    .files = [{ .path = "selected.json"; .state = copied[0]; }]; });
            };
        %%end"#;
        let prepared = prepare_proof_target(&app, array).unwrap();
        let receipt = run_closed_without_named_proofs(&prepared, ScalarCheckerScope::CurrentPackage, 1).unwrap();
        let [failure] = receipt.directives.as_slice() else { panic!("one projected failure"); };
        assert_eq!(failure.code(), &BigInt::from(57));
        assert_eq!(failure.witness.axes().len(), 1);
        assert_eq!(failure.files()[0].text.as_ref(),
            b"{\"type\":{\"kind\":\"i8\"},\"value\":{\"kind\":\"alternatives\",\"values\":[1,3]}}\n");
        let prepared = prepare_proof_target(&app, &array.replace(".code = copied[1]", ".code = copied[0]")).unwrap();
        assert!(matches!(run_closed_without_named_proofs(&prepared, ScalarCheckerScope::CurrentPackage, 1),
            Err(ProjectCheck::Unsupported)));
        assert!(matches!(prepare_proof_target(&app, &array.replace("copied[0]", "copied[3]")),
            Err(ProjectCheck::Invalid(_))));
        assert!(matches!(prepare_proof_target(&app, &array.replace("copied[0]", "copied[value]")),
            Err(ProjectCheck::Invalid(_))));

        let member_code_only = r#"%%start
            struct Snapshot { i8 status; }
            unit(i8) check = fn(value) {
                Snapshot saved = { .status = value; };
                core.require(value != 7, { .stdout = ""; .stderr = ""; .code = saved.status; .files = []; });
            };
        %%end"#;
        let prepared = prepare_proof_target(&app, member_code_only).unwrap();
        let receipt = run_closed_without_named_proofs(&prepared, ScalarCheckerScope::CurrentPackage, 1).unwrap();
        let [failure] = receipt.directives.as_slice() else { panic!("code-only projection demands snapshot"); };
        assert_eq!(failure.code(), &BigInt::from(7));
        assert_eq!(failure.witness.axes().len(), 1);
        assert!(failure.files().is_empty());
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn authored_nominal_field_state_omits_siblings_and_aggregate_identity() {
        let app = source("src/main.w", "authored-field-state");
        let text = r#"%%start
            struct copy Snapshot { i8 saved; bool ready; i8 omitted; }
            unit(i8) check = fn(value) {
                core.narrow(value == 1 || value == 3, { .stdout = ""; .stderr = ""; .code = 1; .files = []; });
                Snapshot original = { .omitted = 44; .ready = true; .saved = value; };
                Snapshot copied = original;
                value = 7;
                core.require(value != 7, { .stdout = ""; .stderr = ""; .code = 57; .files = [
                    { .path = "saved.json"; .state = copied.saved; },
                    { .path = "inverted.json"; .state = !copied.ready; },
                    { .path = "same.json"; .state = copied.saved; }
                ]; });
            };
        %%end"#;
        let prepared = prepare_proof_target(&app, text).unwrap();
        let receipt = run_closed_without_named_proofs(&prepared, ScalarCheckerScope::CurrentPackage, 1).unwrap();
        let [failure] = receipt.directives.as_slice() else { panic!("one field projection witness"); };
        assert_eq!(failure.witness.axes().len(), 1);
        assert!(failure.witness.equal_axes().is_empty());
        let [saved, inverted, same] = failure.files() else { panic!("only the authored scalar projections"); };
        assert_eq!(saved.text.as_ref(),
            b"{\"type\":{\"kind\":\"i8\"},\"value\":{\"kind\":\"alternatives\",\"values\":[1,3]}}\n");
        assert_eq!(inverted.text.as_ref(), b"{\"type\":{\"kind\":\"bool\"},\"value\":false}\n");
        assert_eq!(same.text, saved.text);
        assert!(matches!(prepare_proof_target(&app, &text.replace("copied.saved", "copied.unknown")),
            Err(ProjectCheck::Invalid(_))));
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn copied_aggregate_state_has_only_one_construction_capture() {
        let app = source("src/main.w", "copied-aggregate-state");
        for (declarations, ty, init) in [
            ("struct copy Snapshot { i8 saved; }", "Snapshot", "{ .saved = value; }"),
            ("", "i8[2]", "[value, 4]"),
        ] {
            let text = format!(r#"%%start
                {declarations}
                unit(i8) check = fn(value) {{
                    core.narrow(value == 1 || value == 3, {OUTPUT});
                    {ty} original = {init};
                    {ty} copy_one = original;
                    value = 7;
                    {ty} copy_two = copy_one;
                    core.require(value != 7, {{ .stdout = ""; .stderr = ""; .code = 57;
                        .files = [{{ .path = "a.json"; .state = copy_two; }},
                                  {{ .path = "b.json"; .state = copy_one; }}]; }});
                }};
            %%end"#);
            let prepared = prepare_proof_target(&app, &text).unwrap();
            let (project, calls) = prepared.parts();
            let (module, item, _) = select_checked_root(project, &app, "check").unwrap();
            let structure = &calls.function_body(module, item, None).unwrap().structure;
            assert_eq!(structure.checker_snapshot_locals.len(), 1);
            assert_eq!(structure.checker_snapshot_copies.len(), 2);
            assert_eq!(structure.checker_selected_snapshots.len(), 3);
            let receipt = run_closed_without_named_proofs(&prepared, ScalarCheckerScope::CurrentPackage, 1).unwrap();
            let [failure] = receipt.directives.as_slice() else { panic!("one copy witness"); };
            assert_eq!(failure.witness.axes().len(), 1);
            assert!(failure.witness.equal_axes().is_empty());
            assert_eq!(failure.files()[0].text, failure.files()[1].text);
            let json = std::str::from_utf8(&failure.files()[0].text).unwrap();
            assert!(json.contains(r#"{"kind":"alternatives","values":[1,3]}"#));
            if ty == "Snapshot" {
                let mutated = text.replace("value = 7;", "copy_one.saved = 9; value = 7;");
                let prepared = prepare_proof_target(&app, &mutated).unwrap();
                assert!(matches!(run_closed_without_named_proofs(&prepared, ScalarCheckerScope::CurrentPackage, 1),
                    Err(ProjectCheck::Unsupported)));
            }
        }
    }

