    #[cfg(feature = "internal-checker")]
    #[test]
    fn ordered_named_calling_producer_observes_alias_and_reflected_preimages() {
        let app = source("src/main.w", "named-call-return-preimages");
        let text = r#"%%start
            i8(i8) leaf = fn(n) { n };
            i8(i8) producer = fn(n) { i8 observed = leaf(n); observed };
            proof bounded for producer(entry) -> (out) where (entry >= 0) ensures (out == 7) {}
        %%end"#;
        let run = |text: &str| {
            let (_, proof) = crate::parse_proof_source(app.clone(), text.to_owned(), &[]).ok().unwrap();
            check_loaded_ordered_proof_diagnostics(
                Vec::new(), vec![(proof, Vec::new())], vec![app.clone()], inputs(), ScalarCheckerScope::CurrentPackage,
            )
        };
        let alias = run(text).unwrap().symbolic_diagnostic.unwrap();
        assert_eq!(alias.returned, BigInt::from(0));
        assert!(alias.witness.intervals_at(0, 0).unwrap().eq([
            (&BigInt::from(0), &BigInt::from(6)), (&BigInt::from(8), &BigInt::from(127)),
        ]));
        let affine = text.replace("{ n }", "{ -1 - n }").replace("entry >= 0", "entry < 0");
        let reflected = run(&affine).unwrap().symbolic_diagnostic.unwrap();
        assert_eq!(reflected.returned, BigInt::from(127));
        assert!(reflected.witness.intervals_at(0, 0).unwrap().eq([
            (&BigInt::from(-128), &BigInt::from(-9)), (&BigInt::from(-7), &BigInt::from(-1)),
        ]));
        assert!(run(&affine.replace("entry < 0", "entry == -8")).unwrap().symbolic_diagnostic.is_none());
        let equality = affine.replace("out == 7", "out == core.old(entry)");
        let mismatch = run(&equality).unwrap().symbolic_diagnostic.unwrap();
        assert_eq!(mismatch.returned, BigInt::from(127));
        assert!(mismatch.witness.intervals_at(0, 0).unwrap().eq([(&BigInt::from(-128), &BigInt::from(-1))]));
        let unsigned = equality.replace("i8", "u8").replace("-1 - n", "255 - n").replace("entry < 0", "entry >= 0");
        let mismatch = run(&unsigned).unwrap().symbolic_diagnostic.unwrap();
        assert_eq!(mismatch.returned, BigInt::from(255));
        assert!(mismatch.witness.intervals_at(0, 0).unwrap().eq([(&BigInt::from(0), &BigInt::from(255))]));
        let empty_equality = equality.replace("entry < 0", "entry < -128");
        assert!(run(&empty_equality).unwrap().symbolic_diagnostic.is_none());
        assert!(matches!(run(&empty_equality.replace("-1 - n", "1 - n")), Err(ProjectCheck::Unsupported)),
            "a vacuous entry-equality guard cannot authorize an overflowing computation");
        assert!(matches!(run(&affine.replace("-1 - n", "1 - n")), Err(ProjectCheck::Unsupported)),
            "the proof guard cannot make an overflowing actual computation defined");
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn ordered_named_calling_producer_reuses_return_provenance_for_distinct_guards() {
        let app = source("src/main.w", "batch-named-calling-producer");
        let text = format!(r#"%%start
            unit() checked_step = fn {{ core.require(false, {OUTPUT}); }};
            i8(i8) leaf = fn(n) {{ if (n < 0) {{ -3 }} else {{ 7 }} }};
            i8(i8) producer = fn(n) {{ checked_step(); i8 produced = leaf(n); produced }};
            proof positive for producer(entry) -> (out) where (entry >= 0) ensures (out == 7) {{}}
            proof negative for producer(entry) -> (out) where (entry < 0) ensures (out == -3) {{}}
        %%end"#);
        let run = |text: &str| {
            let (_, proof) = crate::parse_proof_source(app.clone(), text.to_owned(), &[]).ok().unwrap();
            check_loaded_ordered_proof_diagnostics(
                Vec::new(), vec![(proof, Vec::new())], vec![app.clone()], inputs(), ScalarCheckerScope::CurrentPackage,
            ).unwrap()
        };
        let baseline = run(&text.lines().filter(|line| !line.contains("proof negative")).collect::<Vec<_>>().join("\n"));
        let verified = run(&text);
        assert_eq!(verified.directives.len(), baseline.directives.len(), "one producer capture for both goals");
        assert!(verified.symbolic_diagnostic.is_none() && verified.additional_symbolic_diagnostics.is_empty());
        let failed = run(&text.replace("out == 7", "out == 8").replace("out == -3", "out == -4"));
        assert_eq!(failed.directives.len(), baseline.directives.len());
        let first = failed.symbolic_diagnostic.unwrap();
        let [second] = failed.additional_symbolic_diagnostics.as_slice() else { panic!("separate ordered proof failures"); };
        assert_eq!(first.returned, BigInt::from(7));
        assert_eq!(second.returned, BigInt::from(-3));
        assert!(first.witness.intervals_at(0, 0).unwrap().eq([(&BigInt::from(0), &BigInt::from(127))]));
        assert!(second.witness.intervals_at(0, 0).unwrap().eq([(&BigInt::from(-128), &BigInt::from(-1))]));
        assert!(first.directive_position > 0);
        assert_eq!(first.directive_position, second.directive_position);
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn ordered_named_proof_checks_calling_producer_against_its_own_entry() {
        let app = source("src/main.w", "named-proof-calling-producer-entry");
        let text = format!(r#"%%start
            unit() checked_step = fn {{ core.require(false, {OUTPUT}); }};
            i8(i8) leaf = fn(input) {{ input }};
            i8(i8) wrap = fn(value) {{ i8 middle = leaf(value); middle }};
            i8(i8) producer = fn(value) {{ checked_step(); i8 result = wrap(value); result }};
            proof guarded for producer(entry) -> (out) where (entry >= 0) ensures (out == core.old(entry)) {{}}
        %%end"#);
        let run = |text: &str| {
            let (_, proof) = crate::parse_proof_source(app.clone(), text.to_owned(), &[]).ok().unwrap();
            check_loaded_ordered_proof_diagnostics(
                Vec::new(), vec![(proof, Vec::new())], vec![app.clone()], inputs(), ScalarCheckerScope::CurrentPackage,
            )
        };
        let proved = run(&text).unwrap();
        assert!(proved.active && proved.diagnostics.is_empty() && proved.symbolic_diagnostic.is_none());
        assert!(!proved.directives.is_empty());

        let constant = text.replace("{ input }", "{ if (input < 0) { -3 } else { 7 } }");
        let failed = run(&constant).unwrap();
        let proof = failed.symbolic_diagnostic.unwrap();
        assert_eq!(proof.returned, BigInt::from(7));
        assert!(proof.witness.intervals_at(0, 0).unwrap().eq([
            (&BigInt::from(0), &BigInt::from(6)), (&BigInt::from(8), &BigInt::from(127)),
        ]));
        assert!(proof.directive_position > 0);

        for guard in ["entry == 7", "entry < -128"] {
            let unchanged = constant.replace("entry >= 0", guard);
            assert!(run(&unchanged).unwrap().symbolic_diagnostic.is_none());
        }
        let transitive_write = text.replace("{ input }", "{ input = 0; input }");
        assert!(matches!(run(&transitive_write), Err(ProjectCheck::Unsupported)));
    }

