    #[cfg(feature = "internal-checker")]
    #[test]
    fn array_proof_cohort_shares_unused_union_and_publishes_real_declaration_witnesses() {
        use crate::scalar::checker_flow::take_array_return_observations;
        let text = r#"%%start
            i8[2](i8) reflect = fn(value) { [value, -1 - value] };
            proof has_nonnegative for reflect(entry) -> (items) where (entry >= 0 || entry == -2)
                ensures (exists (u64 i where i < 2) { items[i] >= 0 }) {}
            u8[1]() unavailable = fn { [6] };
            proof independent for unavailable() -> (items)
                forall (u64 i where i == 0) ensures (items[i] == 6) {}
            proof never for unavailable() -> (items) where (false)
                forall (u64 i where i == 0) ensures (items[i] == 99) {}
            proof first_bounded for reflect(which) -> (items) where (which == 2 || which == -2)
                forall (u64 i where i == 0) ensures (items[i] <= 2) {}
        %%end"#;
        let declared = ScalarCheckerScope::CurrentPackage;
        take_array_return_observations();
        let proved = check_array_proof_cohort(text, declared).unwrap();
        assert!(proved.active && proved.aggregate_diagnostics.is_empty());
        assert_eq!(take_array_return_observations(), (2, 0));

        let false_goals = text.replace("items[i] >= 0", "items[i] > 0")
            .replace("items[i] == 6", "items[i] == 8")
            .replace("items[i] <= 2", "items[i] < 2");
        let refuted = check_array_proof_cohort(&false_goals, declared).unwrap();
        assert_eq!(take_array_return_observations(), (2, 0));
        let [first, independent, third] = refuted.aggregate_diagnostics.as_slice()
            else { panic!("all three declarations in authored order"); };
        assert!(first.proof.range.start < independent.proof.range.start
            && independent.proof.range.start < third.proof.range.start);
        assert!(first.cell.is_none() && first.call.is_none());
        let zero = BigInt::from(0);
        assert!(first.witness.intervals_at(0, 0).unwrap().eq([(&zero, &zero)]));
        assert_eq!(independent.cell.as_ref().unwrap().value, BigInt::from(6));
        assert!(independent.witness.axes().next().is_none());
        assert_eq!(third.cell.as_ref().unwrap().value, BigInt::from(2));
        let two = BigInt::from(2);
        assert!(third.witness.intervals_at(0, 0).unwrap().eq([(&two, &two)]));

        let main = check_array_proof_cohort(&false_goals, ScalarCheckerScope::MainFlowOnly).unwrap();
        assert!(!main.active && main.aggregate_diagnostics.is_empty());
        assert_eq!(take_array_return_observations(), (0, 0));
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn array_proof_cohort_keeps_actual_calls_separate_and_guards_independent() {
        use crate::scalar::checker_flow::take_array_return_observations;
        let text = format!(r#"%%start
            u8[2](u8,u8) make = fn(tag, value) {{
                if (tag == 1) {{ [value, 7] }} else {{ [9, value] }}
            }};
            proof first for make(tag, entry) -> (items) where (tag == 1 && entry == 3)
                forall (u64 i where i == 0) ensures (items[i] == 3) {{}}
            proof different for make(other, entry) -> (items) where (other == 2 && entry == 5)
                ensures (exists (u64 i where i < 2) {{ items[i] == 5 }}) {{}}
            proof again for make(mark, entry) -> (items) where (mark == 1 && entry == 3)
                ensures (exists (u64 i where i < 2) {{ items[i] == 7 }}) {{ core.witness(1); }}
            u8[2] pick = make(1, 3);
            u8[2] middle = make(2, 5);
            u8[2] repeat = make(1, 3);
            u8 chosen = pick[0];
            u8 outside = middle[1];
            u8 repeated = repeat[0];
            core.require(chosen == 3, {OUTPUT});
            core.require(outside == 5, {OUTPUT});
            core.require(repeated == 3, {OUTPUT});
        %%end"#);
        for scope in [ScalarCheckerScope::MainFlowOnly, ScalarCheckerScope::CurrentPackage] {
            take_array_return_observations();
            let proved = check_array_proof_cohort(&text, scope).unwrap();
            assert!(proved.active && proved.aggregate_diagnostics.is_empty() && proved.directives.is_empty());
            assert_eq!(take_array_return_observations(), (0, 3));
            let refuted = check_array_proof_cohort(
                &text.replace("items[i] == 3", "items[i] == 8").replace("core.witness(1)", "core.witness(0)"), scope,
            ).unwrap();
            let failures = &refuted.aggregate_diagnostics;
            assert_eq!(failures.len(), 4);
            assert!(refuted.directives.is_empty());
            assert_eq!(take_array_return_observations(), (0, 3));
            assert_eq!(failures[0].call, failures[1].call);
            assert_eq!(failures[2].call, failures[3].call);
            assert!(failures[0].call.as_ref().unwrap().range.start < failures[2].call.as_ref().unwrap().range.start);
            assert!(failures[0].proof.range.start < failures[1].proof.range.start);
            assert_eq!(failures[0].proof, failures[2].proof);
            assert_eq!(failures[1].proof, failures[3].proof);
            let [one, three] = [BigInt::from(1), BigInt::from(3)];
            for failure in failures {
                assert_eq!(failure.cell.as_ref().unwrap().value, three);
                assert!(failure.witness.intervals_at(0, 0).unwrap().eq([(&one, &one)]));
                assert!(failure.witness.intervals_at(0, 1).unwrap().eq([(&three, &three)]));
            }
        }
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn array_proof_cohort_restricts_overlapping_rectangles_to_each_authored_guard() {
        use crate::scalar::checker_flow::take_array_return_observations;
        let text = r#"%%start
            u8[2](u8,u8) make = fn(key, value) { [value, key] };
            proof first for make(a, b) -> (items)
                where (a <= 6 && (b == 0 || b == 5))
                forall (u64 i where i == 0) ensures (items[i] <= 5) {}
            proof second for make(x, y) -> (items)
                where (x >= 3 && x <= 8 && (y == 5 || y == 9))
                ensures (exists (u64 i where i == 0) { items[i] >= 5 }) {}
            proof third for make(t, u) -> (items)
                where (t >= 3 && t <= 8 && (u == 5 || u == 9))
                forall (u64 i where i == 1) ensures (items[i] <= 8) {}
        %%end"#;
        let declared = ScalarCheckerScope::CurrentPackage;
        take_array_return_observations();
        let proved = check_array_proof_cohort(text, declared).unwrap();
        assert!(proved.active && proved.aggregate_diagnostics.is_empty());
        assert_eq!(take_array_return_observations(), (1, 0));

        // The proof sees the overlapping first axis, but a real counterexample
        // has to choose y=5, never y=0 from a sibling's guard.
        let refuted = check_array_proof_cohort(&text.replace("items[i] <= 8", "items[i] != 4"), declared).unwrap();
        assert_eq!(take_array_return_observations(), (1, 0));
        let [failure] = refuted.aggregate_diagnostics.as_slice() else { panic!("third proof only"); };
        let cell = failure.cell.as_ref().unwrap();
        assert_eq!((cell.index.clone(), cell.value.clone()), (BigInt::from(1), BigInt::from(4)));
        let [four, five] = [BigInt::from(4), BigInt::from(5)];
        assert!(failure.witness.intervals_at(0, 0).unwrap().eq([(&four, &four)]));
        assert!(failure.witness.intervals_at(0, 1).unwrap().eq([(&five, &five)]));
        assert!(failure.call.is_none());
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn array_proof_cohort_does_not_execute_unadmitted_cartesian_inputs() {
        use crate::scalar::checker_flow::take_array_return_observations;
        let text = r#"%%start
            u8[2](u8,u8) make = fn(tag, value) {
                if (tag == 0) { [value + 1, tag] } else { [value, tag] }
            };
            proof low for make(a,b) -> (items) where (a == 0 && b < 255)
                forall (u64 i where i == 0) ensures (items[i] >= 1) {}
            proof high for make(x,y) -> (items) where (x == 255 && y == 255)
                forall (u64 i where i == 0) ensures (items[i] == 255) {}
        %%end"#;
        let declared = ScalarCheckerScope::CurrentPackage;
        take_array_return_observations();
        let proved = check_array_proof_cohort(text, declared).unwrap();
        assert!(proved.active && proved.aggregate_diagnostics.is_empty());
        assert_eq!(take_array_return_observations(), (1, 0));
        // Make the previously impossible overflow genuinely applicable.
        assert!(matches!(check_array_proof_cohort(&text.replace("b < 255", "b <= 255"), declared),
            Err(ScalarOrderedCheckerOutcome::Unsupported)));

        let refuted = check_array_proof_cohort(&text.replace("items[i] == 255", "items[i] == 254"), declared).unwrap();
        let [failure] = refuted.aggregate_diagnostics.as_slice() else { panic!("high proof only"); };
        let max = BigInt::from(255);
        assert_eq!(failure.cell.as_ref().unwrap().value, max);
        for axis in 0..2 {
            assert!(failure.witness.intervals_at(0, axis).unwrap().eq([(&max, &max)]));
        }
        let main = check_array_proof_cohort(text, ScalarCheckerScope::MainFlowOnly).unwrap();
        assert!(!main.active && main.aggregate_diagnostics.is_empty());
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn boolean_return_proofs_keep_applicable_startup_invocations_and_other_typed_targets() {
        let text = format!(r#"%%start
            bool(bool) identity = fn(flag) {{ flag }};
            bool() always = fn {{ true }};
            u8[1]() make = fn {{ [7] }};
            proof wanted for identity(entry) -> (out) where (entry) ensures (out == true) {{}}
            proof from_nullary for always() -> (out) ensures (out) {{}}
            proof cells for make() -> (items) forall (u64 i where i == 0) ensures (items[i] == 7) {{}}
            bool first = identity(true);
            bool outside = identity(false);
            bool duplicate = identity(true);
            bool initialized = always();
            u8[1] data = make();
            u8 cell = data[0];
            core.require(first, {OUTPUT});
            core.require(duplicate, {OUTPUT});
            core.require(initialized, {OUTPUT});
            core.require(cell == 7, {OUTPUT});
        %%end"#);
        for scope in [ScalarCheckerScope::MainFlowOnly, ScalarCheckerScope::CurrentPackage] {
            let passed = check_array_proof_cohort(&text, scope).unwrap();
            assert!(passed.active && passed.diagnostics.is_empty() && passed.aggregate_diagnostics.is_empty());
            assert!(passed.directives.is_empty() && passed.symbolic_diagnostic.is_none());
            let outside = text.replace("%%end", &format!("core.require(outside, {OUTPUT}); %%end"));
            let checked_outside = check_array_proof_cohort(&outside, scope).unwrap();
            assert_eq!(checked_outside.directives.len(), 1);
            assert!(checked_outside.diagnostics.is_empty());
            let broken = text.replace("out == true", "out != true");
            let failed = check_array_proof_cohort(&broken, scope).unwrap();
            let [first, duplicate] = failed.diagnostics.as_slice() else { panic!("exactly two applicable calls"); };
            assert!(failed.directives.is_empty() && failed.symbolic_diagnostic.is_none());
            assert!(first.invocation.call.range.start < duplicate.invocation.call.range.start);
            for failure in [first, duplicate] {
                assert_eq!(failure.invocation.returned_literal, Some(ScalarCheckerProofLiteral::Boolean(true)));
                assert_eq!(failure.invocation.arguments, [(ScalarType::Bool, BigInt::from(1))]);
                let span = failure.invocation.call.range;
                assert_eq!(&broken[span.start as usize..span.end as usize], "identity(true)");
            }
        }
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn character_return_proofs_use_exact_startup_values_in_a_mixed_catalog() {
        use super::super::checker_flow::take_integer_observations;
        let text = r#"%%start
            char(char) identity = fn(letter) { letter };
            char() accent = fn { 'é' };
            bool() ready = fn { true };
            u8[1]() make = fn { [7] };
            proof crab for identity(entry) -> (out) where (entry == '🦀') ensures (out == '🦀') {}
            proof accented for accent() -> (out) ensures ('é' == out) {}
            proof readiness for ready() -> (out) ensures (out) {}
            proof cells for make() -> (items) forall (u64 i where i == 0) ensures (items[i] == 7) {}
            char prepared = '🦀';
            char first = identity(prepared);
            char outside = identity('β');
            char duplicate = identity(first);
            char marked = accent();
            bool yes = ready();
            u8[1] data = make();
        %%end"#;
        let bad = text.replace("out == '🦀'", "out != '🦀'");
        let _ = take_integer_observations();
        for scope in [ScalarCheckerScope::MainFlowOnly, ScalarCheckerScope::CurrentPackage] {
            let result = check_array_proof_cohort(text, scope).unwrap();
            assert_eq!(take_integer_observations(), (0, 5));
            assert!(result.active && result.directives.is_empty() && result.diagnostics.is_empty());
            assert!(result.aggregate_diagnostics.is_empty() && result.symbolic_diagnostic.is_none());

            let result = check_array_proof_cohort(&bad, scope).unwrap();
            assert_eq!(take_integer_observations(), (0, 5));
            let [first, duplicate] = result.diagnostics.as_slice() else { panic!("two reached calls inside the proof guard"); };
            assert!(result.aggregate_diagnostics.is_empty() && result.symbolic_diagnostic.is_none());
            for (failure, call) in [(first, "identity(prepared)"), (duplicate, "identity(first)")] {
                assert_eq!(failure.invocation.returned_literal, Some(ScalarCheckerProofLiteral::Character('🦀')));
                assert_eq!(failure.invocation.arguments, [(ScalarType::Char, BigInt::from(u32::from('🦀')))]);
                let span = failure.invocation.call.range;
                assert_eq!(&bad[span.start as usize..span.end as usize], call);
            }
        }
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn joint_result_proofs_keep_correlated_mixed_outputs_and_actual_occurrences() {
        use super::super::checker_flow::take_integer_observations;
        let base = r#"%%start
            (u8, bool)(u8) measured = fn(value) {
                bool accepted = if (value <= 7) { true } else { false };
                value, accepted
            };
            proof agreement for measured(entry) -> (size, ok) where (entry == 3 || entry == 9)
                ensures ((ok && size <= 7) || (!ok && size > 7))
                { core.show(!ok || size <= 7); }
        %%end"#;
        let bad = base.replace("core.show(!ok || size <= 7)", "core.show(!ok || size <= 2)");
        let scope = ScalarCheckerScope::CurrentPackage;
        let expected = [(BigInt::from(3), None), (BigInt::from(1), Some(ScalarCheckerProofLiteral::Boolean(true)))];

        let _ = take_integer_observations();
        let good = check_array_proof_cohort(base, scope).unwrap();
        assert!(good.active && good.symbolic_diagnostic.is_none());
        assert_eq!(take_integer_observations(), (1, 0));
        let bad_symbolic = check_array_proof_cohort(&bad, scope).unwrap();
        assert_eq!(take_integer_observations(), (1, 0));
        assert!(bad_symbolic.additional_symbolic_diagnostics.is_empty());
        let failure = bad_symbolic.symbolic_diagnostic.unwrap();
        assert!(failure.failed_step.is_some() && failure.other_output.is_some());
        assert_eq!(failure.returned_pair, Some(expected.clone()));
        let three = BigInt::from(3);
        assert!(failure.witness.intervals_at(0, 0).unwrap().eq([(&three, &three)]));

        let calls = r#"
            u8 one, bool allowed = measured(3);
            u8 other, bool rejected = measured(9);
            u8 again, bool repeated = measured(one);
            u8 outside, bool not_obligated = measured(2);
            %%end"#;
        for scope in [ScalarCheckerScope::MainFlowOnly, ScalarCheckerScope::CurrentPackage] {
            let good = check_array_proof_cohort(&base.replace("%%end", calls), scope).unwrap();
            assert!(good.active && good.diagnostics.is_empty() && good.symbolic_diagnostic.is_none());
            assert_eq!(take_integer_observations(), (0, 4));
            let source = bad.replace("%%end", calls);
            let failed = check_array_proof_cohort(&source, scope).unwrap();
            assert_eq!(take_integer_observations(), (0, 4));
            assert!(failed.symbolic_diagnostic.is_none());
            let [first, repeated] = failed.diagnostics.as_slice() else { panic!("two applicable real calls"); };
            for (failure, call) in [(first, "measured(3)"), (repeated, "measured(one)")] {
                assert!(failure.failed_step.is_some());
                assert_eq!(failure.invocation.returned_pair.as_ref(), Some(&expected));
                let span = failure.invocation.call.range;
                assert_eq!(&source[span.start as usize..span.end as usize], call);
            }
        }
    }

