    #[cfg(feature = "internal-checker")]
    #[test]
    fn mixed_array_catalog_publishes_one_startup_receipt_in_either_declaration_order() {
        use crate::scalar::checker_flow::take_array_return_observations;
        let scalar = "proof scalar_limited for scale(entry) -> (out) where (entry == 3) ensures (out == 3) {}";
        let array = "proof sample_claim for make(entry) -> (items) where (entry == 3)
            forall (u64 i where i == 0) ensures (items[i] == 3) {}";
        let program = |[first, second]: [&str; 2]| format!(r#"%%start
            u8(u8) scale = fn(value) {{ value }};
            u8[2](u8) make = fn(value) {{ [value, 7] }};
            {first}
            {second}
            u8 prepared = scale(3);
            u8[2] sampled = make(prepared);
            u8 checked = sampled[0];
            core.require(checked == 3, {{ .stdout = ""; .stderr = "printed once"; .code = 41;
                .files = [{{ .path = "once.txt"; .text = "one receipt"; }}]; }});
        %%end"#);
        for ordered in [[scalar, array], [array, scalar]] {
            let text = program(ordered);
            for scope in [ScalarCheckerScope::MainFlowOnly, ScalarCheckerScope::CurrentPackage] {
                take_array_return_observations();
                let passed = check_array_proof_cohort(&text, scope).unwrap();
                assert!(passed.active && passed.directives.is_empty() && passed.diagnostics.is_empty());
                assert!(passed.aggregate_diagnostics.is_empty() && passed.symbolic_diagnostic.is_none());
                assert_eq!(take_array_return_observations(), (0, 1));

                let broken = text.replace("ensures (out == 3)", "ensures (out == 4)")
                    .replace("ensures (items[i] == 3)", "ensures (items[i] == 4)")
                    .replace("checked == 3", "checked == 4");
                let failed = check_array_proof_cohort(&broken, scope).unwrap();
                assert_eq!(take_array_return_observations(), (0, 1));
                let [directive] = failed.directives.as_slice() else { panic!("one startup requirement result"); };
                assert_eq!(directive.stderr(), b"printed once");
                assert_eq!(*directive.code(), BigInt::from(41));
                let [file] = directive.files() else { panic!("one authored file in the same receipt"); };
                assert_eq!(file.text.as_ref(), b"one receipt");
                let [scalar] = failed.diagnostics.as_slice() else { panic!("one scalar proof failure"); };
                let [array] = failed.aggregate_diagnostics.as_slice() else { panic!("one array proof failure"); };
                let text_at = |span: &wosy_syntax::SourceSpan| &broken[span.range.start as usize..span.range.end as usize];
                assert_eq!(text_at(&scalar.invocation.call), "scale(3)");
                assert_eq!(text_at(array.call.as_ref().unwrap()), "make(prepared)");
                assert_eq!(scalar.invocation.returned, BigInt::from(3));
                assert_eq!(array.cell.as_ref().unwrap().value, BigInt::from(3));
                assert!(failed.symbolic_diagnostic.is_none() && failed.additional_symbolic_diagnostics.is_empty());
            }
        }
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn ordered_mixed_scalar_witnesses_distinguish_admission_from_predicate_failure() {
        use super::super::checker_flow::take_array_return_observations;
        let text = r#"%%start
            u8(u8) ordinary = fn(value) { value };
            u8(u8) dependent = fn(value) { value };
            u8[1]() make = fn { [7] };
            proof literal_choice for ordinary(entry) -> (out) where (entry >= 4 && entry <= 5)
                ensures (exists (u8 picked where picked >= 3 && picked <= 6) { out > picked && out <= 5 })
                { core.witness(3); }
            proof dependent_choice for dependent(entry) -> (out) where (entry >= 4 && entry <= 5)
                forall (u8 candidate where candidate == 2 || candidate == 4)
                forall (u8 forbidden where forbidden == 1 || forbidden == 7)
                ensures (exists (u8 selection where selection == 2 || selection == 4) { out >= selection && out != forbidden })
                { core.witness(candidate); }
            proof array_choice for make() -> (out)
                ensures (exists (u64 index where index == 0) { out[index] == 7 })
                { core.witness(0); }
        %%end"#;
        let run = |source, scope| check_array_proof_cohort(source, scope).unwrap();
        let package = ScalarCheckerScope::CurrentPackage;
        let _ = take_array_return_observations();
        let passed = run(text, package);
        assert!(passed.active && passed.directives.is_empty() && passed.diagnostics.is_empty()
            && passed.symbolic_diagnostic.is_none() && passed.aggregate_diagnostics.is_empty());
        assert_eq!(take_array_return_observations(), (1, 0));

        let failed_domains = text.replace("picked >= 3", "picked >= 4")
            .replace("selection == 2 || selection == 4", "selection == 2");
        let failed = run(&failed_domains, package);
        let first = failed.symbolic_diagnostic.unwrap();
        let [second] = failed.additional_symbolic_diagnostics.as_slice() else { panic!("two domain refutations"); };
        for (failure, expected) in [(&first, "core.witness(3)"), (second, "core.witness(candidate)")] {
            let step = failure.failed_step.as_ref().unwrap().range;
            assert_eq!(&failed_domains[step.start as usize..step.end as usize], expected);
            assert_eq!(failure.returned, BigInt::from(4));
        }
        assert!(first.proof.range.start < second.proof.range.start && failed.aggregate_diagnostics.is_empty());
        assert_eq!(take_array_return_observations(), (1, 0));

        let failed_predicates = text.replace("out > picked", "out < picked")
            .replace("out >= selection", "out > selection");
        let failed = run(&failed_predicates, package);
        let first = failed.symbolic_diagnostic.unwrap();
        let [second] = failed.additional_symbolic_diagnostics.as_slice() else { panic!("two false predicates"); };
        assert!(first.failed_step.is_none() && second.failed_step.is_none() && failed.aggregate_diagnostics.is_empty());
        assert_eq!(first.returned, BigInt::from(4));
        assert_eq!(second.returned, BigInt::from(4));
        assert_eq!(take_array_return_observations(), (1, 0));

        let main = ScalarCheckerScope::MainFlowOnly;
        let dormant = run(&failed_domains, main);
        assert!(!dormant.active && dormant.symbolic_diagnostic.is_none() && dormant.aggregate_diagnostics.is_empty());
        assert_eq!(take_array_return_observations(), (0, 0));
        let reached = failed_domains.replace("%%end", "u8 first = ordinary(4); u8 second = dependent(first); u8[1] cells = make(); %%end");
        let report = run(&reached, main);
        assert!(report.symbolic_diagnostic.is_none() && report.aggregate_diagnostics.is_empty());
        let [first, second] = report.diagnostics.as_slice() else { panic!("two actual owner activation failures"); };
        assert_ne!(first.invocation.call, second.invocation.call);
        assert!(first.failed_step.is_some() && second.failed_step.is_some());
        assert!(first.invocation.returned == 4.into() && second.invocation.returned == 4.into());
        assert_eq!(take_array_return_observations(), (0, 1));
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn configured_inferred_monotone_existential_chooses_the_hardest_exact_axis() {
        let source = r#"%%start
            u8(u8) unsigned = fn(value) { value };
            i8(i8) signed = fn(value) { value };
            proof high for unsigned(entry) -> (out) where (entry == 4)
                forall (u8 seed where seed == 1 || seed == 3)
                ensures (exists (u8 chosen where (chosen == 2 || chosen == 4) && chosen > seed) { out == chosen }) {}
            proof low for signed(entry) -> (out) where (entry == -3)
                forall (i8 seed where seed == -2 || seed == 0)
                ensures (exists (i8 chosen where (chosen == -3 || chosen == -1) && !(seed <= chosen)) { out == chosen }) {}
        %%end"#;
        let package = ScalarCheckerScope::CurrentPackage;
        let main = ScalarCheckerScope::MainFlowOnly;
        let actual = |text: &str| text.replace("%%end", &format!(
            "u8 a = unsigned({}); i8 b = signed({}); %%end",
            if text.contains("entry == 2") { 2 } else { 4 },
            if text.contains("entry == -1") { -1 } else { -3 },
        ));
        let passed = check_array_proof_cohort(source, package).unwrap();
        assert!(passed.active && passed.symbolic_diagnostic.is_none());
        let passed = check_array_proof_cohort(&actual(source), main).unwrap();
        assert!(passed.active && passed.diagnostics.is_empty());
        for (text, returned, hardest) in [
            (source.replace("entry == 4", "entry == 2"), 2, 3),
            (source.replace("entry == -3", "entry == -1"), -1, -2),
            (source.replace("seed == 1 || seed == 3", "seed == 255"), 4, 255),
        ] {
            let dormant = check_array_proof_cohort(&text, main).unwrap();
            assert!(!dormant.active && dormant.diagnostics.is_empty());
            let failed = check_array_proof_cohort(&text, package).unwrap().symbolic_diagnostic.unwrap();
            let evidence = Some(("seed".into(), BigInt::from(hardest)));
            assert_eq!(failed.quantified_witness, evidence);
            assert_eq!(failed.returned, BigInt::from(returned));
            assert!(failed.failed_step.is_none());
            let report = check_array_proof_cohort(&actual(&text), main).unwrap();
            let [failed] = report.diagnostics.as_slice() else { panic!("one failing monotone existential"); };
            assert_eq!(failed.quantified_witness, evidence);
            assert_eq!(failed.invocation.returned, BigInt::from(returned));
            assert!(failed.failed_step.is_none());
        }
        let empty = source.replace("seed == 1 || seed == 3", "seed == 1 && seed == 3")
            .replace("chosen == 2 || chosen == 4", "chosen == 2 && chosen == 4");
        let vacuous = check_array_proof_cohort(&empty, package).unwrap();
        assert!(vacuous.active && vacuous.symbolic_diagnostic.is_none());
        for unsupported in [
            source.replace("chosen > seed", "chosen != seed"),
            source.replace("chosen > seed", "chosen == seed"),
            source.replace("&& chosen > seed", "|| chosen > seed"),
        ] {
            assert!(matches!(check_array_proof_cohort(&unsupported, package), Err(ScalarOrderedCheckerOutcome::Unsupported)));
        }
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn configured_dependent_existential_checks_relative_where_on_the_typed_axis() {
        let source = r#"%%start
            u8(u8) upward = fn(value) { value };
            i8(i8) downward = fn(value) { value };
            proof forward for upward(entry) -> (out) where (entry == 5)
                forall (u8 seed where seed == 1 || seed == 3)
                forall (u8 other where other == 0 || other == 7)
                ensures (exists (u8 chosen where seed < chosen && chosen <= 4) {
                    out > chosen && out != other
                })
                { core.witness(seed + 1); }
            proof reverse for downward(entry) -> (out) where (entry == 0)
                forall (i8 seed where seed == -1)
                ensures (exists (i8 chosen where !(chosen >= seed) && chosen >= -2) { out > chosen })
                { core.witness(seed - 1); }
        %%end"#;
        let package = ScalarCheckerScope::CurrentPackage;
        let main = ScalarCheckerScope::MainFlowOnly;
        let actual = |text: &str| text.replace("%%end", "u8 a = upward(5); i8 b = downward(0); %%end");
        let pass = check_array_proof_cohort(source, package).unwrap();
        assert!(pass.active && pass.symbolic_diagnostic.is_none());
        let pass = check_array_proof_cohort(&actual(source), main).unwrap();
        assert!(pass.active && pass.diagnostics.is_empty());
        let failure = source.replace("seed < chosen && chosen <= 4", "chosen == seed || chosen == 2");
        let dormant = check_array_proof_cohort(&failure, main).unwrap();
        assert!(!dormant.active && dormant.diagnostics.is_empty());
        let checked = check_array_proof_cohort(&failure, package).unwrap().symbolic_diagnostic.unwrap();
        assert_eq!(checked.quantified_witness, Some(("seed".into(), BigInt::from(3))));
        assert!(checked.failed_step.is_some());
        let reached = check_array_proof_cohort(&actual(&failure), main).unwrap();
        let [checked] = reached.diagnostics.as_slice() else { panic!("one reached relative guard admission"); };
        assert_eq!(checked.quantified_witness, Some(("seed".into(), BigInt::from(3))));
        assert!(checked.failed_step.is_some());
        let opposite = source.replace("!(chosen >= seed)", "chosen >= seed");
        let checked = check_array_proof_cohort(&opposite, package).unwrap().symbolic_diagnostic.unwrap();
        assert_eq!(checked.quantified_witness, Some(("seed".into(), BigInt::from(-1))));
        assert!(checked.failed_step.is_some());
        for rejected in [
            source.replace("seed < chosen", "other < chosen"),
            source.replace("seed < chosen", "entry < chosen"),
            source.replace("seed == 1 || seed == 3", "seed == 255"),
            source.replace("seed == -1", "seed == -128"),
        ] {
            assert!(matches!(check_array_proof_cohort(&rejected, package), Err(ScalarOrderedCheckerOutcome::Unsupported)));
        }
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn configured_inferred_scalar_existential_constructs_typed_witnesses() {
        use super::super::checker_flow::take_array_return_observations;
        let source = r#"%%start
            u8(u8) sparse = fn(value) { value };
            i8(i8) ordered = fn(value) { value };
            u8(u8) different = fn(value) { value };
            u8[1]() make = fn { [7] };
            proof membership for sparse(entry) -> (out) where (entry == 4)
                ensures (exists (u8 chosen where chosen == 4 || chosen == 6) { out == chosen && out <= 6 }) {}
            proof order for ordered(entry) -> (out) where (entry == -2)
                ensures (exists (i8 chosen where chosen == -4 || chosen == -1) { out < chosen }) {}
            proof distinct for different(entry) -> (out) where (entry == 7)
                ensures (exists (u8 chosen where chosen == 7 || chosen == 9) { out != chosen }) {}
            proof cell for make() -> (out)
                ensures (exists (u64 index where index == 0) { out[index] == 7 }) {}
        %%end"#;
        let package = ScalarCheckerScope::CurrentPackage;
        let main = ScalarCheckerScope::MainFlowOnly;
        let actual = |text: &str| text.replace("%%end", &format!(
            "u8 a = sparse({}); i8 b = ordered(-2); u8 c = different(7); u8[1] cells = make(); %%end",
            if text.contains("entry == 5") { 5 } else { 4 },
        ));
        let _ = take_array_return_observations();
        let pass = check_array_proof_cohort(source, package).unwrap();
        assert!(pass.active && pass.symbolic_diagnostic.is_none() && pass.aggregate_diagnostics.is_empty());
        assert_eq!(take_array_return_observations(), (1, 0));
        let pass = check_array_proof_cohort(&actual(source), main).unwrap();
        assert!(pass.active && pass.diagnostics.is_empty() && pass.aggregate_diagnostics.is_empty());
        assert_eq!(take_array_return_observations(), (0, 1));

        for (text, returned) in [
            (source.replace("entry == 4", "entry == 5"), 5),
            (source.replace("chosen == -1", "chosen == -2"), -2),
            (source.replace("chosen == 7 || chosen == 9", "chosen == 7"), 7),
            (source.replace("chosen == 7 || chosen == 9", "chosen == 7 && chosen == 9"), 7),
        ] {
            let dormant = check_array_proof_cohort(&text, main).unwrap();
            assert!(!dormant.active && dormant.diagnostics.is_empty());
            assert_eq!(take_array_return_observations(), (0, 0));
            let symbolic = check_array_proof_cohort(&text, package).unwrap();
            assert!(symbolic.aggregate_diagnostics.is_empty());
            let failed = symbolic.symbolic_diagnostic.unwrap();
            assert_eq!(failed.returned, BigInt::from(returned));
            assert!(failed.failed_step.is_none() && failed.quantified_witness.is_none());
            assert!(text[failed.goal.range.start as usize..failed.goal.range.end as usize].starts_with("exists"));
            assert_eq!(take_array_return_observations(), (1, 0));
            let observed = check_array_proof_cohort(&actual(&text), main).unwrap();
            let [failure] = observed.diagnostics.as_slice() else { panic!("one failed actual choice"); };
            assert_eq!(failure.invocation.returned, BigInt::from(returned));
            assert!(failure.failed_step.is_none() && failure.quantified_witness.is_none() && observed.aggregate_diagnostics.is_empty());
            assert_eq!(take_array_return_observations(), (0, 1));
        }
        let independent = source.replace("out != chosen", "out == 7");
        assert!(check_array_proof_cohort(&independent, package).unwrap().symbolic_diagnostic.is_none());
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn configured_quantified_sparse_refutation_selects_a_real_original_coordinate() {
        let source = r#"%%start
            u8(u8) checked = fn(value) { value };
            proof sparse for checked(entry) -> (out) where (entry == 6)
                forall (u8 seed where seed == 1 || seed == 3)
                forall (u8 other where other == 5 || other == 7)
                ensures (exists (u8 candidate where candidate == 2 || candidate == 4) {
                    out != seed && out != candidate && out != other && out < 8
                })
                { core.witness(seed + 1); }
        %%end"#;
        let package = ScalarCheckerScope::CurrentPackage;
        let main = ScalarCheckerScope::MainFlowOnly;
        let actual = |text: &str, n| text.replace("%%end", &format!("u8 first = checked({n}); u8 second = checked({n}); %%end"));
        let pass = check_array_proof_cohort(source, package).unwrap();
        assert!(pass.active && pass.symbolic_diagnostic.is_none());
        for (returned, origin) in [(3, Some(("seed", 3))), (4, Some(("seed", 3))), (7, Some(("other", 7))), (8, None)] {
            let input = source.replace("entry == 6", &format!("entry == {returned}"));
            let expected = origin.map(|(name, original)| (name.to_owned(), BigInt::from(original)));
            let failed = check_array_proof_cohort(&input, package).unwrap().symbolic_diagnostic.unwrap();
            assert_eq!(failed.returned, BigInt::from(returned));
            assert_eq!(failed.quantified_witness, expected);
            assert!(failed.failed_step.is_none());
            let reached = check_array_proof_cohort(&actual(&input, returned), main).unwrap();
            let [first, second] = reached.diagnostics.as_slice() else { panic!("two distinct reaching occurrences"); };
            assert_ne!(first.invocation.call, second.invocation.call);
            for failure in [first, second] {
                assert_eq!(failure.quantified_witness, expected);
                assert_eq!(failure.invocation.returned, BigInt::from(returned));
                assert!(failure.failed_step.is_none());
            }
        }
        let solo = source.replace("entry == 6", "entry == 4")
            .replace("                forall (u8 other where other == 5 || other == 7)
", "")
            .replace("out != seed && out != candidate && out != other && out < 8", "out != candidate");
        let failed = check_array_proof_cohort(&solo, package).unwrap().symbolic_diagnostic.unwrap();
        assert_eq!(failed.quantified_witness, Some(("seed".into(), BigInt::from(3))));
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn configured_paired_formal_witness_retains_a_real_return_and_entry_pair() {
        let source = r#"%%start
            u8(u8, u8) pick = fn(seed_value, returned) {
                if (seed_value >= 4) { returned } else { returned }
            };
            proof relation for pick(seed, value) -> (out)
                where (seed >= 4 && seed <= 6 && (value == 4 || value == 6))
                ensures (exists (u8 candidate where candidate >= 5 && candidate <= 7) { out != candidate })
                { core.witness(seed + 1); }
        %%end"#;
        let package = ScalarCheckerScope::CurrentPackage;
        let main = ScalarCheckerScope::MainFlowOnly;
        let actual = |text: &str| text.replace("%%end", "u8 reached = pick(5, 6); %%end");
        let good = source.replace("out != candidate", "out <= candidate").replace("value == 4 || value == 6", "value == 4");
        let symbolic = check_array_proof_cohort(&good, package).unwrap();
        assert!(symbolic.active && symbolic.symbolic_diagnostic.is_none());
        let reached = check_array_proof_cohort(&actual(&good).replace("pick(5, 6)", "pick(5, 4)"), main).unwrap();
        assert!(reached.active && reached.diagnostics.is_empty());
        let rejected = check_array_proof_cohort(source, package).unwrap().symbolic_diagnostic.unwrap();
        assert_eq!(rejected.returned, BigInt::from(6));
        assert!(rejected.failed_step.is_none());
        for (axis, point) in [5, 6].into_iter().enumerate() {
            let mut intervals = rejected.witness.intervals_at(0, axis).unwrap();
            let point = BigInt::from(point);
            assert_eq!(intervals.next(), Some((&point, &point)));
            assert!(intervals.next().is_none());
        }
        let sparse_seed = source.replace("seed >= 4 && seed <= 6", "(seed == 4 || seed == 6)")
            .replace("(value == 4 || value == 6)", "value == 6");
        let disjoint = check_array_proof_cohort(&sparse_seed, package).unwrap();
        assert!(disjoint.active && disjoint.symbolic_diagnostic.is_none());
        let rejected = source.replace("seed >= 4 && seed <= 6", "(seed == 4 || seed == 6)");
        assert!(matches!(check_array_proof_cohort(&rejected, package), Err(ScalarOrderedCheckerOutcome::Unsupported)));
        let bad = actual(source);
        let report = check_array_proof_cohort(&bad, main).unwrap();
        let [failure] = report.diagnostics.as_slice() else { panic!("one exact independently projected pair"); };
        assert_eq!(failure.invocation.arguments.iter().map(|(_, n)| n.clone()).collect::<Vec<_>>(), [BigInt::from(5), BigInt::from(6)]);
        assert_eq!(failure.invocation.returned, BigInt::from(6));
        assert!(failure.failed_step.is_none());
        let hole = source.replace("candidate >= 5 && candidate <= 7", "candidate == 5 || candidate == 7")
            .replace("out != candidate", "out <= candidate").replace("value == 4 || value == 6", "value == 4");
        let rejected = check_array_proof_cohort(&hole, package).unwrap().symbolic_diagnostic.unwrap();
        assert_eq!(rejected.returned, BigInt::from(4));
        assert!(rejected.failed_step.is_some());
        let same_axis = source.replace("if (seed_value >= 4) { returned } else { returned }",
            "if (returned <= 8) { seed_value } else { seed_value }").replace("out != candidate", "out < candidate");
        let same_axis = check_array_proof_cohort(&same_axis, package).unwrap();
        assert!(same_axis.active && same_axis.symbolic_diagnostic.is_none());
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn configured_affine_formal_witness_projects_and_inverts_one_entry_row() {
        let source = r#"%%start
            u8(u8) upward = fn(value) { value };
            i8(i8) downward = fn(value) { if (value <= 0) { -2 } else { -2 } };
            proof plus for upward(entry) -> (out) where (entry >= 4 && entry <= 6)
                ensures (exists (u8 picked where picked >= 5 && picked <= 7) { out < picked && out <= 6 })
                { core.witness(entry + 1); }
            proof minus for downward(entry) -> (out) where (entry >= -2 && entry <= 0)
                ensures (exists (i8 picked where picked >= -3 && picked <= -1) { out != picked })
                { core.witness(entry - 1); }
        %%end"#;
        let package = ScalarCheckerScope::CurrentPackage;
        let main = ScalarCheckerScope::MainFlowOnly;
        let actual = |text: &str| text.replace("%%end", "u8 first = upward(5); i8 second = downward(-1); %%end");
        let pass = source.replace("out != picked", "out >= picked").replace("entry <= 0", "entry <= -1");
        let good = check_array_proof_cohort(&pass, package).unwrap();
        assert!(good.active && good.symbolic_diagnostic.is_none());
        let good = check_array_proof_cohort(&actual(&pass), main).unwrap();
        assert!(good.active && good.diagnostics.is_empty());
        let hole = pass.replace("picked >= 5 && picked <= 7", "picked == 5 || picked == 7");
        let symbolic = check_array_proof_cohort(&hole, package).unwrap().symbolic_diagnostic.unwrap();
        assert_eq!(symbolic.returned, BigInt::from(5));
        let step = symbolic.failed_step.unwrap().range;
        assert_eq!(&hole[step.start as usize..step.end as usize], "core.witness(entry + 1)");
        let reached = check_array_proof_cohort(&actual(&hole), main).unwrap();
        let [failure] = reached.diagnostics.as_slice() else { panic!("one real sparse admission failure"); };
        assert_eq!(failure.invocation.arguments[0].1, BigInt::from(5));
        assert!(failure.failed_step.is_some());
        let symbolic = check_array_proof_cohort(source, package).unwrap().symbolic_diagnostic.unwrap();
        assert_eq!(symbolic.returned, BigInt::from(-2));
        assert!(symbolic.failed_step.is_none());
        let reached = check_array_proof_cohort(&actual(source), main).unwrap();
        let [failure] = reached.diagnostics.as_slice() else { panic!("one real relational failure"); };
        assert_eq!(failure.invocation.arguments[0].1, BigInt::from(-1));
        assert_eq!(failure.invocation.returned, BigInt::from(-2));
        assert!(failure.failed_step.is_none());
        for overflow in [
            pass.replace("entry >= 4 && entry <= 6", "entry == 255"),
            pass.replace("entry >= -2 && entry <= -1", "entry == -128"),
        ] {
            assert!(matches!(check_array_proof_cohort(&overflow, package), Err(ScalarOrderedCheckerOutcome::Unsupported)));
        }
    }

