    #[test]
    fn configured_quantifier_products_distinguish_vacuity_and_authored_admission() {
        let source = r#"%%start
            u8(u8) check = fn(value) { value };
            proof witness for check(input) -> (out) where (input == 5)
                forall (u8 seed where seed == 1 || seed == 3)
                forall (u8 unrelated where unrelated == 0 || unrelated == 7)
                ensures (exists (u8 picked where picked == 2 || picked == 4) {
                    out > picked && out != unrelated
                })
                { core.witness(seed + 1); }
        %%end"#;
        let package = ScalarCheckerScope::CurrentPackage;
        let main = ScalarCheckerScope::MainFlowOnly;
        let actual = |text: &str| text.replace("%%end", "u8 reached = check(5); %%end");
        let without_second = |text: &str| text.replace("                forall (u8 unrelated where unrelated == 0 || unrelated == 7)
", "")
            .replace(" && out != unrelated", "");
        let empty_seed = source.replace("seed == 1 || seed == 3", "seed == 1 && seed == 3")
            .replace("picked == 2 || picked == 4", "picked == 2 && picked == 4");
        let empty_companion = source.replace("seed == 1 || seed == 3", "seed == 255")
            .replace("unrelated == 0 || unrelated == 7", "unrelated == 0 && unrelated == 7");
        let empty_pure_universal = source.replace("unrelated == 0 || unrelated == 7", "unrelated == 0 && unrelated == 7")
            .replace("exists (u8 picked where picked == 2 || picked == 4) {", "")
            .replace("out > picked && out != unrelated", "out < seed && out != unrelated")
            .replace("                })
                { core.witness(seed + 1); }", "                ) {}");
        for valid in [&without_second(&empty_seed), &empty_seed, &empty_companion, &empty_pure_universal] {
            let symbolic = check_array_proof_cohort(valid, package).unwrap();
            assert!(symbolic.active && symbolic.symbolic_diagnostic.is_none());
            let reached = check_array_proof_cohort(&actual(valid), main).unwrap();
            assert!(reached.active && reached.diagnostics.is_empty());
        }
        assert!(matches!(check_array_proof_cohort(&empty_companion.replace("seed + 1", "seed * 1"), package),
            Err(ScalarOrderedCheckerOutcome::Unsupported)));
        let sparse = source.replace("picked == 2 || picked == 4", "picked == 2");
        let empty_exists = source.replace("picked == 2 || picked == 4", "picked == 2 && picked == 4");
        for (text, point) in [(&sparse, 3), (&without_second(&sparse), 3), (&empty_exists, 1)] {
            let symbolic = check_array_proof_cohort(text, package).unwrap().symbolic_diagnostic.unwrap();
            assert_eq!(symbolic.quantified_witness, Some(("seed".into(), BigInt::from(point))));
            assert!(symbolic.failed_step.is_some());
            let reached = check_array_proof_cohort(&actual(text), main).unwrap();
            let [failure] = reached.diagnostics.as_slice() else { panic!("one witness admission"); };
            assert_eq!(failure.quantified_witness, Some(("seed".into(), BigInt::from(point))));
            assert_eq!(failure.invocation.returned, BigInt::from(5));
            assert!(failure.failed_step.is_some());
        }
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn configured_formal_existential_witness_uses_one_typed_entry_and_result() {
        let source = r#"%%start
            u8(u8) alias = fn(value) { value };
            i8(i8) fixed = fn(value) { if (value <= 0) { -1 } else { -1 } };
            proof same for alias(entry) -> (out) where (entry >= 4 && entry <= 6)
                ensures (exists (u8 candidate where candidate >= 4 && candidate <= 6) { out == candidate && out <= 6 })
                { core.witness(entry); }
            proof signed for fixed(entry) -> (out) where (entry >= -2 && entry <= 0)
                ensures (exists (i8 candidate where candidate >= -2 && candidate <= 0) { out != candidate })
                { core.witness(entry); }
        %%end"#;
        let package = ScalarCheckerScope::CurrentPackage;
        let main = ScalarCheckerScope::MainFlowOnly;
        let alias_source = source.replace("out != candidate", "out >= candidate").replace("entry <= 0", "entry <= -1");
        let good = check_array_proof_cohort(&alias_source, package).unwrap();
        assert!(good.active && good.symbolic_diagnostic.is_none());
        let actual = |text: &str| text.replace("%%end", "u8 first = alias(5); u8 second = alias(5); i8 third = fixed(-1); %%end");
        let good = check_array_proof_cohort(&actual(&alias_source), main).unwrap();
        assert!(good.active && good.diagnostics.is_empty());
        let hole = alias_source.replace("candidate >= 4 && candidate <= 6", "candidate == 4 || candidate == 6");
        let symbolic = check_array_proof_cohort(&hole, package).unwrap().symbolic_diagnostic.unwrap();
        assert_eq!(symbolic.returned, BigInt::from(5));
        let step = symbolic.failed_step.unwrap().range;
        assert_eq!(&hole[step.start as usize..step.end as usize], "core.witness(entry)");
        let actual_hole = actual(&hole);
        let bad = check_array_proof_cohort(&actual_hole, main).unwrap();
        let [first, second] = bad.diagnostics.as_slice() else { panic!("one report per real call"); };
        assert_ne!(first.invocation.call, second.invocation.call);
        for failure in [first, second] {
            assert_eq!(failure.invocation.returned, BigInt::from(5));
            assert!(failure.failed_step.is_some());
        }
        let symbolic = check_array_proof_cohort(&source, package).unwrap().symbolic_diagnostic.unwrap();
        assert_eq!(symbolic.returned, BigInt::from(-1));
        assert!(symbolic.failed_step.is_none());
        let observed = check_array_proof_cohort(&actual(&source), main).unwrap();
        let [failure] = observed.diagnostics.as_slice() else { panic!("one actual signed predicate"); };
        assert_eq!(failure.invocation.returned, BigInt::from(-1));
        assert!(failure.failed_step.is_none());
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn ordered_scalar_repeated_quantifiers_keep_original_and_translated_rows_distinct() {
        let source = r#"%%start
            u8(u8) checked = fn(value) { value };
            proof distinct for checked(entry) -> (out) where (entry == 4)
                forall (u8 seed where seed == 1 || seed == 3)
                forall (u8 unrelated where unrelated == 0 || unrelated == 7)
                ensures (exists (u8 candidate where candidate == 2 || candidate == 4) {
                    out != seed && out >= candidate && out != unrelated
                })
                { core.witness(seed + 1); }
        %%end"#;
        let package = ScalarCheckerScope::CurrentPackage;
        let main = ScalarCheckerScope::MainFlowOnly;
        let actual = |text: &str| text.replace("%%end", "u8 reached = checked(4); %%end");
        let good = check_array_proof_cohort(source, package).unwrap();
        assert!(good.active && good.symbolic_diagnostic.is_none());
        let good = check_array_proof_cohort(&actual(source), main).unwrap();
        assert!(good.active && good.diagnostics.is_empty());
        let failures = [
            (source.replace("candidate == 2 || candidate == 4", "candidate == 2"), true),
            (source.replace("out >= candidate", "out != candidate"), false),
            (source.replace("out != seed &&", "out <= seed &&"), false),
            (source.replace("unrelated == 0", "unrelated == 4"), false),
        ];
        for (text, shift_domain) in failures {
            let dormant = check_array_proof_cohort(&text, main).unwrap();
            assert!(!dormant.active && dormant.diagnostics.is_empty());
            let symbolic = check_array_proof_cohort(&text, package).unwrap().symbolic_diagnostic.unwrap();
            assert_eq!(symbolic.returned, BigInt::from(4));
            let reached = actual(&text);
            let observed = check_array_proof_cohort(&reached, main).unwrap();
            let [failure] = observed.diagnostics.as_slice() else { panic!("one distinct typed output refutation"); };
            assert_eq!(failure.invocation.returned, BigInt::from(4));
            for (span, text) in [(symbolic.failed_step.as_ref(), text.as_str()), (failure.failed_step.as_ref(), reached.as_str())] {
                assert_eq!(span.is_some(), shift_domain);
                if let Some(span) = span {
                    assert_eq!(&text[span.range.start as usize..span.range.end as usize], "core.witness(seed + 1)");
                }
            }
        }
        let overflow = source.replace("seed == 3", "seed == 255");
        assert!(matches!(check_array_proof_cohort(&overflow, package), Err(ScalarOrderedCheckerOutcome::Unsupported)));
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn ordered_scalar_dependent_witness_translates_checked_typed_domains() {
        let source = r#"%%start
            u8(u8) positive = fn(value) { value };
            i8(i8) negative = fn(value) { value };
            proof plus for positive(entry) -> (out) where (entry == 5)
                forall (u8 seed where seed == 1 || seed == 3)
                ensures (exists (u8 candidate where candidate == 2 || candidate == 4) { out > candidate && out <= 5 })
                { core.witness(seed + 1); }
            proof minus for negative(entry) -> (out) where (entry == -1)
                forall (i8 seed where seed == 0)
                ensures (exists (i8 candidate where candidate == -1) { out == candidate })
                { core.witness(seed - 1); }
        %%end"#;
        let package = ScalarCheckerScope::CurrentPackage;
        let main = ScalarCheckerScope::MainFlowOnly;
        let actual = |text: &str| text.replace("%%end", "u8 check_plus = positive(5); i8 check_minus = negative(-1); %%end");
        let pass = check_array_proof_cohort(source, package).unwrap();
        assert!(pass.active && pass.symbolic_diagnostic.is_none() && pass.additional_symbolic_diagnostics.is_empty());
        let pass = check_array_proof_cohort(&actual(source), main).unwrap();
        assert!(pass.active && pass.diagnostics.is_empty());
        let domain = source.replace("candidate == 2 || candidate == 4", "candidate == 2");
        let predicate = source.replace("out > candidate", "out < candidate");
        for (text, step) in [(&domain, true), (&predicate, false)] {
            let dormant = check_array_proof_cohort(text, main).unwrap();
            assert!(!dormant.active && dormant.diagnostics.is_empty());
            let symbolic = check_array_proof_cohort(text, package).unwrap().symbolic_diagnostic.unwrap();
            assert_eq!(symbolic.returned, BigInt::from(5));
            let reached = actual(text);
            let active = check_array_proof_cohort(&reached, main).unwrap();
            let [failure] = active.diagnostics.as_slice() else { panic!("one actual translated witness obligation"); };
            assert_eq!(failure.invocation.returned, BigInt::from(5));
            for (span, text) in [(symbolic.failed_step.as_ref(), text.as_str()), (failure.failed_step.as_ref(), reached.as_str())] {
                assert_eq!(span.is_some(), step);
                if let Some(span) = span {
                    assert_eq!(&text[span.range.start as usize..span.range.end as usize], "core.witness(seed + 1)");
                }
            }
        }
        for excluded in [
            source.replace("seed == 1 || seed == 3", "seed == 255"),
            source.replace("seed == 0", "seed == -128"),
            source.replace("seed + 1", "seed * 1"),
        ] {
            assert!(matches!(check_array_proof_cohort(&excluded, package), Err(ScalarOrderedCheckerOutcome::Unsupported)));
        }
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn mixed_catalog_uses_quantified_scalar_domains_with_one_ordered_execution() {
        use super::super::checker_flow::{take_array_return_observations, take_integer_observations};
        let text = r#"%%start
            u8(u8) band = fn(value) { value };
            u8[1]() make = fn { [7] };
            u8(u8) scheduled = fn(value) { value };
            proof interval for band(entry) -> (out) where (entry >= 3 && entry <= 5)
                forall (u8 floor where floor <= 2)
                forall (u8 omitted where omitted == 2 || omitted == 6)
                ensures (out >= floor && out != omitted) {}
            proof cell for make() -> (items)
                forall (u64 i where i == 0) ensures (items[i] == 7) {}
            proof later for scheduled(entry) -> (out) where (entry >= 3 && entry <= 5)
                forall (u8 excluded where excluded == 2 || excluded == 6)
                ensures (out != excluded) {}
        %%end"#;
        let scope = ScalarCheckerScope::CurrentPackage;
        let _ = take_integer_observations();
        let _ = take_array_return_observations();
        let good = check_array_proof_cohort(text, scope).unwrap();
        assert!(good.active && good.directives.is_empty() && good.symbolic_diagnostic.is_none()
            && good.additional_symbolic_diagnostics.is_empty() && good.aggregate_diagnostics.is_empty());
        assert_eq!(take_array_return_observations(), (1, 0));
        let wrong = text.replace("omitted == 6", "omitted == 4").replace("excluded == 6", "excluded == 5")
            .replace("items[i] == 7", "items[i] == 8");
        let invalid = check_array_proof_cohort(&wrong, scope).unwrap();
        let first = invalid.symbolic_diagnostic.unwrap();
        let [second] = invalid.additional_symbolic_diagnostics.as_slice() else { panic!("two differently owned scalar goals"); };
        assert!(first.proof.range.start < second.proof.range.start && invalid.directives.is_empty());
        for (failure, expected) in [(&first, 4), (second, 5)] {
            let point = BigInt::from(expected);
            assert_eq!(failure.returned, point);
            assert!(failure.witness.intervals_at(0, 0).unwrap().eq([(&point, &point)]));
        }
        let [array] = invalid.aggregate_diagnostics.as_slice() else { panic!("one array goal"); };
        assert_eq!(array.cell.as_ref().unwrap().value, BigInt::from(7));
        assert_eq!(take_array_return_observations(), (1, 0));
        let idle = check_array_proof_cohort(&wrong, ScalarCheckerScope::MainFlowOnly).unwrap();
        assert!(!idle.active && idle.symbolic_diagnostic.is_none() && idle.aggregate_diagnostics.is_empty());
        assert_eq!(take_array_return_observations(), (0, 0));

        let observed = wrong.replace("%%end", "u8 first = band(4); u8 second = band(first); u8[1] values = make(); %%end");
        let _ = take_integer_observations();
        let receipt = check_array_proof_cohort(&observed, ScalarCheckerScope::MainFlowOnly).unwrap();
        assert!(receipt.symbolic_diagnostic.is_none() && receipt.additional_symbolic_diagnostics.is_empty());
        let [first, second] = receipt.diagnostics.as_slice() else { panic!("two actual fitted arguments, two actual goals"); };
        assert_ne!(first.invocation.call, second.invocation.call);
        assert!(first.invocation.returned == 4.into() && second.invocation.returned == 4.into());
        assert_eq!(take_array_return_observations(), (0, 1));
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn mixed_array_catalog_preserves_symbolic_citations_without_cross_kind_authority() {
        let text = r#"%%start
            u8[2](u8) make = fn(value) { [value, 7] };
            i8(i8) execute = fn(input) { if (input < 0) { -3 } else { 7 } };
            i8(i8) producer = fn(input) { i8 result = execute(input); result };
            proof combined for producer(arg) -> (out) where (arg >= 0) ensures (out == 7) {
                core.use(issued(arg)); core.show(out >= 7);
            }
            proof cells for make(entry) -> (items) where (entry == 3)
                forall (u64 i where i == 0) ensures (items[i] == 3) {}
            proof issued for producer(arg) -> (out) where (arg >= 0) ensures (out <= 7) {}
        %%end"#;
        let scope = ScalarCheckerScope::CurrentPackage;
        let passed = check_array_proof_cohort(text, scope).unwrap();
        assert!(passed.active && passed.symbolic_diagnostic.is_none() && passed.aggregate_diagnostics.is_empty());
        let broken = text.replace("ensures (out == 7)", "ensures (out == 6)")
            .replace("items[i] == 3", "items[i] == 4");
        let failed = check_array_proof_cohort(&broken, scope).unwrap();
        assert!(failed.diagnostics.is_empty() && failed.directives.is_empty());
        let scalar = failed.symbolic_diagnostic.unwrap();
        assert_eq!(scalar.returned, BigInt::from(7));
        assert!(scalar.failed_step.is_none());
        let [array] = failed.aggregate_diagnostics.as_slice() else { panic!("one symbolic array proof failure"); };
        assert!(array.call.is_none());
        assert_eq!(array.cell.as_ref().unwrap().value, BigInt::from(3));
        let main = check_array_proof_cohort(&broken, ScalarCheckerScope::MainFlowOnly).unwrap();
        assert!(!main.active && main.symbolic_diagnostic.is_none() && main.aggregate_diagnostics.is_empty());

        // Even an array proof with the same typed explicit argument cannot
        // supply a scalar proof conclusion through the ordered citation lane.
        let cross_kind = text.replace("u8[2](u8)", "i8[2](i8)")
            .replace("core.use(issued(arg))", "core.use(cells(arg))");
        assert!(matches!(check_array_proof_cohort(&cross_kind, scope), Err(ScalarOrderedCheckerOutcome::Unsupported)));
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn mixed_array_catalog_preserves_ranked_authority_at_actual_and_unused_roots() {
        let program = |extra_scalar: &str| format!(r#"%%start
            u8(u8) descend = fn(value) {{ if (value < 3) {{ 4 }} else {{ descend(value - 3) }} }};
            u8[2](u8) make = fn(value) {{ [value, 7] }};
            u8(u8) leaf = fn(value) {{ value }};
            proof cells for make(entry) -> (items) where (entry == 4)
                ensures (exists (u64 i where i < 2) {{ items[i] == 7 }}) {{ core.witness(1); }}
            proof rank for descend(entry) -> (out) where (entry <= 8) ensures (out == 4) decreases (entry) {{
                if (entry < 3) {{ core.show(out == 4); }} else {{ core.use(rank(entry - 3)); }}
            }}
            {extra_scalar}
        %%end"#);
        for bare in ["", "proof copied for leaf(entry) -> (out) where (entry == 4) ensures (out == 4) {}"] {
            let text = program(bare);
            let actual = text.replace("%%end", &format!(r#"
                u8 descended = descend(8);
                u8 prepared = leaf(descended);
                u8[2] grouped = make(prepared);
                u8 checked = grouped[0];
                core.require(checked == 4, {OUTPUT});
            %%end"#));
            for scope in [ScalarCheckerScope::MainFlowOnly, ScalarCheckerScope::CurrentPackage] {
                let reached = check_array_proof_cohort(&actual, scope).unwrap();
                assert!(reached.active && reached.directives.is_empty() && reached.diagnostics.is_empty());
                assert!(reached.aggregate_diagnostics.is_empty() && reached.symbolic_diagnostic.is_none());
                let outside = actual.replace("descend(8)", "descend(9)");
                assert!(matches!(check_array_proof_cohort(&outside, scope), Err(ScalarOrderedCheckerOutcome::Unsupported)));
            }
            let symbolic = text.replace("%%end", &format!(r#"
                unit(u8) client = fn(input) {{
                    core.narrow(input <= 8, {OUTPUT});
                    u8 result = descend(input);
                    core.require(result == 4, {OUTPUT});
                    core.require(result == 5, {OUTPUT});
                }};
            %%end"#));
            let checked = check_array_proof_cohort(&symbolic, ScalarCheckerScope::CurrentPackage).unwrap();
            assert!(checked.active && checked.symbolic_diagnostic.is_none() && checked.aggregate_diagnostics.is_empty());
            let [failure] = checked.directives.as_slice() else { panic!("ranked summary discharges only the true goal"); };
            assert_eq!(&symbolic[failure.condition.start as usize..failure.condition.end as usize], "result == 5");
        }
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn inferred_fixed_array_exists_uses_each_returns_correlated_cells() {
        let app = source("src/main.w", "inferred-fixed-array-exists");
        let direct = r#"%%start
            i8[3](i8) reflect = fn(value) { [value, 127, -1 - value] };
            proof covered for reflect(entry) -> (items)
                ensures (exists (u64 i where i == 0 || i == 2) { items[i] >= 0 })
            {}
        %%end"#;
        let captured = direct.replace("[value, 127, -1 - value]", r#"
            i8 inverse = -1 - value;
            i8[3] saved = [value, 127, inverse];
            i8[3] copied = saved;
            copied
        "#);
        let parse = |text: &str| crate::parse_proof_source(app.clone(), text.to_owned(), &[]).ok().unwrap().1;
        let run = |text: &str, scope| check_loaded_scalar_ordered_local_proof_contexts(
            Vec::new(), [(parse(text), Vec::new())], vec![app.clone()], inputs(), scope, Vec::new(),
        );
        let selected = |text: &str| check_loaded_scalar_module_proofs(
            &["covered"], Vec::new(), (parse(text), Vec::new()), vec![app.clone()], inputs(),
        ).unwrap();
        let scope = ScalarCheckerScope::CurrentPackage;
        for program in [direct, captured.as_str()] {
            let proved = run(program, scope).unwrap();
            assert!(proved.active && proved.aggregate_diagnostics.is_empty());
            assert_eq!(selected(program), [ScalarModuleProofOutcome::Proved]);
            let refuted = program.replace("items[i] >= 0", "items[i] > 0");
            let failure = run(&refuted, scope).unwrap().aggregate_diagnostics.pop().unwrap();
            assert!(failure.cell.is_none() && failure.failed_step.is_none());
            assert_eq!(failure.witness.row_count(), 1);
            assert_eq!(failure.witness.axes().len(), 1);
            let negative_one = BigInt::from(-1);
            // The array returned at -1 is [-1, 127, 0]; neither admitted cell is positive.
            assert!(failure.witness.intervals_at(0, 0).unwrap().eq([(&negative_one, &negative_one)]));
            assert_eq!(selected(&refuted), [ScalarModuleProofOutcome::Refuted]);
            let main = run(&refuted, ScalarCheckerScope::MainFlowOnly).unwrap();
            assert!(!main.active && main.aggregate_diagnostics.is_empty());
            // The cell at index 1 would mask the counterexample if the
            // quantified domain were treated as one contiguous interval.
            let all_cells = refuted.replace("i == 0 || i == 2", "i < 3");
            assert!(run(&all_cells, scope).unwrap().aggregate_diagnostics.is_empty());
        }

        let empty = direct.replace("i == 0 || i == 2", "i < 0");
        assert!(run(&empty, scope).unwrap().aggregate_diagnostics.pop().unwrap().cell.is_none());
        assert_eq!(selected(&empty), [ScalarModuleProofOutcome::Refuted]);
        let no_call = empty.replace("ensures (exists", "where (false) ensures (exists");
        let inactive = run(&no_call, scope).unwrap();
        assert!(!inactive.active && inactive.aggregate_diagnostics.is_empty());
        let out_of_range = direct.replace("i == 0 || i == 2", "i < 4");
        assert!(matches!(run(&out_of_range, scope), Err(ScalarOrderedCheckerOutcome::Unsupported)));
        let overflow = direct.replace("[value, 127, -1 - value]", "[7, 127, value + 1]")
            .replace("i == 0 || i == 2", "i == 0");
        assert!(matches!(run(&overflow, scope), Err(ScalarOrderedCheckerOutcome::Unsupported)),
            "a passing selected cell cannot mask an unmodeled returned calculation");
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn inferred_fixed_array_exists_checks_each_return_branch() {
        let app = source("src/main.w", "inferred-array-exists-branches");
        let program = r#"%%start
            i8[2](i8) choose = fn(value) {
                if (value < 0) { [value, 0] } else { [0, -1 - value] }
            };
            proof covered for choose(entry) -> (items)
                ensures (exists (u64 i where i < 2) { items[i] >= 0 })
            {}
        %%end"#;
        let run = |text: &str| {
            let (_, catalog) = crate::parse_proof_source(app.clone(), text.to_owned(), &[]).ok().unwrap();
            check_loaded_scalar_ordered_local_proof_contexts(Vec::new(), [(catalog, Vec::new())],
                vec![app.clone()], inputs(), ScalarCheckerScope::CurrentPackage, Vec::new())
        };
        assert!(run(program).unwrap().aggregate_diagnostics.is_empty());
        let wrong_arm = program.replace("[0, -1 - value]", "[-1, -1 - value]");
        let failure = run(&wrong_arm).unwrap().aggregate_diagnostics.pop().unwrap();
        assert!(failure.cell.is_none());
        let zero = BigInt::from(0);
        assert!(failure.witness.intervals_at(0, 0).unwrap().eq([(&zero, &zero)]));
        let returned = failure.output.range;
        assert_eq!(&wrong_arm[returned.start as usize..returned.end as usize], "[-1, -1 - value]");
    }

    #[cfg(feature = "internal-checker")]
