    #[cfg(feature = "internal-checker")]
    #[test]
    fn public_ordered_library_credit_proof_feeds_each_actual_downstream_requirement() {
        let app = source("src/main.w", "ordered-library-credit-root");
        let lib = source("src/credit.w", "ordered-library-credit-provider");
        let root = r#"%%start
            accounting = namespace app "src/credit.w";
            unit() entry = fn {
                u8 core.context.credit = 3;
                accounting.spend();
                core.require(core.context.credit == 2, { .stdout = ""; .stderr = "first debit"; .code = 71; .files = []; });
                if (true) {
                    u8 core.context.credit = 3;
                    accounting.spend();
                    core.require(core.context.credit == 2, { .stdout = ""; .stderr = "shadow debit"; .code = 72; .files = []; });
                };
                accounting.spend();
                core.require(core.context.credit == 1, { .stdout = ""; .stderr = "second debit"; .code = 73; .files = []; });
            };
            entry();
        %%end"#;
        let library = r#"%%start
            unit() consume = fn { core.context.credit = core.context.credit - 1; };
            unit() spend = fn { consume(); };
            proof debit for consume() -> (null)
                ensures (core.context.credit == core.old(core.context.credit) - 1) {}
        %%end"#;
        for target_layout in [ScalarTargetLayout::NATIVE64, ScalarTargetLayout::WASM32] {
            let run = |root: &str, library: &str, scope| {
                let (_, app_catalog) = crate::parse_proof_source(app.clone(), root.to_owned(), &[]).ok().unwrap();
                let (_, lib_catalog) = crate::parse_proof_source(lib.clone(), library.to_owned(), &[]).ok().unwrap();
                let import = ScalarNamespaceBinding { binding: "accounting".into(), target: lib.clone(), span: ByteSpan::new(0, 0) };
                check_loaded_scalar_ordered_local_proof_contexts(
                    Vec::new(), [(lib_catalog, Vec::new()), (app_catalog, vec![import])],
                    vec![app.clone(), lib.clone()], ScalarPreparationInputs { target_layout }, scope, Vec::new(),
                )
            };
            for scope in [ScalarCheckerScope::MainFlowOnly, ScalarCheckerScope::CurrentPackage] {
                let checked = run(root, library, scope).unwrap();
                assert!(checked.active && checked.directives.is_empty() && checked.contextual_diagnostic.is_none());
                let stale = root.replace("core.context.credit == 1", "core.context.credit == 2");
                let result = run(&stale, library, scope).unwrap();
                assert!(result.contextual_diagnostic.is_none());
                let [failed] = result.directives.as_slice() else { panic!("only the second ordinary debit obligation"); };
                assert_eq!(failed.code(), &BigInt::from(73));
                let condition = failed.condition;
                assert_eq!(failed.source, app);
                assert_eq!(&stale[condition.start as usize..condition.end as usize], "core.context.credit == 2");
                let unchanged = library.replace("credit = core.context.credit - 1;", "credit = core.context.credit - 0;");
                let false_proof = run(root, &unchanged, scope).unwrap();
                let failure = false_proof.contextual_diagnostic.unwrap();
                assert!(false_proof.directives.is_empty());
                assert_eq!((&failure.entry, &failure.exit), (&BigInt::from(3), &BigInt::from(3)));
                assert_eq!(&failure.call.source, &lib);
                // The same one-debit program succeeds at credit 1 and
                // refuses at credit 0; no concurrent shadow or later call
                // can account for this outcome.
                let one = root.split_once("                if (true)").unwrap().0
                    .replace("u8 core.context.credit = 3;", "u8 core.context.credit = 1;")
                    .replace("core.context.credit == 2", "core.context.credit == 0")
                    + "            }; entry(); %%end";
                let paid = run(&one, library, scope).unwrap();
                assert!(paid.active && paid.contextual_diagnostic.is_none() && paid.directives.is_empty());
                let overdrawn = one.replace("u8 core.context.credit = 1;", "u8 core.context.credit = 0;");
                assert!(matches!(run(&overdrawn, library, scope), Err(ScalarOrderedCheckerOutcome::Unsupported)));
            }
        }
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn public_ordered_unused_contextual_proof_observes_arbitrary_entry_and_exact_exit() {
        let app = source("src/main.w", "public-symbolic-contextual-proof");
        let text = r#"%%start
            unit() type_provider = fn {
                u8 core.context.credit = 3;
                if (core.context.credit == 3) {};
            };
            unit() unchanged = fn {
                if (core.context.credit == 3) { core.context.credit = 3; };
            };
            proof preserved for unchanged() -> (null)
                ensures (core.context.credit == core.old(core.context.credit) + 0) {}
        %%end"#;
        let run = |program: &str, scope| {
            let (_, proof) = crate::parse_proof_source(app.clone(), program.to_owned(), &[]).ok().unwrap();
            check_loaded_scalar_ordered_local_proof_contexts(Vec::new(), [(proof, Vec::new())],
                vec![app.clone()], inputs(), scope, Vec::new())
        };
        let passing = run(text, ScalarCheckerScope::CurrentPackage).unwrap();
        assert!(passing.active && passing.directives.is_empty() && passing.contextual_diagnostic.is_none());
        // A lexical declaration supplies the static type, not the symbolic
        // value. The counterexample starts at 11, away from its initializer.
        let false_proof = text.replace("credit == 3) { core.context.credit = 3", "credit == 11) { core.context.credit = 2");
        let rejected = run(&false_proof, ScalarCheckerScope::CurrentPackage).unwrap();
        assert!(rejected.active && rejected.directives.is_empty());
        let diagnostic = rejected.contextual_diagnostic.unwrap();
        assert!(diagnostic.symbolic);
        assert_eq!(diagnostic.call.source, app);
        assert_eq!(&false_proof[diagnostic.call.range.start as usize..diagnostic.call.range.end as usize], "unchanged");
        assert_eq!((diagnostic.entry, diagnostic.exit), (BigInt::from(11), BigInt::from(2)));
        let main = run(&false_proof, ScalarCheckerScope::MainFlowOnly).unwrap();
        assert!(!main.active && main.directives.is_empty() && main.contextual_diagnostic.is_none());
        for claim in ["+ 1", "- 1"] {
            let out_of_range = false_proof.replace("+ 0", claim);
            assert!(matches!(run(&out_of_range, ScalarCheckerScope::CurrentPackage),
                Err(ScalarOrderedCheckerOutcome::Unsupported)));
            assert!(!run(&out_of_range, ScalarCheckerScope::MainFlowOnly).unwrap().active);
        }
        let missing = false_proof.replace("%%end", "unchanged(); %%end");
        assert!(matches!(run(&missing, ScalarCheckerScope::CurrentPackage), Err(ScalarOrderedCheckerOutcome::Unsupported)));
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn private_guarded_context_keeps_proof_and_ordinary_domains_distinct() {
        use std::num::NonZeroUsize;
        let source = source("src/main.w", "private-guarded-context");
        let zero = OUTPUT.replace(".code = 1", ".code = 0");
        let later = OUTPUT.replace(".code = 1", ".code = 19");
        let program = format!(r#"%%start
            unit(u8) consume = fn(charged) {{
                if (charged == 1) {{ core.context.credit = core.context.credit - 1; }}
                else {{ core.context.credit = core.context.credit - 1; }};
            }};
            unit() entry = fn {{
                u8 core.context.credit = 3;
                consume(1);
                core.require(false, {zero});
                core.require(false, {later});
            }};
            proof debit for consume(cost) -> (null) where (cost <= 1)
                ensures (core.context.credit == core.old(core.context.credit) - 1) {{}}
            entry();
        %%end"#);
        for layout in [ScalarTargetLayout::NATIVE64, ScalarTargetLayout::WASM32] {
            for scope in [ScalarCheckerScope::CurrentPackage, ScalarCheckerScope::MainFlowOnly] {
                let prepare = |text: &str| {
                    let (_, parsed) = crate::parse_configured_proof_source(source.clone(), text.to_owned(), &[]).ok().unwrap();
                    prepare_loaded_scalar_ordered_local_proof_contexts(Vec::new(),
                        [(parsed, Vec::new())], vec![source.clone()], ScalarPreparationInputs { target_layout: layout },
                        scope, Vec::new()).ok().unwrap()
                };
                let unguarded = program.replace(" where (cost <= 1)", "");
                let ordinary = prepare(&unguarded).run().unwrap();
                assert!(matches!(prepare(&program).run(), Err(ScalarOrderedCheckerOutcome::Unsupported)));
                for cap in [1, 3] {
                    let (report, completion) = prepare(&program).search_startup_with_guarded_context(NonZeroUsize::new(cap).unwrap()).unwrap();
                    assert!(report.contextual_diagnostic.is_none());
                    assert_eq!(report.directives, ordinary.directives[..cap.min(2)]);
                    assert_eq!(completion, Some(if cap == 1 { StartupAuthoredCompletion::LimitReached } else { StartupAuthoredCompletion::Exhausted }));
                }
                let wrong = program.replace("credit = core.context.credit - 1", "credit = core.context.credit - 0");
                let (refuted, completion) = prepare(&wrong).search_startup_with_guarded_context(NonZeroUsize::MIN).unwrap();
                assert!(completion.is_none() && refuted.directives.is_empty());
                let proof = refuted.contextual_diagnostic.unwrap();
                assert_eq!((proof.entry, proof.exit), (3.into(), 3.into()));
                assert_eq!(proof.explicit_entry, Some(("cost".into(), 1.into())));
                assert_eq!(&wrong[proof.call.range.start as usize..proof.call.range.end as usize], "consume(1)");
                let outside = wrong.replace("consume(1)", "consume(2)");
                let (ordinary_only, completion) = prepare(&outside).search_startup_with_guarded_context(NonZeroUsize::MIN).unwrap();
                assert!(ordinary_only.contextual_diagnostic.is_none());
                assert_eq!(completion, Some(StartupAuthoredCompletion::LimitReached));
                assert_eq!(ordinary_only.directives.len(), 1);
                assert_eq!(ordinary_only.directives[0].code(), &BigInt::from(0));
                let prefix = format!("core.require(false, {zero}); core.require(false, {later});");
                let after_cap = program.replace("consume(1);", &format!("{prefix} consume(1);"));
                let top_level_cap = program.replace("entry();", &format!("{prefix} entry();"));
                let opaque = program.replace("entry();", &format!(
                    "core.require(false, {zero}); core.require(false || true, {later}); entry();"));
                assert!(matches!(prepare(&opaque).search_startup_with_guarded_context(NonZeroUsize::MIN),
                    Err(ScalarOrderedCheckerOutcome::Unsupported)));
                for crossed in [after_cap, top_level_cap] {
                    let (selected, completion) = prepare(&crossed).search_startup_with_guarded_context(NonZeroUsize::MIN).unwrap();
                    assert!(selected.contextual_diagnostic.is_none());
                    assert_eq!(completion, Some(StartupAuthoredCompletion::LimitReached));
                    assert_eq!(selected.directives.len(), 1);
                    assert_eq!(selected.directives[0].code(), &BigInt::from(0));
                    let failed = crossed.replace("credit = core.context.credit - 1", "credit = core.context.credit - 0");
                    let (selected, completion) = prepare(&failed).search_startup_with_guarded_context(NonZeroUsize::MIN).unwrap();
                    assert!(completion.is_none() && selected.directives.is_empty());
                    let evidence = selected.contextual_diagnostic.unwrap();
                    assert_eq!((evidence.entry, evidence.exit), (3.into(), 3.into()));
                    assert_eq!(&failed[evidence.call.range.start as usize..evidence.call.range.end as usize], "consume(1)");
                    let excluded = failed.replace("consume(1)", "consume(2)");
                    let (selected, completion) = prepare(&excluded).search_startup_with_guarded_context(NonZeroUsize::MIN).unwrap();
                    assert!(selected.contextual_diagnostic.is_none());
                    assert_eq!(completion, Some(StartupAuthoredCompletion::LimitReached));
                    assert_eq!(selected.directives.len(), 1);
                    let pruned = crossed.replace("consume(1);", &format!("core.narrow(false, {later}); consume(1);"));
                    assert!(matches!(prepare(&pruned).search_startup_with_guarded_context(NonZeroUsize::MIN),
                        Err(ScalarOrderedCheckerOutcome::Unsupported)));
                }
            }
        }
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn public_ordered_contextual_proof_uses_canonical_scopes_without_build_admission() {
        let app = source("src/main.w", "public-contextual-proof");
        let text = r#"%%start
            unit() consume = fn { core.context.credit = core.context.credit - 1; };
            unit() relay = fn { consume(); };
            unit() entry = fn {
                u8 core.context.credit = 3;
                relay();
                core.require(false, { .stdout = ""; .stderr = "ordinary entry effect"; .code = 76; .files = []; });
            };
            unit(u8) unused = fn(value) {
                core.require(value == 0, { .stdout = ""; .stderr = "ordinary symbolic effect"; .code = 77; .files = []; });
            };
            proof debit for consume() -> (null)
                ensures (core.context.credit == core.old(core.context.credit) - 1) {}
            entry();
        %%end"#;
        let run = |program: &str, scope| {
            let (_, proof) = crate::parse_proof_source(app.clone(), program.to_owned(), &[]).ok().unwrap();
            check_loaded_scalar_ordered_local_proof_contexts(Vec::new(), [(proof, Vec::new())],
                vec![app.clone()], inputs(), scope, Vec::new())
        };
        for (scope, expected) in [(ScalarCheckerScope::MainFlowOnly, vec![76]),
            (ScalarCheckerScope::CurrentPackage, vec![76, 77])]
        {
            let result = run(text, scope).unwrap();
            assert!(result.active && result.contextual_diagnostic.is_none());
            assert_eq!(result.directives.iter().map(|record| record.code().clone()).collect::<Vec<_>>(),
                expected.into_iter().map(BigInt::from).collect::<Vec<_>>());
            let false_proof = text.replace("credit = core.context.credit - 1", "credit = core.context.credit - 0");
            let refusal = run(&false_proof, scope).unwrap();
            let diagnostic = refusal.contextual_diagnostic.unwrap();
            assert!(refusal.directives.is_empty());
            assert_eq!((&diagnostic.entry, &diagnostic.exit), (&BigInt::from(3), &BigInt::from(3)));
            let snippet = |span: &wosy_syntax::SourceSpan| {
                assert_eq!(span.source, app);
                &false_proof[span.range.start as usize..span.range.end as usize]
            };
            assert_eq!(snippet(&diagnostic.call), "consume()");
            assert_eq!(snippet(&diagnostic.supplying_call), "relay()");
            assert_eq!(snippet(&diagnostic.binding).trim_end(), "core.context.credit");
        }
        let parsed = crate::parse_source(app.clone(), text.to_owned(), &[]);
        let build_source = super::super::derive_scalar_declarations_from_cst(parsed.result.canonical_cst());
        assert!(super::super::prepare_scalar_project(vec![(build_source, Vec::new())],
            vec![app.clone()], inputs()).is_err());
        let second_proof = text.replace("%%end", "proof ordinary for unused(value) -> (null) ensures (true) {} %%end");
        assert!(run(&second_proof, ScalarCheckerScope::CurrentPackage).is_err());
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn exact_contextual_summary_keys_repeated_ordinary_arguments_and_shadowed_binding() {
        let app = source("src/main.w", "explicit-contextual-summary-occurrence");
        let text = r#"%%start
            unit(u8) debit = fn(charged) { core.context.credit = core.context.credit - charged; };
            unit(u8) relay = fn(cost) { debit(cost); };
            unit() entry = fn {
                u8 core.context.credit = 7;
                relay(2);
                core.require(core.context.credit == 5, { .stdout = ""; .stderr = "first"; .code = 91; .files = []; });
                core.context.credit = 7;
                relay(2);
                core.require(core.context.credit == 5, { .stdout = ""; .stderr = "repeated"; .code = 92; .files = []; });
                core.context.credit = 7;
                relay(3);
                core.require(core.context.credit == 4, { .stdout = ""; .stderr = "changed"; .code = 93; .files = []; });
                if (true) {
                    u8 core.context.credit = 7;
                    relay(2);
                    core.require(core.context.credit == 5, { .stdout = ""; .stderr = "shadowed"; .code = 94; .files = []; });
                };
                core.require(core.context.credit == 4, { .stdout = ""; .stderr = "restored"; .code = 95; .files = []; });
            };
            proof spend for debit(cost) -> (null)
                ensures (core.context.credit == core.old(core.context.credit) - cost) {}
            entry();
        %%end"#;
        for target_layout in [ScalarTargetLayout::NATIVE64, ScalarTargetLayout::WASM32] {
            let run = |program: &str, scope| {
                let (_, source) = crate::parse_configured_root_proof_source(app.clone(), program.to_owned(), &[]).ok().unwrap();
                let headers = source.contextual_proofs.into_iter().map(|header| (app.clone(), header)).collect();
                check_prepared_contextual_proofs(vec![(source.declarations, Vec::new())], vec![app.clone()],
                    headers, ScalarPreparationInputs { target_layout }, scope, true).unwrap()
            };
            for scope in [ScalarCheckerScope::MainFlowOnly, ScalarCheckerScope::CurrentPackage] {
                let valid = run(text, scope);
                assert!(valid.directives.is_empty());
                assert_eq!(valid.contextual_proofs.entries.len(), 1);
                let proof = valid.contextual_proofs.entries.values().next().unwrap();
                let [first, repeat, changed, shadowed] = proof.observations.as_slice() else { panic!("four concrete calls"); };
                assert!(!first.reused && repeat.reused && !changed.reused && !shadowed.reused);
                assert_eq!(first.call, repeat.call);
                assert_ne!(first.supplying_call, repeat.supplying_call);
                assert_eq!(first.binding, changed.binding);
                assert_ne!(first.binding, shadowed.binding);
                assert_eq!((repeat.entry.clone(), repeat.exit.clone()), (7.into(), 5.into()));
                assert_eq!(changed.explicit, Some(("cost".into(), 3.into())));
                assert_eq!((changed.entry.clone(), changed.exit.clone()), (7.into(), 4.into()));
                assert!(proof.verified.is_some() && proof.refutation.is_none());
                // Opposite arithmetic agrees with the theorem only at
                // zero cost. It first creates a valid receipt, then must
                // re-observe cost 3 and remove the receipt on refutation.
                let stale = text.replace("core.context.credit - charged", "core.context.credit + charged")
                    .replacen("relay(2)", "relay(0)", 2)
                    .replacen("core.context.credit == 5", "core.context.credit == 7", 2);
                let refuted = run(&stale, scope);
                assert_eq!(refuted.contextual_proofs.entries.len(), 1);
                let proof = refuted.contextual_proofs.entries.values().next().unwrap();
                assert!(proof.verified.is_none());
                let failure = proof.refutation.as_ref().unwrap();
                assert_eq!(failure.explicit, Some(("cost".into(), 3.into())));
                assert_eq!((failure.entry.clone(), failure.exit.clone()), (7.into(), 10.into()));
                assert_eq!(&stale[failure.supplying_call.start as usize..failure.supplying_call.end as usize], "relay(3)");
                assert_eq!(&stale[failure.call.start as usize..failure.call.end as usize], "debit(cost)");
            }
        }
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn exact_contextual_nested_proof_uses_old_from_the_same_call_and_binding() {
        let app = source("src/main.w", "checked-contextual-named-actual-proof");
        let text = r#"%%start
            unit() consume = fn { core.context.credit = core.context.credit - 1; };
            unit() relay = fn { consume(); };
            unit() entry = fn {
                u8 core.context.credit = 3;
                relay();
                core.require(false, { .stdout = ""; .stderr = "earlier private output"; .code = 70; .files = []; });
                if (true) {
                    u8 core.context.credit = 20;
                    relay();
                };
                relay();
                core.context.credit = 3;
                relay();
                core.require(core.context.credit == 2, { .stdout = ""; .stderr = ""; .code = 71; .files = []; });
                core.context.credit = 3;
                consume();
            };
            proof debit for consume() -> (null)
                ensures (core.context.credit == core.old(core.context.credit) - 1) {}
            entry();
        %%end"#;
        let run = |program: &str, target_layout| {
            let parsed = crate::parse_source(app.clone(), program.to_owned(), &[]);
            assert!(parsed.diagnostics.is_empty(), "{:?}", parsed.diagnostics);
            check_internal_contextual_proof(parsed.result.canonical_cst(), ScalarPreparationInputs { target_layout })
        };
        for layout in [ScalarTargetLayout::NATIVE64, ScalarTargetLayout::WASM32] {
            let (observations, directives) = run(text, layout).unwrap();
            let [outer, inner, restored, reused, different_site] = observations.as_slice()
                else { panic!("expected five source-ordered actual occurrences"); };
            let [effect] = directives.as_slice() else { panic!("one reached ordinary effect"); };
            assert_eq!(effect.code(), &BigInt::from(70));
            for (observation, (entry, exit)) in [outer, inner, restored].into_iter().zip([(3, 2), (20, 19), (2, 1)]) {
                assert_eq!((&observation.entry, &observation.exit), (&BigInt::from(entry), &BigInt::from(exit)));
                let text_at = |span: ByteSpan| &text[span.start as usize..span.end as usize];
                assert_eq!(text_at(observation.call), "consume()");
                assert_eq!(text_at(observation.supplying_call), "relay()");
            }
            assert_ne!(outer.binding, inner.binding);
            assert_eq!(outer.binding, restored.binding);
            assert_ne!(outer.supplying_call, restored.supplying_call);
            assert!(!outer.reused && !inner.reused && !restored.reused && reused.reused && !different_site.reused);
            assert_eq!((&reused.binding, &reused.entry, &reused.exit), (&outer.binding, &outer.entry, &outer.exit));
            assert_eq!(reused.call, outer.call);
            assert_ne!(reused.supplying_call, outer.supplying_call);
            assert_ne!(different_site.call, outer.call);
            assert_eq!(different_site.binding, outer.binding);
            let equal_shadow = text.replace("credit = 20;", "credit = 3;");
            let (records, _) = run(&equal_shadow, layout).unwrap();
            assert_eq!(records[1].entry, records[0].entry);
            assert_ne!(records[1].binding, records[0].binding);
            assert!(!records[1].reused && records[3].reused);
            let with_effect = text.replace("core.context.credit = core.context.credit - 1;", concat!(
                "core.context.credit = core.context.credit - 1; ",
                r#"core.require(false, { .stdout = ""; .stderr = ""; .code = 72; .files = []; });"#
            ));
            let (records, directives) = run(&with_effect, layout).unwrap();
            assert!(records.iter().all(|record| !record.reused));
            assert_eq!(directives.iter().filter(|report| report.code() == &BigInt::from(72)).count(), 5);
            let wrong_effect = text.replace("core.context.credit = core.context.credit - 1;", "core.context.credit = core.context.credit - 0;");
            let failure = run(&wrong_effect, layout).unwrap_err();
            let InternalContextualProofError::Refuted { goal, occurrence } = failure else { panic!("{failure:?}"); };
            let goal_text = "core.context.credit == core.old(core.context.credit) - 1";
            assert_eq!(wrong_effect[goal.start as usize..goal.end as usize].trim_end(), goal_text);
            assert_eq!(goal.start as usize, wrong_effect.find(goal_text).unwrap());
            assert_eq!((occurrence.entry, occurrence.exit), (BigInt::from(3), BigInt::from(3)));
            for refused in [
                text.replace("core.old(core.context.credit)", "core.old(core.context.other)"),
                text.replace("for consume()", "for entry()"),
                text.replace("credit = 20;", "credit = 0;"),
                text.replace(" - 1) {}", " - (1 + 0)) {}"),
                text.replace("core.old(core.context.credit)", "core.old((core.context.credit = 0))"),
            ] {
                assert!(matches!(run(&refused, layout), Err(InternalContextualProofError::Check(ProjectCheck::Unsupported))));
            }
        }
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn exact_contextual_nested_unit_calls_preserve_entry_snapshots_and_shadow_identity() {
        let app = source("src/main.w", "checked-contextual-call-state");
        let text = r#"%%start
            unit() consume = fn { core.context.credit = core.context.credit - 1; };
            unit() relay = fn { consume(); };
            unit() entry = fn {
                u8 core.context.credit = 3;
                u8 old_outer = core.context.credit;
                relay();
                core.require(false, { .stdout = ""; .stderr = ""; .code = 46; .files = [
                    { .path = "old.json"; .state = old_outer; },
                    { .path = "new.json"; .state = core.context.credit; }
                ]; });
                if (true) {
                    u8 core.context.credit = 20;
                    u8 old_inner = core.context.credit;
                    relay();
                    core.require(false, { .stdout = ""; .stderr = ""; .code = 47; .files = [
                        { .path = "old.json"; .state = old_inner; },
                        { .path = "new.json"; .state = core.context.credit; }
                    ]; });
                };
                relay();
                core.require(false, { .stdout = ""; .stderr = ""; .code = 48; .files = [
                    { .path = "old.json"; .state = old_outer; },
                    { .path = "new.json"; .state = core.context.credit; }
                ]; });
            };
            entry();
        %%end"#;
        let run = |text: &str, target_layout| {
            let parsed = crate::parse_source(app.clone(), text.to_owned(), &[]);
            assert!(parsed.diagnostics.is_empty(), "{:?}", parsed.diagnostics);
            check_internal_contextual_calls(parsed.result.canonical_cst(), ScalarPreparationInputs { target_layout })
        };
        for layout in [ScalarTargetLayout::NATIVE64, ScalarTargetLayout::WASM32] {
            let report = run(text, layout).unwrap();
            let [outer, inner, restored] = report.directives.as_slice() else { panic!("expected three reached receipts"); };
            for (record, (code, before, after)) in [outer, inner, restored].into_iter().zip([(46, 3, 2), (47, 20, 19), (48, 3, 1)]) {
                assert_eq!(record.code(), &BigInt::from(code));
                let state = |value| format!("{{\"type\":{{\"kind\":\"u8\"}},\"value\":{value}}}\n");
                assert_eq!(record.files()[0].text.as_ref(), state(before).as_bytes());
                assert_eq!(record.files()[1].text.as_ref(), state(after).as_bytes());
            }
            let outer_axes = outer.witness.axes().collect::<Vec<_>>();
            let inner_axes = inner.witness.axes().collect::<Vec<_>>();
            assert_eq!(outer_axes[0], inner_axes[0]);
            assert_ne!(outer_axes[0], inner_axes[2]);
            assert_eq!(outer_axes, restored.witness.axes().collect::<Vec<_>>());
            // The outer receipt was already reached when inner overflow is found;
            // no partial report may escape the failed transfer.
            let overflow = text.replace("credit = 20;", "credit = 0;");
            assert!(matches!(run(&overflow, layout), Err(ProjectCheck::Unsupported)));
        }
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn contextual_counter_update_keeps_old_preimages_and_refuses_invalid_width() {
        let app = source("src/main.w", "checked-contextual-counter");
        let text = r#"%%start
            unit(u8) debit = fn(initial) {
                core.narrow(initial == 1 || initial == 3, { .stdout = ""; .stderr = ""; .code = 1; .files = []; });
                u8 core.context.remaining = initial;
                u8 previous = core.context.remaining;
                core.context.remaining = core.context.remaining - 1;
                u8 current = core.context.remaining;
                if (current == 2) {
                    core.require(previous == 3 && initial == 3, { .stdout = ""; .stderr = "lost preimage"; .code = 61; .files = []; });
                    core.require(false, { .stdout = ""; .stderr = ""; .code = 63; .files = [
                        { .path = "old.json"; .state = previous; },
                        { .path = "new.json"; .state = core.context.remaining; }
                    ]; });
                } else {
                    core.require(current == 0 && previous == 1 && initial == 1,
                        { .stdout = ""; .stderr = "wrong debit"; .code = 59; .files = []; });
                };
            };
        %%end"#;
        let actual = text.replace("%%end", "debit(1); debit(3); %%end");
        let run = |program: &str, scope| {
            let prepared = prepare_proof_target(&app, program).unwrap();
            run_closed_without_named_proofs(&prepared, scope, 1)
        };
        for (program, scope) in [(text, ScalarCheckerScope::CurrentPackage),
            (actual.as_str(), ScalarCheckerScope::MainFlowOnly), (actual.as_str(), ScalarCheckerScope::CurrentPackage)]
        {
            let receipt = run(program, scope).unwrap();
            let [failure] = receipt.directives.as_slice() else { panic!("one exact debit receipt"); };
            assert_eq!(failure.code(), &BigInt::from(63));
            assert_eq!(failure.files()[0].text.as_ref(), b"{\"type\":{\"kind\":\"u8\"},\"value\":3}\n");
            assert_eq!(failure.files()[1].text.as_ref(), b"{\"type\":{\"kind\":\"u8\"},\"value\":2}\n");
        }
        let underflow = text.replace("initial == 1", "initial == 0");
        let over_budget = text.replace("initial == 1 || initial == 3", "initial <= 64")
            .replace("remaining - 1", "remaining + 1");
        for refusals in [underflow, over_budget] {
            assert!(matches!(run(&refusals, ScalarCheckerScope::CurrentPackage), Err(ProjectCheck::Unsupported)));
        }
        let returning = r#"%%start
            u8(u8) debit = fn(initial) {
                u8 core.context.remaining = initial;
                core.context.remaining = core.context.remaining - 1;
                u8 current = core.context.remaining;
                core.require(false, { .stdout = ""; .stderr = "returning write"; .code = 65; .files = []; });
                current
            };
            u8 saved = debit(3);
            core.require(saved != 2, { .stdout = ""; .stderr = "bad return"; .code = 67; .files = []; });
        %%end"#;
        let prepared = prepare_proof_target(&app, returning).unwrap();
        let (project, calls) = prepared.parts();
        let (module, item, _) = select_checked_root(project, &app, "debit").unwrap();
        let body = calls.function_body(module, item, None).unwrap();
        assert_eq!(body.structure.checker_contextual_counter_updates.len(), 1);
        for scope in [ScalarCheckerScope::MainFlowOnly, ScalarCheckerScope::CurrentPackage] {
            assert!(matches!(run_closed_without_named_proofs(&prepared, scope, 1), Err(ProjectCheck::Unsupported)));
        }
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn symbolic_contextual_boolean_writes_preserve_old_aliases_and_restore_outer_scope() {
        let app = source("src/main.w", "symbolic-contextual-bool");
        let program = r#"%%start
            unit(bool) inspect = fn(input) {
                bool core.context.ready = input;
                bool prior = core.context.ready;
                if (prior) {
                    bool core.context.ready = core.context.ready;
                    core.context.ready = false;
                    core.require(core.context.ready, { .stdout = ""; .stderr = ""; .code = 98;
                        .files = [{ .path = "inner.json"; .state = core.context.ready; }]; });
                    core.require(prior, { .stdout = ""; .stderr = "lost alias"; .code = 96; .files = []; });
                    core.context.ready = prior;
                    core.require(core.context.ready, { .stdout = ""; .stderr = "lost copied write"; .code = 97; .files = []; });
                    core.context.ready = false;
                } else {
                    core.require(!core.context.ready, { .stdout = ""; .stderr = "wrong initial lane"; .code = 95; .files = []; });
                };
                core.require(!core.context.ready, { .stdout = ""; .stderr = ""; .code = 99;
                    .files = [{ .path = "outer.json"; .state = core.context.ready; }]; });
            };
        %%end"#;
        let actual = program.replace("%%end", "inspect(false); inspect(true); %%end");
        for (text, scope) in [(program, ScalarCheckerScope::CurrentPackage),
            (actual.as_str(), ScalarCheckerScope::MainFlowOnly), (actual.as_str(), ScalarCheckerScope::CurrentPackage)]
        {
            let prepared = prepare_proof_target(&app, text).unwrap();
            let receipt = run_closed_without_named_proofs(&prepared, scope, 1).unwrap();
            let [inner, outer] = receipt.directives.as_slice() else { panic!("inner and restored outer Boolean states"); };
            assert_eq!((inner.code(), outer.code()), (&BigInt::from(98), &BigInt::from(99)));
            let inner_axes = inner.witness.axes().collect::<Vec<_>>();
            let outer_axes = outer.witness.axes().collect::<Vec<_>>();
            assert_eq!((inner_axes.len(), outer_axes.len()), (4, 3));
            assert_eq!(inner_axes[1], outer_axes[1]);
            assert_ne!(inner_axes[3], outer_axes[1]);
            let one = BigInt::from(1);
            assert!(inner.witness.intervals_at(0, 0).unwrap().eq([(&one, &one)]));
            assert!(outer.witness.intervals_at(0, 0).unwrap().eq([(&one, &one)]));
            assert_eq!(inner.files()[0].text.as_ref(), b"{\"type\":{\"kind\":\"bool\"},\"value\":false}\n");
            assert_eq!(outer.files()[0].text.as_ref(), b"{\"type\":{\"kind\":\"bool\"},\"value\":true}\n");
        }
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn exact_contextual_boolean_overwrites_inner_place_and_restores_outer_binding() {
        let inner = OUTPUT.replace(".code = 1", ".code = 98");
        let outer = OUTPUT.replace(".code = 1", ".code = 99");
        let program = format!(r#"%%start
            unit() startup = fn {{
                bool initial = true;
                bool core.context.ready = initial;
                if (core.context.ready) {{
                    bool core.context.ready = core.context.ready;
                    core.context.ready = false;
                    core.require(core.context.ready, {inner});
                }};
                core.require(!core.context.ready, {outer});
            }};
            startup();
        %%end"#);
        let app = source("src/main.w", "exact-contextual-bool");
        let prepared = prepare_proof_target(&app, &program).unwrap();
        for scope in [ScalarCheckerScope::MainFlowOnly, ScalarCheckerScope::CurrentPackage] {
            let receipt = run_closed_without_named_proofs(&prepared, scope, 1).unwrap();
            let [inner, outer] = receipt.directives.as_slice() else { panic!("expected inner and restored outer Boolean receipts"); };
            assert_eq!(inner.code(), &BigInt::from(98));
            assert_eq!(outer.code(), &BigInt::from(99));
            let inner_axes = inner.witness.axes().collect::<Vec<_>>();
            let outer_axes = outer.witness.axes().collect::<Vec<_>>();
            assert_eq!((inner_axes.len(), outer_axes.len()), (3, 2));
            assert_eq!(inner_axes[1], outer_axes[1]);
            assert_ne!(inner_axes[2], outer_axes[1]);
            let zero = BigInt::from(0);
            let one = BigInt::from(1);
            assert!(inner.witness.intervals_at(0, 2).unwrap().eq([(&zero, &zero)]));
            assert!(outer.witness.intervals_at(0, 1).unwrap().eq([(&one, &one)]));
        }
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn completed_namespace_boolean_return_preserves_receipts_and_empty_lanes() {
        let app = source("src/main.w", "completed-bool-namespace-root");
        let child = source("src/calc.w", "completed-bool-namespace-child");
        let app_text = r#"%%start
            lib = namespace demo "src/calc.w";
            alias = namespace demo "src/calc.w";
            if (lib.choose(true)) {
                core.require(false, { .stdout = ""; .stderr = "branch"; .code = 53; .files = []; });
            };
            bool unavailable = alias.retain(false);
            core.require(unavailable, { .stdout = ""; .stderr = "unreachable"; .code = 59; .files = []; });
        %%end"#;
        let child_text = r#"%%start
            core.require(false, { .stdout = ""; .stderr = "init"; .code = 47; .files = []; });
            bool(bool) choose = fn(entry) {
                core.require(false, { .stdout = ""; .stderr = "choose"; .code = 51;
                    .files = [{ .path = "chosen.json"; .state = entry; }]; });
                entry
            };
            bool(bool) retain = fn(entry) {
                core.narrow(entry, { .stdout = ""; .stderr = "pruned"; .code = 57;
                    .files = [{ .path = "rejected.json"; .state = entry; }]; });
                entry
            };
        %%end"#;
        let namespace = |name: &str| {
            let start = app_text.find(&format!("{name} =")).unwrap();
            let end = start + app_text[start..].find(';').unwrap() + 1;
            ScalarNamespaceBinding {
                binding: name.into(), target: child.clone(), span: ByteSpan::new(start as u32, end as u32),
            }
        };
        let prepare = |child_text: &str| prepare_checker_project(vec![
            (declarations(&app, app_text), vec![namespace("lib"), namespace("alias")]),
            (declarations(&child, child_text), Vec::new()),
        ], vec![app.clone(), child.clone()], inputs()).unwrap();
        let context_variants = [
            ("i8 core.context.count = 7;", "core.context.count", false),
            ("bool core.context.ready = entry;", "core.context.ready", true),
        ].map(|(declaration, context_name, is_bool)| {
            let text = child_text.replace("bool(bool) choose = fn(entry) {",
                &format!("bool(bool) choose = fn(entry) {{ {declaration}"))
                .replace(r#".path = "chosen.json"; .state = entry"#,
                    &format!(r#".path = "chosen.json"; .state = {context_name}"#));
            assert!(text.contains(&format!(".state = {context_name}")));
            let prepared = prepare(&text);
            let (project, calls) = prepared.parts();
            let (module, item, _) = select_checked_root(project, &child, "choose").unwrap();
            let structure = &calls.function_body(module, item, None).unwrap().structure;
            assert!(structure.checker_contextual_occurrences.is_empty());
            assert!(structure.checker_contextual_read_locals.is_empty());
            assert_eq!(structure.checker_has_bool_contextual_declaration, is_bool);
            assert_eq!(structure.checker_contextual_declarations.is_empty(), is_bool);
            assert_eq!(structure.has_ordinary_contextual_places(), !is_bool);
            prepared
        });
        let prepared = prepare(child_text);
        for scope in [ScalarCheckerScope::MainFlowOnly, ScalarCheckerScope::CurrentPackage] {
            for contextual in &context_variants {
                assert!(matches!(run_closed_without_named_proofs(contextual, scope, 2), Err(ProjectCheck::Unsupported)));
            }
            let receipt = run_closed_without_named_proofs(&prepared, scope, 2).unwrap();
            assert!(receipt.directives.iter().map(|failure| (&failure.source, failure.code().clone())).eq([
                (&child, 47.into()), (&child, 51.into()), (&app, 53.into()), (&child, 57.into()),
            ]));
            assert_eq!(receipt.directives[1].files()[0].text.as_ref(),
                b"{\"type\":{\"kind\":\"bool\"},\"value\":true}\n");
            assert_eq!(receipt.directives[3].files()[0].text.as_ref(),
                b"{\"type\":{\"kind\":\"bool\"},\"value\":false}\n");
        }
        let (project, calls) = prepared.parts();
        let (_, ordinals) = package_initialization_order(project).unwrap();
        let (root, target) = (ordinals[&app], ordinals[&child]);
        let ModuleInitializationDetail::Occurrences(topology) = &calls.initialization_region(root).unwrap().detail
            else { panic!("expected typed startup"); };
        let occurrence = topology.structure.blocks[topology.structure.root.0].items.iter().find_map(|item| {
            let BlockItemKind::Binding(binding) = &item.kind else { return None; };
            let BindingInitialization::Outputs(outputs) = &binding.initialization else { return None; };
            Some(outputs.primary)
        }).unwrap();
        let outside = SourceIdentity::new(app.project.clone(), "other".into(), app.path.clone(), app.revision.clone());
        for (caller, visit) in [(&app, InitializationVisit::Unseen), (&app, InitializationVisit::Started),
            (&outside, InitializationVisit::Completed)]
        {
            let mut visits = vec![InitializationVisit::Unseen; project.modules.len()];
            visits[root] = InitializationVisit::Started;
            visits[target] = visit;
            let mut actual = CheckedCalls {
                project, calls, active: HashSet::new(), active_depth: 0, reached: HashSet::new(),
            #[cfg(feature = "internal-checker")] mixed_reached: None,
                had_obligations: false, observer: ProofFreeOrderedEvidence, symbolic_module: 0,
            };
            let mut failures = OrderedFailures::default();
            let sink = RefCell::new(&mut failures);
            let result = run_initializer_call(topology, &mut actual, occurrence, &ScalarType::Bool, None, |_, _| None,
                Some((caller, OrderedCallCollection::new(&sink, Some(&visits)))), None, None);
            assert!(matches!(result, Err(ProjectCheck::Unsupported)));
            assert!(sink.borrow().records.is_empty());
        }
    }

