    #[cfg(feature = "internal-checker")]
    #[test]
    fn ordered_named_stacked_mixed_proofs_use_bool_guard_and_indexed_integer_old() {
        let app = source("src/main.w", "ordered-stacked-proof-exact-mixed");
        let text = format!(r#"%%start
            i16(bool, i16) leaf = fn(enabled, value) {{
                if (enabled) {{ 42 }} else {{ if (value == 300) {{ 9 }} else {{ value }} }}
            }};
            i16(bool, i16) producer = fn(enabled, value) {{ i16 result = leaf(enabled, value); result }};
            proof old_when_enabled for leaf(enabled, before) -> (out)
                where (enabled && before >= 0) ensures (out == core.old(before)) {{}}
            proof bounded for producer(enabled, before) -> (out)
                where (enabled && before >= 0) ensures (out <= 42) {{}}
            i16 inactive = producer(false, 300);
            i16 saved = producer(true, 300);
            core.require(inactive == 9, {OUTPUT});
            core.require(saved == 42, {OUTPUT});
        %%end"#);
        let run = |text: &str, scope| {
            let (_, proof) = crate::parse_proof_source(app.clone(), text.to_owned(), &[]).ok().unwrap();
            check_loaded_ordered_proof_diagnostics_in_scope::<true>(
                Vec::new(), vec![(proof, Vec::new())], vec![app.clone()], inputs(), scope, Vec::new(),
            )
        };
        for scope in [ScalarCheckerScope::MainFlowOnly, ScalarCheckerScope::CurrentPackage] {
            let report = run(&text, scope).unwrap();
            let [failure] = report.diagnostics.as_slice() else { panic!("only true original entry is applicable"); };
            assert!(report.directives.is_empty() && report.symbolic_diagnostic.is_none());
            assert_eq!(failure.invocation.arguments, [(ScalarType::Bool, BigInt::from(1)), (ScalarType::I16, BigInt::from(300))]);
            assert_eq!(failure.invocation.returned, BigInt::from(42));
            let reversed = text.replace("bool, i16", "i16, bool")
                .replace("enabled, value", "value, enabled").replace("enabled, before", "before, enabled")
                .replace("false, 300", "300, false").replace("true, 300", "300, true");
            let report = run(&reversed, scope).unwrap();
            let [failure] = report.diagnostics.as_slice() else { panic!("reversed typed entry tuple"); };
            assert_eq!(failure.invocation.arguments, [(ScalarType::I16, BigInt::from(300)), (ScalarType::Bool, BigInt::from(1))]);
            assert_eq!(failure.invocation.returned, BigInt::from(42));
            let proved = text.replace("producer(true, 300)", "producer(true, 42)");
            assert!(run(&proved, scope).unwrap().diagnostics.is_empty());
            let negative = text.replacen("where (enabled", "where (!enabled", 1);
            let report = run(&negative, scope).unwrap();
            let [failure] = report.diagnostics.as_slice() else { panic!("only false original entry is applicable"); };
            assert_eq!(failure.invocation.arguments[0], (ScalarType::Bool, BigInt::from(0)));
            assert_eq!(failure.invocation.returned, BigInt::from(9));
        }
        let unused = text.split_once("i16 inactive =").unwrap().0.to_owned() + "%%end";
        let symbolic = run(&unused, ScalarCheckerScope::CurrentPackage).unwrap().symbolic_diagnostic.unwrap();
        assert_eq!(symbolic.returned, BigInt::from(42));
        assert!(symbolic.witness.intervals_at(0, 0).unwrap().eq([(&BigInt::from(1), &BigInt::from(1))]));
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn ordered_named_stacked_proofs_keep_two_typed_formals_in_order() {
        let app = source("src/main.w", "ordered-stacked-proof-exact-pair");
        let text = format!(r#"%%start
            i16(i8, i16) leaf = fn(tag, value) {{ if (tag > 0) {{ 42 }} else {{ if (value == 300) {{ 9 }} else {{ value }} }} }};
            i16(i8, i16) producer = fn(tag, value) {{ i16 result = leaf(tag, value); result }};
            proof old_second for leaf(selector, before) -> (out)
                where (selector > 0) ensures (out == core.old(before)) {{}}
            proof bounded for producer(selector, before) -> (out)
                where (selector > 0) ensures (out <= 42) {{}}
            i16 inactive = producer(-1, 300);
            i16 saved = producer(1, 300);
            core.require(inactive == 9, {OUTPUT});
            core.require(saved == 42, {OUTPUT});
        %%end"#);
        let run = |text: &str, scope| {
            let (_, proof) = crate::parse_proof_source(app.clone(), text.to_owned(), &[]).ok().unwrap();
            check_loaded_ordered_proof_diagnostics_in_scope::<true>(
                Vec::new(), vec![(proof, Vec::new())], vec![app.clone()], inputs(), scope, Vec::new(),
            )
        };
        for scope in [ScalarCheckerScope::MainFlowOnly, ScalarCheckerScope::CurrentPackage] {
            let report = run(&text, scope).unwrap();
            let [failure] = report.diagnostics.as_slice() else { panic!("only the guard's positive exact pair is applicable"); };
            assert!(report.symbolic_diagnostic.is_none() && report.directives.is_empty());
            let site = &failure.invocation;
            assert_eq!(site.arguments, [(ScalarType::I8, BigInt::from(1)), (ScalarType::I16, BigInt::from(300))]);
            assert_eq!(site.returned, BigInt::from(42));
            let snippet = |span: ByteSpan| &text[span.start as usize..span.end as usize];
            assert_eq!(snippet(site.call.range), "leaf(tag, value)");
            assert_eq!(snippet(site.outer_call.as_ref().unwrap().range), "producer(1, 300)");
            let proved = text.replace("producer(1, 300)", "producer(1, 42)");
            assert!(run(&proved, scope).unwrap().diagnostics.is_empty());
        }
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn ordered_named_stacked_proofs_preserve_distinct_intermediate_occurrences() {
        let app = source("src/main.w", "ordered-stacked-proof-occurrence");
        let text = format!(r#"%%start
            i8(i8) leaf = fn(input) {{ if (input < 0) {{ -3 }} else {{ 7 }} }};
            i8(i8) bridge = fn(input) {{ i8 result = leaf(input); result }};
            i8(i8) producer = fn(input) {{
                i8 first = bridge(input);
                i8 second = bridge(input);
                if (first == 7) {{ second }} else {{ first }}
            }};
            proof inner for leaf(entry) -> (out) where (entry >= 0) ensures (out <= 6) {{}}
            proof outer for producer(entry) -> (out) ensures (out <= 7) {{}}
            i8 saved = producer(3);
            core.require(saved == 7, {OUTPUT});
        %%end"#);
        let run = |text: &str, scope| {
            let (_, proof) = crate::parse_proof_source(app.clone(), text.to_owned(), &[]).ok().unwrap();
            check_loaded_ordered_proof_diagnostics_in_scope::<true>(
                Vec::new(), vec![(proof, Vec::new())], vec![app.clone()], inputs(), scope, Vec::new(),
            )
        };
        let snippet = |span: ByteSpan| &text[span.start as usize..span.end as usize];
        for scope in [ScalarCheckerScope::MainFlowOnly, ScalarCheckerScope::CurrentPackage] {
            let report = run(&text, scope).unwrap();
            let [first, second] = report.diagnostics.as_slice() else { panic!("both real nested sites must report"); };
            assert!(report.symbolic_diagnostic.is_none() && report.directives.is_empty());
            for failure in [first, second] {
                let site = &failure.invocation;
                assert_eq!(site.arguments, [(ScalarType::I8, BigInt::from(3))]);
                assert_eq!(site.returned, BigInt::from(7));
                assert_eq!(snippet(site.outer_call.as_ref().unwrap().range), "producer(3)");
                assert_eq!(snippet(site.call.range), "leaf(input)");
                let [bridge] = site.intermediate_calls.as_slice() else { panic!("ambiguous nested route"); };
                assert_eq!(snippet(bridge.range), "bridge(input)");
            }
            assert!(first.invocation.intermediate_calls[0].range.start < second.invocation.intermediate_calls[0].range.start);
        }
        let cited_bridge = text.replace("proof outer", r#"proof bridge_base for bridge(entry) -> (out) ensures (out == 7) {}
            proof bridge_citing for bridge(entry) -> (out) ensures (out <= 7) { core.use(bridge_base(entry)); }
            proof outer"#);
        for scope in [ScalarCheckerScope::MainFlowOnly, ScalarCheckerScope::CurrentPackage] {
            assert_eq!(run(&cited_bridge, scope).unwrap().diagnostics.len(), 2);
            let refuted_bridge = cited_bridge.replace("ensures (out == 7) {}", "ensures (out == 6) {}")
                .replace("for leaf(entry) -> (out) where (entry >= 0) ensures (out <= 6)",
                         "for leaf(entry) -> (out) where (entry >= 0) ensures (out <= 7)");
            let report = run(&refuted_bridge, scope).unwrap();
            let [first, second] = report.diagnostics.as_slice() else { panic!("both cited calls must report their own premise"); };
            let snippet = |span: ByteSpan| &refuted_bridge[span.start as usize..span.end as usize];
            for failure in [first, second] {
                assert!(snippet(failure.proof.range).starts_with("proof bridge_base"));
                let site = &failure.invocation;
                assert_eq!(site.arguments, [(ScalarType::I8, BigInt::from(3))]);
                assert_eq!(site.returned, BigInt::from(7));
                assert_eq!(snippet(site.outer_call.as_ref().unwrap().range), "producer(3)");
                assert_eq!(snippet(site.call.range), "bridge(input)");
                assert!(site.intermediate_calls.is_empty());
                assert!(failure.failed_step.is_none());
            }
            assert!(first.invocation.call.range.start < second.invocation.call.range.start);
        }
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn ordered_calling_citation_then_show_checks_both_on_original_returned_states() {
        let file = source("src/main.w", "ordered-calling-citation-then-show");
        let text = r#"%%start
            i8(i8) execute = fn(input) { if (input < 0) { -3 } else { 7 } };
            i8(i8) producer = fn(input) { i8 result = execute(input); result };
            proof combined for producer(arg) -> (out) where (arg >= 0) ensures (out == 7) {
                core.use(issued(arg)); core.show(out >= 7);
            }
            proof issued for producer(arg) -> (out) where (arg >= 0) ensures (out <= 7) {}
        %%end"#;
        let run = |text: &str| {
            let (_, proof) = crate::parse_proof_source(file.clone(), text.to_owned(), &[]).ok().unwrap();
            check_loaded_ordered_proof_diagnostics_in_scope::<true>(
                Vec::new(), vec![(proof, Vec::new())], vec![file.clone()], inputs(),
                ScalarCheckerScope::CurrentPackage, Vec::new(),
            )
        };
        let proved = run(text).unwrap();
        assert!(proved.active && proved.symbolic_diagnostic.is_none());
        let false_goal = text.replace("out == 7", "out == 6");
        let refuted = run(&false_goal).unwrap().symbolic_diagnostic.unwrap();
        assert!(refuted.failed_step.is_none());
        let false_show = false_goal.replace("out >= 7", "out > 7");
        let failed_step = run(&false_show).unwrap().symbolic_diagnostic.unwrap();
        assert!(failed_step.failed_step.is_some());
        assert_eq!(failed_step.returned, BigInt::from(7));
        assert!(failed_step.witness.intervals_at(0, 0).unwrap().eq([(&BigInt::from(0), &BigInt::from(127))]));
        for (label, rejected) in [
            ("failed dependency precedes show", false_show.replace("out <= 7", "out <= 6")),
            ("guard does not imply peer guard", text.replacen("arg >= 0", "arg >= -1", 1)),
            ("reversed step order", text.replace("core.use(issued(arg)); core.show(out >= 7);",
                "core.show(out >= 7); core.use(issued(arg));")),
            ("mixed proof cannot be cited", text.replace("%%end",
                "proof reuse for producer(arg) -> (out) where (arg >= 0) ensures (out <= 8) { core.use(combined(arg)); }\n%%end")),
        ] {
            let result = run(&rejected);
            assert!(matches!(result, Err(ProjectCheck::Unsupported)), "{label}: {:?}", result.err());
        }
    }

