    #[cfg(feature = "internal-checker")]
    #[test]
    fn observed_ordinary_enum_match_result_reaches_later_requirement() {
        let text = format!(r#"%%start
            enum copy Region {{ left(u8, u16); right(u16, u8); }}
            unit(bool, u16) inspect = fn(flag, entry) {{
                u16 actual = match (if (flag) {{ Region.left(3, entry) }} else {{ Region.right(513, 7) }}) {{
                    right(wide, narrow) {{ wide }}
                    left(narrow, wide) {{ wide }}
                }};
                core.require(actual == 256, {OUTPUT});
            }};
            inspect(true, 256);
            inspect(false, 256);
        %%end"#);
        let app = source("src/main.w", "observed-runtime-enum-match");
        let run = |text: &str, scope| {
            let parsed = parse_source(app.clone(), text.to_owned(), &[]);
            assert!(parsed.diagnostics.is_empty(), "{:?}", parsed.diagnostics);
            let declarations = super::super::derive_scalar_check_declarations_from_cst(parsed.result.canonical_cst());
            check_loaded_scalar_ordered_local_proof_contexts(
                vec![(declarations, Vec::new())], Vec::new(), vec![app.clone()], inputs(), scope, Vec::new(),
            )
        };
        for scope in [ScalarCheckerScope::MainFlowOnly, ScalarCheckerScope::CurrentPackage] {
            let both = run(&text, scope).unwrap();
            let [failed] = both.directives.as_slice() else { panic!("only the actually selected right arm refutes"); };
            assert_eq!(failed.code(), &BigInt::from(1));
            assert_eq!(&text[failed.condition.start as usize..failed.condition.end as usize], "actual == 256");
            let right = BigInt::from(513);
            assert!(failed.witness.intervals_at(0, 2).unwrap().eq([(&right, &right)]));
            let true_only = text.replace("inspect(false, 256);", "");
            let passed = run(&true_only, scope).unwrap();
            assert!(passed.active && passed.directives.is_empty());
        }
        let dormant = text.replace("inspect(true, 256);", "").replace("inspect(false, 256);", "");
        let idle = run(&dormant, ScalarCheckerScope::MainFlowOnly).unwrap();
        assert!(!idle.active && idle.directives.is_empty());
        let symbolic = run(&dormant, ScalarCheckerScope::CurrentPackage).unwrap();
        assert!(symbolic.active && !symbolic.directives.is_empty());
        let unsupported = text.replace("left(narrow, wide) { wide }", "left(narrow, wide) { wide ^ 1 }");
        assert!(matches!(run(&unsupported, ScalarCheckerScope::MainFlowOnly), Err(ScalarOrderedCheckerOutcome::Invalid(_))));
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn symbolic_ordinary_enum_match_preserves_selector_and_payload_correlation() {
        let text = format!(r#"%%start
            enum copy Region {{ left(u8, u16); right(u16, u8); }}
            unit(bool, u16) inspect = fn(flag, entry) {{
                u16 actual = match (if (flag) {{ Region.left(3, entry) }} else {{ Region.right(513, 7) }}) {{
                    right(wide, narrow) {{ wide }}
                    left(narrow, wide) {{ wide }}
                }};
                core.require(!flag || actual == entry, {OUTPUT});
                core.require(flag || actual == 513, {OUTPUT});
            }};
        %%end"#);
        let app = source("src/main.w", "symbolic-runtime-enum-match");
        let run = |text: &str, scope| {
            let parsed = parse_source(app.clone(), text.to_owned(), &[]);
            assert!(parsed.diagnostics.is_empty(), "{:?}", parsed.diagnostics);
            let declarations = super::super::derive_scalar_check_declarations_from_cst(parsed.result.canonical_cst());
            check_loaded_scalar_ordered_local_proof_contexts(
                vec![(declarations, Vec::new())], Vec::new(), vec![app.clone()], inputs(), scope, Vec::new(),
            ).unwrap()
        };
        let main = run(&text, ScalarCheckerScope::MainFlowOnly);
        assert!(!main.active && main.directives.is_empty());
        let passed = run(&text, ScalarCheckerScope::CurrentPackage);
        assert!(passed.active && passed.directives.is_empty());
        let refuted = text.replace("actual == 513", "actual == 512");
        let failed = run(&refuted, ScalarCheckerScope::CurrentPackage);
        let [only] = failed.directives.as_slice() else { panic!("exactly one symbolic obligation fails"); };
        assert_eq!(&refuted[only.condition.start as usize..only.condition.end as usize], "flag || actual == 512");
        assert_eq!(only.witness.row_count(), 1);
        let zero = BigInt::from(0);
        let max = BigInt::from(u16::MAX);
        let selected = BigInt::from(513);
        assert!(only.witness.intervals_at(0, 0).unwrap().eq([(&zero, &zero)]));
        assert!(only.witness.intervals_at(0, 1).unwrap().eq([(&zero, &max)]));
        assert!(only.witness.intervals_at(0, 2).unwrap().eq([(&selected, &selected)]));
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn private_symbolic_enum_match_keeps_real_selector_and_arm_history() {
        use std::num::NonZeroUsize;
        let root = source("src/main.w", "private-symbolic-enum-source");
        for integer in [false, true] {
            for same_tag in [false, true] {
                let first_ty = if integer { "i8" } else { "bool" };
                let condition = if integer { "input < 0" } else { "input" };
                let second = if same_tag { "Region.left(7, 513)" } else { "Region.right(513, 7)" };
                let program = format!(r#"%%start
                    enum copy Region {{ left(u8, u16); right(u16, u8); }}
                    unit({first_ty}, u16) inspect = fn(input, entry) {{
                        u16 actual = match (if ({condition}) {{ Region.left(3, entry) }} else {{ {second} }}) {{
                            right(wide, narrow) {{ wide }}
                            left(narrow, wide) {{ wide }}
                        }};
                        core.require(actual != 513, {OUTPUT});
                    }};
                %%end"#);
                let at = |text: &str, offset: usize| {
                    let start = offset + program[offset..].find(text).unwrap();
                    wosy_syntax::SourceSpan::new(root.clone(), ByteSpan::new(start as u32, (start + text.len()) as u32))
                };
                let guard = at(condition, program.find("if (").unwrap());
                let left_arm = at("{ wide }", program.find("left(narrow, wide)").unwrap());
                let right_arm = at("{ wide }", program.find("right(wide, narrow)").unwrap());
                for target_layout in [ScalarTargetLayout::NATIVE64, ScalarTargetLayout::WASM32] {
                    let prepare = |scope| {
                        let parsed = parse_source(root.clone(), program.clone(), &[]);
                        assert!(parsed.diagnostics.is_empty(), "{:?}", parsed.diagnostics);
                        let declarations = super::super::derive_scalar_check_declarations_from_cst(parsed.result.canonical_cst());
                        prepare_loaded_scalar_ordered_local_proof_contexts(
                            vec![(declarations, Vec::new())], [], vec![root.clone()],
                            ScalarPreparationInputs { target_layout }, scope, Vec::new()).unwrap()
                    };
                    for scope in [ScalarCheckerScope::MainFlowOnly, ScalarCheckerScope::CurrentPackage] {
                        let old = prepare(scope).run().unwrap();
                        for cap in [1, 2, 3] {
                            let (selected, end, trace, _) = prepare(scope)
                                .search_startup_authored_path(NonZeroUsize::new(cap).unwrap()).unwrap();
                            if scope == ScalarCheckerScope::MainFlowOnly {
                                assert!(old.directives.is_empty() && selected.is_empty());
                                assert_eq!(end, StartupAuthoredCompletion::Exhausted);
                                continue;
                            }
                            assert!(old.active && !old.directives.is_empty());
                            assert_eq!(selected.len(), cap.min(2));
                            assert_eq!(end, if cap == 3 { StartupAuthoredCompletion::Exhausted } else { StartupAuthoredCompletion::LimitReached });
                            assert!(trace.contains_branch(guard.clone(), true) && trace.contains_match_arm(&left_arm));
                            assert_eq!(trace.contains_branch(guard.clone(), false), cap >= 2);
                            assert_eq!(trace.contains_match_arm(&right_arm), !same_tag && cap >= 2);
                            let verify = |row: &ScalarOrderedCheckerFailure, domains: [(i32,i32); 3]| {
                                assert_eq!(row.witness.row_count(), 1);
                                for (axis, (lo, hi)) in domains.into_iter().enumerate() {
                                    assert!(row.witness.intervals_at(0, axis).unwrap().eq([(&lo.into(), &hi.into())]));
                                }
                            };
                            verify(&selected[0], [if integer { (-128,-1) } else { (1,1) }, (513,513), (513,513)]);
                            if cap >= 2 {
                                verify(&selected[1], [if integer { (0,127) } else { (0,0) }, (0,65535), (513,513)]);
                            }
                        }
                    }
                }
            }
        }
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn symbolic_ordinary_enum_match_uses_typed_integer_selector_order() {
        let text = format!(r#"%%start
            enum copy Region {{ left(u8, u16); right(u16, u8); }}
            unit(i8, u16) inspect = fn(input, entry) {{
                u16 actual = match (if (input < 0) {{ Region.left(3, entry) }} else {{ Region.right(513, 7) }}) {{
                    right(wide, narrow) {{ wide }}
                    left(narrow, wide) {{ wide }}
                }};
                core.require(input >= 0 || actual == entry, {OUTPUT});
                core.require(input < 0 || actual == 513, {OUTPUT});
            }};
        %%end"#);
        let app = source("src/main.w", "symbolic-runtime-enum-match-order");
        let run = |text: &str| {
            let parsed = parse_source(app.clone(), text.to_owned(), &[]);
            assert!(parsed.diagnostics.is_empty(), "{:?}", parsed.diagnostics);
            let declarations = super::super::derive_scalar_check_declarations_from_cst(parsed.result.canonical_cst());
            check_loaded_scalar_ordered_local_proof_contexts(
                vec![(declarations, Vec::new())], Vec::new(), vec![app.clone()], inputs(),
                ScalarCheckerScope::CurrentPackage, Vec::new(),
            )
        };
        for text in [&text, &text.replace("if (input < 0)", "if (0 > input)")] {
            let passed = run(text).unwrap();
            assert!(passed.active && passed.directives.is_empty());
            let refuted = text.replace("actual == 513", "actual == 512");
            let failed = run(&refuted).unwrap();
            let [only] = failed.directives.as_slice() else { panic!("only the nonnegative path fails"); };
            assert_eq!(&refuted[only.condition.start as usize..only.condition.end as usize], "input < 0 || actual == 512");
            let zero = BigInt::from(0);
            let max = BigInt::from(i8::MAX);
            let payload_max = BigInt::from(u16::MAX);
            let result = BigInt::from(513);
            assert_eq!(only.witness.row_count(), 1);
            assert!(only.witness.intervals_at(0, 0).unwrap().eq([(&zero, &max)]));
            assert!(only.witness.intervals_at(0, 1).unwrap().eq([(&zero, &payload_max)]));
            assert!(only.witness.intervals_at(0, 2).unwrap().eq([(&result, &result)]));
        }
        for unsupported in [text.replace("if (input < 0)", "if ((input ^ 1) < 0)"),
            text.replace("if (input < 0)", "if (input < 128)")]
        {
            assert!(matches!(run(&unsupported), Err(ScalarOrderedCheckerOutcome::Invalid(_))));
        }
    }

    #[cfg(feature = "internal-checker")]
    #[test]
    fn symbolic_ordinary_enum_match_calculates_selected_wrapping_payload() {
        let text = format!(r#"%%start
            enum copy Region {{ left(u8); right(u8); }}
            unit(u8) inspect = fn(input) {{
                u8 actual = match (if (input >= 254) {{ Region.left(input) }} else {{ Region.right(17) }}) {{
                    right(payload) {{ payload }}
                    left(payload) {{ payload +@ 1 }}
                }};
                core.require(input != 254 || actual == 255, {OUTPUT});
                core.require(input != 255 || actual == 0, {OUTPUT});
                core.require(input >= 254 || actual == 17, {OUTPUT});
            }};
        %%end"#);
        let app = source("src/main.w", "symbolic-runtime-enum-selected-wrap");
        let run = |text: &str, scope| {
            let parsed = parse_source(app.clone(), text.to_owned(), &[]);
            assert!(parsed.diagnostics.is_empty(), "{:?}", parsed.diagnostics);
            let declarations = super::super::derive_scalar_check_declarations_from_cst(parsed.result.canonical_cst());
            check_loaded_scalar_ordered_local_proof_contexts(
                vec![(declarations, Vec::new())], Vec::new(), vec![app.clone()], inputs(), scope, Vec::new(),
            )
        };
        let constructor = text.replace("Region.left(input)", "Region.left(1 +@ input)")
            .replace("left(payload) { payload +@ 1 }", "left(payload) { payload }");
        for text in [&text, &constructor] {
            let checked = run(text, ScalarCheckerScope::CurrentPackage).unwrap();
            assert!(checked.active && checked.directives.is_empty());
            let actual = text.replace("%%end", "inspect(254); inspect(255); %%end");
            let checked = run(&actual, ScalarCheckerScope::MainFlowOnly).unwrap();
            assert!(checked.active && checked.directives.is_empty());
            let refuted = text.replace("actual == 0", "actual == 1");
            let failed = run(&refuted, ScalarCheckerScope::CurrentPackage).unwrap();
            let [only] = failed.directives.as_slice() else { panic!("only the maximal wrapping input refutes"); };
            assert_eq!(&refuted[only.condition.start as usize..only.condition.end as usize], "input != 255 || actual == 1");
            let maximum = BigInt::from(u8::MAX);
            let zero = BigInt::from(0);
            assert_eq!(only.witness.row_count(), 1);
            assert!(only.witness.intervals_at(0, 0).unwrap().eq([(&maximum, &maximum)]));
            assert!(only.witness.intervals_at(0, 1).unwrap().eq([(&zero, &zero)]));
        }
        let broad = text.replace("if (input >= 254)", "if (input >= 0)")
            .replace("input >= 254 || actual == 17", "actual != 0 || input == 255");
        let checked = run(&broad, ScalarCheckerScope::CurrentPackage).unwrap();
        assert!(checked.active && checked.directives.is_empty());
        let double = text.replace("Region.left(input)", "Region.left(input +@ 1)");
        assert!(matches!(run(&double, ScalarCheckerScope::CurrentPackage), Err(ScalarOrderedCheckerOutcome::Invalid(_))));
    }

